/* ============ Yardımcılar ============ */
const $=(s,r=document)=>r.querySelector(s);
const $$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=s=>String(s??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
const rid=()=>Date.now().toString(36)+Math.random().toString(36).slice(2,8);
const clone=o=>JSON.parse(JSON.stringify(o??null));
const now=()=>Date.now();
const H=3600e3;
const APP_URL=location.origin+location.pathname;
const fmt=n=>new Intl.NumberFormat("tr-TR").format(n);
const short=n=>n>=1e6?(n/1e6).toFixed(1).replace(".",",")+" Mn":n>=1e4?Math.round(n/1e3)+" B":fmt(n);
function ago(t){const s=(now()-t)/1e3;if(s<60)return"şimdi";if(s<3600)return Math.floor(s/60)+" dk";if(s<86400)return Math.floor(s/3600)+" sa";if(s<604800)return Math.floor(s/86400)+" g";return Math.floor(s/604800)+" hf"}
const LS={get(k,d=null){try{const v=localStorage.getItem(k);return v==null?d:JSON.parse(v)}catch{return d}},set(k,v){try{localStorage.setItem(k,JSON.stringify(v));return true}catch{return false}},del(k){try{localStorage.removeItem(k)}catch{}}};
const SS={get(k){try{return sessionStorage.getItem(k)}catch{return null}},set(k,v){try{sessionStorage.setItem(k,v)}catch{}},del(k){try{sessionStorage.removeItem(k)}catch{}}};
function hash32(str,seed){let h=seed>>>0;for(let i=0;i<str.length;i++){h^=str.charCodeAt(i);h=Math.imul(h,16777619)}return(h>>>0).toString(16).padStart(8,"0")}
async function sha(s){try{const b=await crypto.subtle.digest("SHA-256",new TextEncoder().encode(s));return[...new Uint8Array(b)].map(x=>x.toString(16).padStart(2,"0")).join("")}catch{return hash32(s,2166136261)+hash32(s,99991)+hash32(s,7)}}
function richText(t){return esc(t).replace(/(#[\wçğıöşüÇĞİÖŞÜ]+)/g,'<span class="ht">$1</span>').replace(/(^|\s)@([a-z0-9._]+)/gi,'$1<button class="ht" data-mention="$2">@$2</button>')}
const vib=ms=>{try{if(settings.haptics===false)return;navigator.vibrate&&navigator.vibrate(ms)}catch{}};
/* ============ 4.0 kancalar ============ */
/* Sürüm: ana.ara.yama (4.1.0). Hata düzeltme ve küçük şeyler → yama artar (4.1.1); büyük güncelleme → ara artar (4.2.0).
   APP_V = ana*10000 + ara*100 + yama (4.1.0 → 40100). Başlıktaki <meta name="kadraj-version"> ile aynı tutulmalı.
   Eski biçim (4.0 → 40) verNorm ile çevrilir. "İki sürüm geride" ara sürüm sayısıyla ölçülür (yamalar engellemez). */
const APP_V=60816,APP_VER="6.8.16";
/* Güncelleme adları (sahibinin isteği, 6.0.5): her ara sürümün bir adı var, Türkiye'nin rüzgârları. Yeni ara sürümde buraya sıradakini ekle. */
const VER_NAMES={60:"Poyraz",61:"Lodos",62:"Karayel",63:"Yıldız",64:"Keşişleme",65:"Kıble",66:"Gündoğusu",67:"Günbatısı",68:"Meltem",69:"Bora"};
const APP_NAME=VER_NAMES[Math.floor(APP_V/10000)*10+Math.floor(APP_V/100)%100]||"";
const APP_FULL=APP_NAME?`${APP_VER} ${APP_NAME}`:APP_VER;
const verNorm=x=>{x=Math.max(0,Math.floor(+x||0));return x<1000?Math.floor(x/10)*10000+(x%10)*100:x};
const verLvl=x=>Math.floor(verNorm(x)/100);
/* 4.9: fark sürüm adımıyla sayılır (4.9 → 5.0 bir adım); eskisi ana*100+ara farkıydı ve 5.0'ı 91 sürüm ileride sanıyordu */
const verStep=x=>{const n=verNorm(x);return Math.floor(n/10000)*10+Math.floor(n/100)%100};
const verGap=x=>verStep(x)-verStep(APP_V);
/* data-act="x" olan düğmeler için ek eylemler: ACT.x=(t,d,e)=>{...} (tıklama dağıtıcısının sonunda çağrılır) */
const ACT={};
/* Kancalar: after(routeName) her render sonrası · enter(fresh) uygulamaya girince · profiles(map) profiller gelince · boot() açılışta */
const HOOKS={after:[],enter:[],profiles:[],boot:[]};
function runHooks(k,...a){for(const f of HOOKS[k]||[])try{f(...a)}catch(e){console.warn("hook",k,e)}}

