const LocalDB=(()=>{
 const KEY="kadraj_db";let data=LS.get(KEY,{})||{};const subs=new Set();
 const parent=p=>p.slice(0,p.lastIndexOf("/"));
 function save(){const ok=LS.set(KEY,data);if(!ok)toast("Cihaz depolaması doldu. Birkaç eski paylaşımı sil.");return ok}
 function notify(p){for(const s of subs)s.check(p)}
 function merge(a,b){const o={...a};for(const[k,v]of Object.entries(b)){if(v&&typeof v==="object"&&!Array.isArray(v)&&o[k]&&typeof o[k]==="object"&&!Array.isArray(o[k]))o[k]=merge(o[k],v);else o[k]=v}return o}
 function match(v,w){if(!w)return true;const[f,op,val]=w;if(op==="array-contains")return Array.isArray(v[f])&&v[f].includes(val);if(op==="==")return v[f]===val;return true}
 addEventListener("storage",e=>{if(e.key===KEY){data=LS.get(KEY,{})||{};for(const s of subs)s.all()}});
 return{
  async get(p){return data[p]?clone(data[p]):null},
  async set(p,o){const prev=data[p];data[p]=clone(o);if(!save()){if(prev)data[p]=prev;else delete data[p];throw{code:"quota_exceeded"}}notify(p)},
  async update(p,o){if(!data[p])throw{code:"invalid_argument"};const prev=data[p];data[p]=merge(data[p],clone(o));if(!save()){data[p]=prev;throw{code:"quota_exceeded"}}notify(p)},
  async del(p){delete data[p];save();notify(p)},
  watchCol(col,cb,opts={}){let q=false;const fire=()=>{q=false;let out=[];for(const[p,v]of Object.entries(data)){if(parent(p)===col&&match(v,opts.where))out.push({id:p.slice(col.length+1),...clone(v)})}
    if(opts.orderBy){const[f,d]=opts.orderBy;out.sort((a,b)=>((a[f]??0)-(b[f]??0))*(d==="desc"?-1:1))}if(opts.limit)out=out.slice(0,opts.limit);cb(out)};
   const s={check:p=>{if(parent(p)===col&&!q){q=true;queueMicrotask(fire)}},all:fire};subs.add(s);setTimeout(fire);return()=>subs.delete(s)},
  watchDoc(path,cb){const fire=()=>cb(data[path]?clone(data[path]):null);const s={check:p=>{if(p===path)fire()},all:fire};subs.add(s);setTimeout(fire);return()=>subs.delete(s)}
 }})();
