const EMBED_CFG={"apiKey": "AIzaSyA_VeF7m3WxigutKtM2lzQmdhIn4IgBjZI", "authDomain": "kadraj-6f1e0.firebaseapp.com", "projectId": "kadraj-6f1e0", "storageBucket": "kadraj-6f1e0.firebasestorage.app", "messagingSenderId": "575068718085", "appId": "1:575068718085:web:e05e02f00b5946d801c86c"};
const FBV="10.12.2";let FB=null;const FB_UNSUBS=new Set();
async function loadFirebase(cfg){const base=`https://www.gstatic.com/firebasejs/${FBV}/`;const[appM,A,F]=await Promise.all([import(base+"firebase-app.js"),import(base+"firebase-auth.js"),import(base+"firebase-firestore.js")]);
 const app=appM.initializeApp(cfg);const auth=A.getAuth(app);try{auth.languageCode="tr"}catch{}
 let db;try{db=F.initializeFirestore(app,{ignoreUndefinedProperties:true,localCache:F.persistentLocalCache({tabManager:F.persistentMultipleTabManager()})})}catch(e){try{db=F.initializeFirestore(app,{ignoreUndefinedProperties:true})}catch{db=F.getFirestore(app)}}
 FB={app,auth,db,A,F};return FB}
/* 6.8.4: KU = bu cihazın Firestore işlem sayacı (okuma r, yazma w, silme d; 6.8.5: gönderilen mesaj ms, silinen mesaj md; bölge 70 günlük toplamı games/ku-<gün>'e ekler) */
const KU_MSG=/^chats\/[^/]+\/msgs\/[^/]+$/;
const KU={r:0,w:0,d:0,ms:0,md:0,wc:{},log:[]};
/* kuCol: yolun hangi özelliğe ait olduğu (sohbet mesajları "mesaj"); kuW: yazma/silmeyi özelliğiyle ve zamanıyla kaydeder (son 400 işlem, yalnızca bellekte) */
const kuCol=p=>{const a=String(p).split("/");return a[0]==="chats"&&a[2]==="msgs"?"mesaj":a[0]==="data"&&a[1]==="users"?"kişisel ("+(a[3]||"").replace(/^bot-.*/,"bot")+")":a[0]==="games"?"games ("+String(a[1]||"").replace(/[-_].*$/,"")+")":a[0]};
function kuW(p,t){const c=kuCol(p);KU.wc[c]=(KU.wc[c]||0)+1;KU.log.push([Date.now(),c,t]);if(KU.log.length>400)KU.log.splice(0,KU.log.length-400)}
function FirebaseDB(){const{F,db}=FB;
 const flat=(obj,prefix=[],out=[])=>{for(const[k,v]of Object.entries(obj)){if(v&&typeof v==="object"&&!Array.isArray(v)&&Object.keys(v).length)flat(v,[...prefix,k],out);else out.push(new F.FieldPath(...prefix,k),v===undefined?null:v)}return out};
 const track=u=>{const f=()=>{try{u()}catch{}FB_UNSUBS.delete(f)};FB_UNSUBS.add(f);return f};
 const onErr=e=>{console.warn("firestore",e);if(e&&e.code==="permission-denied")rulesWarn()};
 /* dinleyici ilk sunucu yanıtında bütün belgeler (boşsa 1), sonra yalnızca değişenler okunmuş sayılır */
 const kuSnap=()=>{let on=false;return s=>{if(s.metadata&&s.metadata.fromCache)return;if(!on){on=true;KU.r+=s.docs?Math.max(1,s.size):1}else KU.r+=s.docChanges?s.docChanges().filter(c=>c.type!=="removed").length:1}};
 return{
  async get(p){KU.r++;const s=await F.getDoc(F.doc(db,p));return s.exists()?s.data():null},
  set:(p,o)=>{KU.w++;kuW(p,"w");if(KU_MSG.test(p))KU.ms++;return F.setDoc(F.doc(db,p),o)},
  update(p,o){const args=flat(o);if(!args.length)return Promise.resolve();KU.w++;kuW(p,"w");return F.updateDoc(F.doc(db,p),...args)},
  del:p=>{KU.d++;kuW(p,"d");if(KU_MSG.test(p))KU.md++;return F.deleteDoc(F.doc(db,p))},
  watchCol(col,cb,opts={}){const cons=[];if(opts.where)cons.push(F.where(...opts.where));if(opts.orderBy)cons.push(F.orderBy(...opts.orderBy));cons.push(F.limit(opts.limit||500));const k=kuSnap();
   return track(F.onSnapshot(F.query(F.collection(db,col),...cons),s=>{k(s);cb(s.docs.map(d=>({id:d.id,...d.data()})))},opts.onError||onErr))},
  watchDoc(p,cb){const k=kuSnap();return track(F.onSnapshot(F.doc(db,p),s=>{k(s);cb(s.exists()?s.data():null)},onErr))}}}
function unsubAll(){[...FB_UNSUBS].forEach(f=>f())}
let rulesWarned=false;function rulesWarn(){if(rulesWarned)return;rulesWarned=true;toast("Firebase veritabanı kuralları izin vermiyor. Kurulumdaki kuralları Firestore > Kurallar'a yapıştırıp Yayınla'ya bas.")}
/* çevrimiçi durumu ve dürtme: Firestore ile */
function FsRoom(){const{F,db}=FB;let state={typing:null},hb=null,docs=[],cb=null,pokeH=null;const handled=new Set();
 const push=()=>S.uid&&S.authed&&!S.guest&&document.visibilityState!=="hidden"?(KU.w++,kuW("presence","w"),F.setDoc(F.doc(db,"presence/"+S.uid),{uid:S.uid,typing:state.typing||null,at:Date.now(),seen:Date.now(),hide:settings.showActive===false}).catch(()=>{})):Promise.resolve();
 const fire=()=>{const vis=docs.filter(d=>!d.hide||d.uid===S.uid);S.lastSeen=Object.fromEntries(vis.map(d=>[d.uid,Math.max(d.seen||0,d.at||0)]));if(!cb)return;const lim=Date.now()-200e3;cb({peers:vis.filter(d=>d.at>lim).map(d=>({presence:{uid:d.uid,typing:d.typing},isMe:d.uid===S.uid}))})};
 setInterval(fire,30e3);
 const off=()=>{if(S.uid&&S.authed&&!S.guest)KU.w++,kuW("presence","w"),F.setDoc(F.doc(db,"presence/"+S.uid),{uid:S.uid,typing:null,at:0,seen:Date.now()}).catch(()=>{})};
 addEventListener("pagehide",off);
 document.addEventListener("visibilitychange",()=>{if(document.visibilityState==="visible")push();else off()});
 return{
  presence(p){Object.assign(state,p);if(!hb)hb=setInterval(push,90e3);return push()},
  onPeers(f){cb=f},
  listen(){const u1=DB.watchCol("presence",d=>{docs=d;fire()},{limit:300});
   const u2=DB.watchCol("pokes",ds=>{for(const d of ds){if(handled.has(d.id))continue;handled.add(d.id);if(d.at>S.bootAt-5000&&pokeH)pokeH({data:d});DB.del("pokes/"+d.id).catch(()=>{})}},{where:["to","==",S.uid],limit:50});
   return()=>{u1();u2()}},
  async emit(topic,data){KU.w++;kuW("pokes","w");await F.addDoc(F.collection(db,"pokes"),{...data,topic,at:Date.now()})},
  on(t,h){pokeH=h},
  async leave(){if(hb){clearInterval(hb);hb=null}if(S.uid)await F.setDoc(F.doc(db,"presence/"+S.uid),{uid:S.uid,typing:null,at:0,seen:Date.now()}).catch(()=>{})}}}
/* kurulum yardımcıları */
function parseCfg(t){t=(t||"").trim();let o=null;try{o=JSON.parse(t)}catch{}if(!o||typeof o!=="object"){o={};for(const k of["apiKey","authDomain","projectId","storageBucket","messagingSenderId","appId"]){const m=t.match(new RegExp(k+"[\"']?\\s*[:=]\\s*[\"'`]([^\"'`]+)[\"'`]"));if(m)o[k]=m[1]}}
 if(!o.apiKey||!o.projectId||!o.appId)return null;return{apiKey:o.apiKey,authDomain:o.authDomain||o.projectId+".firebaseapp.com",projectId:o.projectId,storageBucket:o.storageBucket||"",messagingSenderId:o.messagingSenderId||"",appId:o.appId}}
const b64e=s=>btoa(unescape(encodeURIComponent(s))).replace(/\+/g,"-").replace(/\//g,"_").replace(/=+$/,"");
const b64d=s=>decodeURIComponent(escape(atob(s.replace(/-/g,"+").replace(/_/g,"/"))));
function inviteLink(){const c=LS.get("kadraj_fb_cfg");if(!c||c.projectId===EMBED_CFG.projectId)return APP_URL;return c?APP_URL+"#k="+b64e(JSON.stringify(c)):APP_URL}
function readHashCfg(){const m=location.hash.match(/k=([A-Za-z0-9_-]+)/);if(!m)return null;try{return parseCfg(b64d(m[1]))}catch{return null}}


async function write(fn,{quiet=false}={}){if(!S.canWrite){if(!quiet)noWrite();return false}try{await fn();return true}catch(e){console.warn(e);if(quiet)return false;if(e&&e.code==="permission-denied"){toast("Firebase kuralları bu işleme izin vermiyor. Kurulumdaki kuralları yapıştırıp Yayınla'ya bastığından emin ol.");return false}if(e&&e.code==="resource-exhausted"){toast("Firebase'in günlük ücretsiz kotası doldu. Yarın tekrar dene.");return false}
 const msg=(e&&e.message)||"";
 if(e&&(e.code==="invalid_argument"||e.code==="transform_error")){if(/256|KiB|large|size|byte/i.test(msg))toast("Dosya çok büyük. Daha küçük bir fotoğraf dene.");else if(S.mode==="cloud"&&/permission|level|write|denied|granted/i.test(msg)){S.canWrite=false;noWrite()}else toast("Kaydedilemedi: "+(msg||"geçersiz veri"))}
 else if(e&&e.code==="not_granted"){S.canWrite=false;noWrite()}
 else if(e&&e.code==="quota_exceeded")toast("Depolama doldu. Eski paylaşımları sil ve tekrar dene.");else toast("Kaydedilemedi. Bağlantını kontrol edip tekrar dene.");return false}}
function noWrite(){toast("Bu sayfada değişiklik yapma iznin yok. Sahibinden seni “Düzenleyen” olarak davet etmesini iste.")}

/* ============ Profil yardımcıları ============ */
function P(uid){if(BOT[uid])return BOT[uid];const p=S.profiles[uid];if(p)return{...p,avatar:p.avatar||initialsAv(p.name||p.username,uid)};return{uid,username:"kullanici",name:"Bilinmeyen hesap",avatar:initialsAv("?",uid),missing:true,following:{}}}
const me=()=>P(S.uid);
function isFollowing(a,b){if(BOT[a])return BOT[a].following.includes(b);return !!S.profiles[a]?.following?.[b]}
function followersOf(uid){const hs=Object.values(S.profiles).filter(p=>p.following&&p.following[uid]).map(p=>p.uid);const bots=BOT[uid]?BOTS.filter(b=>b.following.includes(uid)).map(b=>b.uid):Object.entries(S.profiles[uid]?.botFollowers||{}).filter(([k,v])=>v&&BOT[k]).map(([k])=>k);return[...new Set([...bots,...hs])]}
function followingOf(uid){if(BOT[uid])return BOT[uid].following;return Object.entries(S.profiles[uid]?.following||{}).filter(([,v])=>v).map(([k])=>k)}
const followerCount=uid=>(BOT[uid]?.baseFollowers||0)+followersOf(uid).length;
let humans=()=>Object.keys(S.profiles).filter(u=>u!==S.uid&&!P(u).missing);
function allPostsOld(){return[...BOT_POSTS,...Object.values(S.posts).filter(p=>p&&p.uid&&S.profiles[p.uid])].sort((a,b)=>b.at-a.at)}
const postByIdOld=id=>BOT_POSTS.find(p=>p.id===id)||S.posts[id]||kvById(id);
/* 4.4.0: "Çocuk modundakiler göremez" (p.noKids) işaretli paylaşımlar Çocuk Modu'ndaki kişiye hiç görünmez (sahibi hariç) */
const kidHid=p=>!!(p&&p.noKids&&p.uid!==S.uid&&isChild(S.uid));
function allPosts(){return allPostsOld().filter(p=>!kidHid(p))}
const postById=id=>{const p=postByIdOld(id);return kidHid(p)||(p&&p.arch&&p.uid!==S.uid)?undefined:p};
const postsOf=uid=>allPosts().filter(p=>p.uid===uid);
function canSee(p){const owner=S.profiles[p.uid];if(!owner||!owner.private||p.uid===S.uid)return true;return isFollowing(S.uid,p.uid)}
function storiesOf(uid){const lim=now()-24*H;return[...BOT_STORIES,...Object.values(S.stories)].filter(s=>s.uid===uid&&s.at>lim&&(!s.cf||uid===S.uid||isClose(uid,S.uid))).sort((a,b)=>a.at-b.at)}
const seenStories=()=>LS.get("kadraj_seen",{})||{};
function storyRing(uid){const st=storiesOf(uid);if(!st.length)return"";const seen=seenStories();return st.every(s=>seen[s.id])?"ring seen":st.some(s=>s.cf)?"ring cf":"ring"}
function avatar(uid,size=44,opts={}){const p=P(uid);const ring=opts.ring===false?"":storyRing(uid);const on=opts.online!==false&&isActive(uid)?'<i class="on"></i>':"";
 const inner=`<img src="${esc(p.avatar)}" alt="" loading="lazy" decoding="async">${on}`;
 return ring&&opts.click!==false?`<button class="av ${ring}" style="--s:${size}px" data-story="${esc(uid)}" aria-label="${esc(p.username)} hikâyesi">${inner}</button>`:`<span class="av ${ring}" style="--s:${size}px">${inner}</span>`}
let badge=uid=>BOT[uid]?(BOT[uid].ai?'<span class="tag">'+I("spark")+'AI</span>':'<span class="tag">bot</span>'):isVerified(uid)?'<span class="vbadge" title="Onaylı hesap" aria-label="Onaylı hesap"><svg viewBox="0 0 24 24"><path d="M12 2l2.4 1.8 3-.2.9 2.9 2.5 1.7-1 2.8 1 2.8-2.5 1.7-.9 2.9-3-.2L12 22l-2.4-1.8-3 .2-.9-2.9-2.5-1.7 1-2.8-1-2.8 2.5-1.7.9-2.9 3 .2z"/><path d="m8 12.3 2.6 2.5L16 9.5" fill="none" stroke="#fff" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"/></svg></span>':"";
const postThumb=p=>R(p.kind==="reel"?(p.poster||(p.slides&&p.slides[0])||p.img||""):(p.src||p.img||""));
/* beğeni, yorum, oy */
const metaOf=id=>S.meta[id]||{likes:{},comments:{},votes:{}};
const likers=id=>Object.entries(metaOf(id).likes||{}).filter(([k,v])=>v&&!(k.startsWith("bot:")&&!BOT[k])).sort((a,b)=>b[1]-a[1]).map(([k])=>k);
const iLike=id=>!!(metaOf(id).likes||{})[S.uid];
const likeCount=p=>(p.baseLikes||0)+likers(p.id).length;
function commentsOf(p){const seed=(p.cm||[]).map((c,i)=>({id:"s"+i,uid:c[0],text:c[1],at:p.at+(i+1)*600e3}));const live=Object.entries(metaOf(p.id).comments||{}).filter(([,c])=>c&&c.text&&c.uid&&!(String(c.uid).startsWith("bot:")&&!BOT[c.uid])).map(([id,c])=>({id,...c}));return[...seed,...live].sort((a,b)=>a.at-b.at)}
function votesOf(p){const base=(p.baseVotes||p.options.map(()=>0)).slice();for(const[,i]of Object.entries(metaOf(p.id).votes||{}))if(i!=null&&base[i]!=null)base[i]++;return base}
const myVote=id=>{const v=(metaOf(id).votes||{})[S.uid];return v==null?null:v};
function deepMerge(a,b){for(const[k,v]of Object.entries(b)){if(v&&typeof v==="object"&&!Array.isArray(v)&&a[k]&&typeof a[k]==="object")deepMerge(a[k],v);else a[k]=v}return a}
async function setMeta(id,patch){const path="meta/"+id;const cur=S.meta[id];const next=deepMerge(cur?clone(cur):{likes:{},comments:{},votes:{}},clone(patch));S.meta={...S.meta,[id]:next};scheduleRefresh();
 return write(async()=>{if(cur)return DB.update(path,patch);try{await DB.update(path,patch)}catch(e){const c=e&&e.code;if(c==="not-found"||c==="invalid_argument")return DB.set(path,next);throw e}})}
async function toggleLike(id,onlyLike){if(!guard())return;const liked=iLike(id);if(onlyLike&&liked)return;vib(15);await setMeta(id,{likes:{[S.uid]:liked?0:now()}})}
async function addComment(id,text,re){if(!guard())return;text=text.trim().slice(0,600);if(!text)return;if(isChild(S.uid))text=cleanText(text);await setMeta(id,{comments:{[rid()]:{uid:S.uid,text,at:now(),...(re?{re:String(re).slice(0,40)}:{})}}})}
async function delComment(pid,cid){await setMeta(pid,{comments:{[cid]:null}})}
async function vote(id,i){if(!guard())return;vib(15);await setMeta(id,{votes:{[S.uid]:i}})}
async function toggleFollow(uid){if(!guard()||uid===S.uid)return;const v=isFollowing(S.uid,uid)?0:now();const mine=S.profiles[S.uid];if(mine)S.profiles={...S.profiles,[S.uid]:{...mine,following:{...(mine.following||{}),[uid]:v}}};scheduleRefresh();
 await write(()=>DB.update("profiles/"+S.uid,{following:{[uid]:v}}));if(v)toast(`@${P(uid).username} takip ediliyor`,uid)}
function guard(){if(S.guest){toast("Bunu yapmak için hesap gerekiyor.");return false}if(!S.admin&&typeof muteOf==="function"&&muteOf(S.uid)){const m=muteOf(S.uid);toast(m.until>now()+3650*24*H?"Yönetici seni susturdu. Şimdilik paylaşım ve mesaj gönderemezsin.":`Yönetici seni ${new Date(m.until).toLocaleString("tr-TR",{day:"numeric",month:"short",hour:"2-digit",minute:"2-digit"})} tarihine kadar susturdu.`);return false}if(!S.canWrite){noWrite();return false}return true}
const isSaved=id=>!!S.saved[id];
async function toggleSave(id){if(!guard())return;const v=!isSaved(id);S.saved={...S.saved,[id]:v};scheduleRefresh();await write(()=>DB.set(`data/users/${S.uid}/saved`,{ids:S.saved}));toast(v?"Kaydedilenlere eklendi":"Kaydedilenlerden çıkarıldı")}

/* ============ Sohbet anahtarları ============ */
/* key: "u:<uid>" birebir/bot · "g:<gid>" grup · "meydan" */
const cidFor=(a,b)=>{const k=a<b?a+"|"+b:b+"|"+a;return"dm-"+hash32(k,2166136261)+hash32(k,40503)};
function keyInfo(key){if(key==="meydan")return{type:"meydan",cid:"meydan"};if(key.startsWith("g:"))return{type:"group",cid:key.slice(2)};const uid=key.slice(2);if(BOT[uid])return{type:"bot",uid,bot:BOT[uid]};return{type:"dm",uid,cid:cidFor(S.uid,uid)}}
function chatListOld(){const out=[];const hid=(S.hidden&&S.hidden.chats)||{};const loaded=Object.keys(S.profiles).length>0;
 for(const[id,c]of Object.entries(S.chats)){if(hid[id]&&hid[id]>=(c.updatedAt||0))continue;
  if(c.group){out.push({key:"g:"+id,group:true,name:c.name||"Grup",photo:c.photo||null,members:c.members||[],last:c.last,at:c.updatedAt||0,unread:!!(c.last&&c.last.from!==S.uid&&c.last.at>((c.reads||{})[S.uid]||0))});continue}
  const other=(c.members||[]).find(m=>m!==S.uid);if(!other)continue;if(loaded&&!BOT[other]&&!S.profiles[other])continue;
  out.push({key:"u:"+other,other,last:c.last,at:c.updatedAt||0,unread:!!(c.last&&c.last.from!==S.uid&&c.last.at>((c.reads||{})[S.uid]||0))})}
 for(const[k,c]of Object.entries(S.botchats)){const b=BOTS.find(x=>x.key===k);if(!b||!c.msgs?.length)continue;const l=c.msgs[c.msgs.length-1];out.push({key:"u:"+b.uid,other:b.uid,last:{text:l.text,from:l.from,at:l.at},at:l.at,unread:l.from!==S.uid&&l.at>(c.readAt||0)})}
 return out.sort((a,b)=>b.at-a.at)}
const groupAv=(c,id)=>(c&&c.photo)||initialsAv((c&&c.name)||"Grup",id);
/* aktiflik (4.0): ayarlarda "Aktiflik durumu" kapalıysa (settings.showActive===false) kimsenin durumu gösterilmez */
const lastSeenAt=uid=>(S.lastSeen||{})[uid]||0;
const isActive=uid=>settings.showActive!==false&&!!uid&&!BOT[uid]&&S.online.has(uid);
function activeLabel(uid){if(settings.showActive===false||!uid||BOT[uid])return"";if(S.online.has(uid))return"Şu an aktif";const t=lastSeenAt(uid);if(!t)return"";const m=(now()-t)/60e3;if(m<1)return"Az önce aktifti";if(m<60)return`${Math.round(m)} dk önce aktifti`;if(m<1440)return`${Math.round(m/60)} sa önce aktifti`;if(m<10080)return`${Math.round(m/1440)} gün önce aktifti`;return""}
const activeUsers=()=>humans().filter(isActive);
function seenText(uid){if(settings.showActive===false)return"";if(S.online.has(uid))return"Çevrimiçi";const t=(S.lastSeen||{})[uid];if(!t)return"Çevrimdışı";const a=ago(t);return"Son görülme "+(a==="şimdi"?"az önce":a+" önce")}
const msgPreview=m=>m?(m.text||(m.mus?"Şarkı: "+String(m.mus.t||""):m.gpoll?"Anket: "+String(m.gpoll.q||""):m.once?"Tek seferlik fotoğraf":m.post?"Bir paylaşım gönderdi":m.img?"Fotoğraf":m.video?"Video":m.audio?"Sesli mesaj":m.call?"Arama":m.game?"Satranç daveti":"")):"";
const noteOf=u=>{const n=S.profiles[u]&&S.profiles[u].note;return n&&n.text&&n.at>now()-24*H?n.text:""};
function saveHidden(){const h=S.hidden||{};return write(()=>DB.set(`data/users/${S.uid}/hidden`,{msgs:h.msgs||{},chats:h.chats||{}}),{quiet:true})}
function chatHead(key){const k=keyInfo(key);
 if(k.type==="meydan")return`<div class="chat-head"><span class="av" style="--s:40px"><img src="${MEYDAN_AV}" alt=""></span><div class="t"><div>Meydan</div><div>${S.online.size+1} kişi şu an burada · herkese açık</div></div></div>`;
 if(k.type==="group"){const c=S.chats[k.cid]||{};const on=(c.members||[]).filter(u=>u!==S.uid&&S.online.has(u)).length;return`<button class="chat-head" data-act="chatinfo"><span class="av" style="--s:40px"><img src="${esc(groupAv(c,k.cid))}" alt=""></span><div class="t"><div>${esc(c.name||"Grup")}</div><div>${(c.members||[]).length} kişi${on?` · ${on} çevrimiçi`:""}</div></div></button><button class="ib plain" data-act="groupmenu" aria-label="Grup seçenekleri">${I("more")}</button>`}
 const uid=k.uid;const p=P(uid);const typing=S.typing[uid]===cidFor(S.uid,uid);const st=p.ai?"Yapay zekâ rehberi · her zaman açık":BOT[uid]?"Bot · otomatik yanıt":typing?"yazıyor…":seenText(uid);
 return`<button class="chat-head" ${BOT[uid]?`data-prof="${esc(uid)}"`:`data-act="chatinfo"`}>${avatar(uid,40,{click:false})}<div class="t"><div>${esc(nickOf(cidFor(S.uid,uid),uid)||p.name)}${badge(uid)}</div><div class="${S.online.has(uid)||typing?"onl":""}">${esc(st)}</div></div></button>${!BOT[uid]&&S.mode==="cloud"?`<button class="ib" data-call="${esc(uid)}" data-v="0" aria-label="Sesli ara">${I("phone")}</button><button class="ib" data-call="${esc(uid)}" data-v="1" aria-label="Görüntülü ara">${I("video")}</button>`:!BOT[uid]&&S.online.has(uid)?`<button class="ib" data-nudge="${esc(uid)}" aria-label="Dürt">${I("hand")}</button>`:""}`}
function vChats(){const all=chatList();const list=all.filter(c=>c.key!=="u:bot:rota");const rota=all.find(c=>c.key==="u:bot:rota");const md=S.meydan;
 const onl=[...S.online].filter(u=>S.profiles[u]&&u!==S.uid);
 let h=isChild(S.uid)?"":`<button class="square" data-chat="meydan"><span class="ic">${I("globe")}</span><span style="min-width:0"><b>Meydan</b><small>${md&&md.last?esc(((md.last.from===S.uid?"Sen: ":P(md.last.from).username+": ")+md.last.text).slice(0,60)):"Bu sayfadaki herkesin ortak sohbeti"}</small></span><span class="live">${meydanUnread()?"YENİ":(onl.length+1)+" burada"}</span></button>`;
 const ppl=humans().filter(u=>S.online.has(u)||noteOf(u)).sort((a,b)=>((S.online.has(b)?1:0)-(S.online.has(a)?1:0))||((S.profiles[b]?.note?.at||0)-(S.profiles[a]?.note?.at||0)));
 const mine=noteOf(S.uid);
 h=(h||"")+`<div class="notes"><div class="nt"><button class="nb ${mine?"":"add"}" data-act="note">${mine?esc(mine):"Not ekle"}</button><button data-act="note" aria-label="Notun">${avatar(S.uid,62,{click:false,ring:false,online:false})}</button><span class="n">Notun</span></div>`+
  ppl.map(u=>{const n=noteOf(u);return`<div class="nt">${n?`<button class="nb" data-note="${esc(u)}">${esc(n)}</button>`:""}<button data-note="${esc(u)}" aria-label="${esc(P(u).username)}">${avatar(u,62,{click:false,ring:false})}</button><span class="n">${esc(P(u).username)}</span></div>`}).join("")+
  (ppl.length?"":`<div class="nt-empty">Arkadaşların uygulamayı açınca ya da not bırakınca burada görünür.</div>`)+`</div>`;
 h+=`<div class="quick"><button data-act="newchat">${I("chat")}Yeni mesaj</button><button data-act="newgroup">${I("users")}Grup kur</button><button data-act="invite">${I("link")}Davet et</button></div>`;
 h+=`<div class="box"><button class="row ${rota?.unread?"unread":""}" data-msg="bot:rota" data-crow="u:bot:rota">${avatar("bot:rota",50,{click:false})}<div class="t"><div><b>Rota</b>${badge("bot:rota")}</div><div class="s">${esc(rota?.last?.text||"Bir şey sor: uygulama, fotoğraf, kod, satranç…")}</div></div>${rota?.unread?'<i class="udot"></i>':""}</button></div>`;
 h+=`<h3 class="sec-h"><span>Sohbetler</span>${list.length?'<span class="muted" style="font:500 .75rem var(--f-body)">Silmek için basılı tut</span>':""}</h3>`;
 if(!list.length)h+=`<div class="empty" style="padding:20px 24px"><b>Henüz sohbet yok</b>Bir arkadaşına yaz, grup kur ya da Meydan'a uğra.</div>`;
 else h+=`<div class="box">${list.map(c=>{if(c.group)return`<button class="row ${c.unread?"unread":""}" data-chat="${esc(c.key)}" data-crow="${esc(c.key)}"><span class="av" style="--s:50px"><img src="${esc(groupAv(c,c.key.slice(2)))}" alt=""></span><div class="t"><div><b>${esc(c.name)}</b>${c.pinned?`<span class="pinic">${I("pin")}</span>`:""} <span class="muted" style="font-size:.78rem">${c.members.length} kişi</span></div><div class="s">${esc(c.last?((c.last.from===S.uid?"Sen":P(c.last.from).username)+": "+c.last.text):"")} · ${ago(c.at)}</div></div>${c.unread?'<i class="udot"></i>':""}</button>`;
  const p=P(c.other);const typing=S.typing[c.other]===cidFor(S.uid,c.other);const last=typing?"yazıyor…":(c.last?.from===S.uid?"Sen: ":"")+(c.last?.text||"");return`<button class="row ${c.unread?"unread":""}" data-chat="${esc(c.key)}" data-crow="${esc(c.key)}">${avatar(c.other,50,{click:false})}<div class="t"><div><b>${esc(p.name)}</b>${badge(c.other)}${c.pinned?`<span class="pinic">${I("pin")}</span>`:""}</div><div class="s">${esc(last)} · ${ago(c.at)}</div></div>${c.unread?'<i class="udot"></i>':""}</button>`}).join("")}</div>`;
 const bots=BOTS.filter(b=>!b.ai&&!S.botchats[b.key]?.msgs?.length);
 if(bots.length)h+=`<h3 class="sec-h"><span>Botlarla dene</span></h3><div class="hrow">${bots.map(b=>`<div class="pcard"><button data-msg="${esc(b.uid)}">${avatar(b.uid,52,{click:false,ring:false})}</button><div class="n"><b>${esc(b.username)}</b></div><button class="btn sm sec block" data-msg="${esc(b.uid)}">Yaz</button></div>`).join("")}</div>`;
 return h}
function renderMsgs(){const box=$("#msgs");if(!box||S.route.name!=="chat")return;const key=S.route.params.key;applyWp(box,key);const k=keyInfo(key);const atBottom=box._pin!==false&&box.scrollHeight-box.scrollTop-box.clientHeight<90;
 const hid=(S.hidden&&S.hidden.msgs)||{};const hc=((S.hidden&&S.hidden.chats)||{})[k.cid]||0;const msgs=currentMsgs().filter(m=>!(m.id&&hid[m.id])&&!(hc&&m.at<=hc));let h="";
 const fresh=S.midsKey!==key;if(fresh){S.knownMids=new Set();S.seenKeys=new Set();S.midsKey=key}
 if(k.type==="meydan")h+=`<div class="hero"><span class="av" style="--s:68px"><img src="${MEYDAN_AV}" alt=""></span><b>Meydan</b><span>Bu sayfaya erişimi olan herkesin ortak sohbeti. Mesajında <b>@rota</b> yazarsan yapay zekâ rehberi de katılır.</span></div>`;
 else if(k.type==="group"){const c=S.chats[k.cid]||{};h+=`<div class="hero"><span class="av" style="--s:68px"><img src="${esc(groupAv(c,k.cid))}" alt=""></span><b>${esc(c.name||"Grup")}</b><span>${esc((c.members||[]).map(u=>"@"+P(u).username).join(" · "))}</span></div>`}
 else{const uid=k.uid;const p=P(uid);h+=`<div class="hero">${avatar(uid,68,{click:false,ring:false})}<b>${esc(p.name)}</b><span>${p.ai?"Uygulamanın nasıl çalıştığını anlatır, açıklama yazar, kod sorularını yanıtlar, test bildirimi üretir."+(S.caps.sample?"":" (Şu an hazır yanıtlarla çalışıyor.)"):"@"+esc(p.username)+(BOT[uid]?" · bot, hazır yanıtlarla konuşur":" · "+esc(seenText(uid)))}</span></div>`}
 /* görüldü: okuyan kişinin küçük fotoğrafı, okuduğu son mesajın altında */
 const seenAt={};
 if(k.type==="dm"||k.type==="group"){const c=S.chats[k.cid]||{};const rd=c.reads||{};const others=k.type==="dm"?[k.uid]:(c.members||[]).filter(u=>u!==S.uid);
  for(const u of others){const t=rd[u]||0;if(!t||(c.noSeen||{})[u])continue;let idx=-1;
   if(k.type==="dm"){/* 6.0.1: görüldü, gördüğü son mesajımın altında durur; karşı taraf yazarken ya da yanıt verince de yeri değişmez */let lm=-1;for(let i=msgs.length-1;i>=0;i--)if(msgs[i].from===S.uid&&!msgs[i].sys&&msgs[i].at<=t){lm=i;break}if(lm<0)continue;idx=lm}
   else{for(let i=msgs.length-1;i>=0;i--)if(msgs[i].at<=t){idx=i;break}if(idx<0||msgs[idx].from===u)continue;let later=false;for(let i=idx+1;i<msgs.length;i++)if(msgs[i].from===u){later=true;break}if(later)continue}
   (seenAt[idx]=seenAt[idx]||[]).push([u,t])}}
 let lastAt=0;const multi=k.type==="group"||k.type==="meydan";
 msgs.forEach((m,idx)=>{if(m.sys){h+=`<div class="stamp sysn" data-k="${esc(m.id||String(m.at))}">${esc(m.text||"")}</div>`;lastAt=m.at;S.knownMids.add(m.id||String(m.at));return}const gap=m.at-lastAt;if(gap>30*60e3)h+=`<div class="stamp" data-k="t-${esc(m.id||String(m.at))}">${new Date(m.at).toLocaleString("tr-TR",{day:"numeric",month:"short",hour:"2-digit",minute:"2-digit"})}</div>`;const prev=msgs[idx-1];const showSender=multi&&m.from!==S.uid&&(!prev||prev.from!==m.from||gap>5*60e3);const nx=msgs[idx+1];const dmAv=k.type==="dm"&&m.from!==S.uid&&(!nx||nx.sys||nx.from!==m.from||nx.at-m.at>5*60e3);lastAt=m.at;
  const mine=m.from===S.uid;let body="";const isAI=m.from==="bot:rota";const mk=m.id||String(m.at);const isNew=!fresh&&!S.knownMids.has(mk);
  if(m.del)body="Bu mesaj silindi";else{if(m.fwd)body+=`<span class="fwd">${I("send")}İletildi</span>`;
   if(m.reply)body+=`<button class="quote" data-jump="${esc(m.reply.mid)}">${esc(P(m.reply.from).username)}: ${esc(m.reply.text||"")}</button>`;
   if(m.audio)body+=audHtml(m);
   if(m.call)body+=`<button class="callmsg" data-call="${esc(mine?(keyInfo(key).uid||""):m.from)}" data-v="${m.call.video?1:0}">${I(m.call.video?"video":"phone")}<span>${esc(callLabel(m.call,mine))}</span></button>`;
   if(m.post){const p0=postById(m.post);const p=p0&&canSee(p0)?p0:null;body+=p?`<button class="mp" data-open="${esc(p.id)}">${postThumb(p)?`<img src="${esc(postThumb(p))}" alt="">`:`<div class="note" style="margin:0;min-height:6rem;font-size:.85rem;border-radius:0;background:${p.kind==="poll"?"#0c7a63":NOTE_BG[p.bg||0]}">${esc(p.text||p.question||"")}</div>`}<span>@${esc(P(p.uid).username)}</span></button>`:"<i>Paylaşım kaldırılmış</i>"}
   if(m.game)body+=gameMsgHtml(m);
   if(m.once)body+=onceHtml(m);else if(m.img)body+=`<img class="att" src="${esc(m.img)}" alt="Fotoğraf" data-view="1">`;
   if(m.text)body+=isAI&&!mine?md(m.text):esc(m.text);
   if(m.edited)body+=`<span class="edl">düzenlendi</span>`;if(m.sch&&m.at>now())body+=`<span class="edl schl">${I("bell")}Zamanlandı · ${esc(schLabel(m.at))}</span>`}
  const hearts=Object.keys(msgReacts(m)).length;
  h+=`<div class="mrow ${mine?"me":""} ${hearts?"has-react":""} ${isNew?"nw":""}" data-k="${esc(mk)}">${multi&&!mine?(showSender?`<button class="avb" data-prof="${esc(m.from)}" aria-label="${esc(P(m.from).name)} profili">${avatar(m.from,32,{click:false,ring:false,online:false})}</button>`:'<span style="width:32px;flex:none"></span>'):k.type==="dm"&&!mine?(dmAv?`<button class="avb dmav" data-prof="${esc(m.from)}" aria-label="${esc(P(m.from).name)} profili">${avatar(m.from,28,{click:false,ring:false,online:false})}</button>`:'<span class="dmav-sp" style="width:28px;flex:none"></span>'):""}<div class="mcol">${showSender?`<button class="sender" data-prof="${esc(m.from)}">${esc(P(m.from).name||P(m.from).username)}${BOT[m.from]?badge(m.from):""} <span class="muted">@${esc(P(m.from).username)}</span></button>`:""}<div class="msg ${isAI&&!mine?"ai":""} ${m.del?"del":""}" ${m.id&&k.type!=="bot"?`data-mid="${esc(m.id)}" id="m-${esc(m.id)}"`:k.type==="bot"&&!m.del&&msgCopyText(m)?`data-bmc="${m.at}"`:""}>${body}${hearts?reactChip(m):""}</div></div></div>`;
  if(seenAt[idx])h+=`<div class="seenrow">${seenAt[idx].slice(0,8).map(([u,t])=>`<button class="seenav ${S.seenKeys&&!S.seenKeys.has(u+":"+(m.id||m.at))&&!fresh?"nw":""}" data-seen="${esc(u)}" data-t="${t}" aria-label="${esc(P(u).username)} gördü"><img src="${esc(P(u).avatar)}" alt=""></button>`).join("")}</div>`;
  if(seenAt[idx]){S.seenKeys=S.seenKeys||new Set();seenAt[idx].forEach(([u])=>S.seenKeys.add(u+":"+(m.id||m.at)))}
  S.knownMids.add(mk)});
 const typer=k.type==="dm"?(S.typing[k.uid]===k.cid?k.uid:null):(multi?Object.keys(S.typing).find(u=>S.typing[u]===k.cid):null);
 if((k.type==="bot"&&(S.botTyping===k.uid||S.tbTyping===k.uid))||typer||(multi&&S.botTyping==="bot:rota@"+key))h+=multi&&typer?`<div class="mrow">${avatar(typer,32,{click:false,ring:false,online:false})}<div class="typing" aria-label="${esc(P(typer).username)} yazıyor"><i></i><i></i><i></i></div></div>`:`<div class="typing" aria-label="yazıyor"><i></i><i></i><i></i></div>`;
 if(S.stream&&S.stream.key===key&&S.stream.text)h+=`<div class="mrow"><div class="mcol"><div class="msg ai">${md(S.stream.text)}</div></div></div>`;/* 5.1.1: boş "…" balonu yazıyor noktalarıyla çift görünüyordu */
 if(!msgs.length&&k.type!=="bot")h+=`<div class="empty" style="padding:10px"><span>İlk mesajı sen yaz.</span></div>`;
 box.innerHTML=h;if(atBottom||S.forceBottom){box.scrollTop=box.scrollHeight;box._pin=true;S.forceBottom=false}
 /* 4.4.1: klavye açılınca, yanıt çubuğu çıkınca ya da fotoğraf geç yüklenince en alttaysan altta kal */
 if(!box._wired){box._wired=1;box._pin=true;box.addEventListener("scroll",()=>{box._pin=box.scrollHeight-box.scrollTop-box.clientHeight<90},{passive:true});
  if(window.ResizeObserver)new ResizeObserver(()=>{if(box._pin)msgsPin(box)}).observe(box);box.addEventListener("load",()=>{if(box._pin)msgsPin(box)},true)}}

const meydanUnread=()=>{const m=S.meydan;return!!(m&&m.last&&m.last.from!==S.uid&&m.last.at>LS.get("kadraj_meydan_"+S.uid,0))};
const unreadCount=()=>chatList().filter(c=>c.unread).length+(meydanUnread()?1:0);

/* ============ Etkinlik ============ */
function activity(){const out=[];const mine=new Set(Object.values(S.posts).filter(p=>p.uid===S.uid).map(p=>p.id));
 for(const id of mine){const m=metaOf(id);for(const[u,at]of Object.entries(m.likes||{}))if(at&&u!==S.uid)out.push({t:"like",uid:u,at,pid:id});for(const[,c]of Object.entries(m.comments||{}))if(c&&c.uid!==S.uid)out.push({t:"comment",uid:c.uid,at:c.at,pid:id,text:c.text})}
 for(const p of Object.values(S.profiles)){const at=p.following?.[S.uid];if(at&&p.uid!==S.uid)out.push({t:"follow",uid:p.uid,at})}
 for(const[u,at]of Object.entries(S.profiles[S.uid]?.botFollowers||{}))if(at&&BOT[u])out.push({t:"follow",uid:u,at});
 /* 6.7: yeniden paylaşım, etiketleme, açılan zaman kapsülü */
 for(const p of Object.values(S.profiles)){if(!p||p.uid===S.uid||!p.rp||typeof p.rp!=="object")continue;for(const[id,at]of Object.entries(p.rp))if(at&&mine.has(id))out.push({t:"repost",uid:p.uid,at,pid:id})}
 for(const p of Object.values(S.posts))if(p&&p.uid!==S.uid&&S.profiles[p.uid]&&Array.isArray(p.tags)&&p.tags.includes(S.uid)&&!capLocked(p))out.push({t:"tag",uid:p.uid,at:p.at,pid:p.id});
 for(const id of mine){const p=S.posts[id];if(p&&p.cap&&p.cap<=now())out.push({t:"cap",uid:S.uid,at:p.cap,pid:id})}
 return out.sort((a,b)=>b.at-a.at)}
const newActivity=()=>{const seen=LS.get("kadraj_act_"+S.uid,0);return activity().filter(a=>a.at>seen).length};

function toast(text,uid,key){if(!text)return;const t=document.createElement("div");t.className="toast"+(key?" tap":"");t.innerHTML=(uid?avatar(uid,28,{ring:false,click:false,online:false}):"")+`<span>${esc(text)}</span>`+(key?I("next"):"");if(key)t.onclick=()=>{t.remove();openTarget(key)};$("#toasts").appendChild(t);setTimeout(()=>{t.style.transition="opacity .3s";t.style.opacity="0";setTimeout(()=>t.remove(),320)},3600)}

/* ============ Yönlendirme ============ */
function go(name,params={}){if(name==="edit")S.editDraft=null;S.stack.push(S.route);S.route={name,params};navPush();render(true)}
function back(){S.route=S.stack.pop()||{name:"feed",params:{}};render(true)}
function tab(name){S.stack=[];S.route={name,params:name==="profile"?{uid:S.uid}:{}};if(name==="profile")S.profTab="posts";navPush();render(true)}
let navDepth=0;
function navPush(){try{navDepth++;history.pushState({kd:navDepth},"")}catch{}}
function navInit(){try{history.replaceState({kd:0},"");history.pushState({kd:1},"");navDepth=1}catch{}}
addEventListener("popstate",e=>{
 if($$("#overlay .layer").length){closeTop();navPush();return}
 if(S.route.name==="chessgame"&&CH&&CH.view!=null){CH.view=null;chDraw();navPush();return}
 if(S.stack.length){back();navPush();return}
 if(S.route.name!=="feed"){tab("feed");return}
 /* kök (Akış): çıkmayı engelle, yerinde kal */
 navPush()});
/* Android uygulamasının geri tuşu (MainActivity): 1 = Kadraj içinde geri gitti, 0 = uygulamadan çık. */
window.kBack=()=>{try{if($$("#overlay .layer").length){closeTop();return 1}if(S.route.name==="chessgame"&&CH&&CH.view!=null){CH.view=null;chDraw();return 1}
 if(S.stack.length){back();return 1}if(S.authed&&S.route.name!=="feed"){tab("feed");return 1}}catch{}return 0};
let refreshQ=false;
function scheduleRefresh(){if(refreshQ)return;refreshQ=true;requestAnimationFrame(()=>{refreshQ=false;refresh()})}
function refresh(){if(!S.authed)return;renderDock();renderTop();const r=S.route.name;
 if(r==="chat"){renderMsgs();refreshLayers();return}
 if(r==="reels"){updateReelCounts();refreshLayers();return}
 if(r==="edit")return;
 if(r==="chessgame"){chUI();return}
 const a=document.activeElement;if(a&&$("#main").contains(a)&&/INPUT|TEXTAREA/.test(a.tagName)){S.dirty=true;return}
 render(false);refreshLayers()}
document.addEventListener("focusout",()=>{if(S.dirty){S.dirty=false;setTimeout(()=>{const a=document.activeElement;if(!(a&&/INPUT|TEXTAREA/.test(a.tagName)))scheduleRefresh()},60)}});

/* ============ Çizim ============ */
const main=()=>$("#main");
function render(full){const m=main();const st=m.scrollTop;const r=S.route;
 $("#top").hidden=!S.authed||r.name==="reels";$("#dock").hidden=!S.authed||r.name==="chat"||r.name==="reels"||r.name==="chessgame";
 if(activeReel)deactivateReel(activeReel);renderTop();renderDock();
 m.className="";let html="";
 if(S.authed&&!S.admin&&typeof bakimOn==="function"&&bakimOn()&&r.name!=="settings"){m.innerHTML=vBakim();return}
 switch(r.name){case"feed":html=vFeed();break;case"explore":html=vExplore();break;case"reels":m.className="snap";html=vReels();break;case"profile":html=vProfile(r.params.uid);break;case"post":html=vPost(r.params.id);break;case"activity":html=vActivity();break;case"chats":html=vChats();break;case"chat":m.className="chatmode";html=vChat(r.params.key);break;case"settings":html=vSettings();break;case"edit":html=vEdit();break;case"people":html=vPeople(r.params);break;case"invite":html=vInvite();break;case"chess":html=vChess();break;case"admin":html=vAdmin();break;case"chessgame":m.className="chessmode";html=vChessGame();break;default:html=vFeed()}
 m.innerHTML=html;m.scrollTop=full?0:st;if(full&&!["reels","chat","chessgame"].includes(r.name)){m.classList.add("enter");clearTimeout(m._et);m._et=setTimeout(()=>m.classList.remove("enter"),700)}afterRender()}
function renderTop(){if(!S.authed)return;const r=S.route.name;const t=$("#top");let h="";const backBtn=`<button class="ib plain" data-act="back" aria-label="Geri">${I("back")}</button>`;
 /* 5.7.3: üst çubukta satranç ve tema düğmesi yok (tema Ayarlar › Görünüm'de, satranç Keşfet'teki kartta) */
 if(r==="feed"){h=`<div class="brand">${VF}<span class="wordmark">kadraj</span></div>`}
 else if(r==="explore")h=`<h1>Keşfet</h1>`;
 else if(r==="chats")h=`<h1>Sohbet</h1><div class="acts"><button class="ib" data-act="games" aria-label="Oyunlar">${I("pad")}</button><button class="ib" data-act="invite" aria-label="Arkadaş davet et">${I("link")}</button><button class="ib" data-act="newgroup" aria-label="Grup kur">${I("users")}</button><button class="ib" data-act="newchat" aria-label="Yeni sohbet">${I("edit")}</button></div>`;
 else if(r==="profile"){const p=P(S.route.params.uid);const own=p.uid===S.uid;h=(S.stack.length?backBtn:"")+`<h1>${esc(p.username)}${badge(p.uid)}</h1>`+(own?`<div class="acts">${S.mode==="cloud"?`<button class="ib" data-act="posta" aria-label="Kadraj Posta">${I("mail")}${postaUnread()?'<i class="dot"></i>':""}</button>`:""}<button class="ib" data-go="settings" aria-label="Ayarlar">${I("gear")}</button></div>`:`<button class="ib" data-act="profmenu" data-uid="${esc(p.uid)}" aria-label="Diğer">${I("more")}</button>`)}
 else if(r==="post")h=backBtn+`<h1>Paylaşım</h1>`;
 else if(r==="activity")h=(S.stack.length?backBtn:"")+`<h1>Bildirimler</h1>`;
 else if(r==="chat"){const ck=S.route.params.key;let ty="";try{ty=keyInfo(ck).type}catch{}h=backBtn+chatHead(ck)+(ty==="dm"||ty==="group"?`<button class="ib" data-act="chatinfo" aria-label="Sohbet ayrıntıları">${I("info")}</button>`:`<button class="ib" data-act="wallpaper" aria-label="Sohbet teması">${I("palette")}</button>`)}
 else if(r==="settings")h=backBtn+`<h1>Ayarlar</h1>`;
 else if(r==="edit")h=backBtn+`<h1>Profili düzenle</h1>`;
 else if(r==="people")h=backBtn+`<h1>${esc(P(S.route.params.uid).username)}</h1>`;
 else if(r==="invite")h=backBtn+`<h1>Arkadaşlarını getir</h1>`;
 else if(r==="admin")h=backBtn+`<h1>Yönetici</h1>`;
 else if(r==="chess")h=(S.stack.length?backBtn:"")+`<h1>Satranç</h1>`;
 else if(r==="chessgame")h=backBtn+`<h1>${CH?(CH.mode==="bot"?"Rota · "+CLEVELS[CH.level].n:CH.mode==="local"?"İki kişilik oyun":"@"+esc(P(oppOf(CH.doc||{})).username)):"Satranç"}</h1>`;
 t.innerHTML=h}
function renderDock(){if(!S.authed)return;const r=S.route.name;const isCur=n=>r===n||(n==="profile"&&r==="profile"&&S.route.params.uid===S.uid)||(n==="chats"&&r==="chat");const curTab=["feed","explore","chats","activity","profile"].find(isCur)||"";const na=newActivity();const pop=S._dockCur!==curTab;S._dockCur=curTab;const cur=n=>isCur(n)?(pop?'class="pop" ':"")+'aria-current="page"':"";const u=unreadCount();
 $("#dock").innerHTML=`<nav aria-label="Ana menü"><button data-tab="feed" ${cur("feed")}>${I("home")}<span class="dl">Akış</span></button><button data-tab="explore" ${cur("explore")}>${I("search")}<span class="dl">Keşfet</span></button><button data-go="reels">${I("reels")}<span class="dl">Klaket</span></button><button data-act="create" aria-label="Oluştur"><span class="create">${I("add")}</span></button><button data-tab="chats" ${cur("chats")}>${I("chat")}<span class="dl">Sohbet</span>${u?`<span class="cnt-badge">${u}</span>`:""}</button><button data-tab="activity" ${cur("activity")}>${I("bell")}<span class="dl">Bildirim</span>${na?`<span class="cnt-badge">${na>99?"99+":na}</span>`:""}</button><button data-tab="profile" ${cur("profile")}><span class="me"><img src="${esc(me().avatar)}" alt="" style="width:100%;height:100%;object-fit:cover"></span><span class="dl">Ben</span></button></nav>`}

/* --- Akış --- */
function vFeed(){const fol=followingOf(S.uid);
 const withStories=[...new Set([...fol,...BOTS.map(b=>b.uid),...Object.keys(S.profiles)])].filter(u=>u!==S.uid&&storiesOf(u).length&&canSeeUser(u)&&!muS(u));
 const seen=seenStories();withStories.sort((a,b)=>(storiesOf(a).every(s=>seen[s.id])?1:0)-(storiesOf(b).every(s=>seen[s.id])?1:0));
 let h=`<div class="chips" role="group" aria-label="Akış filtresi">${[["all","Herkes"],["following","Takip ettiklerim"],["fav","Favoriler"]].map(([k,l])=>`<button class="chip" data-seg="${k}" aria-pressed="${S.feedSeg===k}">${l}</button>`).join("")}<button class="chip" data-go="reels">${I("reels")}Klaketler</button></div>`;
 h+=`<div class="stories"><div class="story"><span style="position:relative">${storiesOf(S.uid).length?avatar(S.uid,62):`<button class="av" style="--s:62px" data-act="addstory" aria-label="Hikâye ekle"><img src="${esc(me().avatar)}" alt=""></button>`}${S.guest?"":`<button class="plus" data-act="addstory" aria-label="Hikâye ekle">${I("add")}</button>`}</span><span class="n muted">Hikâyen</span></div>`+
  withStories.map(u=>`<div class="story">${avatar(u,62,{online:false})}<span class="n">${esc(P(u).username)}</span></div>`).join("")+`</div>`;
 h+=childBanner();if(S.guest)h+=`<div class="banner">${I("info")}<span>Misafir olarak geziniyorsun. Paylaşım ve mesaj için uygulamanın sahibi seni bu sayfaya <b>Düzenleyen</b> olarak davet etmeli.</span></div>`;
 else if(!Object.values(S.posts).some(p=>p.uid===S.uid))h+=`<div class="banner">${I("spark")}<span>İlk paylaşımını yap: alttaki <b>+</b> düğmesine dokun. Telefondan fotoğraf seçemezsen Kadraj galerisinden seç, çizim yap ya da bir not yaz.</span></div>`;
 const an=S.adm&&S.adm.duyuru;if(an&&an.text&&an.at>LS.get("kadraj_ann_seen",0))h=h.replace('<div class="stories">',`<div class="banner ann">${I("bell")}<span><b>Yönetici duyurusu</b><br>${esc(an.text)}</span><button class="ib plain" data-act="annhide" aria-label="Duyuruyu kapat">${I("close")}</button></div><div class="stories">`);
 if(!isStandalone()&&!LS.get("kadraj_inst_hide")&&!LS.get("kadraj_installed"))h=h.replace('<div class="stories">',`<div class="banner inst">${I("home")}<span><b>Kadraj'ı ana ekranına ekle</b><br>Uygulama gibi tam ekran açılır.</span><button class="btn sm" data-act="install">Ekle</button><button class="ib plain" data-act="insthide" aria-label="Kapat">${I("close")}</button></div><div class="stories">`);
 let posts=allPosts().filter(p=>canSee(p)&&(p.uid===S.uid||!muP(p.uid)));if(S.feedSeg==="following")posts=posts.filter(p=>p.uid===S.uid||fol.includes(p.uid));if(S.feedSeg==="fav"){const fv=favsOf(S.uid);posts=posts.filter(p=>fv[p.uid])}
 const items=feedItems(posts,fol);const pin=pinnedId();if(pin){const i=items.findIndex(x=>x.p.id===pin&&!x.by);if(i>0){const[x]=items.splice(i,1);items.unshift(x)}}
 const sugg=[...humans(),...BOTS.map(b=>b.uid)].filter(u=>!isFollowing(S.uid,u));
 items.forEach(({p,by},i)=>{if(p.id===pin&&!by)h+=`<div class="pinlbl">${I("spark")}Öne çıkan paylaşım</div>`;h+=postCard(p,{by});if(i===1&&sugg.length&&fol.length<6&&S.feedSeg!=="fav")h+=suggBlock(sugg)});
 if(!items.length)h+=S.feedSeg==="fav"?`<div class="empty"><span class="ic">${I("star")}</span><b>${favCount()?"Favorilerinden yeni paylaşım yok":"Favorilerin boş"}</b>${favCount()?"Favorilerine eklediğin kişiler paylaşınca burada görünür.":"Sevdiğin hesapları Favorilere ekle; burada yalnızca onların paylaşımları görünsün."}<button class="btn sm" data-act="favlist">Favorileri düzenle</button></div>`:`<div class="empty"><span class="ic">${I("users")}</span><b>Burası henüz sessiz</b>Takip ettiğin kimsenin paylaşımı yok. “Herkes” sekmesine geç ya da birkaç hesap takip et.</div>`;
 else h+=`<div class="empty" style="padding:24px">${I("check")}<span>Hepsi bu kadar. Yeni paylaşımlar buraya düşecek.</span></div>`;
 return h}
function suggBlock(list){return`<section class="sugg"><h3 class="sec-h"><span>Tanışmak isteyebileceklerin</span><button class="btn ghost sm" data-tab="explore">Tümü</button></h3><div class="hrow">${list.slice(0,10).map(u=>{const p=P(u);return`<div class="pcard"><button data-prof="${esc(u)}">${avatar(u,64,{click:false})}</button><div class="n"><b>${esc(p.username)}</b></div><div class="n muted">${BOT[u]?(BOT[u].ai?"Yapay zekâ rehberi":"Test hesabı"):S.online.has(u)?"Şu an çevrimiçi":"Kadraj'da"}</div><button class="btn sm block" data-follow="${esc(u)}">Takip et</button></div>`}).join("")}</div></section>`}
function mediaHtml(p){
 if(p.kind==="note")return`<div class="note" style="background:${NOTE_BG[p.bg||0]}" data-dbl="${esc(p.id)}">${esc(p.text)}</div>`;
 if(p.kind==="poll")return pollHtml(p);
 if(p.kind==="reel"){const th=postThumb(p);return`<button class="media" style="--ar:4/5;display:block;width:100%" data-reel="${esc(p.id)}" aria-label="Klaketi izle">${th?`<img src="${esc(th)}" alt="" loading="lazy" decoding="async">`:""}<span class="badge-k">${I("reels")}Klaket${p.music&&p.music!=="none"?" · müzikli":""}</span><span class="playbig"><span>${I("play")}</span></span></button>`}
 {const im=phList(p);if(im.length>1)return phCarousel(p,im)}
 return`<div class="media" style="--ar:${esc(p.ar||"1/1")}" data-dbl="${esc(p.id)}"><img src="${esc(R(p.src||p.img))}" alt="${esc((p.caption||"").slice(0,80))}" loading="lazy" decoding="async" ${p.css?`style="filter:${esc(p.css)}"`:""}></div>`}
function pollHtml(p){const votes=votesOf(p);const tot=votes.reduce((a,b)=>a+b,0);const mv=myVote(p.id);const shown=mv!=null||p.uid===S.uid;
 return`<div class="poll"><div class="q">${esc(p.question)}</div>${p.options.map((o,i)=>{const pc=tot?Math.round(votes[i]/tot*100):0;return`<button class="popt ${mv===i?"mine":""}" data-vote="${esc(p.id)}" data-i="${i}">${shown?`<i class="bar" style="width:${pc}%"></i>`:""}<span>${esc(o)}</span>${shown?`<span class="pc">%${pc}</span>`:""}${mv===i?`<span>${I("check")}</span>`:""}</button>`}).join("")}<div class="tot">${fmt(tot)} oy${mv==null&&p.uid!==S.uid?" · oy verince sonuçları görürsün":""}</div></div>`}
function postCard(p,{full=false,by=null}={}){if(capLocked(p))return capCard(p);const u=P(p.uid);const followed=p.uid===S.uid||isFollowing(S.uid,p.uid);const liked=iLike(p.id);const cs=commentsOf(p);const kindLbl={note:"not",poll:"anket",reel:"Klaket"}[p.kind]||"";
 return`<article class="card" data-pid="${esc(p.id)}">${by?rpBy(by):""}<div class="card-h">${avatar(p.uid,40)}<div class="who"><div><button data-prof="${esc(p.uid)}"><span class="uname">${esc(u.name)}</span></button>${badge(p.uid)}${followed?"":` · <button class="follow-link" data-follow="${esc(p.uid)}">Takip et</button>`}</div><div class="sub">@${esc(u.username)} · ${ago(p.at)}${p.loc?" · "+esc(p.loc):""}${kindLbl?" · "+kindLbl:""}</div></div><button class="ib plain" data-act="postmenu" data-id="${esc(p.id)}" aria-label="Seçenekler">${I("more")}</button></div>
 ${mediaHtml(p)}
 <div class="pills"><button class="pill ${liked?"liked":""}" data-like="${esc(p.id)}" aria-pressed="${liked}" aria-label="Beğen">${I("heart")}<span>${settings.hideLikes&&p.uid!==S.uid?"":short(likeCount(p))}</span></button><button class="pill" data-comments="${esc(p.id)}" aria-label="Yorumlar">${I("comment")}${cs.length}</button><button class="pill" data-share="${esc(p.id)}" aria-label="Arkadaşına gönder">${I("send")}</button>${p.uid!==S.uid&&!S.guest&&!p.bot&&!BOT[p.uid]?`<button class="pill ${iRp(p.id)?"rpon":""}" data-rp="${esc(p.id)}" aria-pressed="${iRp(p.id)}" aria-label="Yeniden paylaş">${I("repost")}</button>`:""}<span class="sp"></span><button class="pill ${isSaved(p.id)?"saved":""}" data-save="${esc(p.id)}" aria-label="Kaydet">${I("bookmark")}</button></div>
 <div class="card-b">${capLbl(p)}${tagLine(p)}${p.caption?`<div class="cap"><button class="uname" data-prof="${esc(p.uid)}">${esc(u.username)}</button> ${richText(p.caption)}</div>`:""}
 ${(full?cs:cs.slice(-1)).map(c=>`<div class="cap"><button class="uname" data-prof="${esc(c.uid)}">${esc(P(c.uid).username)}</button> ${richText(c.text)}</div>`).join("")}
 ${!full&&cs.length>1?`<button class="more" data-comments="${esc(p.id)}">${cs.length} yorumun hepsini gör</button>`:""}
 ${p.exif?`<div class="meta-line mono">${esc(p.exif)}</div>`:""}</div></article>`}

/* --- Keşfet --- */
function vExplore(){const q=(S.q||"").trim().toLocaleLowerCase("tr");
 let h=`<div class="search"><input class="in" id="q" type="search" placeholder="Kişi ya da #etiket ara" value="${esc(S.q||"")}" autocomplete="off" aria-label="Ara"></div>`;
 if(q){const people=[...BOTS.map(b=>b.uid),...Object.keys(S.profiles)].filter(u=>{const p=P(u);return(p.username+" "+p.name).toLocaleLowerCase("tr").includes(q.replace(/^@/,""))});
  const tagPosts=q.startsWith("#")?allPosts().filter(p=>canSee(p)&&((p.caption||"")+" "+(p.text||"")).toLocaleLowerCase("tr").includes(q)):[];
  if(people.length)h+=`<div class="box">${people.map(u=>personRow(u)).join("")}</div>`;
  if(tagPosts.length)h+=`<h3 class="sec-h">${esc(q)}</h3>`+grid(tagPosts);
  if(!people.length&&!tagPosts.length)h+=`<div class="empty"><b>Sonuç yok</b>“${esc(q)}” için bir şey bulamadık. Kullanıcı adının bir kısmını dene.</div>`;
  return h}
 const ppl=[...humans(),...BOTS.map(b=>b.uid)];const mt=myTurnGames();
 h+=okulHtml();
 h+=`<h3 class="sec-h"><span>Kişiler</span></h3><div class="hrow" style="margin-bottom:16px">${ppl.map(u=>{const p=P(u);return`<div class="pcard"><button data-prof="${esc(u)}">${avatar(u,56,{click:false})}</button><div class="n"><b>${esc(p.username)}</b></div>${u===S.uid||S.guest?"":`<button class="btn sm block ${isFollowing(S.uid,u)?"sec":""}" data-follow="${esc(u)}">${isFollowing(S.uid,u)?"Takiptesin":"Takip et"}</button>`}</div>`}).join("")}</div>`;
 const ps=allPosts().filter(canSee).sort((a,b)=>hash32(a.id,9).localeCompare(hash32(b.id,9)));
 return h+`<h3 class="sec-h"><span>Keşfedilecekler</span></h3>`+grid(ps)}
function personRow(u){const p=P(u);return`<div class="row"><button data-prof="${esc(u)}">${avatar(u,48,{click:false})}</button><button class="t" data-prof="${esc(u)}"><div><b>${esc(p.name)}</b>${badge(u)}</div><div class="s">@${esc(p.username)}${S.online.has(u)?" · çevrimiçi":""}</div></button>${u!==S.uid&&!S.guest?`<button class="btn sm ${isFollowing(S.uid,u)?"sec":""}" data-follow="${esc(u)}">${isFollowing(S.uid,u)?"Takiptesin":"Takip et"}</button>`:""}</div>`}
function tileInner(p){if(p.kind==="note")return`<span class="tx" style="background:${NOTE_BG[p.bg||0]}">${esc((p.text||"").slice(0,70))}</span>`;if(p.kind==="poll")return`<span class="tx" style="background:#0c7a63">${esc(p.question.slice(0,60))}</span><span class="k">${I("poll")}</span>`;const th=postThumb(p);return(th?`<img src="${esc(th)}" alt="" loading="lazy" decoding="async" ${p.css?`style="filter:${esc(p.css)}"`:""}>`:`<span class="tx" style="background:#111">${I("play")}</span>`)+(p.kind==="reel"?`<span class="k">${I("reels")}</span>`:p.kind==="photo"&&phList(p).length>1?`<span class="k" aria-label="Çoklu fotoğraf">${I("stack")}</span>`:"")}
const pinsOf=uid=>((S.profiles[uid]||{}).pins||[]).filter(id=>{const p=postById(id);return p&&p.uid===uid}).slice(0,3);
function withPins(list,uid){const pins=pinsOf(uid);if(!pins.length)return list;const top=pins.map(id=>list.find(p=>p.id===id)).filter(Boolean);return[...top,...list.filter(p=>!pins.includes(p.id))]}
async function togglePin(id){if(!guard())return;const cur=pinsOf(S.uid);const on=cur.includes(id);if(!on&&cur.length>=3)return toast("En fazla 3 paylaşım sabitleyebilirsin. Önce birini kaldır.");
 const pins=on?cur.filter(x=>x!==id):[id,...cur];S.profiles={...S.profiles,[S.uid]:{...S.profiles[S.uid],pins}};render(false);
 if(await write(()=>DB.update("profiles/"+S.uid,{pins})))toast(on?"Sabitleme kaldırıldı":"Profilinde en üste sabitlendi")}
function grid(posts,pins){if(!posts.length)return"";return`<div class="grid">${posts.map(p=>`<button class="tile" data-open="${esc(p.id)}" aria-label="Paylaşımı aç">${tileInner(p)}${pins&&pins.includes(p.id)?`<span class="pn" aria-label="Sabitlendi">${I("pin")}</span>`:""}${settings.hideLikes&&p.uid!==S.uid?"":`<span class="c">${I("heart")}${short(likeCount(p))}</span>`}</button>`).join("")}</div>`}

/* --- Reels --- */
function reelList(){return allPosts().filter(p=>p.kind==="reel"&&canSee(p))}
function slidesHtml(p){if(p&&p.kvy)return kyHtml(p);return(p.slides||[]).map((s,i)=>`<img class="slide ${i===0?"on":""}" src="${esc(R(s))}" alt="">`).join("")+(p.text?`<div class="rtext">${esc(p.text)}</div>`:"")}
function vReels(){const list=reelList();const top=`<div class="reel-top"><div><button class="ib" data-act="back" aria-label="Geri">${I("back")}</button><b>Klaketler</b><button class="ib" data-act="mute" aria-label="Sesi aç/kapat">${I(S.muted?"mute":"vol")}</button><button class="rnew" data-act="newreel" aria-label="Video ekle">${I("film")}<span>Video ekle</span></button></div></div>`;
 if(!list.length)return top+`<div class="empty" style="color:#fff;height:100%;align-content:center"><b style="color:#fff">Henüz Klaket yok</b>İlk Klaketi sen oluştur.</div>`;
 return top+list.map((p,i)=>{const u=P(p.uid);const liked=iLike(p.id);const fol=p.uid===S.uid||isFollowing(S.uid,p.uid);
 const sg=rsOk(p),mus=sg||(p.music&&p.music!=="none");const media=p.video?`<div class="rblur"${p.poster?` data-p="${esc(R(p.poster))}"`:""}></div><video src="${esc(vsrc(p))}"${vref(p)}${p.dur?` data-dur="${+p.dur||0}"`:""} poster="${esc(R(p.poster||""))}" loop playsinline ${S.muted||mus?"muted":""} preload="${settings.dataSaver?(i<1?"metadata":"none"):i<1?"auto":i<3?"metadata":"none"}" disablepictureinpicture data-rv ${mus?'data-mus="1"':""}></video><div class="rprog"><i></i></div><span class="rpause">${I("play")}</span><button class="rhint" hidden>${I("vol")}Sesi açmak için dokun</button>`:`<div class="fx-${esc(p.fx||"zoom")}" style="position:absolute;inset:0">${slidesHtml(p)}</div>`;
 return`<section class="reel" data-pid="${esc(p.id)}">${media}<div class="shade"></div>
 <div class="side"><button class="${liked?"liked":""}" data-like="${esc(p.id)}" aria-label="Beğen"><span>${I("heart")}</span><span data-likecount-r="${esc(p.id)}">${settings.hideLikes&&p.uid!==S.uid?"Beğen":short(likeCount(p))}</span></button><button data-comments="${esc(p.id)}" aria-label="Yorumlar"><span>${I("comment")}</span><span>${commentsOf(p).length}</span></button><button data-share="${esc(p.id)}" aria-label="Gönder"><span>${I("send")}</span><span>Gönder</span></button><button data-save="${esc(p.id)}" class="${isSaved(p.id)?"saved":""}" aria-label="Kaydet"><span>${I("bookmark")}</span><span>Kaydet</span></button><button data-act="postmenu" data-id="${esc(p.id)}" aria-label="Seçenekler"><span>${I("more")}</span></button></div>
 <div class="info"><div class="u"><button data-prof="${esc(p.uid)}" style="display:flex;align-items:center;gap:10px">${avatar(p.uid,34,{click:false,ring:false,online:false})}<span>${esc(u.username)}</span></button>${fol?"":`<button class="fbtn" data-follow="${esc(p.uid)}">Takip et</button>`}</div><div class="c">${richText(p.caption||"")}</div>${sg?`<div class="rsg">${I("music")}<span>${esc(p.song.t)}</span></div>`:""}<div class="aud">${I("music")}<span>${mus?esc(MUSIC_NAMES[p.music]||"Müzik")+" · Kadraj Ses":esc(u.username)+" · Orijinal ses"}</span></div></div></section>`}).join("")}
function updateReelCountsOld(){for(const el of $$("[data-likecount-r]")){const p=postById(el.dataset.likecountR);if(p)el.textContent=settings.hideLikes&&p.uid!==S.uid?"Beğen":short(likeCount(p))}for(const b of $$(".reel [data-like]"))b.classList.toggle("liked",iLike(b.dataset.like))}

/* --- Profil --- */
function vProfile(uid){const p=P(uid);const own=uid===S.uid;const posts=postsOf(uid);const locked=!own&&S.profiles[uid]?.private&&!isFollowing(S.uid,uid);
 let h=`<div class="prof"><div class="prof-top">${avatar(uid,84)}<div class="stats"><div><b>${fmt(posts.length)}</b><span>paylaşım</span></div><button data-people="followers" data-uid="${esc(uid)}"><b>${short(followerCount(uid))}</b><span>takipçi</span></button><button data-people="following" data-uid="${esc(uid)}"><b>${fmt(followingOf(uid).length)}</b><span>takip</span></button></div></div>
 <div><b style="font:600 1.05rem/1.3 var(--f-display)">${esc(p.name)}</b>${!own&&!BOT[uid]&&!p.missing?` <span class="tag ${S.online.has(uid)?"":"off"}">${esc(seenText(uid))}</span>`:""}${p.private?` <span class="tag">${I("lock")}gizli</span>`:""}${p.chess&&p.chess.g?` <span class="tag">${I("knight")}${p.chess.r}</span>`:""}</div>${noteOf(uid)?`<div class="pnote">${I("chat")}<span>${esc(noteOf(uid))}</span></div>`:""}${p.bio?`<div class="bio">${richText(p.bio)}</div>`:""}
 <div class="btns">${own?`<button class="btn sec" data-go="edit">${I("edit")}Düzenle</button><button class="btn sec" data-act="invite">${I("users")}Davet et</button>`:S.guest?"":`<button class="btn ${isFollowing(S.uid,uid)?"sec":""}" data-follow="${esc(uid)}">${isFollowing(S.uid,uid)?"Takiptesin":isFollowing(uid,S.uid)?"Sen de takip et":"Takip et"}</button><button class="btn sec" data-msg="${esc(uid)}">${I("chat")}Mesaj</button>${BOT[uid]?`<button class="btn sec" data-go="chess" aria-label="Satranç oyna" style="flex:0 0 auto">${I("knight")}</button>`:`<button class="btn sec" data-chinv="${esc(uid)}" aria-label="Satranca davet et" style="flex:0 0 auto">${I("knight")}</button>`}`}</div></div>`;
 if(locked)return h+`<div class="empty"><span class="ic">${I("lock")}</span><b>Bu hesap gizli</b>Paylaşımlarını görmek için takip et.</div>`;
 const rps=Object.entries(rpOf(uid)).filter(([,at])=>at).sort((a,b)=>b[1]-a[1]).map(([id])=>postById(id)).filter(x=>x&&x.uid!==uid&&canSee(x)&&!capLocked(x));const tgd=allPosts().filter(x=>x.uid!==uid&&tagsOf(x).includes(uid)&&canSee(x)&&!capLocked(x));
 const tabs=[["posts","Paylaşımlar","grid"],["reels","Klaketler","reels"],...(rps.length?[["rp","Yeniden","repost"]]:[]),...(tgd.length?[["tag","Etiketler","users"]]:[]),...(own?[["saved","Kaydedilenler","bookmark"]]:[])];
 if(!tabs.some(t=>t[0]===S.profTab))S.profTab="posts";
 h+=`<div class="ptabs${tabs.length>3?" many":""}" role="tablist">${tabs.map(([k,l,ic])=>`<button class="chip" role="tab" aria-pressed="${S.profTab===k}" aria-label="${l}" data-ptab="${k}">${I(ic)}<span class="pl">${l}</span></button>`).join("")}</div>`;
 if(S.profTab==="saved")h+=kolChips();const kp=S.profTab==="saved"?kolPosts():null;
 const list=S.profTab==="posts"?posts.filter(x=>x.kind!=="reel"):S.profTab==="reels"?posts.filter(x=>x.kind==="reel"):S.profTab==="rp"?rps:S.profTab==="tag"?tgd:kp||Object.entries(S.saved).filter(([,v])=>v).map(([id])=>postById(id)).filter(Boolean).filter(canSee);
 if(!list.length)h+=`<div class="empty"><span class="ic">${I(S.profTab==="saved"?"bookmark":S.profTab==="reels"?"reels":"image")}</span><b>${S.profTab==="saved"?(kp?"Bu koleksiyon boş":"Kaydedilen yok"):own?"İlk paylaşımını yap":"Henüz paylaşım yok"}</b>${S.profTab==="saved"?(kp?"Paylaşımın ⋯ menüsünden Koleksiyona kaydet'e dokun.":"Paylaşımlardaki yer imi düğmesiyle kaydet."):own?`<button class="btn sm" data-act="${S.profTab==="reels"?"newreel":"create"}">${S.profTab==="reels"?"Klaket oluştur":"Paylaşım oluştur"}</button>`:""}</div>`;
 else h+=S.profTab==="saved"||S.profTab==="rp"||S.profTab==="tag"?grid(list):grid(withPins(list,uid),pinsOf(uid));
 return h}
function vPeople({uid,type}){const list=type==="followers"?followersOf(uid):followingOf(uid);
 return`<div class="ptabs"><button class="chip" aria-pressed="${type==="followers"}" data-swap="followers">${short(followerCount(uid))} takipçi</button><button class="chip" aria-pressed="${type==="following"}" data-swap="following">${fmt(followingOf(uid).length)} takip</button></div>`+(list.length?`<div class="box">${list.map(u=>personRow(u)).join("")}</div>`:`<div class="empty"><b>Liste boş</b>${type==="followers"&&BOT[uid]?"Bu sayıya test için temsili takipçiler dahil.":"Henüz kimse yok."}</div>`)}
function vPost(id){const p=postById(id);if(!p)return`<div class="empty"><b>Paylaşım bulunamadı</b>Silinmiş olabilir.</div>`;if(!canSee(p))return`<div class="empty"><span class="ic">${I("lock")}</span><b>Bu hesap gizli</b>Paylaşımlarını görmek için takip et.<button class="btn sm" data-prof="${esc(p.uid)}">Profile git</button></div>`;return postCard(p,{full:true})}

/* --- Bildirimler --- */
function vActivity(){const list=activity();const seen=LS.get("kadraj_act_"+S.uid,0);LS.set("kadraj_act_"+S.uid,now());
 if(!list.length)return`<div class="empty"><span class="ic">${I("bell")}</span><b>Henüz bildirim yok</b>Biri paylaşımını beğendiğinde, yorum yaptığında ya da seni takip ettiğinde burada görünür.<button class="btn sm" data-msg="bot:rota">Rota ile test bildirimi oluştur</button></div>`;
 /* 6.0: satırda bildirim türü rozeti (kalp, yorum, takip), yorum metni ayrı satırda */
 const KIND={like:["heart","paylaşımını beğendi."],comment:["comment","yorum yaptı."],follow:["users","seni takip etmeye başladı."],repost:["repost","paylaşımını yeniden paylaştı."],tag:["users","seni bir paylaşımda etiketledi."],cap:["capsule","· zaman kapsülün bugün açıldı."]};
 const row=a=>{const p=P(a.uid);const post=a.pid&&postById(a.pid);const[ic,txt]=KIND[a.t]||KIND.like;const th=post&&postThumb(post);
  return`<div class="row act-row" data-t="${esc(a.t)}"><span class="act-av">${avatar(a.uid,44)}<i class="act-ic" aria-hidden="true">${I(ic)}</i></span><div class="t" style="white-space:normal"><button data-prof="${esc(a.uid)}"><b>${esc(p.username)}</b></button> ${esc(txt)} <span class="muted">${ago(a.at)}</span>${a.t==="comment"&&a.text?`<span class="act-q">${esc(a.text)}</span>`:""}</div>${post?`<button class="act-th" data-open="${esc(post.id)}" aria-label="Paylaşımı aç">${th?`<img src="${esc(th)}" alt="">`:I(post.kind==="poll"?"poll":"type")}</button>`:a.t==="follow"&&!isFollowing(S.uid,a.uid)?`<button class="btn sm" data-follow="${esc(a.uid)}">Takip et</button>`:""}</div>`};
 const nw=list.filter(a=>a.at>seen),old=list.filter(a=>a.at<=seen);
 return(nw.length?`<h3 class="sec-h">Yeni</h3><div class="box">${nw.map(row).join("")}</div>`:"")+(old.length?`<h3 class="sec-h">Daha önce</h3><div class="box">${old.map(row).join("")}</div>`:"")}

