/* --- Sohbet --- */
/* sohbet duvar kağıdı (3.9): yalnızca bu cihazda; settings.wp[key] ya da settings.wp["*"]. 4.0: ortak sohbet temaları, yeni applyWp ve wallpaperMenu B bloğunda; eskileri ...Old */
const WP_HEART="data:image/svg+xml,"+encodeURIComponent(`<svg xmlns="http://www.w3.org/2000/svg" width="56" height="56" viewBox="0 0 56 56"><g fill="#ff3b5c" fill-opacity=".16"><path transform="translate(4 4) scale(.75)" d="${IP.heart.match(/d="([^"]+)"/)[1]}"/><path transform="translate(32 30) scale(.6)" d="${IP.heart.match(/d="([^"]+)"/)[1]}"/></g></svg>`);
const wpLsKey=key=>"kadraj_wp_"+String(key).replace(/[^\w:-]/g,"_");
function vChat(key){const k=keyInfo(key);const isRota=k.type==="bot"&&k.bot.ai;
 const chips=isRota?["Satranç oynayalım","Kadraj'ı nasıl kullanırım?","Arkadaşlarımla nasıl konuşurum?","Test bildirimleri oluştur","Fotoğraf yüklenmiyor","JavaScript'te debounce yaz"]:k.type==="bot"?["Merhaba!","Bugün ne paylaştın?","Bana bir öneri ver"]:[];/* 5.1: insan sohbetlerinde hazır mesaj çipleri kaldırıldı (eskiden Meydan "Selam herkese!", grup "Selam ekip!", birebir "Selam!/Nasılsın?") */
 if(S.replyKey!==key){S.replyTo=null;S.replyKey=key}
 return`<div class="msgs" id="msgs"></div><div class="cchips">${chips.map(c=>`<button data-chip="${esc(c)}">${esc(c)}</button>`).join("")}</div><div id="replyBar"></div><form class="composer" id="composer"><button type="button" class="ib cplus" data-act="plus" aria-label="Ekle" ${k.type==="bot"?"hidden":""}>${I("add")}</button><textarea id="msgIn" rows="1" placeholder="${isRota?"Rota'ya bir şey sor…":k.type==="meydan"?"Meydan'a yaz…":"Mesaj yaz…"}" aria-label="Mesaj"></textarea><button class="send" type="submit" id="sendBtn" aria-label="${k.type==="bot"?"Gönder":"Sesli mesaj kaydet"}">${I(k.type==="bot"?"send":"mic")}</button></form>`}
/* 6.8.8: mesajın kopyalanacak metni (Rota'nın biçim işaretleri ve "(Yapay zekâ …)" notu olmadan; anket ve şarkı da) */
function msgCopyText(m){if(!m||m.del||m.once)return"";let t=String(m.text||"");
 if(t&&/^bot:|^rota$/.test(String(m.from))||BOT[m.from])t=t.replace(/^\(Yapay zekâ [^)]*\)\s*/,"").replace(/^```[^\n]*$/gm,"").replace(/\*\*|__/g,"").replace(/^#{1,6}\s+/gm,"").replace(/\n{3,}/g,"\n\n").trim();
 if(!t&&m.gpoll&&m.gpoll.q)t=[m.gpoll.q,...(m.gpoll.o||[]).map((o,i)=>(i+1)+". "+o)].join("\n");
 if(!t&&m.mus&&m.mus.t)t=String(m.mus.t);return t}
/* bot sohbetlerinde (Rota, Test botu) mesajların kimliği yok: basılı tut / sağ tık yalnızca kopyalama penceresi açar */
function bmcMenu(at){const m=currentMsgs().find(x=>String(x.at)===String(at));const t=msgCopyText(m);if(!t)return;vib(20);
 const l=sheet("menu","",`<button class="opt" id="bmcC">${I("copy")}Metni kopyala</button>`);$("#bmcC",l).onclick=()=>{closeLayer("menu");copyText(t,"Mesaj kopyalandı")}}
document.addEventListener("pointerdown",e=>{const b=e.target.closest&&e.target.closest(".msg[data-bmc]");if(!b||e.button>0)return;clearTimeout(lpT);lpXY=[e.clientX,e.clientY];lpT=setTimeout(()=>{if(!$('#overlay [data-layer="menu"]'))bmcMenu(b.dataset.bmc)},500)});
document.addEventListener("contextmenu",e=>{const b=e.target.closest&&e.target.closest(".msg[data-bmc]");if(!b)return;e.preventDefault();clearTimeout(lpT);if(!$('#overlay [data-layer="menu"]'))bmcMenu(b.dataset.bmc)});
function copyOld(s){const t=document.createElement("textarea");t.value=s;t.setAttribute("readonly","");t.style.cssText="position:fixed;top:0;left:0;opacity:0;pointer-events:none";document.body.appendChild(t);let ok=false;try{t.select();t.setSelectionRange(0,s.length);ok=document.execCommand("copy")}catch{}t.remove();return ok}
function currentMsgs(){const k=keyInfo(S.route.params.key);if(k.type==="bot")return S.botchats[k.bot.key]?.msgs||[];return S.msgs}
function md(t){let s=esc(t);const blocks=[];s=s.replace(/```(\w*)\n?([\s\S]*?)```/g,(_,l,c)=>{blocks.push(`<pre><code>${c.replace(/\n$/,"")}</code></pre>`);return`\u0000${blocks.length-1}\u0000`});
 s=s.replace(/`([^`\n]+)`/g,"<code>$1</code>").replace(/\*\*([^*\n]+)\*\*/g,"<b>$1</b>");
 s=s.split(/\n{2,}/).map(par=>{const out=[];let list=null,txt=[];const flushT=()=>{if(txt.length){out.push("<p>"+txt.join("<br>")+"</p>");txt=[]}};const flushL=()=>{if(list){out.push("<ul>"+list.map(x=>"<li>"+x+"</li>").join("")+"</ul>");list=null}};
  for(const l of par.split("\n")){const m=l.match(/^\s*(?:[-*\u2022]|\d+[.)])\s+(.*)$/);if(m){flushT();(list=list||[]).push(m[1])}else if(l.trim()){flushL();txt.push(l)}}flushT();flushL();return out.join("")}).join("");
 return s.replace(/<p>\u0000(\d+)\u0000<\/p>|\u0000(\d+)\u0000/g,(_,a,b)=>blocks[a??b])}

/* --- Davet --- */
function tanitimUrl(){return new URL("tanitim.html",APP_URL).href}
function inviteText(){return`Kadraj'a gel, orada konuşalım!\n${inviteLink()}\nBağlantıyı aç, e-postanla hesap oluştur ve beni bul: @${me().username}\nNeler var, önce bir bak: ${tanitimUrl()}`}
function vInvite(){const cloud=S.mode==="cloud";
 if(!cloud)return`<div class="banner">${I("info")}<span>Şu an <b>kurulumsuz demo</b> modundasın; veriler sadece bu cihazda. Arkadaşlarınla konuşmak için önce Firebase'i kur.</span></div><div style="padding:0 16px"><button class="btn block" data-act="resetcfg">Firebase'i kur</button></div>`;
 return`<div class="banner">${I("info")}<span>Bu bağlantıyı alan herkes Kadraj'a girip kendi e-postasıyla hesap açabilir. Sadece güvendiğin kişilere gönder.</span></div>
 <h3 class="sec-h">Arkadaşına göndereceğin mesaj</h3><div class="invite-text" id="invTxt">${esc(inviteText())}</div>
 <div style="padding:0 16px 16px;display:grid;gap:8px">${navigator.share?`<button class="btn block" data-act="shareinvite">${I("send")}WhatsApp ya da başka uygulamayla gönder</button>`:""}<button class="btn ${navigator.share?"sec":""} block" data-act="copyinvite">${I("copy")}Davet mesajını kopyala</button><button class="btn sec block" data-act="tanitim">${I("spark")}Kadraj tanıtımını aç</button></div>
 <h3 class="sec-h">Arkadaşın ne yapacak?</h3><ol class="steps"><li>Bağlantıya dokunur, Kadraj açılır.</li><li><b>Hesap oluştur</b>'a dokunur; adını, kullanıcı adını, e-postasını ve şifresini yazar.</li><li>Keşfet'te seni bulur, takip eder ve Sohbet'ten yazar.</li></ol>
 <h3 class="sec-h">İçeride konuşmanın yolları</h3>
 <div class="box">${[["globe","Meydan","Uygulamadaki herkesin canlı ortak sohbeti"],["chat","Birebir mesaj","Fotoğraf ve paylaşım gönder, çift dokunarak kalp bırak, uzun basarak geri al"],["users","Grup sohbeti","İstediğin arkadaşlarla grup kur, @rota'yı çağır"],["phone","Sesli ve görüntülü arama","Birebir sohbetin üstündeki telefon ve kamera düğmeleri"],["mic","Sesli mesaj","Mesaj kutusu boşken mikrofona dokun, konuş, gönder"],["hand","Dürt","Şu an açık olan arkadaşına titreşimli dürtme gönder"],["reply","Hikâye yanıtı","Bir hikâyeye yazdığın yanıt mesaj olarak gider"],["send","Paylaşım gönder","Her kartın altındaki uçak düğmesiyle"]].map(([ic,b,s])=>`<div class="srow">${I(ic)}<span class="t">${b}<small>${s}</small></span></div>`).join("")}</div>`}

