async function publishComposer(){const c=S.cmp;const l=$('#overlay [data-layer="composer"]');const go=$("#cmpGo",l);const id=rid();const at=now();
 const base={uid:S.uid,at,caption:cleanText((c.caption||"").trim()),loc:(c.loc||"").trim(),...(c.noKids?{noKids:1}:{}),...(c.kind==="reel"&&musClean(c.song)?{song:musClean(c.song)}:{}),...(c.kind==="photo"&&Array.isArray(c.tags)&&c.tags.length?{tags:c.tags.slice(0,10)}:{}),...((c.kind==="photo"||c.kind==="note")&&c.capAt>now()?{cap:c.capAt}:{})};let doc,path="posts/"+id;
 try{
  if(c.kind==="photo"&&c.imgs&&c.imgs.length>1){go.disabled=true;doc={...base,...await phPack(c,go)};if(!l.isConnected)return}
  else if(c.kind==="photo"){if(c.src&&c.ar==="1/1")doc={...base,kind:"photo",src:c.src,css:FILTERS[c.filter][1]||"",ar:c.ar,exif:`Filtre: ${FILTERS[c.filter][0]}`};
   else{const cv=$("#cCv",l);doc={...base,kind:"photo",img:encode(cv,170000),ar:c.ar,exif:`Filtre: ${FILTERS[c.filter][0]} · ${cv.width} × ${cv.height}`}}}
  else if(c.kind==="story"){path="stories/"+id;doc={uid:S.uid,at,...stDoc(c,$("#cCv",l))}}
  else if(c.kind==="note"){if(!(c.text||"").trim())return toast("Notuna bir şey yaz.");doc={...base,kind:"note",text:kidClean(c.text.trim()),bg:c.bg}}
  else if(c.kind==="poll"){const opts=c.options.map(o=>o.trim()).filter(Boolean);if(!(c.question||"").trim())return toast("Bir soru yaz.");if(opts.length<2)return toast("En az iki seçenek yaz.");doc={...base,kind:"poll",question:kidClean(c.question.trim()),options:opts.map(kidClean)}}
  else if(c.kind==="reel"){if(c.mode==="video"){if(!c.video)return toast("Önce bir video seç.");go.disabled=true;go.textContent="Hazırlanıyor…";const poster=(c.kedPoster&&c.ked&&c.video===c.kedOut)?c.kedPoster:await videoPoster(c.videoUrl);const vdur=await vidDur(c.video).catch(()=>0);const ref=await storeVideo(c.video,(i,n)=>go.textContent=`Yükleniyor %${Math.round(i/Math.max(1,n)*100)}`);if(!l.isConnected){delChunks(ref);return toast("Klaket paylaşılmadı: pencere kapatıldı.")}vcache[ref]=c.videoUrl;doc={...base,kind:"reel",video:ref,poster,...(vdur>0?{dur:Math.round(vdur*10)/10}:{}),exif:"Video · "+(c.video.size/1048576).toFixed(1).replace(".",",")+" MB",...(c.vmusic&&c.vmusic!=="none"?{music:c.vmusic}:{})}}
   else{if(!c.slides.length)return toast("En az bir kare ekle.");doc={...base,kind:"reel",slides:c.slides.slice(),fx:c.fx,music:c.music,text:kidClean((c.text||"").trim())}}}
  go.disabled=true;go.textContent="Paylaşılıyor…";
  const ok=await write(()=>DB.set(path,doc));
  if(!ok){if(doc&&doc.video)delChunks(doc.video);go.disabled=false;go.textContent="Paylaş";return}
  if(c.kind==="story"){S.stories={...S.stories,[id]:{id,...doc}};stMentionSend(c);closeLayer("composer");toast("Hikâyen paylaşıldı");return tab("feed")}
  S.posts={...S.posts,[id]:{id,...doc}};closeLayer("composer");toast({photo:"Fotoğraf paylaşıldı",note:"Not paylaşıldı",poll:"Anket yayında",reel:"Klaket paylaşıldı"}[c.kind]);
  if(c.kind==="reel"){S.stack=[{name:"feed",params:{}}];S.route={name:"reels",params:{start:id}};render(true)}else tab("feed")}
 catch(e){console.warn(e);toast(e&&e.code==="quota_exceeded"?"Cihaz depolaması doldu. Daha kısa bir video seç ya da eski paylaşımları sil.":e&&e.name==="NotReadableError"?"Video dosyası okunamadı. “Başka video seç” ile videoyu yeniden seç ve hemen paylaş.":"Paylaşılamadı: "+(e&&e.message?e.message:"bilinmeyen hata"));go.disabled=false;go.textContent="Paylaş"}}
/* uygulama içi video kaydı (çekim) */
function openRecorder(maxS=20){return new Promise(resolve=>{let stream=null,mr=null,chunks=[],facing="environment",t0=0,raf=0,done=false,recording=false;
 const finish=v=>{if(done)return;done=true;cancelAnimationFrame(raf);try{if(mr&&mr.state!=="inactive")mr.stop()}catch{}if(stream)stream.getTracks().forEach(t=>t.stop());closeLayer("rec");resolve(v)};
 if(!navigator.mediaDevices||!navigator.mediaDevices.getUserMedia||!window.MediaRecorder){toast("Bu tarayıcı uygulama içi kaydı desteklemiyor. Telefonun kamerası açılıyor.");nativePick("video/*","environment").then(f=>resolve(f||null));return}
 const l=openLayer("rec",`<div class="vrec" role="dialog" aria-label="Video çek"><video id="vrV" playsinline muted autoplay></video><div class="vr-top"><button class="ib" id="vrX" aria-label="Kapat">${I("close")}</button><span class="vr-time" id="vrT">0:00 / ${mmss(maxS)}</span><button class="ib" id="vrF" aria-label="Kamerayı çevir">${I("flip")}</button></div><div class="vr-prog"><i id="vrP"></i></div><div class="vr-bot"><button class="vr-btn" id="vrB" aria-label="Kaydı başlat"><span></span></button></div><div class="vr-hint" id="vrH">Kamera açılıyor…</div></div>`,{noScrim:true,onClose:()=>finish(null)});
 const V=$("#vrV",l),B=$("#vrB",l),H_=$("#vrH",l);
 let gen=0;const open=async()=>{const my=++gen;if(stream)stream.getTracks().forEach(t=>t.stop());stream=null;const vc={facingMode:facing,width:{ideal:720},height:{ideal:1280}};let ns=null;
  try{ns=await navigator.mediaDevices.getUserMedia({video:vc,audio:{echoCancellation:true}})}catch(e){try{ns=await navigator.mediaDevices.getUserMedia({video:vc})}catch(e2){if(done||my!==gen)return;H_.textContent=e2&&e2.name==="NotAllowedError"?"Kamera izni verilmedi. Tarayıcı ayarlarından bu siteye kamera izni ver.":"Kamera açılamadı.";return}}
  if(done||my!==gen){ns.getTracks().forEach(t=>t.stop());return}stream=ns;V.srcObject=stream;V.style.transform=facing==="user"?"scaleX(-1)":"";V.play().catch(()=>{});H_.textContent=`Kaydetmek için dokun · en fazla ${maxS} saniye`};
 const stop=()=>{if(mr&&mr.state!=="inactive")mr.stop()};
 B.onclick=()=>{if(!stream)return;if(recording)return stop();const types=["video/mp4;codecs=avc1","video/mp4","video/webm;codecs=vp9,opus","video/webm;codecs=vp8,opus","video/webm"];const mt=types.find(t=>MediaRecorder.isTypeSupported&&MediaRecorder.isTypeSupported(t))||"";
  const br=S.mode==="local"?900000:1000000;try{mr=new MediaRecorder(stream,mt?{mimeType:mt,videoBitsPerSecond:br,audioBitsPerSecond:64000}:{videoBitsPerSecond:br})}catch{mr=new MediaRecorder(stream)}
  chunks=[];mr.ondataavailable=e=>{if(e.data&&e.data.size)chunks.push(e.data)};
  mr.onstop=()=>{recording=false;l.classList.remove("on");const type=(mr.mimeType||mt||"video/webm").split(";")[0];const blob=new Blob(chunks,{type});if(Date.now()-t0<800||!blob.size){H_.textContent="Çok kısa oldu, tekrar dene.";return}
   const f=new File([blob],"cekim."+(type.includes("mp4")?"mp4":"webm"),{type});f._rec=true;finish(f)};
  mr.start(250);recording=true;t0=Date.now();l.classList.add("on");H_.textContent="Bitirmek için tekrar dokun";vib(20);
  const tick=()=>{const s=(Date.now()-t0)/1000;$("#vrT",l).textContent=`${mmss(s)} / ${mmss(maxS)}`;$("#vrP",l).style.width=Math.min(100,s/maxS*100)+"%";if(s>=maxS)return stop();raf=requestAnimationFrame(tick)};tick()};
 $("#vrX",l).onclick=()=>finish(null);
 $("#vrF",l).onclick=()=>{if(recording)return;facing=facing==="user"?"environment":"user";open()};
 open()})}
function videoPoster(url){return new Promise(res=>{const v=document.createElement("video");v.muted=true;v.preload="auto";v.src=url;v.playsInline=true;try{const pp=v.play();if(pp&&pp.then)pp.then(()=>v.pause()).catch(()=>{})}catch{}v.onloadeddata=()=>{v.currentTime=Math.min(1,(v.duration||2)/2)};v.onseeked=()=>{try{res(toCanvas(v,360,640).toDataURL("image/jpeg",.7))}catch{res("")}};v.onerror=()=>res("");setTimeout(()=>res(""),6000)})}
/* video parçaları */
const vcache={};
const RB={};function RV(x){if(!x)return x;const d=ASSETS[x];if(!d)return x;if(RB[x])return RB[x];try{const i=d.indexOf(",");const mime=d.slice(5,d.indexOf(";"))||"video/mp4";const bin=atob(d.slice(i+1));const u=new Uint8Array(bin.length);for(let k=0;k<bin.length;k++)u[k]=bin.charCodeAt(k);return RB[x]=URL.createObjectURL(new Blob([u],{type:mime}))}catch{return d}}
/* Cloudinary videoları akıcı oynasın: 720p, H.264 MP4, otomatik kalite (Cloudinary ilk izlemede dönüştürür ve önbellekler) */
/* 4.5: daha net görüntü (1080p, q_auto:good) */
const cldTx=()=>settings.dataSaver?"f_mp4,vc_h264,q_auto,w_720,c_limit":"f_mp4,vc_h264,q_auto:good,w_1080,c_limit";
const cldPlay=u=>typeof u==="string"&&/^https:\/\/res\.cloudinary\.com\/[^/]+\/video\/upload\/v\d+\//.test(u)?u.replace("/video/upload/","/video/upload/"+cldTx()+"/").replace(/\.(webm|mov|mkv|3gp|m4v|avi)$/i,".mp4"):u;
const vsrc=p=>!p.video?"":vcache[p.video]||(p.video.startsWith("chunk:")?"":cldPlay(RV(p.video)));
const vref=p=>p.video&&p.video.startsWith("chunk:")?` data-vref="${esc(p.video)}"`:"";
async function resolveVideo(ref){if(vcache[ref])return vcache[ref];const[,vid,n]=ref.split(":");const parts=await Promise.all([...Array(+n)].map((_,i)=>DB.get(`vchunks/${vid}-${i}`).catch(()=>null)));if(parts.some(x=>!x))return null;
 if(parts[0].b&&parts[0].b.toUint8Array)return vcache[ref]=URL.createObjectURL(new Blob(parts.map(x=>x.b.toUint8Array()),{type:parts[0].m||"video/mp4"}));
 const durl=parts.map(x=>x.d).join("");const comma=durl.indexOf(",");const mime=(durl.slice(5,comma).split(";")[0])||"video/mp4";const bin=atob(durl.slice(comma+1));const u8=new Uint8Array(bin.length);for(let i=0;i<bin.length;i++)u8[i]=bin.charCodeAt(i);
 return vcache[ref]=URL.createObjectURL(new Blob([u8],{type:mime}))}
/* 4.8: Klakette parçalı videolar yalnızca açık, önceki ve sonraki için indirilir (eskisi hepsini birden indiriyordu) */
function hydrateVideos(){const near=new Set();if(activeReel){near.add(activeReel);if(activeReel.nextElementSibling)near.add(activeReel.nextElementSibling);if(activeReel.previousElementSibling)near.add(activeReel.previousElementSibling)}
 for(const v of $$("video[data-vref]")){if(v.getAttribute("src")||v._hy)continue;const r=v.closest(".reel");if(r&&!near.has(r))continue;v._hy=true;resolveVideo(v.dataset.vref).then(u=>{v._hy=false;if(u&&v.isConnected){v.src=u;if(activeReel&&activeReel.contains(v)&&settings.autoplay)v.play().catch(()=>{if(!v.muted&&activeReel&&activeReel.contains(v)){v.muted=true;v.play().catch(()=>{});S.needUnmute=true;const h=activeReel.querySelector(".rhint");if(h)h.hidden=false}})}}).catch(()=>{v._hy=false})}}
const VMAX=4*1024*1024;
/* 4.0: video parçaları bulutta ham bayt olarak saklanır (base64'e göre ~%25 daha az yer); yükleme yarıda kalırsa yazılan parçalar silinir */
function delChunks(ref){if(!ref||!String(ref).startsWith("chunk:"))return;const[,vid,n]=String(ref).split(":");for(let i=0;i<+n;i++)DB.del(`vchunks/${vid}-${i}`).catch(()=>{})}
/* 4.1: sahne videoları Cloudinary'de (ücretsiz plan, imzasız "Kadraj" ön ayarı). Paylaşımın video alanına doğrudan https adresi yazılır. Olmazsa Firestore parçalarına düşer. */
const CLD={cloud:"jw9koecu",preset:"Kadraj",maxMB:40,maxS:120};
const cldOn=()=>S.mode==="cloud"&&!!CLD.cloud&&!!CLD.preset;
function cldUpload(file,onProg){return new Promise((res,rej)=>{const fd=new FormData();fd.append("file",file);fd.append("upload_preset",CLD.preset);
 const x=new XMLHttpRequest();x.open("POST",`https://api.cloudinary.com/v1_1/${CLD.cloud}/video/upload`);
 x.upload.onprogress=e=>{if(e.lengthComputable&&onProg)onProg(e.loaded,e.total)};
 x.onload=()=>{let j=null;try{j=JSON.parse(x.responseText)}catch{}if(x.status>=200&&x.status<300&&j&&j.secure_url){cldTrack(j.bytes||file.size);cldWarm(j.secure_url);res(j.secure_url)}else rej(new Error((j&&j.error&&j.error.message)||"Cloudinary yüklemesi başarısız"))};
 x.onerror=()=>rej(new Error("Bağlantı hatası"));x.ontimeout=()=>rej(new Error("Zaman aşımı"));x.timeout=10*60e3;x.send(fd)})}
function vidDur(file){return new Promise(r=>{const v=document.createElement("video");const u=URL.createObjectURL(file);v.preload="metadata";v.muted=true;v.onloadedmetadata=()=>{const d=v.duration;URL.revokeObjectURL(u);r(isFinite(d)?d:0)};v.onerror=()=>{URL.revokeObjectURL(u);r(0)};setTimeout(()=>r(0),8000);v.src=u})}
/* 4.4.1: bulut yüklemesi bağlantıdan düşerse bir kez daha dener; yine olmazsa büyük videoyu telefonda küçültüp yedek yola (Firestore parçaları) koyar.
   O da olmazsa Cloudinary'nin asıl hata sebebini gösterir (eskiden yalnızca "Video yüklenemedi" yazıyordu). */
async function storeVideo(file,onProg){
 if(cldOn()){let err=null;for(let i=0;i<2;i++){try{return await cldUpload(file,onProg)}catch(e){console.warn("cloudinary",e);err=e;if(!/Bağlantı|Zaman/.test(e&&e.message||""))break}}
  if(file.size>VMAX){toast("Bulut yüklemesi olmadı, video küçültülüyor…");let g=null;try{g=await compressVideo(file,{maxS:60,limit:Math.round(VMAX*.85),onProg:p=>onProg&&onProg(Math.round(p*100),100)})}catch(e2){console.warn(e2)}
   if(!g||g.size>VMAX)throw new Error("Video yüklenemedi ("+((err&&err.message)||"bulut hatası")+"). Daha kısa bir video dene.");file=g}}
 return storeVideoFs(file,onProg)}
async function storeVideoFs(file,onProg){const vid=rid();let done=0;
 try{if(S.mode==="cloud"&&FB&&FB.F&&FB.F.Bytes){const u8=new Uint8Array(await file.arrayBuffer());const CH=900000;const n=Math.ceil(u8.length/CH);const m=(file.type||"video/mp4").split(";")[0];
   for(let i=0;i<n;i++){onProg&&onProg(i,n);await DB.set(`vchunks/${vid}-${i}`,i===0?{b:FB.F.Bytes.fromUint8Array(u8.slice(i*CH,(i+1)*CH)),m}:{b:FB.F.Bytes.fromUint8Array(u8.slice(i*CH,(i+1)*CH))});done++}return`chunk:${vid}:${n}`}
  const durl=await readFile(file);const CH=180000;const n=Math.ceil(durl.length/CH);
  for(let i=0;i<n;i++){onProg&&onProg(i,n);await DB.set(`vchunks/${vid}-${i}`,{d:durl.slice(i*CH,(i+1)*CH)});done++}return`chunk:${vid}:${n}`}
 catch(e){for(let i=0;i<done;i++)DB.del(`vchunks/${vid}-${i}`).catch(()=>{});throw e}}

/* ============ Müzik (cihazda üretilir) ============ */
const MUSIC_NAMES={lofi:"Lo-fi",enerjik:"Enerjik",sakin:"Sakin",none:"Yok"};
const Music={ctx:null,timer:null,on:false,master:null,
 start(style){this.stop();if(!style||style==="none")return;let ctx;try{ctx=this.ctx||(this.ctx=new(window.AudioContext||window.webkitAudioContext)())}catch{return}try{ctx.resume()}catch{}
  const ST={lofi:{bpm:76,chords:[[220,261.6,329.6,392],[174.6,220,261.6,329.6],[130.8,164.8,196,246.9],[196,246.9,293.7,349.2]],kick:true,hat:true,lead:false},
   enerjik:{bpm:120,chords:[[164.8,207.7,246.9],[220,277.2,329.6],[146.8,185,220],[196,246.9,293.7]],kick:true,hat:true,lead:true},
   sakin:{bpm:58,chords:[[261.6,329.6,392,493.9],[220,261.6,329.6,392],[174.6,220,261.6,349.2],[196,246.9,293.7,392]],kick:false,hat:false,lead:true}}[style];if(!ST)return;
  const master=ctx.createGain();master.gain.value=.32;master.connect(ctx.destination);this.master=master;this.on=true;
  const spb=60/ST.bpm/2;let step=0,next=ctx.currentTime+.06;
  const tone=(f,t,d,type,v)=>{const o=ctx.createOscillator(),g=ctx.createGain();o.type=type;o.frequency.value=f;g.gain.setValueAtTime(0,t);g.gain.linearRampToValueAtTime(v,t+.03);g.gain.exponentialRampToValueAtTime(.0008,t+d);o.connect(g);g.connect(master);o.start(t);o.stop(t+d+.05)};
  const kick=t=>{const o=ctx.createOscillator(),g=ctx.createGain();o.frequency.setValueAtTime(130,t);o.frequency.exponentialRampToValueAtTime(42,t+.18);g.gain.setValueAtTime(.7,t);g.gain.exponentialRampToValueAtTime(.001,t+.25);o.connect(g);g.connect(master);o.start(t);o.stop(t+.3)};
  const nb=ctx.createBuffer(1,Math.floor(ctx.sampleRate*.05),ctx.sampleRate);const nd=nb.getChannelData(0);for(let i=0;i<nd.length;i++)nd[i]=(Math.random()*2-1)*(1-i/nd.length);
  const hat=t=>{const s=ctx.createBufferSource(),f=ctx.createBiquadFilter(),g=ctx.createGain();s.buffer=nb;f.type="highpass";f.frequency.value=6000;g.gain.value=.14;s.connect(f);f.connect(g);g.connect(master);s.start(t)};
  const sched=(s,t)=>{const ch=ST.chords[Math.floor(s/8)%ST.chords.length];if(s%8===0)ch.forEach(f=>tone(f,t,spb*8*.95,"triangle",.07));if(ST.kick&&s%4===0)kick(t);if(ST.hat&&s%2===1)hat(t);if(ST.lead&&s%2===0)tone(ch[(s/2)%ch.length|0]*2,t,spb*1.6,"sine",.045)};
  this.timer=setInterval(()=>{while(next<ctx.currentTime+.25){sched(step,next);next+=spb;step++}},60)},
 stop(){if(this.timer)clearInterval(this.timer);this.timer=null;this.on=false;if(this.master){try{this.master.disconnect()}catch{}this.master=null}}};

/* ============ Kayıt / giriş ============ */
const USER_RE=/^[a-z0-9._]{3,24}$/;
function takenUsername(n,exceptUid){return BOTS.some(b=>b.username===n)||Object.values(S.profiles).some(p=>p.username===n&&p.uid!==exceptUid)}
function authShell(html,cls){S.authed=false;$("#top").hidden=true;$("#dock").hidden=true;const m=main();m.className="";m.innerHTML=`<div class="auth${cls?" "+cls:""}">${html}</div>`;m.scrollTop=0;introDone()}
const mosaic=`<div class="mosaic"><img src="${R("img/iskele.jpg")}" alt=""><img src="${R("img/kedi.jpg")}" alt=""><img src="${R("img/gunbatimi.jpg")}" alt=""></div>`;
const modeChip=()=>`<span class="modechip ${S.mode==="cloud"?"cloud":""}"><i></i>${S.mode==="cloud"?"Firebase · arkadaşlarınla canlı":"Demo · yalnızca bu cihaz"}</span>`;
const brandLine=`<div class="brand" style="margin-bottom:12px">${VF}<span class="wordmark">kadraj</span></div>`;
function showWelcome(){authShell(welScreen(S.mode==="local"),"wel");
 $("#wReg").onclick=showRegister;const wl=$("#wLog");if(wl)wl.onclick=()=>showLogin();welWire()}
function showRegister(){const sug=S.viewer?.name||"";let avData=null;
 authShell(`<div>${brandLine}<h2>Hesap oluştur</h2><p class="lead">Bir dakikadan kısa sürer.</p></div>${modeChip()}
 <form id="regF" novalidate><div class="avpick"><span class="av" style="--s:64px"><img id="rAv" src="${initialsAv(sug||"Yeni",S.uid||"x")}" alt=""></span><button type="button" class="btn sec sm" id="rAvBtn">${I("image")}Profil fotoğrafı</button></div>
 <div class="field"><label for="rName">Ad soyad</label><input class="in" id="rName" autocomplete="name" maxlength="40" value="${esc(sug)}" required></div>
 <div class="field"><label for="rUser">Kullanıcı adı</label><input class="in" id="rUser" autocomplete="username" autocapitalize="off" maxlength="24" placeholder="ornek.kullanici" required></div>
 <div class="field"><label for="rPw">Şifre</label><input class="in" id="rPw" type="password" autocomplete="new-password" minlength="6" placeholder="En az 6 karakter" required></div>
 <label class="check"><input type="checkbox" id="rRem" checked>Beni hatırla</label><div class="err" id="rErr"></div><button class="btn block" type="submit">Kayıt ol</button></form>
 ${S.mode==="local"?`<div class="divider">ya da</div><button class="btn ghost" id="toLogin">Zaten hesabım var</button>`:""}`);
 const nameIn=$("#rName");nameIn.oninput=()=>{if(!avData)$("#rAv").src=initialsAv(nameIn.value||"Yeni",S.uid||"x");const ui=$("#rUser");if(!ui.dataset.touched)ui.value=slug(nameIn.value)};$("#rUser").oninput=e=>e.target.dataset.touched=1;if(sug&&!$("#rUser").value)$("#rUser").value=slug(sug);
 $("#rAvBtn").onclick=async()=>{const r=await pickImage({title:"Profil fotoğrafı"});if(r){avData=toCanvas(r.img,240,240).toDataURL("image/jpeg",.8);$("#rAv").src=avData}};
 const tl=$("#toLogin");if(tl)tl.onclick=()=>showLogin();
 $("#regF").onsubmit=async e=>{e.preventDefault();const err=$("#rErr");const name=$("#rName").value.trim(),un=$("#rUser").value.trim().toLowerCase(),pw=$("#rPw").value;
  if(!name)return err.textContent="Adını yaz.";if(!USER_RE.test(un))return err.textContent="Kullanıcı adı 3–24 karakter olmalı: küçük harf, rakam, nokta ve alt çizgi.";
  if(takenUsername(un,S.uid))return err.textContent=`“${un}” kullanılıyor. Başka bir ad dene.`;if(pw.length<6)return err.textContent="Şifre en az 6 karakter olmalı.";
  const btn=$("#regF button[type=submit]");btn.disabled=true;btn.textContent="Oluşturuluyor…";
  if(S.mode==="local")S.uid="local-"+un;
  const salt=rid();const hash=await sha(salt+pw);
  const prof={uid:S.uid,username:un,name,bio:"",avatar:avData||null,following:{"bot:rota":now()},botFollowers:{},private:false,createdAt:now()};
  try{await DB.set("profiles/"+S.uid,prof);await DB.set(`data/users/${S.uid}/secret`,{salt,hash})}
  catch(ex){console.warn(ex);btn.disabled=false;btn.textContent="Kayıt ol";if(S.mode==="cloud"){S.canWrite=false;return err.textContent="Bu sayfaya yazma iznin yok. Sahibinden seni “Düzenleyen” olarak davet etmesini iste."}return err.textContent="Kaydedilemedi. Tarayıcı depolaması kapalı olabilir."}
  if(S.mode==="local"){const acc=LS.get("kadraj_accounts",{})||{};acc[un]=S.uid;LS.set("kadraj_accounts",acc)}
  S.profiles={...S.profiles,[S.uid]:prof};remember($("#rRem").checked);await enterApp(true)}}
function slug(s){return(s||"").toLocaleLowerCase("tr").replace(/ç/g,"c").replace(/ğ/g,"g").replace(/ı/g,"i").replace(/ö/g,"o").replace(/ş/g,"s").replace(/ü/g,"u").replace(/[^a-z0-9]+/g,".").replace(/^\.+|\.+$/g,"").slice(0,20)}
function showLogin(prefill){const cloud=S.mode==="cloud";const p=cloud?S.profiles[S.uid]:null;
 authShell(`<div>${brandLine}<h2>${cloud&&p?"Tekrar hoş geldin":"Giriş yap"}</h2></div>${modeChip()}
 ${cloud&&p?`<div class="avpick">${avatar(S.uid,58,{ring:false,click:false,online:false})}<div><b>${esc(p.name)}</b><div class="muted">@${esc(p.username)}</div></div></div>`:""}
 <form id="logF" novalidate>${cloud?"":`<div class="field"><label for="lUser">Kullanıcı adı</label><input class="in" id="lUser" autocomplete="username" autocapitalize="off" value="${esc(prefill||"")}" required></div>`}
 <div class="field"><label for="lPw">Şifre</label><input class="in" id="lPw" type="password" autocomplete="current-password" required></div>
 <label class="check"><input type="checkbox" id="lRem" checked>Beni hatırla</label><div class="err" id="lErr"></div><button class="btn block" type="submit">Giriş yap</button></form>
 <button class="btn ghost" id="forgot">Şifremi unuttum</button>${cloud?"":`<div class="divider">ya da</div><button class="btn line block" id="toReg">Yeni hesap oluştur</button>`}`);
 const tr=$("#toReg");if(tr)tr.onclick=showRegister;$("#forgot").onclick=()=>resetFlow();
 $("#logF").onsubmit=async e=>{e.preventDefault();const err=$("#lErr");let uid=S.uid;
  if(!cloud){const un=$("#lUser").value.trim().toLowerCase();uid=(LS.get("kadraj_accounts",{})||{})[un];if(!uid)return err.textContent="Bu cihazda bu kullanıcı adıyla hesap yok."}
  const sec=await DB.get(`data/users/${uid}/secret`);if(!sec)return err.textContent="Şifre kaydı bulunamadı. “Şifremi unuttum” ile yeni şifre belirle.";
  if(await sha(sec.salt+$("#lPw").value)!==sec.hash)return err.textContent="Şifre yanlış. Tekrar dene.";
  S.uid=uid;if(!cloud)S.profiles={...S.profiles,[uid]:await LocalDB.get("profiles/"+uid)};remember($("#lRem").checked);await enterApp()}}
function resetFlow(){const cloud=S.mode==="cloud";
 authShell(`<div><h2>Yeni şifre belirle</h2><p class="lead">Bu cihazdaki hesabın için yeni şifre belirleyebilirsin.</p></div>
 <form id="rsF" novalidate>${cloud?"":`<div class="field"><label for="rsUser">Kullanıcı adı</label><input class="in" id="rsUser" autocapitalize="off" required></div>`}<div class="field"><label for="rsPw">Yeni şifre</label><input class="in" id="rsPw" type="password" minlength="6" autocomplete="new-password" required></div><div class="err" id="rsErr"></div><button class="btn block">Şifreyi kaydet</button></form><button class="btn ghost" id="rsBack">Girişe dön</button>`);
 $("#rsBack").onclick=()=>showLogin();
 $("#rsF").onsubmit=async e=>{e.preventDefault();const err=$("#rsErr");let uid=S.uid;if(!cloud){uid=(LS.get("kadraj_accounts",{})||{})[$("#rsUser").value.trim().toLowerCase()];if(!uid)return err.textContent="Bu cihazda böyle bir hesap yok."}
  const pw=$("#rsPw").value;if(pw.length<6)return err.textContent="Şifre en az 6 karakter olmalı.";const salt=rid();const hash=await sha(salt+pw);
  try{await DB.set(`data/users/${uid}/secret`,{salt,hash})}catch{return err.textContent="Kaydedilemedi."}
  toast("Şifren güncellendi. Şimdi giriş yapabilirsin.");showLogin(cloud?"":$("#rsUser").value)}}
function remember(on){if(on)LS.set("kadraj_session",S.uid);else LS.del("kadraj_session");SS.set("kadraj_sess",S.uid)}
function wireEdit(f){const D=S.editDraft||(S.editDraft={});const keep=()=>{const n=$("#eName"),u=$("#eUser"),b=$("#eBio");if(n)D.name=n.value;if(u)D.user=u.value;if(b)D.bio=b.value};f.addEventListener("input",keep);
 $("#editAvBtn").onclick=async()=>{keep();const r=await pickImage({title:"Profil fotoğrafı"});if(!r)return;const av=toCanvas(r.img,240,240).toDataURL("image/jpeg",.82);D.av=av;const im=$("#editAv");if(im)im.src=av;
  /* fotoğrafı hemen kaydet: sayfa yenilense de kaybolmaz */
  S.profiles={...S.profiles,[S.uid]:{...S.profiles[S.uid],avatar:av}};renderDock();
  if(await write(()=>DB.update("profiles/"+S.uid,{avatar:av}))){toast("Profil fotoğrafın güncellendi")}};
 f.onsubmit=async e=>{e.preventDefault();const err=$("#eErr");const name=$("#eName").value.trim(),un=$("#eUser").value.trim().toLowerCase(),bio=$("#eBio").value.trim();
  if(!name)return err.textContent="Adını yaz.";if(!USER_RE.test(un))return err.textContent="Kullanıcı adı 3–24 karakter: küçük harf, rakam, nokta, alt çizgi.";if(takenUsername(un,S.uid))return err.textContent=`“${un}” başka birinde.`;
  const patch={name,username:un,bio};if(D.av)patch.avatar=D.av;
  if(await write(()=>DB.update("profiles/"+S.uid,patch))){S.profiles={...S.profiles,[S.uid]:{...S.profiles[S.uid],...patch}};if(S.mode==="local"){const acc=LS.get("kadraj_accounts",{})||{};for(const k in acc)if(acc[k]===S.uid)delete acc[k];acc[un]=S.uid;LS.set("kadraj_accounts",acc)}S.editDraft=null;toast("Profil güncellendi");back()}}}
async function onSetting(id,v){if(id==="setRemember"&&S.mode==="cloud"){await setPersist(v);toast(v?"Bu cihazda hatırlanacaksın":"Tarayıcıyı kapatınca çıkış yapılacak");return}else if(id==="setNotify"){settings.notify=v;saveSettings();if(v)askNotif(false)}else if(id==="setAutoplay"){settings.autoplay=v;saveSettings()}else if(id==="setRemember"){remember(v);toast(v?"Bu cihazda hatırlanacaksın":"Bir dahaki girişte şifre sorulacak")}
 else if(id==="setPrivate"){if(await write(()=>DB.update("profiles/"+S.uid,{private:v}))){S.profiles={...S.profiles,[S.uid]:{...S.profiles[S.uid],private:v}};toast(v?"Hesabın artık gizli":"Hesabın herkese açık")}}}
function changePw(){if(S.mode==="cloud")return fbChangePw();const l=sheet("pw","Şifreyi değiştir",`<form class="form" id="cpF"><div class="field"><label for="cp0">Mevcut şifre</label><input class="in" id="cp0" type="password" autocomplete="current-password"></div><div class="field"><label for="cp1">Yeni şifre</label><input class="in" id="cp1" type="password" autocomplete="new-password" minlength="6"></div><div class="err" id="cpE"></div><button class="btn block">Güncelle</button></form>`);
 $("#cpF",l).onsubmit=async e=>{e.preventDefault();const er=$("#cpE",l);const sec=await DB.get(`data/users/${S.uid}/secret`);if(sec&&await sha(sec.salt+$("#cp0",l).value)!==sec.hash)return er.textContent="Mevcut şifre yanlış.";const pw=$("#cp1",l).value;if(pw.length<6)return er.textContent="Yeni şifre en az 6 karakter olmalı.";const salt=rid();const hash=await sha(salt+pw);if(await write(()=>DB.set(`data/users/${S.uid}/secret`,{salt,hash}))){closeLayer("pw");toast("Şifren değişti")}}}
function logout(){if(S.mode==="cloud")return fbLogout();dialog("Çıkış yapılsın mı?",`@${esc(me().username)} hesabından çıkacaksın.`,[{label:"Çıkış yap",cls:"danger",fn:()=>{LS.del("kadraj_session");SS.del("kadraj_sess");teardownUser();closeAll();S.authed=false;if(S.mode==="cloud")showLogin();else{S.uid=null;showWelcome()}}},{label:"Vazgeç"}])}
function confirmDelete(){if(S.mode==="cloud")return fbDelete();dialog("Hesap silinsin mi?","Profilin, paylaşımların ve hikâyelerin kalıcı olarak silinir. Bu işlem geri alınamaz.",[{label:"Hesabı kalıcı olarak sil",cls:"danger",fn:async()=>{const uid=S.uid;for(const p of Object.values(S.posts).filter(p=>p.uid===uid)){await DB.del("posts/"+p.id).catch(()=>{});await DB.del("meta/"+p.id).catch(()=>{});delChunks(p.video)}for(const s of Object.values(S.stories).filter(s=>s.uid===uid))await DB.del("stories/"+s.id).catch(()=>{});
  await DB.del("profiles/"+uid).catch(()=>{});await DB.del(`data/users/${uid}/secret`).catch(()=>{});await DB.del(`data/users/${uid}/saved`).catch(()=>{});
  if(S.mode==="local"){const acc=LS.get("kadraj_accounts",{})||{};for(const k in acc)if(acc[k]===uid)delete acc[k];LS.set("kadraj_accounts",acc)}
  LS.del("kadraj_session");teardownUser();S.authed=false;const pr={...S.profiles};delete pr[uid];S.profiles=pr;toast("Hesabın silindi");if(S.mode==="cloud")showRegister();else{S.uid=null;showWelcome()}}},{label:"Vazgeç"}])}

/* ============ Abonelikler ============ */
let notifReady=false;setTimeout(()=>notifReady=true,4000);
/* sistem (telefon) bildirimi: uygulama arka plandayken de görünür */
function notifPerm(){try{return typeof Notification!=="undefined"?Notification.permission:"unsupported"}catch{return"unsupported"}}
async function askNotif(silent){if(typeof Notification==="undefined")return"unsupported";if(Notification.permission==="granted")return"granted";if(Notification.permission==="denied")return"denied";
 try{const r=await Notification.requestPermission();if(!silent)toast(r==="granted"?"Bildirimler açık":"Bildirime izin verilmedi");scheduleRefresh();return r}catch{return"default"}}
function sysNote(title,body,tag,o={}){try{if(typeof Notification==="undefined"||Notification.permission!=="granted")return;if(!settings.notify)return;if(document.visibilityState==="visible")return;
 const ic=typeof o.icon==="string"&&/^data:image\/(jpe?g|png|webp)/.test(o.icon)?o.icon:"icon-192.png";const key=o.key||"";
 const opts={body:body||"",tag:tag||"kadraj",icon:ic,badge:"icon-192.png",renotify:true,vibrate:[70,40,70],timestamp:now(),data:{key}};
 const plain=()=>{try{const n=new Notification(title,opts);n.onclick=()=>{try{window.focus()}catch{}n.close();openTarget(key)}}catch{}};
 if(navigator.serviceWorker&&navigator.serviceWorker.ready){navigator.serviceWorker.ready.then(reg=>reg.showNotification(title,opts)).catch(plain);return}
 return plain();
 if(navigator.serviceWorker&&navigator.serviceWorker.ready){navigator.serviceWorker.ready.then(reg=>{reg.showNotification(title,{body:body||"",tag:tag||"kadraj",icon:"icon-192.png",badge:"icon-192.png",renotify:true}).catch(()=>{new Notification(title,{body,tag,icon:"icon-192.png"})})}).catch(()=>{try{new Notification(title,{body,tag,icon:"icon-192.png"})}catch{}})}
 else new Notification(title,{body,tag,icon:"icon-192.png"})}catch{}}
function subscribeShared(){admSubscribe();
 DB.watchCol("profiles",docs=>{const m={};for(const d of docs)if(d.uid)m[d.uid]=d;const mine=S.profiles[S.uid];if(mine&&m[S.uid]&&S.route.name==="edit"&&S.editDraft&&S.editDraft.av&&m[S.uid].avatar!==S.editDraft.av)m[S.uid]={...m[S.uid],avatar:S.editDraft.av};if(mine&&!m[S.uid]&&S.authed)m[S.uid]=mine;S.profiles=m;runHooks("profiles",m);scheduleRefresh()},{limit:500});
 postsSub();
 DB.watchCol("meta",docs=>{const m={};for(const d of docs)m[d.id]=d;notifyMeta(m);S.meta=m;scheduleRefresh()},{limit:600,...(S.mode==="cloud"&&FB&&FB.F&&FB.F.documentId?{orderBy:[FB.F.documentId(),"desc"]}:{})});
 DB.watchCol("stories",docs=>{const m={};const lim=now()-24*H;for(const d of docs)if(d.at>lim)m[d.id]=d;S.stories=m;scheduleRefresh()},{orderBy:["at","desc"],limit:120});
 DB.watchDoc("chats/meydan",d=>{const o=S.meydan;S.meydan=d;if(d&&d.last&&notifReady&&settings.notify&&settings.nMsg!==false&&S.authed&&!isChild(S.uid)&&d.last.from!==S.uid&&d.last.at>(S.bootAt||Infinity)&&d.last.at>(LS.get("kadraj_meydan_"+S.uid,0)||0)&&(!o||!o.last||o.last.at<d.last.at)&&!(S.route.name==="chat"&&S.route.params.key==="meydan"))notifyMeydan(d);scheduleRefresh()})}
let userUnsub=[];
function subscribeUser(){teardownUser();const u=S.uid;if(S.mode==="cloud"&&FB)userUnsub.push(listenCalls());
 userUnsub.push(DB.watchCol("chats",docs=>{const m={};for(const d of docs)m[d.id]=d;notifyChats(m);S.chats=m;S._chatsIn=1;if(S.route.name==="chat"&&chatKey&&m[chatKey])markRead(chatKey);scheduleRefresh()},{where:["members","array-contains",u],limit:200,onError:()=>{S._chatsIn=1;scheduleRefresh()}}));
 userUnsub.push(DB.watchCol("games",docs=>{const m={};for(const d of docs){m[d.id]=d;if(d.status==="over"&&now()-(d.updatedAt||d.at||0)>2*24*H&&(d.players||[])[0]===S.uid)DB.del("games/"+d.id).catch(()=>{})}notifyGames(m);S.games=m;chRateMissed(m);S.gamesDenied=false;if(CH&&CH.mode==="online"&&m[CH.gid])chSync(m[CH.gid]);scheduleRefresh()},{where:["players","array-contains",u],limit:60,onError:e=>{if(e&&e.code==="permission-denied"){S.gamesDenied=true;scheduleRefresh()}}}));
 userUnsub.push(DB.watchDoc(`data/users/${u}/hidden`,d=>{S.hidden=d||{msgs:{},chats:{}};scheduleRefresh()}));
 userUnsub.push(DB.watchDoc(`data/users/${u}/saved`,d=>{S.saved=(d&&d.ids)||{};scheduleRefresh()}));
 watchBotChats()}
let botWatch={};function watchBotChats(){if(!S.uid)return;for(const b of BOTS){if(botWatch[b.key])continue;const k=b.key;botWatch[k]=DB.watchDoc(`data/users/${S.uid}/bot-${k}`,d=>{S.botchats={...S.botchats,[k]:d||{msgs:[]}};scheduleRefresh()});userUnsub.push(botWatch[k])}}
function teardownUser(){S._chatsIn=0;userUnsub.forEach(f=>{try{f()}catch{}});userUnsub=[];botWatch={};stopChat();S.chats={};S.botchats={};S.saved={};S.games={};S.hidden={};CH=null}
let chatUnsub=null,chatKey=null;
function openChat(key){if(S.route.name==="chat"&&S.route.params.key===key)return;const k=keyInfo(key);if(k.type==="meydan"&&childBlockMeydan())return;if(k.type==="dm"&&!childGate(k.uid))return;go("chat",{key})}
function startChat(key){const k=keyInfo(key);if(k.type==="bot"){stopChat();markBotRead(k.uid);return}if(chatKey===k.cid)return;stopChat();chatKey=k.cid;S.msgs=[];
 if(k.type==="meydan")LS.set("kadraj_meydan_"+S.uid,now());
 chatUnsub=DB.watchCol(`chats/${k.cid}/msgs`,docs=>{S.msgs=docs.sort((a,b)=>a.at-b.at);if(S.route.name==="chat")renderMsgs();if(k.type==="meydan")LS.set("kadraj_meydan_"+S.uid,now());else markRead(k.cid)},{orderBy:["at","desc"],limit:300})}
function stopChat(){if(REC)stopRec(false);if(AUD&&PLAYING){AUD.pause();PLAYING=null}if(chatUnsub){try{chatUnsub()}catch{}}chatUnsub=null;chatKey=null}
async function markRead(cid){const c=S.chats[cid];if(!c)return;if(document.visibilityState==="hidden")return;const lm=chatKey===cid&&S.msgs.length?S.msgs[S.msgs.length-1].at:0;const la=Math.max((c.last&&c.last.at)||0,lm);if(!la)return;if(((c.reads||{})[S.uid]||0)>=la)return;if(!S.canWrite||S.guest)return;const t=Math.max(now(),la+1);S.chats={...S.chats,[cid]:{...c,reads:{...(c.reads||{}),[S.uid]:t}}};const ns=settings.readReceipts===false;try{await DB.update("chats/"+cid,{reads:{[S.uid]:t},noSeen:{[S.uid]:ns}})}catch{}}
document.addEventListener("visibilitychange",()=>{if(document.visibilityState==="visible"&&S.route.name==="chat"&&chatKey&&chatKey!=="meydan")markRead(chatKey)});
async function markBotRead(uid){const k=BOT[uid].key;const c=S.botchats[k];if(!c||!c.msgs?.length)return;const l=c.msgs[c.msgs.length-1];if((c.readAt||0)>=l.at||l.from===S.uid)return;S.botchats={...S.botchats,[k]:{...c,readAt:now()}};try{await DB.set(`data/users/${S.uid}/bot-${k}`,{msgs:c.msgs,readAt:now()})}catch{}}
function notifyMeta(m){if(!notifReady||!settings.notify||!S.authed)return;for(const[id,d]of Object.entries(m)){const p=S.posts[id];if(!p||p.uid!==S.uid)continue;const old=S.meta[id]||{};for(const[u,at]of Object.entries(d.likes||{}))if(settings.nLike!==false&&at&&u!==S.uid&&!(old.likes||{})[u]&&at>S.bootAt){toast(`@${P(u).username} paylaşımını beğendi`,u,"post:"+id);sysNote("Yeni beğeni",`@${P(u).username} paylaşımını beğendi`,"like-"+id,{key:"post:"+id,icon:P(u).avatar})}for(const[cid,c]of Object.entries(d.comments||{}))if(settings.nComment!==false&&c&&c.uid!==S.uid&&!(old.comments||{})[cid]&&c.at>S.bootAt){toast(`@${P(c.uid).username}: ${c.text.slice(0,60)}`,c.uid,"post:"+id);sysNote("Yeni yorum",`@${P(c.uid).username}: ${c.text.slice(0,60)}`,"cm-"+cid,{key:"post:"+id,icon:P(c.uid).avatar})}}}
function notifyChats(m){if(!notifReady||!settings.notify||settings.nMsg===false)return;for(const[id,c]of Object.entries(m)){const o=S.chats[id];if(c.last&&c.last.from!==S.uid&&c.last.at>S.bootAt&&(!o||!o.last||o.last.at<c.last.at)){if(S.route.name==="chat"&&keyInfo(S.route.params.key).cid===id)continue;const nk=c.group?"g:"+id:"u:"+c.last.from;toast(`${c.group?c.name+" · ":""}${P(c.last.from).name}: ${c.last.text}`,c.last.from,nk);vib(30);sysNote((c.group?c.name:P(c.last.from).name),(c.group?P(c.last.from).name+": ":"")+c.last.text,"m-"+id,{key:nk,icon:P(c.last.from).avatar})}}}
function notifyNewPosts(m){if(!notifReady||!settings.notify||settings.nPost===false||!S.authed)return;for(const[id,p]of Object.entries(m))if(!S.posts[id]&&p.uid!==S.uid&&p.at>S.bootAt&&isFollowing(S.uid,p.uid)&&!kidHid(p)){toast(`@${P(p.uid).username} yeni bir paylaşım yaptı`,p.uid,"post:"+id);sysNote("Yeni paylaşım",`@${P(p.uid).username} yeni bir paylaşım yaptı`,"post-"+id,{key:"post:"+id,icon:P(p.uid).avatar})}}

/* ============ Mesaj gönderme ============ */
function wireComposer(){const f=$("#composer"),inp=$("#msgIn");if(!f)return;const key=S.route.params.key;const k=keyInfo(key);const btn=$("#sendBtn");const voice=k.type!=="bot";
 const grow=()=>cfGrow(inp);/* 6.0: yükseklik görünmez bir kopyada ölçülür, kutu yumuşakça büyür (bölge 60CHAT) */
 const icon=()=>{if(btn&&voice){const has=!!inp.value.trim();btn.innerHTML=I(has?"send":"mic");btn.setAttribute("aria-label",has?"Gönder":"Sesli mesaj kaydet")}};
 inp.addEventListener("input",()=>{grow();icon();typingPing(key)});
 inp.addEventListener("keydown",e=>{if(e.key==="Enter"&&!e.shiftKey&&settings.enterSend!==false){e.preventDefault();if(inp.value.trim())f.requestSubmit()}});
 f.onsubmit=async e=>{e.preventDefault();const v=inp.value.trim();if(!v){if(voice)startRec();return}inp.value="";grow();icon();typingStop();S.forceBottom=true;const extra=S.replyTo?{reply:S.replyTo}:{};S.replyTo=null;drawReply();try{inp.focus({preventScroll:true})}catch{inp.focus()}await sendMessage(key,{text:v,...extra});try{inp.focus({preventScroll:true})}catch{}};
 drawReply();grow()}
function drawReply(){const b=$("#replyBar");if(!b)return;const r=S.replyTo;b.innerHTML=r?`<div class="replybar">${I("reply")}<span class="t"><b>${esc(P(r.from).username)}</b> · ${esc(r.text)}</span><button class="ib plain" data-act="noreply" aria-label="Yanıtı iptal et" style="width:2.2rem;height:2.2rem">${I("close")}</button></div>`:""}
/* ---- sesli mesaj ---- */
const mmss=x=>{x=Math.max(0,Math.round(x||0));return`${Math.floor(x/60)}:${String(x%60).padStart(2,"0")}`};
let REC=null,AUD=null,PLAYING=null;
function audHtmlOld(m){return`<span class="audm"><button class="ap" data-play="${esc(m.id||"")}" aria-label="Sesli mesajı oynat">${I(PLAYING===m.id?"pause":"play")}</button><span class="bar"><i id="ab-${esc(m.id||"")}"></i></span><span class="t" id="at-${esc(m.id||"")}">${mmss(m.dur)}</span></span>`}
async function startRec(){if(!guard()||REC)return;if(!navigator.mediaDevices||!navigator.mediaDevices.getUserMedia||!window.MediaRecorder)return toast("Bu tarayıcı ses kaydını desteklemiyor.");
 let stream;try{stream=await navigator.mediaDevices.getUserMedia({audio:{echoCancellation:true,noiseSuppression:true}})}catch(e){return toast(e&&e.name==="NotAllowedError"?"Mikrofon izni verilmedi. Tarayıcı ayarlarından bu siteye mikrofon izni ver.":"Mikrofon açılamadı.")}
 const types=["audio/webm;codecs=opus","audio/mp4","audio/ogg;codecs=opus","audio/webm"];const mt=types.find(t=>MediaRecorder.isTypeSupported&&MediaRecorder.isTypeSupported(t))||"";
 let mr;try{mr=new MediaRecorder(stream,mt?{mimeType:mt,audioBitsPerSecond:32000}:{audioBitsPerSecond:32000})}catch{mr=new MediaRecorder(stream)}
 const chunks=[];mr.ondataavailable=e=>{if(e.data&&e.data.size)chunks.push(e.data)};
 REC={mr,stream,chunks,start:now(),key:S.route.params.key};mr.start(250);vib(30);
 const f=$("#composer");if(f)f.innerHTML=`<button type="button" class="ib" data-act="reccancel" aria-label="Kaydı iptal et">${I("trash")}</button><div class="rec"><i class="dot"></i><span>Kaydediliyor</span><span id="recT" class="mono" style="margin-left:auto;font-size:.85rem">0:00</span></div><button type="button" class="send" data-act="recsend" aria-label="Sesli mesajı gönder">${I("send")}</button>`;
 REC.timer=setInterval(()=>{if(!REC)return;const x=(now()-REC.start)/1000;const t=$("#recT");if(t)t.textContent=mmss(x);if(x>=120)stopRec(true)},250)}
async function stopRec(send){if(!REC)return;const r=REC;REC=null;clearInterval(r.timer);const dur=Math.round((now()-r.start)/1000);
 await new Promise(res=>{r.mr.onstop=res;try{r.mr.stop()}catch{res()}setTimeout(res,1500)});r.stream.getTracks().forEach(t=>t.stop());
 if(S.route.name==="chat"&&S.route.params.key===r.key)render(false);
 if(!send)return;if(dur<1)return toast("Çok kısa oldu. Konuşup sonra gönder'e bas.");
 const blob=new Blob(r.chunks,{type:(r.mr.mimeType||"audio/webm").split(";")[0]});if(blob.size>650000)return toast("Ses kaydı çok büyük, daha kısa kaydet.");
 const durl=await readFile(blob);S.forceBottom=true;const extra=S.replyTo?{reply:S.replyTo}:{};S.replyTo=null;await sendMessage(r.key,{audio:durl,dur,text:"",...extra})}
function playAudioOld(mid){const m=S.msgs.find(x=>x.id===mid);if(!m||!m.audio)return;if(!AUD){AUD=new Audio();AUD.ontimeupdate=()=>{if(!PLAYING)return;const b=$("#ab-"+CSS.escape(PLAYING)),t=$("#at-"+CSS.escape(PLAYING));const d=AUD.duration&&isFinite(AUD.duration)?AUD.duration:(S.msgs.find(x=>x.id===PLAYING)?.dur||1);if(b)b.style.width=Math.min(100,AUD.currentTime/d*100)+"%";if(t)t.textContent=mmss(AUD.currentTime)};AUD.onended=()=>{PLAYING=null;renderMsgs()}}
 if(PLAYING===mid){AUD.pause();PLAYING=null;renderMsgs();return}
 AUD.pause();AUD.src=m.audio;PLAYING=mid;AUD.play().catch(()=>{PLAYING=null;toast("Bu ses bu cihazda çalınamadı.")});renderMsgs()}
/* ---- arama: WebRTC, sinyal Firestore üzerinden ---- */
const ICE={iceServers:[{urls:["stun:stun.l.google.com:19302","stun:stun1.l.google.com:19302","stun:stun2.l.google.com:19302"]}]};
let CALL=null,toneT=null,vibT=null;
function callLabel(c,mine){if(!c)return"";const t=c.video?"Görüntülü arama":"Sesli arama";if(c.status==="ok")return`${t} · ${mmss(c.dur)}`;if(c.status==="declined")return mine?`${t} · reddedildi`:`${t} · reddettin`;if(c.status==="canceled")return mine?`${t} · iptal edildi`:`Cevapsız ${t.toLocaleLowerCase("tr")}`;return mine?`${t} · cevap yok`:`Cevapsız ${t.toLocaleLowerCase("tr")}`}
const callSupported=()=>!!(window.RTCPeerConnection&&navigator.mediaDevices&&navigator.mediaDevices.getUserMedia);
function getMedia(video,facing="user"){return navigator.mediaDevices.getUserMedia({audio:{echoCancellation:true,noiseSuppression:true},video:video?{facingMode:facing,width:{ideal:640},height:{ideal:480}}:false})}
function mediaErr(e){console.warn(e);toast(e&&e.name==="NotAllowedError"?"Mikrofon/kamera izni verilmedi. Tarayıcı ayarlarından bu siteye izin ver.":e&&e.name==="NotFoundError"?"Mikrofon ya da kamera bulunamadı.":"Mikrofon/kamera açılamadı.")}
function newPC(id){const{F,db}=FB;const pc=new RTCPeerConnection(ICE);
 pc.onicecandidate=e=>{if(e.candidate)F.addDoc(F.collection(db,"calls",id,"cands"),{from:S.uid,c:e.candidate.toJSON(),at:Date.now()}).catch(()=>{})};
 pc.ontrack=e=>{if(!CALL||CALL.pc!==pc)return;CALL.remote=e.streams&&e.streams[0]?e.streams[0]:new MediaStream([e.track]);attachStreams()};
 pc.onconnectionstatechange=()=>{if(!CALL||CALL.pc!==pc)return;const st=pc.connectionState;
  if(st==="connected"&&CALL.status!=="connected"){CALL.status="connected";CALL.start=now();stopTone();vibStop();clearTimeout(CALL.discT);CALL.tick=setInterval(updCallStatus,1000);renderCall()}
  else if(st==="failed")endCall(true,"Bağlantı kurulamadı. İkiniz de Wi-Fi'ye bağlanıp tekrar deneyin.");
  else if(st==="disconnected"){clearTimeout(CALL.discT);CALL.discT=setTimeout(()=>{if(CALL&&CALL.pc===pc&&pc.connectionState!=="connected")endCall(true,"Bağlantı koptu.")},10000)}};
 return pc}
function listenCands(){const c=CALL;const{F,db}=FB;c.pend=c.pend||[];
 c.unsubs.push(F.onSnapshot(F.collection(db,"calls",c.id,"cands"),s=>{for(const ch of s.docChanges()){if(ch.type!=="added")continue;const d=ch.doc.data();if(!d||d.from===S.uid||CALL!==c)continue;const ic=new RTCIceCandidate(d.c);if(c.pc&&c.pc.remoteDescription)c.pc.addIceCandidate(ic).catch(e=>console.warn(e));else c.pend.push(ic)}}))}
function flushCands(){const c=CALL;if(!c||!c.pc)return;const p=c.pend||[];c.pend=[];p.forEach(ic=>c.pc.addIceCandidate(ic).catch(()=>{}))}
async function startCall(uid,video){if(!guard())return;if(S.mode!=="cloud")return toast("Arama için Firebase bağlantısı gerekiyor.");if(!callSupported())return toast("Bu tarayıcı aramayı desteklemiyor. Chrome ya da Safari'yi dene.");if(CALL)return toast("Zaten bir aramadasın.");if(BOT[uid])return toast("Botlar aranamaz.");
 let stream;try{stream=await getMedia(video)}catch(e){return mediaErr(e)}
 const{F,db}=FB;const ref=F.doc(F.collection(db,"calls"));const id=ref.id;
 const c=CALL={id,ref,peer:uid,video:!!video,role:"caller",status:"ringing",stream,unsubs:[],start:0,mic:true,cam:!!video,facing:"user",pend:[]};
 const pc=newPC(id);c.pc=pc;stream.getTracks().forEach(t=>pc.addTrack(t,stream));
 showCallUI();listenCands();
 try{const offer=await pc.createOffer();await pc.setLocalDescription(offer);await F.setDoc(ref,{from:S.uid,to:uid,video:!!video,status:"ringing",offer:{type:offer.type,sdp:offer.sdp},at:Date.now()})}catch(e){console.warn(e);c.outcome="failed";return endCall(false,e&&e.code==="permission-denied"?"Arama kuralları eksik. Firestore kurallarını güncelle.":"Arama başlatılamadı.")}
 startTone("back");
 c.unsubs.push(F.onSnapshot(ref,async s=>{if(CALL!==c)return;const d=s.exists()?s.data():null;if(!d){endCall(false);return}
  if(d.answer&&!pc.currentRemoteDescription){try{await pc.setRemoteDescription(d.answer);flushCands();if(c.status==="ringing"){c.status="connecting";stopTone();renderCall()}}catch(e){console.warn(e)}}
  if(d.status==="declined"){c.outcome="declined";endCall(false,"Arama reddedildi.")}else if(d.status==="ended")endCall(false,"Arama bitti.")}));
 c.noAns=setTimeout(()=>{if(CALL===c&&c.status==="ringing"){c.outcome="missed";F.updateDoc(ref,{status:"missed"}).catch(()=>{});endCall(false,"Cevap yok.")}},40000)}
function listenCalls(){const{F,db}=FB;const seen=new Set();
 return F.onSnapshot(F.query(F.collection(db,"calls"),F.where("to","==",S.uid)),s=>{for(const ch of s.docChanges()){const id=ch.doc.id;const d=ch.doc.data()||{};
  if(ch.type==="removed"){if(CALL&&CALL.id===id)endCall(false);continue}
  if(d.status==="ringing"&&!seen.has(id)&&Date.now()-d.at<45000){seen.add(id);if(CALL||(isChild(S.uid)&&!childCanDM(d.from))){F.updateDoc(F.doc(db,"calls/"+id),{status:"declined"}).catch(()=>{});continue}incomingCall(id,d)}
  else if(CALL&&CALL.id===id&&(d.status==="ended"||d.status==="missed"))endCall(false,d.status==="missed"?"Cevapsız arama.":"Arama bitti.")}},e=>console.warn("calls",e))}
function incomingCall(id,d){const{F,db}=FB;CALL={id,ref:F.doc(db,"calls/"+id),peer:d.from,video:!!d.video,role:"callee",status:"incoming",offer:d.offer,unsubs:[],start:0,mic:true,cam:!!d.video,facing:"user",pend:[]};
 const c=CALL;c.unsubs.push(F.onSnapshot(c.ref,s=>{if(CALL!==c)return;const x=s.exists()?s.data():null;if(!x||x.status==="ended"||x.status==="missed")endCall(false,x&&x.status==="ended"&&c.status!=="incoming"?"Arama bitti.":"Cevapsız arama.")}));
 showCallUI();startTone("ring");vibLoop()}
async function acceptCall(){const c=CALL;if(!c||c.status!=="incoming")return;stopTone();vibStop();c.status="connecting";renderCall();
 let stream;try{stream=await getMedia(c.video)}catch(e){mediaErr(e);return declineCall()}
 if(CALL!==c){stream.getTracks().forEach(t=>t.stop());return}
 c.stream=stream;const pc=newPC(c.id);c.pc=pc;stream.getTracks().forEach(t=>pc.addTrack(t,stream));listenCands();
 try{await pc.setRemoteDescription(c.offer);flushCands();const ans=await pc.createAnswer();await pc.setLocalDescription(ans);await FB.F.updateDoc(c.ref,{answer:{type:ans.type,sdp:ans.sdp},status:"accepted"})}catch(e){console.warn(e);return endCall(true,"Arama bağlanamadı.")}
 renderCall()}
function declineCall(){const c=CALL;if(!c)return;FB.F.updateDoc(c.ref,{status:"declined"}).catch(()=>{});endCall(false)}
function endCall(notify,msg){const c=CALL;if(!c)return;const wasLive=c.status==="connected";const dur=c.start?Math.round((now()-c.start)/1000):0;CALL=null;
 stopTone();vibStop();clearTimeout(c.noAns);clearTimeout(c.discT);clearInterval(c.tick);
 c.unsubs.forEach(u=>{try{u()}catch{}});try{c.pc&&c.pc.close()}catch{}
 if(c.stream)c.stream.getTracks().forEach(t=>t.stop());
 if(notify&&c.ref)FB.F.updateDoc(c.ref,{status:"ended"}).catch(()=>{});
 if(c.role==="caller"&&c.outcome!=="failed"){const st=wasLive?"ok":(c.outcome||"canceled");Promise.resolve(sendMessage("u:"+c.peer,{call:{video:c.video,status:st,dur}})).catch(()=>{});setTimeout(()=>FB.F.deleteDoc(c.ref).catch(()=>{}),5000)}
 closeLayer("call");if(msg)toast(msg)}
function showCallUI(){openLayer("call",`<div class="call" id="callBox"></div>`,{noScrim:true});renderCall()}
function renderCall(){const box=$("#callBox");const c=CALL;if(!box||!c)return;const p=P(c.peer);const live=c.status==="connected";
 const st={ringing:"Çalıyor…",incoming:c.video?"Görüntülü arama geliyor":"Sesli arama geliyor",connecting:"Bağlanıyor…",connected:mmss(c.start?(now()-c.start)/1000:0)}[c.status]||"";
 box.className="call"+(c.video?" vid":"")+(live?" live":"");
 box.innerHTML=`${c.video?`<video id="rv" autoplay playsinline></video><video id="lv" autoplay playsinline muted ${c.stream?"":"hidden"} style="${c.facing==="user"?"":"transform:none"}"></video>`:`<audio id="ra" autoplay></audio>`}
 <div class="who">${c.video&&live?"":avatar(c.peer,112,{click:false,ring:false,online:false})}<b>${esc(p.name)}</b><span id="callSt">${esc(st)}</span></div>
 <div class="ctrls">${c.status==="incoming"?`<span class="lbl2"><button class="cb red" data-cact="decline" aria-label="Reddet">${I("hangup")}</button>Reddet</span><span class="lbl2"><button class="cb green pulse" data-cact="accept" aria-label="Kabul et">${I(c.video?"video":"phone")}</button>Kabul et</span>`:`<span class="lbl2"><button class="cb ${c.mic?"":"on"}" data-cact="mic" aria-label="Mikrofon">${I(c.mic?"mic":"micoff")}</button>${c.mic?"Sessize al":"Sesi aç"}</span>${c.video?`<span class="lbl2"><button class="cb ${c.cam?"":"on"}" data-cact="cam" aria-label="Kamera">${I(c.cam?"video":"camoff")}</button>Kamera</span><span class="lbl2"><button class="cb" data-cact="flip" aria-label="Kamerayı çevir">${I("flip")}</button>Çevir</span>`:""}<span class="lbl2"><button class="cb red" data-cact="end" aria-label="Aramayı kapat">${I("hangup")}</button>Kapat</span>`}</div>
 ${c.status==="ringing"?`<div class="note2">Arkadaşının Kadraj'ı o an açık olmalı.</div>`:""}`;
 attachStreams()}
function attachStreams(){const c=CALL;if(!c)return;const rv=$("#rv"),lv=$("#lv"),ra=$("#ra");
 if(c.remote){if(rv&&rv.srcObject!==c.remote){rv.srcObject=c.remote;rv.play().catch(()=>{})}if(ra&&ra.srcObject!==c.remote){ra.srcObject=c.remote;ra.play().catch(()=>{})}}
 if(lv&&c.stream&&lv.srcObject!==c.stream){lv.hidden=false;lv.srcObject=c.stream;lv.play().catch(()=>{})}}
function updCallStatus(){const e=$("#callSt");if(e&&CALL&&CALL.start)e.textContent=mmss((now()-CALL.start)/1000)}
async function callAction(a){const c=CALL;if(!c)return;
 if(a==="accept")return acceptCall();if(a==="decline")return declineCall();
 if(a==="end"){if(c.role==="caller"&&c.status==="ringing")c.outcome="canceled";return endCall(true)}
 if(a==="mic"){c.mic=!c.mic;c.stream&&c.stream.getAudioTracks().forEach(t=>t.enabled=c.mic);return renderCall()}
 if(a==="cam"){c.cam=!c.cam;c.stream&&c.stream.getVideoTracks().forEach(t=>t.enabled=c.cam);return renderCall()}
 if(a==="flip"){try{const facing=c.facing==="user"?"environment":"user";const ns=await navigator.mediaDevices.getUserMedia({video:{facingMode:facing,width:{ideal:640},height:{ideal:480}}});const nt=ns.getVideoTracks()[0];const sender=c.pc&&c.pc.getSenders().find(x=>x.track&&x.track.kind==="video");if(sender)await sender.replaceTrack(nt);c.stream.getVideoTracks().forEach(t=>{c.stream.removeTrack(t);t.stop()});c.stream.addTrack(nt);c.facing=facing;renderCall()}catch(e){toast("Kamera çevrilemedi.")}}}
function startTone(kind){stopTone();let ctx;try{ctx=Music.ctx||(Music.ctx=new(window.AudioContext||window.webkitAudioContext)());ctx.resume()}catch{return}
 const beep=()=>{const t=ctx.currentTime;const ring=kind==="ring";[ring?660:440,ring?880:480].forEach(f=>{const o=ctx.createOscillator(),g=ctx.createGain();o.frequency.value=f;g.gain.setValueAtTime(0,t);g.gain.linearRampToValueAtTime(ring?.09:.05,t+.04);g.gain.setValueAtTime(ring?.09:.05,t+(ring?.7:1.1));g.gain.linearRampToValueAtTime(0,t+(ring?.8:1.2));o.connect(g);g.connect(ctx.destination);o.start(t);o.stop(t+1.3)})};
 beep();toneT=setInterval(beep,kind==="ring"?1800:3500)}
function stopTone(){clearInterval(toneT);toneT=null}
function vibLoop(){vibStop();vib([500,300,500]);vibT=setInterval(()=>vib([500,300,500]),2200)}
function vibStop(){clearInterval(vibT);vibT=null;try{navigator.vibrate&&navigator.vibrate(0)}catch{}}
/* ---- çevrimdışı uyarısı ---- */
function netBar(){let b=document.getElementById("netbar");if(navigator.onLine){if(b)b.remove();return}if(!b){b=document.createElement("div");b.id="netbar";b.className="netbar";b.textContent="İnternet bağlantısı yok. Gönderdiklerin bağlantı gelince iletilecek.";document.body.appendChild(b)}}
addEventListener("online",netBar);addEventListener("offline",netBar);setTimeout(netBar,1500);

async function sendMessage(key,payload){const k=keyInfo(key);if(k.type==="dm"&&!childGate(k.uid))return;if(isChild(S.uid)&&payload&&payload.text)payload={...payload,text:cleanText(payload.text)};if(k.type==="bot"){if(S.guest&&!BOT[k.uid].ai)return sendToBot(k.uid,payload);Promise.resolve(sendToBot(k.uid,payload)).catch(()=>{});return true}if(!guard())return;
 const at=now();const mid=at.toString(36)+Math.random().toString(36).slice(2,6);const msg={from:S.uid,at,...payload};if(!msg.text)delete msg.text;
 if(S.route.name==="chat"&&chatKey===k.cid){S.msgs=[...S.msgs,{id:mid,...msg}];renderMsgs()}
 if(!await write(()=>DB.set(`chats/${k.cid}/msgs/${mid}`,msg))){if(S.msgs.some(x=>x.id===mid)){S.msgs=S.msgs.filter(x=>x.id!==mid);renderMsgs()}return false}
 const preview=payload.text||(payload.mus?"Şarkı: "+String(payload.mus.t||""):payload.gpoll?"Anket: "+String(payload.gpoll.q||""):payload.once?"Tek seferlik fotoğraf":payload.post?"Bir paylaşım gönderdi":payload.img?"Fotoğraf":payload.video?"Video":payload.audio?"Sesli mesaj":payload.call?callLabel(payload.call,false):"");
 if(k.type==="meydan")await write(()=>DB.set("chats/meydan",{last:{text:preview,from:S.uid,at},updatedAt:at}),{quiet:true});
 else if(k.type==="group")await write(()=>DB.update("chats/"+k.cid,{last:{text:preview,from:S.uid,at},updatedAt:at,reads:{[S.uid]:at}}),{quiet:true});
 else{const meta={members:[S.uid,k.uid].sort(),last:{text:preview,from:S.uid,at},updatedAt:at,reads:{[S.uid]:at}};await write(()=>S.chats[k.cid]?DB.update("chats/"+k.cid,meta):DB.set("chats/"+k.cid,meta),{quiet:true})}
 if((k.type==="meydan"||k.type==="group")&&/@rota\b/i.test(payload.text||""))rotaInRoom(key,k);return true}
async function rotaInRoom(key,k){S.botTyping="bot:rota@"+key;renderMsgs();let reply=null;
 try{const sample=S.caps.sample;if(sample){const tr=S.msgs.slice(-14).map(m=>`${P(m.from).name}: ${m.text||"[paylaşım]"}`).join("\n");const r=await sample(`${ROTA_SYS}\n\nŞu an "${k.type==="meydan"?"Meydan (herkese açık ortak sohbet)":"bir grup sohbeti"}" içindesin ve biri seni @rota diye çağırdı. Konuşma:\n${tr}\n\nRota olarak kısa (1-4 cümle) yanıt ver. Sadece yanıt metnini yaz.`,{cache:false,modelTier:"quick"});reply=(r&&r.text||"").trim()}}catch(e){console.warn(e)}
 if(!reply)reply=fallbackRota(S.msgs[S.msgs.length-1]?.text||"");S.botTyping=null;
 const at=now();const mid=at.toString(36)+"rota";const msg={from:"bot:rota",text:reply,at};if(chatKey===k.cid){S.msgs=[...S.msgs,{id:mid,...msg}];renderMsgs()}
 await write(()=>DB.set(`chats/${k.cid}/msgs/${mid}`,msg),{quiet:true});
 if(k.type==="meydan")await write(()=>DB.set("chats/meydan",{last:{text:reply.slice(0,80),from:"bot:rota",at},updatedAt:at}),{quiet:true});else await write(()=>DB.update("chats/"+k.cid,{last:{text:reply.slice(0,80),from:"bot:rota",at},updatedAt:at}),{quiet:true})}
async function attachPhoto(){const r=await pickImage({title:"Fotoğraf gönder"});if(!r)return;const iw=r.img.naturalWidth||r.img.width,ih=r.img.naturalHeight||r.img.height;const s=Math.min(1,900/Math.max(iw,ih));const c=document.createElement("canvas");c.width=Math.round(iw*s);c.height=Math.round(ih*s);c.getContext("2d").drawImage(r.img,0,0,c.width,c.height);S.forceBottom=true;const extra=S.replyTo?{reply:S.replyTo}:{};S.replyTo=null;drawReply();await sendMessage(S.route.params.key,{img:encode(c,150000),text:"",...extra})}
let typingT=null,typingLast=0;
function typingPing(key){const room=S.caps.room;const k=keyInfo(key);if(!room||k.type==="bot")return;if(now()-typingLast>2500){typingLast=now();room.presence({uid:S.uid,typing:k.cid}).catch(()=>{})}clearTimeout(typingT);typingT=setTimeout(typingStop,4000)}
function typingStop(){const room=S.caps.room;clearTimeout(typingT);if(!room||!typingLast)return;typingLast=0;room.presence({uid:S.uid,typing:null}).catch(()=>{})}
async function nudge(uid){if(!guard())return;const room=S.caps.room;if(!room)return toast("Dürtme için canlı bağlantı yok.");try{await room.emit("nudge",{to:uid,from:S.uid});vib(20);toast(`@${P(uid).username} dürtüldü`,uid)}catch(e){toast("Dürtme gönderilemedi. Düzenleyen yetkisi gerekiyor olabilir.")}}

function msgMenu(mid){const key=S.route.params.key;const k=keyInfo(key);const m=S.msgs.find(x=>x.id===mid);if(!m||m.del)return;vib(20);const mine=m.from===S.uid;const canAll=mine||(S.admin&&k.type!=="dm");const canEdit=mine&&m.text&&!m.audio&&!m.game&&!m.call;
 const l=sheet("menu","",`${k.type!=="bot"?`<div class="rxpick" role="group" aria-label="Tepki seç">${REACTS.map(([t,lb])=>`<button type="button" data-rxp="${t}" class="${msgReacts(m)[S.uid]===t?"on":""}" aria-label="${lb}">${rxSvg(t)}</button>`).join("")}</div>`:""}<button class="opt" id="mmR">${I("reply")}Yanıtla</button>${m.text||m.img||m.post||m.audio?`<button class="opt" id="mmF">${I("send")}İlet</button>`:""}${msgCopyText(m)?`<button class="opt" id="mmC">${I("copy")}Metni kopyala</button>`:""}${canEdit?`<button class="opt" id="mmE">${I("edit")}Düzenle</button>`:""}<button class="opt" id="mmM">${I("eye")}Benden sil</button>${canAll?`<button class="opt red" id="mmD">${I("trash")}Herkesten sil</button>`:""}<button class="opt" data-act="close">${I("close")}Vazgeç</button>`);
 $("#mmR",l).onclick=()=>{closeLayer("menu");S.replyTo={mid,from:m.from,text:msgPreview(m).slice(0,80)};drawReply();const i=$("#msgIn");if(i)i.focus()};const fw=$("#mmF",l);if(fw)fw.onclick=()=>{closeLayer("menu");fwdSheet(m)};$$("[data-rxp]",l).forEach(b=>b.onclick=()=>{closeLayer("menu");setReact(mid,b.dataset.rxp)});const c=$("#mmC",l);if(c)c.onclick=()=>{closeLayer("menu");copyText(msgCopyText(m),"Mesaj kopyalandı")};
 const ed=$("#mmE",l);if(ed)ed.onclick=()=>{closeLayer("menu");const l2=sheet("medit","Mesajı düzenle",`<form class="form" id="meF"><textarea class="in" id="meT" maxlength="2000">${esc(m.text)}</textarea><button class="btn block">Kaydet</button></form>`);const ta=$("#meT",l2);ta.focus();ta.setSelectionRange(ta.value.length,ta.value.length);
  $("#meF",l2).onsubmit=async ev=>{ev.preventDefault();if(!guard())return;const v=kidClean(ta.value.trim());if(!v||v===m.text){closeLayer("medit");return}const t=now();S.msgs=S.msgs.map(x=>x.id===mid?{...x,text:v,edited:t}:x);renderMsgs();closeLayer("medit");
   if(await write(()=>DB.update(`chats/${k.cid}/msgs/${mid}`,{text:v,edited:t}))){const last=S.msgs[S.msgs.length-1];if(last&&last.id===mid)await updateLast(k,last)}}};
 $("#mmM",l).onclick=()=>{closeLayer("menu");S.hidden=S.hidden||{msgs:{},chats:{}};S.hidden.msgs={...(S.hidden.msgs||{}),[mid]:now()};renderMsgs();saveHidden();toast("Mesaj senden silindi")};
 const dl=$("#mmD",l);if(dl)dl.onclick=()=>{closeLayer("menu");dialog("Herkesten silinsin mi?","Mesaj sohbetteki herkes için kalıcı olarak silinir.",[{label:"Herkesten sil",cls:"danger",fn:async()=>{const wasLast=S.msgs[S.msgs.length-1]?.id===mid;S.msgs=S.msgs.filter(x=>x.id!==mid);renderMsgs();
  if(await write(()=>DB.del(`chats/${k.cid}/msgs/${mid}`))){if(wasLast)await updateLast(k,S.msgs[S.msgs.length-1]||null);toast("Mesaj silindi")}}},{label:"Vazgeç"}])}}
