/* büyük videoları telefonda küçült (sahne yükleme) */
function compressVideo(file,{maxS=30,limit=VMAX,onProg,maxSide=854}={}){return new Promise((resolve,reject)=>{const url=URL.createObjectURL(file);const v=document.createElement("video");v.playsInline=true;v.preload="auto";v.setAttribute("playsinline","");
 let raf=0,mr=null,chunks=[],done=false,ac=null,dur=maxS,cw=0,ch=0,ctx=null;
 const clean=()=>{cancelAnimationFrame(raf);try{v.pause()}catch{}try{ac&&ac.close()}catch{}v.removeAttribute("src");try{v.load()}catch{}URL.revokeObjectURL(url)};
 const fail=msg=>{if(done)return;done=true;try{mr&&mr.state!=="inactive"&&mr.stop()}catch{}clean();reject(new Error(msg))};
 v.onerror=()=>fail("Bu video açılamadı. Telefonun video biçimi desteklenmiyor olabilir; “Kamerayla çek” ile dene.");
 v.onloadedmetadata=async()=>{const W=v.videoWidth,Hh=v.videoHeight;if(!W||!Hh)return fail("Video okunamadı.");const s=Math.min(1,maxSide/Math.max(W,Hh));cw=Math.round(W*s/2)*2;ch=Math.round(Hh*s/2)*2;
  const cv=document.createElement("canvas");cv.width=cw;cv.height=ch;ctx=cv.getContext("2d");dur=Math.min(maxS,isFinite(v.duration)&&v.duration>0?v.duration:maxS);
  let stream;try{stream=cv.captureStream(30)}catch{return fail("Bu tarayıcı videoyu küçültemiyor. “Kamerayla çek”i dene.")}
  try{const AC=window.AudioContext||window.webkitAudioContext;ac=new AC();const src=ac.createMediaElementSource(v);const dst=ac.createMediaStreamDestination();src.connect(dst);dst.stream.getAudioTracks().forEach(t=>stream.addTrack(t));ac.resume&&ac.resume()}catch{v.muted=true}
  const types=["video/mp4;codecs=avc1","video/mp4","video/webm;codecs=vp9,opus","video/webm;codecs=vp8,opus","video/webm"];const mt=types.find(t=>window.MediaRecorder&&MediaRecorder.isTypeSupported&&MediaRecorder.isTypeSupported(t))||"";
  const br=Math.round(Math.max(350000,Math.min(maxSide>854?2500000:1100000,(limit*0.82*8)/dur-56000)));
  try{mr=new MediaRecorder(stream,mt?{mimeType:mt,videoBitsPerSecond:br,audioBitsPerSecond:48000}:{videoBitsPerSecond:br})}catch{return fail("Bu tarayıcı video kaydedemiyor.")}
  mr.ondataavailable=e=>{if(e.data&&e.data.size)chunks.push(e.data)};
  mr.onstop=()=>{if(done)return;done=true;clean();const type=(mr.mimeType||mt||"video/webm").split(";")[0];const blob=new Blob(chunks,{type});if(!blob.size)return reject(new Error("Video hazırlanamadı."));resolve(new File([blob],"flick."+(type.includes("mp4")?"mp4":"webm"),{type}))};
  const draw=()=>{if(done)return;try{ctx.drawImage(v,0,0,cw,ch)}catch{}onProg&&onProg(Math.min(1,v.currentTime/dur));if(v.currentTime>=dur-.04||v.ended){try{v.pause();mr.state!=="inactive"&&mr.stop()}catch{}return}raf=requestAnimationFrame(draw)};
  v.onended=()=>{try{mr.state!=="inactive"&&mr.stop()}catch{}};
  try{await v.play()}catch{v.muted=true;try{await v.play()}catch{return fail("Video oynatılamadı.")}}
  mr.start(500);draw()};
 v.src=url})}
