/* ============ Satranç ============ */
const CC=ChessCore();const PIMG=pieceSvgs();
const CLEVELS=[{n:"Çaylak",r:400,all:true,depth:2,sigma:170,bl:.22},{n:"Acemi",r:800,all:true,depth:2,sigma:60,bl:.07},{n:"Orta",r:1200,all:true,depth:3,sigma:18,bl:.02},{n:"Zor",r:1600,depth:5,time:1400},{n:"Usta",r:2000,depth:8,time:2800}];
const CTHEMES={kadraj:["#e6efe9","#6f9f8d","Kadraj"],yesil:["#ebecd0","#779556","Klasik"],ahsap:["#f0d9b5","#b58863","Ahşap"],gece:["#dee3e6","#8ca2ad","Gece"]};
const PNAME={1:"piyon",2:"at",3:"fil",4:"kale",5:"vezir",6:"şah"};
const REASON={mat:"Şah mat",pat:"Pat (hamle yok)","50 hamle kuralı":"50 hamle kuralı","yetersiz taş":"Mat için yeterli taş yok","üç kez tekrar":"Aynı konum üç kez tekrarlandı",teslim:"Teslim olundu",anlasma:"Anlaşmalı beraberlik",iptal:"Oyun iptal edildi"};
const sleep=ms=>new Promise(r=>setTimeout(r,ms));
const gauss=()=>{let u=0,v=0;while(!u)u=Math.random();while(!v)v=Math.random();return Math.sqrt(-2*Math.log(u))*Math.cos(2*Math.PI*v)};
/* motor: Web Worker içinde (arayüz donmasın) */
let CWK=null,CWN=0;const CWQ={};
const packR=r=>({u:r.move?CC.uci(r.move):null,score:r.score,all:r.all?r.all.map(x=>({u:CC.uci(x.m),s:x.s})):null});
function engineRun(fen,o){return new Promise(res=>{const id=++CWN;const local=()=>{const g=CC.fromFen(fen);res(packR(CC.search(g,o)))};
 if(CWK===null){try{const src=`const C=(${ChessCore.toString()})();onmessage=e=>{const{id,fen,o}=e.data;const g=C.fromFen(fen);const r=C.search(g,o);postMessage({id,r:{u:r.move?C.uci(r.move):null,score:r.score,all:r.all?r.all.map(x=>({u:C.uci(x.m),s:x.s})):null}})}`;
  CWK=new Worker(URL.createObjectURL(new Blob([src],{type:"text/javascript"})));CWK.onmessage=e=>{const q=CWQ[e.data.id];if(q){delete CWQ[e.data.id];clearTimeout(q.t);q.res(e.data.r)}};CWK.onerror=()=>{CWK=false;for(const k of Object.keys(CWQ)){const q=CWQ[k];delete CWQ[k];clearTimeout(q.t);q.local()}}}catch{CWK=false}}
 if(CWK){CWQ[id]={res,local,t:setTimeout(()=>{if(CWQ[id]){delete CWQ[id];local()}},(o.time||2000)+9000)};CWK.postMessage({id,fen,o});return}
 setTimeout(local,20)})}
/* ses */
const CSND={ctx:null,play(kind){if(settings.chessSound===false)return;let c;try{c=this.ctx||(this.ctx=new(window.AudioContext||window.webkitAudioContext)());c.resume&&c.resume()}catch{return}const t=c.currentTime;
 const click=(t0,v,f)=>{const n=c.createBuffer(1,Math.floor(c.sampleRate*.06),c.sampleRate),d=n.getChannelData(0);for(let i=0;i<d.length;i++)d[i]=(Math.random()*2-1)*Math.pow(1-i/d.length,4);const s=c.createBufferSource(),bp=c.createBiquadFilter(),g=c.createGain();s.buffer=n;bp.type="bandpass";bp.frequency.value=f||1500;bp.Q.value=1.2;g.gain.value=v;s.connect(bp);bp.connect(g);g.connect(c.destination);s.start(t0)};
 const ping=(t0,f,d,v)=>{const o=c.createOscillator(),g=c.createGain();o.type="sine";o.frequency.value=f;g.gain.setValueAtTime(0,t0);g.gain.linearRampToValueAtTime(v,t0+.01);g.gain.exponentialRampToValueAtTime(.001,t0+d);o.connect(g);g.connect(c.destination);o.start(t0);o.stop(t0+d+.05)};
 if(kind==="move")click(t,1.6,1300);else if(kind==="capture"){click(t,2.2,900);click(t+.05,1.4,1700)}else if(kind==="castle"){click(t,1.4,1300);click(t+.09,1.4,1200)}
 else if(kind==="check"){click(t,1.6,1300);ping(t+.02,880,.35,.12)}else if(kind==="end"){[523,659,784].forEach((f,i)=>ping(t+i*.12,f,.6,.1))}else if(kind==="lose"){[392,330,262].forEach((f,i)=>ping(t+i*.14,f,.6,.1))}else if(kind==="bad")ping(t,180,.18,.12)}};
/* Rota'nın animasyonlu yüzü */
let RBN=0;
function botFace(size=56){const id="rb"+(++RBN);return`<span class="rbot" style="--s:${size}px"><svg viewBox="0 0 120 120" aria-hidden="true"><defs><linearGradient id="${id}" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#19b08e"/><stop offset="1" stop-color="#0a4f73"/></linearGradient></defs>
<g class="rb-all"><line x1="60" y1="24" x2="60" y2="11" stroke="#0a4f73" stroke-width="4" stroke-linecap="round"/><g class="rb-needle"><path d="M60 0 65.5 10 60 20 54.5 10z" fill="#ffcf4d" stroke="#0a4f73" stroke-width="2"/></g>
<circle cx="13" cy="62" r="7" fill="#ffcf4d"/><circle cx="107" cy="62" r="7" fill="#ffcf4d"/>
<rect x="15" y="23" width="90" height="82" rx="32" fill="url(#${id})"/><rect x="25" y="37" width="70" height="52" rx="21" fill="#082a24"/>
<g class="rb-eyes"><g class="eo"><ellipse class="eye" cx="45" cy="59" rx="7" ry="8.5" fill="#d9fff3"/><ellipse class="eye" cx="75" cy="59" rx="7" ry="8.5" fill="#d9fff3"/></g><g class="eh"><path d="M37 61q8-10 16 0M67 61q8-10 16 0" stroke="#d9fff3" stroke-width="4.5" fill="none" stroke-linecap="round"/></g><g class="es"><path d="M37 52l14 4M83 52l-14 4" stroke="#ffcf4d" stroke-width="3.5" stroke-linecap="round"/></g></g>
<g class="rb-m"><path class="m0" d="M50 76q10 6 20 0" stroke="#3fd3ab" stroke-width="4" fill="none" stroke-linecap="round"/><path class="m1" d="M46 74q14 12 28 0z" fill="#3fd3ab"/><path class="m2" d="M50 80q10-7 20 0" stroke="#3fd3ab" stroke-width="4" fill="none" stroke-linecap="round"/><ellipse class="m3" cx="60" cy="78" rx="5" ry="6" fill="#3fd3ab"/></g>
<circle class="rb-ch" cx="33" cy="80" r="5" fill="#ff8fa3" opacity=".55"/><circle class="rb-ch" cx="87" cy="80" r="5" fill="#ff8fa3" opacity=".55"/></g></svg></span>`}
/* durum */
let CH=null,CHEL={},CDRAG=null;
function chNew(mode,o={}){const g=CC.fromFen(CC.START);CH={mode,g,moves:[],keys:[CC.toFen(g,true)],my:o.my||0,level:o.level??1,flip:(o.my||0)===8,sel:-1,targets:[],last:null,over:null,thinking:false,eval:0,gid:o.gid||null,mood:"",view:null,hint:null,rated:false,doc:null,bubble:null};return CH}
function chApply(m,q){const san=CC.san(CH.g,m);CC.make(CH.g,m);CH.moves.push({u:CC.uci(m),san,m,q:q||""});CH.keys.push(CC.toFen(CH.g,true));CH.last={f:m.f,t:m.t};CH.sel=-1;CH.targets=[];CH.hint=null;
 const st=CC.status(CH.g,CH.keys);if(st.over&&!CH.over)CH.over=st;return st}
function chReplay(list){for(const u of list){const m=CC.fromUci(CH.g,u);if(!m)break;chApply(m)}}
function chSave(){if(!CH||CH.mode==="online")return;const k="kadraj_chess_"+CH.mode+"_"+S.uid;if(CH.over&&CH.rated)LS.del(k);else LS.set(k,{moves:CH.moves.map(x=>x.u),my:CH.my,level:CH.level,eval:CH.eval,flip:CH.flip,rated:!!CH.rated})}
function chLoad(mode){const d=LS.get("kadraj_chess_"+mode+"_"+S.uid);if(!d)return null;chNew(mode,{my:d.my,level:d.level});CH.flip=!!d.flip;chReplay(d.moves||[]);CH.eval=d.eval||0;CH.rated=!!d.rated;return CH}
function chessStats(uid){const c=(S.profiles[uid]||{}).chess||{};return{r:c.r||800,w:c.w||0,l:c.l||0,d:c.d||0,g:c.g||0}}
async function chRate(opp,score){if(S.guest||!S.canWrite)return 0;const st=chessStats(S.uid);const exp=1/(1+Math.pow(10,(opp-st.r)/400));const K=st.g<10?40:24;const nr=Math.max(100,Math.round(st.r+K*(score-exp)));
 const c={r:nr,w:st.w+(score===1?1:0),l:st.l+(score===0?1:0),d:st.d+(score===.5?1:0),g:st.g+1};S.profiles={...S.profiles,[S.uid]:{...S.profiles[S.uid],chess:c}};
 write(()=>DB.update("profiles/"+S.uid,{chess:c}),{quiet:true});return nr-st.r}
const myGames=()=>Object.values(S.games||{}).filter(g=>g&&g.players&&(g.status!=="over"||now()-(g.updatedAt||0)<2*24*H)).sort((a,b)=>(b.updatedAt||0)-(a.updatedAt||0));
const gTurnUid=d=>(d.moves||[]).length%2===0?d.w:d.b;
const myTurnGames=()=>myGames().filter(d=>(d.status==="active"&&gTurnUid(d)===S.uid)||(d.status==="invite"&&d.to===S.uid)).length;
const oppOf=d=>(d.players||[]).find(u=>u!==S.uid)||d.from;

/* ---- lobi ---- */
function vChess(){const st=chessStats(S.uid);const lv=settings.chessLevel??1;const col=settings.chessColor||"w";const saved=LS.get("kadraj_chess_bot_"+S.uid);const pass=LS.get("kadraj_chess_local_"+S.uid);
 let h=`<div class="chero"><div class="chero-bot">${botFace(84)}<div class="cbub show">Bir oyuna ne dersin? Seviyeni seç, ben hazırım.</div></div></div>`;
 h+=`<div class="box cbox"><span class="lbl">Rakibin: Rota</span><div class="lvls" role="group" aria-label="Seviye">${CLEVELS.map((l,i)=>`<button class="lvl" data-clvl="${i}" aria-pressed="${lv===i}"><b>${l.n}</b><span>${l.r}</span></button>`).join("")}</div>
 <span class="lbl">Taşların</span><div class="seg">${[["w","Beyaz"],["r","Rastgele"],["b","Siyah"]].map(([v,l])=>`<button data-ccol="${v}" aria-pressed="${col===v}">${l}</button>`).join("")}</div>
 <button class="btn block" data-chs="botnew">${I("knight")}Rota'ya karşı oyna</button>${saved&&saved.moves&&saved.moves.length?`<button class="btn sec block" data-chs="botresume">Yarım kalan oyuna dön · ${CLEVELS[saved.level]?.n||""}, ${Math.ceil(saved.moves.length/2)}. hamle</button>`:""}</div>`;
 h+=`<div class="cstats"><div><b>${st.r}</b><span>Puanın</span></div><div><b>${st.w}</b><span>Galibiyet</span></div><div><b>${st.d}</b><span>Beraberlik</span></div><div><b>${st.l}</b><span>Yenilgi</span></div></div>`;
 h+=`<h3 class="sec-h"><span>Arkadaşlarınla</span></h3><div class="quick" style="grid-template-columns:1fr 1fr"><button data-chs="invite">${I("users")}Arkadaşını davet et</button><button data-chs="${pass&&pass.moves&&pass.moves.length?"passresume":"pass"}">${I("rotate")}Aynı telefonda iki kişi</button></div>`;
 if(S.gamesDenied)h+=`<div class="banner">${I("info")}<span>Arkadaşla satranç için uygulamanın sahibi Firebase kurallarını güncellemeli (games satırı).</span></div>`;
 const gs=myGames();if(gs.length)h+=`<div class="box">${gs.map(d=>{const o=oppOf(d);const p=P(o);const mine=d.status==="active"&&gTurnUid(d)===S.uid;const inv=d.status==="invite";
  const sub=d.status==="over"?(d.reason==="iptal"?"İptal edildi":d.result==="1/2"?"Berabere bitti":((d.result==="1-0")===(d.w===S.uid)?"Kazandın":"Kaybettin")):inv?(d.to===S.uid?"Seni davet etti":"Davetin bekliyor"):mine?"Sıra sende":"Rakibin düşünüyor";
  return`<button class="row" data-cgame="${esc(d.id)}">${avatar(o,44,{click:false,ring:false})}<div class="t"><div><b>${esc(p.name)}</b></div><div class="s">${esc(sub)} · ${Math.ceil((d.moves||[]).length/2)}. hamle · ${ago(d.updatedAt||d.at)}</div></div>${mine||(inv&&d.to===S.uid)?'<span class="cturn">SIRA SENDE</span>':""}</button>`}).join("")}</div>`;
 const lb=Object.values(S.profiles).filter(p=>p&&p.chess&&p.chess.g).sort((a,b)=>b.chess.r-a.chess.r).slice(0,10);
 h+=`<h3 class="sec-h"><span>Kadraj sıralaması</span>${I("trophy")}</h3>`+(lb.length?`<div class="box">${lb.map((p,i)=>`<button class="row ${p.uid===S.uid?"meh":""}" data-prof="${esc(p.uid)}"><span class="rank">${i+1}</span>${avatar(p.uid,40,{click:false,ring:false})}<div class="t"><div><b>${esc(P(p.uid).name)}</b></div><div class="s">${p.chess.w} galibiyet · ${p.chess.d} beraberlik · ${p.chess.l} yenilgi</div></div><b class="crate">${p.chess.r}</b></button>`).join("")}</div>`:`<div class="empty" style="padding:16px 24px">Henüz kimse oynamadı. İlk sıraya sen yerleş.</div>`);
 h+=`<h3 class="sec-h"><span>Tahta</span></h3><div class="cthemes">${Object.entries(CTHEMES).map(([k,[a,b,n]])=>`<button data-cth="${k}" aria-pressed="${(settings.board||"kadraj")===k}"><i style="background:linear-gradient(135deg,${a} 50%,${b} 50%)"></i>${n}</button>`).join("")}</div>`;
 return h}

/* ---- oyun ekranı ---- */
function vChessGame(){if(!CH)return`<div class="empty"><b>Oyun bulunamadı</b><button class="btn sm" data-tab="explore">Geri dön</button></div>`;const th=CTHEMES[settings.board||"kadraj"]||CTHEMES.kadraj;
 return`<div class="chess" style="--cl:${th[0]};--cd:${th[1]}"><div class="cpl" id="cplT"></div><div class="cmain"><div class="cevalbar" id="cEval"><i></i><span></span></div><div class="cboard" id="cBoard"><div class="csq" id="cSq"></div><div class="cmk" id="cMk"></div><div class="cpcs" id="cPcs"></div><svg class="carrow" id="cArrow" viewBox="0 0 800 800"></svg><div class="cov" id="cOv"></div></div></div><div class="cpl" id="cplB"></div><div class="cmoves" id="cMoves"></div><div class="cctl" id="cCtl"></div></div>`}
const sqXY=s=>{let x=s&7,y=s>>3;if(CH.flip){x=7-x;y=7-y}return[x,y]};
const tf=s=>{const[x,y]=sqXY(s);return`translate(${x*100}%,${y*100}%)`};
function chViewGame(){if(CH.view==null)return CH.g;const g=CC.fromFen(CC.START);for(let i=0;i<CH.view;i++)CC.make(g,CH.moves[i].m);return g}
function chDraw(){const bd=$("#cBoard");if(!bd||!CH)return;const th=CTHEMES[settings.board||"kadraj"]||CTHEMES.kadraj;
 let sq="";for(let y=0;y<8;y++)for(let x=0;x<8;x++){const f=CH.flip?7-x:x,r=CH.flip?7-y:y;const dark=(x+y)%2===1;sq+=`<i class="${dark?"d":"l"}">${x===0?`<em class="rk">${8-r}</em>`:""}${y===7?`<em class="fl">${"abcdefgh"[f]}</em>`:""}</i>`}
 $("#cSq").innerHTML=sq;const g=chViewGame();CHEL={};const pc=$("#cPcs");pc.innerHTML="";
 for(let s=0;s<64;s++){const p=g.b[s];if(!p)continue;const el=document.createElement("div");el.className="pc";el.style.transform=tf(s);el.innerHTML=`<img src="${PIMG[p]}" alt="" draggable="false">`;pc.appendChild(el);CHEL[s]=el}
 chMarks();chArrow();chUI()}
function chMarks(){const mk=$("#cMk");if(!mk||!CH)return;let h="";const g=chViewGame();const lm=CH.view==null?CH.last:(CH.view>0?{f:CH.moves[CH.view-1].m.f,t:CH.moves[CH.view-1].m.t}:null);
 if(lm){h+=`<i class="lm" style="transform:${tf(lm.f)}"></i><i class="lm" style="transform:${tf(lm.t)}"></i>`}
 if(CC.inCheck(g)){const k=g.k[g.turn>>3];h+=`<i class="chk" style="transform:${tf(k)}"></i>`}
 if(CH.sel>=0&&CH.view==null){h+=`<i class="sel" style="transform:${tf(CH.sel)}"></i>`;const seen=new Set();for(const m of CH.targets){if(seen.has(m.t))continue;seen.add(m.t);h+=`<i class="${m.c?"cap":"dot"}" style="transform:${tf(m.t)}"></i>`}}
 if(CH.hint){h+=`<i class="hint" style="transform:${tf(CH.hint.f)}"></i><i class="hint" style="transform:${tf(CH.hint.t)}"></i>`}
 mk.innerHTML=h}
function chArrow(){const a=$("#cArrow");if(!a)return;if(!CH||!CH.hint){a.innerHTML="";return}const c=s=>{const[x,y]=sqXY(s);return[x*100+50,y*100+50]};const[x1,y1]=c(CH.hint.f),[x2,y2]=c(CH.hint.t);const L=Math.hypot(x2-x1,y2-y1);const ux=(x2-x1)/L,uy=(y2-y1)/L;const ex=x2-ux*28,ey=y2-uy*28;
 a.innerHTML=`<line x1="${x1+ux*18}" y1="${y1+uy*18}" x2="${ex}" y2="${ey}" stroke="rgba(255,170,0,.85)" stroke-width="20" stroke-linecap="round"/><path d="M${x2} ${y2} L${ex-uy*30} ${ey+ux*30} L${ex+uy*30} ${ey-ux*30}Z" fill="rgba(255,170,0,.85)" transform="translate(${ux*4} ${uy*4})"/>`}
function chAnim(m){const pcs=CHEL;if(!$("#cBoard"))return;const mover=m.p&8;const capSq=m.fl&1?m.t+(mover?-8:8):(pcs[m.t]?m.t:-1);
 if(capSq>=0&&pcs[capSq]){const c=pcs[capSq];delete pcs[capSq];c.classList.add("gone");setTimeout(()=>c.remove(),300)}
 const el=pcs[m.f];if(el){delete pcs[m.f];el.classList.remove("drag");el.style.transform=tf(m.t);pcs[m.t]=el;el.style.zIndex=3;setTimeout(()=>el.style.zIndex="",260);if(m.pr)setTimeout(()=>{const im=el.querySelector("img");if(im)im.src=PIMG[m.pr]},170)}
 if(m.fl&2){const rf=m.t>m.f?m.t+1:m.t-2,rt=m.t>m.f?m.t-1:m.t+1;const r=pcs[rf];if(r){delete pcs[rf];r.style.transform=tf(rt);pcs[rt]=r}}}
function chSoundFor(m,st){if(st&&st.over)return CSND.play("end");if(st&&st.check)return CSND.play("check");CSND.play(m.fl&2?"castle":m.c?"capture":"move")}
/* oyuncu çubukları, hamle listesi, düğmeler */
function chMaterial(g){const cnt={0:[0,0,0,0,0,0,0],8:[0,0,0,0,0,0,0]};for(let s=0;s<64;s++){const p=g.b[s];if(p)cnt[p&8][p&7]++}const start=[0,8,2,2,2,1,1];const val=[0,1,3,3,5,9,0];
 const capBy=c=>{const o=c^8;let out=[];for(const t of[5,4,3,2,1]){const n=Math.max(0,start[t]-cnt[o][t]);for(let i=0;i<n;i++)out.push(o|t)}return out};
 const sc=c=>cnt[c].reduce((a,n,t)=>a+n*val[t],0);return{capBy,diff:sc(0)-sc(8)}}
function chPlayerBar(side){const g=CH.g;const mat=chMaterial(chViewGame());const caps=mat.capBy(side);const adv=side===0?mat.diff:-mat.diff;const turn=!CH.over&&g.turn===side&&CH.view==null;
 const capH=`<span class="ccap">${caps.map(p=>`<img src="${PIMG[p]}" alt="">`).join("")}${adv>0?`<b>+${adv}</b>`:""}</span>`;
 let who="",av="",extra="";
 if(CH.mode==="bot"&&side!==CH.my){const L=CLEVELS[CH.level];av=`<span class="cbotav ${CH.mood||""} ${CH.thinking?"thinking":""}">${botFace(46)}</span>`;who=`<b>Rota</b><span class="tag">${I("spark")}AI</span> <span class="crt">${L.n} · ${L.r}</span>`;extra=`<div class="cbub ${CH.bubble?"show":""}" id="cBub">${esc(CH.bubble||"")}</div>`}
 else if(CH.mode==="local"){av=`<span class="cside ${side?"b":"w"}"><img src="${PIMG[side|6]}" alt=""></span>`;who=`<b>${side?"Siyah":"Beyaz"}</b>`}
 else{const uid=CH.mode==="online"?(side===CH.my?S.uid:oppOf(CH.doc||{})):S.uid;const p=P(uid);av=avatar(uid,46,{click:false,ring:false});who=`<b>${esc(uid===S.uid?"Sen":p.name)}</b> <span class="crt">${chessStats(uid).r}</span>`}
 return`<div class="cpl-in ${turn?"turn":""}">${av}<div class="cwho"><div>${who}</div>${capH}</div>${turn&&side!==CH.my&&(CH.mode==="online"||(CH.mode==="bot"&&CH.thinking))?'<span class="cdots"><i></i><i></i><i></i></span>':""}</div>${extra}`}
function chUI(){if(!CH||!$("#cBoard"))return;const top=CH.flip?0:8;const bot=top^8;
 $("#cplT").innerHTML=chPlayerBar(top);$("#cplB").innerHTML=chPlayerBar(bot);
 const ev=$("#cEval");if(ev){const show=CH.mode==="bot"&&settings.evalBar!==false;ev.hidden=!show;if(show){const cp=CH.eval;const mate=Math.abs(cp)>CC.MATE-1000;const w=mate?(cp>0?100:0):50+50*(2/(1+Math.exp(-cp/350))-1);
  ev.classList.toggle("fl",CH.flip);ev.classList.toggle("bl",w<50);ev.querySelector("i").style.height=w+"%";ev.querySelector("span").textContent=mate?"M"+Math.ceil((CC.MATE-Math.abs(cp))/2):(Math.abs(cp)/100).toFixed(1)}}
 const mv=$("#cMoves");let h="";CH.moves.forEach((x,i)=>{if(i%2===0)h+=`<span class="cn">${i/2+1}.</span>`;const cur=CH.view==null?i===CH.moves.length-1:i===CH.view-1;h+=`<button class="cmv ${cur?"cur":""}" data-cply="${i+1}">${esc(x.san)}${x.q?`<em class="q${x.q.length>1?"2":x.q==="!"?"g":"1"}">${x.q}</em>`:""}</button>`});
 mv.innerHTML=h||`<span class="muted" style="font-size:.85rem;padding:0 4px">${CH.mode==="bot"?"İlk hamle "+(CH.my===0?"senden":"Rota'dan"):"Beyaz başlar"}</span>`;const cur=mv.querySelector(".cur");if(cur)cur.scrollIntoView({inline:"center",block:"nearest"});
 const B=(a,ic,l,dis)=>`<button data-chs="${a}" ${dis?"disabled":""}>${I(ic)}<span>${l}</span></button>`;const n=CH.moves.length;const v=CH.view==null?n:CH.view;
 let c="";if(CH.mode==="bot")c=B("undo","undo","Geri al",CH.thinking||!n)+B("hint","bulb","İpucu",CH.thinking||!!CH.over||CH.g.turn!==CH.my);
 else if(CH.mode==="local")c=B("undo","undo","Geri al",!n);
 else{const d=CH.doc||{};const act=d.status==="active"&&!CH.over;c=(d.drawOffer&&d.drawOffer!==S.uid&&act?B("drawyes","check","Berabere kabul"):B("draw","hand","Berabere",!act||d.drawOffer===S.uid))+B("resign","flag","Teslim",!act)}
 c+=B("flip","rotate","Çevir")+B("prev","prev","Önceki",v<=0)+B("next","next","Sonraki",v>=n)+B("menu","more","Daha");
 $("#cCtl").innerHTML=c}
function chBubble(t,ms=3800){if(!CH)return;CH.bubble=t;const b=$("#cBub");if(b){b.textContent=t;b.classList.remove("show");void b.offsetWidth;b.classList.add("show")}const f=$(".cbotav");if(f){f.classList.remove("talk");void f.offsetWidth;f.classList.add("talk")}clearTimeout(CH._bt);CH._bt=setTimeout(()=>{if(!CH)return;CH.bubble=null;const b2=$("#cBub");if(b2)b2.classList.remove("show")},ms)}
function chMood(m){if(!CH)return;CH.mood=m;const f=$(".cbotav");if(f){f.classList.remove("happy","sad","surp");if(m)f.classList.add(m)}}
const pick=a=>a[Math.floor(Math.random()*a.length)];
/* giriş: dokun-dokun ve sürükle */
function chCanMove(){if(!CH||CH.over||CH.thinking||CH.view!=null)return false;if(CH.mode==="local")return true;if(CH.g.turn!==CH.my)return false;if(CH.mode==="online"){const d=CH.doc;return!!d&&d.status==="active"}return true}
function chSqAt(e){const r=$("#cBoard").getBoundingClientRect();let x=Math.floor((e.clientX-r.left)/r.width*8),y=Math.floor((e.clientY-r.top)/r.height*8);if(x<0||x>7||y<0||y>7)return-1;if(CH.flip){x=7-x;y=7-y}return y*8+x}
function chSelect(s){CH.sel=s;CH.targets=s<0?[]:CC.legal(CH.g).filter(m=>m.f===s);chMarks()}
function chWire(){const bd=$("#cBoard");if(!bd)return;
 bd.onpointerdown=e=>{if(!CH)return;if(e.target.closest&&e.target.closest("#cOv.on"))return;if(CH.view!=null){CH.view=null;chDraw();return}const s=chSqAt(e);if(s<0)return;const p=CH.g.b[s];
  if(CH.sel>=0&&CH.targets.some(m=>m.t===s)){chTry(CH.sel,s);return}
  if(p&&(p&8)===CH.g.turn&&chCanMove()){const was=CH.sel===s;chSelect(s);CDRAG={s,el:CHEL[s],x:e.clientX,y:e.clientY,moved:false,was};try{bd.setPointerCapture(e.pointerId)}catch{}e.preventDefault()}
  else{if(p&&chCanMove()===false&&CH.mode==="bot"&&CH.thinking)toast("Rota düşünüyor…");chSelect(-1)}};
 bd.onpointermove=e=>{const D=CDRAG;if(!D||!D.el)return;if(!D.moved&&Math.hypot(e.clientX-D.x,e.clientY-D.y)>5){D.moved=true;D.el.classList.add("drag")}
  if(D.moved){const r=bd.getBoundingClientRect();const z=r.width/8;D.el.style.transform=`translate(${e.clientX-r.left-z/2}px,${e.clientY-r.top-z/2}px) scale(1.12)`}};
 const up=e=>{const D=CDRAG;CDRAG=null;if(!D||!CH)return;if(D.moved){const s=chSqAt(e);if(s>=0&&s!==D.s&&CH.targets.some(m=>m.t===s)){D.el.classList.add("nt");chTry(D.s,s);requestAnimationFrame(()=>D.el.classList.remove("nt"))}else{D.el.classList.remove("drag");D.el.style.transform=tf(D.s);if(s>=0&&s!==D.s)CSND.play("bad")}}else if(D.was){chSelect(-1)}};
 bd.onpointerup=up;bd.onpointercancel=e=>{const D=CDRAG;CDRAG=null;if(D&&D.el){D.el.classList.remove("drag");D.el.style.transform=tf(D.s)}}}
function chTry(f,t){const c=CH.targets.filter(m=>m.f===f&&m.t===t);if(!c.length)return;if(c.length>1)return chPromo(c);chUser(c[0])}
function chPromo(cands){const ov=$("#cOv");const col=cands[0].p&8;const[x]=sqXY(cands[0].t);
 ov.innerHTML=`<div class="cpromo" style="left:${x*12.5}%">${[5,4,3,2].map(t=>`<button data-pr="${t}"><img src="${PIMG[col|t]}" alt="${PNAME[t]}"></button>`).join("")}<button data-pr="0" class="x">${I("close")}</button></div>`;ov.classList.add("on");
 $$("[data-pr]",ov).forEach(b=>b.onclick=ev=>{ev.stopPropagation();ov.classList.remove("on");ov.innerHTML="";const t=+b.dataset.pr;if(!t){chDraw();return}const m=cands.find(x=>(x.pr&7)===t);if(m)chUser(m)})}
function chUser(m){if(!chCanMove())return;const st=chApply(m);chAnim(m);chSoundFor(m,st);chMarks();chArrow();chUI();vib(10);
 if(CH.mode==="online")chPush();else chSave();
 if(CH.over)return setTimeout(chOver,350);
 if(CH.mode==="bot"){if(st.check&&Math.random()<.6){chMood("surp");chBubble(pick(["Şah mı? Bakalım…","Ah, şah! Düşünmem lazım.","Şah çektin, cesursun."]))}setTimeout(chBot,280)}}
/* Rota'nın hamlesi */
async function chBot(){if(!CH||CH.over||CH.mode!=="bot"||CH.g.turn===CH.my||CH.thinking)return;const tok=CH;CH.thinking=true;chUI();const L=CLEVELS[CH.level];const t0=Date.now();
 const before=CH.my===0?CH.eval:-CH.eval;
 const r=await engineRun(CC.toFen(CH.g),{...(L.all?{all:true,depth:L.depth}:{depth:L.depth,time:L.time}),keys:CH.keys});
 await sleep(Math.max(0,(L.all?650:300)+Math.random()*650-(Date.now()-t0)));
 if(CH!==tok||CH.over||CH.g.turn===CH.my){if(CH===tok){CH.thinking=false;chUI()}return}
 CH.thinking=false;let u=r.u,score=r.score;
 if(r.all&&r.all.length){let best=r.all[0],bv=-1e9;for(const x of r.all){const v=x.s+gauss()*L.sigma;if(v>bv){bv=v;best=x}}if(Math.random()<L.bl&&r.all[0].s<CC.MATE-1000)best=r.all[Math.floor(Math.random()*r.all.length)];u=best.u;score=best.s}
 const m=u&&CC.fromUci(CH.g,u);if(!m){chUI();return}
 /* oyuncunun son hamlesini değerlendir */
 const after=-r.score;let said=false;const pm=CH.moves[CH.moves.length-1];
 if(pm&&CH.moves.length>2&&Math.abs(before)<CC.MATE-1000&&Math.abs(after)<CC.MATE-1000){const d=after-before;
  if(d<-260){pm.q="??";chMood("happy");chBubble(pick(["Bunu kaçırdın sanırım…","Hmm, bu hamle pahalıya patlayabilir.","Teşekkürler, bunu bekliyordum!"]));said=true}
  else if(d<-120){pm.q="?";chBubble(pick(["Pek iyi bir hamle değildi.","Daha iyisi vardı bence.","Hmm, emin misin?"]));said=true}
  else if(d>180){pm.q="!";chMood("sad");chBubble(pick(["Vay, güzel yakaladın!","Bunu görmeni istemiyordum.","Harika hamle!"]));said=true}}
 else if(pm&&after>CC.MATE-1000&&before<CC.MATE-1000){pm.q="!!";chMood("sad");chBubble("Eyvah, matı görüyorsun galiba…");said=true}
 if(CH.view!=null){CH.view=null;chDraw()}const st=chApply(m);chAnim(m);chSoundFor(m,st);chMarks();
 const bc=CH.my^8;CH.eval=bc===0?score:-score;
 if(!said){if(st.check)chBubble(pick(["Şah!","Şah! Sıra sende.","Şah çekiyorum."]));else if(m.c&&(m.c&7)>=4)chBubble(`Bu ${PNAME[m.c&7]} artık benim.`);else if(m.fl&2)chBubble("Şahımı güvene alıyorum.");else if(CH.moves.length<=2)chBubble(pick(["Hadi bakalım!","İyi şanslar!","Klasik bir başlangıç."]));else if(Math.random()<.16)chBubble(pick(["Sıra sende.","Planım var, göreceksin.","Hmm… ilginç bir oyun.","Dikkatli ol."]))}
 if(!CH.over){const bot=score;chMood(bot>CC.MATE-1000||bot>260?"happy":bot<-260?"sad":(st.check?"":CH.mood==="surp"?"":CH.mood))}
 chUI();chSave();if(CH.over)setTimeout(chOver,400)}
/* oyun sonu */
async function chOver(){if(!CH||!CH.over)return;const o=CH.over;const res=o.result;const me0=CH.my;const myWin=(res==="1-0"&&me0===0)||(res==="0-1"&&me0===8);const draw=res==="1/2";
 let title=draw?"Berabere":CH.mode==="local"?(res==="1-0"?"Beyaz kazandı":"Siyah kazandı"):myWin?"Kazandın!":"Kaybettin";let delta=null;
 if(o.reason==="iptal"){title="İptal edildi";CH.rated=true}
 if(!CH.rated){CH.rated=true;const score=draw?.5:myWin?1:0;
  if(CH.mode==="bot")delta=await chRate(CLEVELS[CH.level].r,score);
  else if(CH.mode==="online"){const done=LS.get("kadraj_cg_rated",{})||{};if(!done[CH.gid]&&!(((CH.doc||{}).rated||{})[S.uid])){done[CH.gid]=1;LS.set("kadraj_cg_rated",done);const gid=CH.gid;write(()=>DB.update("games/"+gid,{rated:{[S.uid]:1}}),{quiet:true});delta=await chRate(chessStats(oppOf(CH.doc||{})).r,score)}}
  chSave();if(CH.mode==="bot"){LS.del("kadraj_chess_bot_"+S.uid)}if(CH.mode==="local")LS.del("kadraj_chess_local_"+S.uid)}
 if(CH.mode==="bot"){if(draw){chMood("");chBubble("Berabere! Güzel mücadeleydi.",6000)}else if(myWin){chMood("sad");chBubble(pick(["Tebrikler, beni yendin!","İyi oyundu, bu sefer sen kazandın."]),6000)}else{chMood("happy");chBubble(pick(["İyi oyundu! Rövanş?","Bu sefer ben kazandım. Bir daha?"]),6000)}}
 if((CH.over||{}).reason!=="iptal")CSND.play(draw?"draw":myWin||CH.mode==="local"?"end":"lose");if(myWin)confetti();
 const ov=$("#cOv");if(!ov)return;
 ov.innerHTML=`<div class="cend"><div class="ct">${myWin?I("trophy"):I("knight")}</div><b>${title}</b><span>${esc(REASON[o.reason]||o.reason||"")}${delta!=null&&delta!==0?` · puan ${delta>0?"+":""}${delta}`:""}</span><div class="cbtns"><button class="btn" data-chs="${CH.mode==="online"?"rematch":"again"}">${I("rotate")}${CH.mode==="online"?"Rövanş iste":"Yeni oyun"}</button><button class="btn sec" data-chs="share">${I("send")}Akışta paylaş</button><button class="btn ghost" data-chs="review">Tahtaya bak</button></div></div>`;ov.classList.add("on");chUI()}
function confetti(){const host=$("#cBoard");if(!host)return;const cols=["#ffcf4d","#3fd3ab","#e23e57","#1d4ed8","#f97316"];for(let i=0;i<40;i++){const c=document.createElement("i");c.className="conf";c.style.cssText=`left:${Math.random()*100}%;background:${cols[i%5]};animation-delay:${Math.random()*.4}s;animation-duration:${1.4+Math.random()}s;transform:rotate(${Math.random()*360}deg)`;host.appendChild(c);setTimeout(()=>c.remove(),2600)}}
/* açma */
function chOpen(){S.stack=S.route.name==="chessgame"?S.stack:[...S.stack,S.route];S.route={name:"chessgame",params:{}};render(true)}
function chStartBot(){const lv=settings.chessLevel??1;let col=settings.chessColor||"w";if(col==="r")col=Math.random()<.5?"w":"b";chNew("bot",{my:col==="b"?8:0,level:lv});chSave();chOpen();setTimeout(()=>{chBubble(pick([`${CLEVELS[lv].n} seviyedeyim. Hazırsan başlayalım!`,"İyi şanslar! Merak etme, nazik oynarım. Belki.","Hadi bakalım, ilk hamle "+(CH.my===0?"senden.":"benden.")]));if(CH.my===8)setTimeout(chBot,500)},350)}
async function chessAct(a,t){if(!CH&&!["botnew","botresume","invite","pass","passresume"].includes(a))return;
 if(a==="botnew")return chStartBot();
 if(a==="botresume"){if(!(CH&&CH.mode==="bot"&&!CH.over))chLoad("bot");if(!CH)return;chOpen();if(CH.g.turn!==CH.my)setTimeout(chBot,400);return}
 if(a==="pass"){chNew("local");chSave();return chOpen()}
 if(a==="passresume"){chLoad("local");return chOpen()}
 if(a==="invite")return chInvitePick();
 if(a==="flip"){CH.flip=!CH.flip;chSave();return chDraw()}
 if(a==="prev"||a==="next"){const n=CH.moves.length;let v=CH.view==null?n:CH.view;if(a==="prev"){v=Math.max(0,v-1);CH.view=v;CH.sel=-1;CH.targets=[];return chDraw()}
  if(v>=n)return;const m=CH.moves[v].m;v++;CH.view=v>=n?null:v;chAnim(m);CSND.play(m.c?"capture":"move");chMarks();return chUI()}
 if(a==="undo"){if(CH.thinking)return;const ov=$("#cOv");if(ov){ov.classList.remove("on");ov.innerHTML=""}const k=CH.mode==="bot"?(CH.g.turn===CH.my?2:1):1;const list=CH.moves.slice(0,Math.max(0,CH.moves.length-k)).map(x=>x.u);
  const keep={mode:CH.mode,my:CH.my,level:CH.level,flip:CH.flip,eval:CH.eval,rated:CH.rated};chNew(keep.mode,{my:keep.my,level:keep.level});CH.flip=keep.flip;CH.eval=keep.eval;CH.rated=keep.rated;chReplay(list);CH.over=null;chSave();chDraw();if(CH.mode==="bot"){chBubble(pick(["Tamam, geri alalım.","Bir şans daha!","Peki, tekrar düşün."]));if(CH.g.turn!==CH.my)setTimeout(chBot,400)}return}
 if(a==="hint"){if(!chCanMove())return;$$('[data-chs="hint"]').forEach(b=>b.disabled=true);chBubble("Bir bakayım…",2000);const r=await engineRun(CC.toFen(CH.g),{depth:4,time:1200,keys:CH.keys});const m=r.u&&CC.fromUci(CH.g,r.u);if(!m||!CH)return chUI();CH.hint={f:m.f,t:m.t};chMarks();chArrow();chUI();chBubble(`Ben olsam ${CC.san(CH.g,m)} oynardım.`,4500);return}
 if(a==="again"){const ov=$("#cOv");ov.classList.remove("on");ov.innerHTML="";if(CH.mode==="local"){chNew("local");chSave();return chDraw()}return chStartBot()}
 if(a==="review"){const ov=$("#cOv");ov.classList.remove("on");ov.innerHTML="";return}
 if(a==="share")return chShare();
 if(a==="menu")return chMenu();
 if(a==="resign")return dialog("Teslim olunsun mu?","Oyun kaybedilmiş sayılır.",[{label:"Teslim ol",cls:"danger",fn:()=>chFinishOnline(CH.my===0?"0-1":"1-0","teslim")},{label:"Vazgeç"}]);
 if(a==="draw"){await write(()=>DB.update("games/"+CH.gid,{drawOffer:S.uid,updatedAt:now()}));toast("Beraberlik teklif edildi");return}
 if(a==="drawyes")return chFinishOnline("1/2","anlasma");
 if(a==="rematch"){const o=oppOf(CH.doc||{});if(o)return chCreateOnline(o)}}
function chMenu(){const l=sheet("cmenu","Satranç",`${CH.mode!=="online"?`<button class="opt" id="cmNew">${I("rotate")}Yeni oyun</button>`:""}${CH.mode==="bot"&&!CH.over?`<button class="opt red" id="cmRes">${I("flag")}Teslim ol</button>`:""}
 <div class="set" style="margin:0 0 6px"><h3>Tahta</h3><div class="cthemes" style="padding:0 12px">${Object.entries(CTHEMES).map(([k,[a,b,n]])=>`<button data-cth="${k}" aria-pressed="${(settings.board||"kadraj")===k}"><i style="background:linear-gradient(135deg,${a} 50%,${b} 50%)"></i>${n}</button>`).join("")}</div></div>
 <label class="srow"><span class="t">Ses</span><span class="sw"><input type="checkbox" id="cmSnd" ${settings.chessSound!==false?"checked":""}><span></span></span></label>${CH.mode==="bot"?`<label class="srow"><span class="t">Değerlendirme çubuğu<small>Kimin önde olduğunu gösterir</small></span><span class="sw"><input type="checkbox" id="cmEv" ${settings.evalBar!==false?"checked":""}><span></span></span></label>`:""}<button class="opt" data-act="close">${I("close")}Kapat</button>`);
 const nw=$("#cmNew",l);if(nw)nw.onclick=()=>{closeLayer("cmenu");if(CH.mode==="local"){chNew("local");chSave();return chDraw()}dialog("Yeni oyun?","Bu oyun yarıda kalır.",[{label:"Yeni oyun",fn:()=>chStartBot()},{label:"Vazgeç"}])};
 const rs=$("#cmRes",l);if(rs)rs.onclick=()=>{closeLayer("cmenu");CH.over={over:true,result:CH.my===0?"0-1":"1-0",reason:"teslim"};chOver()};
 $("#cmSnd",l).onchange=e=>{settings.chessSound=e.target.checked;saveSettings()};const ev=$("#cmEv",l);if(ev)ev.onchange=e=>{settings.evalBar=e.target.checked;saveSettings();chUI()}}
function chSetTheme(k){settings.board=k;saveSettings();$$("[data-cth]").forEach(b=>b.setAttribute("aria-pressed",b.dataset.cth===k));const c=$(".chess");if(c){c.style.setProperty("--cl",CTHEMES[k][0]);c.style.setProperty("--cd",CTHEMES[k][1])}}
/* sonucu tahta resmiyle paylaş */
async function chShare(){if(!guard())return;const W=1080;const cv=document.createElement("canvas");cv.width=W;cv.height=1350;const x=cv.getContext("2d");const th=CTHEMES[settings.board||"kadraj"]||CTHEMES.kadraj;const z=W/8;const g=CH.g;
 x.fillStyle="#0f1f1a";x.fillRect(0,0,W,1350);for(let r=0;r<8;r++)for(let f=0;f<8;f++){x.fillStyle=(r+f)%2?th[1]:th[0];x.fillRect(f*z,r*z,z,z)}
 if(CH.last){x.fillStyle="rgba(255,214,10,.42)";for(const s of[CH.last.f,CH.last.t]){const[a,b]=sqXY(s);x.fillRect(a*z,b*z,z,z)}}
 try{const imgs={};for(let s=0;s<64;s++){const p=g.b[s];if(!p)continue;imgs[p]=imgs[p]||await loadImg(PIMG[p]);const[a,b]=sqXY(s);x.drawImage(imgs[p],a*z+4,b*z+4,z-8,z-8)}cv.toDataURL("image/jpeg",.5)}
 catch{for(let s=0;s<64;s++){const p=g.b[s];if(!p)continue;const[a,b]=sqXY(s);x.fillStyle=p&8?"#26332e":"#fbfaf5";x.beginPath();x.arc(a*z+z/2,b*z+z/2,z*.36,0,7);x.fill();x.fillStyle=p&8?"#fff":"#111";x.font=`700 ${z*.38}px sans-serif`;x.textAlign="center";x.textBaseline="middle";x.fillText(" PAFKVŞ"[p&7],a*z+z/2,b*z+z/2)}}
 const res=CH.over?CH.over.result:null;const myWin=res&&((res==="1-0"&&CH.my===0)||(res==="0-1"&&CH.my===8));const opp=CH.mode==="bot"?`Rota (${CLEVELS[CH.level].n})`:CH.mode==="online"?"@"+P(oppOf(CH.doc||{})).username:"";
 const line=!res?"Kadraj satranç":res==="1/2"?(opp?`${opp} ile berabere`:"Berabere"):CH.mode==="local"?(res==="1-0"?"Beyaz kazandı":"Siyah kazandı"):myWin?`${opp} karşısında galibiyet`:`${opp} karşısında mağlubiyet`;
 x.fillStyle="#fff";x.font="700 60px Unbounded, 'Avenir Next', sans-serif";x.textAlign="center";x.textBaseline="middle";x.fillText(line,W/2,W+105,W-100);x.fillStyle="#3fd3ab";x.font="600 38px 'Avenir Next', sans-serif";x.fillText(`${Math.ceil(CH.moves.length/2)} hamle · ${REASON[CH.over?.reason]||"oyun sürüyor"} · kadraj`,W/2,W+185,W-100);
 const cap=!res?"Kadraj'da satranç oynuyorum. #satranç":CH.mode==="local"?(res==="1/2"?"Karşılıklı oynadık, berabere bitti. #satranç":`Karşılıklı oynadık, ${res==="1-0"?"Beyaz":"Siyah"} kazandı. #satranç`):res==="1/2"?`${opp} ile berabere kaldık. #satranç`:myWin?`${opp} karşısında kazandım! ${Math.ceil(CH.moves.length/2)} hamle sürdü. #satranç`:`${opp} bu sefer kazandı, rövanş yakında. #satranç`;
 S.cmp={kind:"photo",filter:0,ar:"4/5",slides:[],fx:"zoom",music:"lofi",text:"",bg:0,options:["",""],mode:"slides",img:cv,caption:cap,loc:""};drawComposer()}
