 h+=`<h3 class="sec-h"><span>Araçlar</span></h3><div class="set">${admTemaRow()}<button class="srow" data-adm="meydanclr">${I("globe")}<span class="t">Meydan'ı temizle<small>Ortak sohbetteki tüm mesajlar silinir</small></span></button><button class="srow" data-adm="storyclr">${I("eye")}<span class="t">Eski hikâyeleri temizle<small>24 saati geçmiş hikâyeleri veritabanından siler</small></span></button><label class="srow"><span class="t">Bakım modu<small>Açıkken yönetici dışında kimse uygulamayı kullanamaz</small></span><span class="sw"><input type="checkbox" id="admBk" ${bakimOn()?"checked":""}><span></span></span></label><button class="srow" data-adm="childmode">${I("lock")}<span class="t">Çocuk modu<small>Bir hesaba küfür süzgeci ve güvenli sohbet öner</small></span></button>${pin?`<button class="srow" data-adm="unpin">${I("spark")}<span class="t">Öne çıkanı kaldır</span></button>`:""}</div>`;
 const lg=(S.adm&&S.adm.log&&S.adm.log.items)||[];
 if(lg.length)h+=`<h3 class="sec-h"><span>Son işlemler</span></h3><div class="box adm-log">${lg.slice(0,12).map(x=>`<div class="row"><span class="dotx"></span><div class="t"><div>${esc(x.x)}</div><div class="s">${ago(x.t)}${x.by&&x.by!==S.uid?" · @"+esc(P(x.by).username):""}</div></div></div>`).join("")}</div>`;
 h+=`<h3 class="sec-h"><span>Kurulum</span></h3><div class="box adm-box"><p class="muted" style="margin:0;font-size:.85rem">Panel işlemlerinin (hesap kapatma, duyuru, bot, rozet) çalışması için bu kuralları bir kez Firebase'de <b>Firestore Database › Kurallar</b>'a yapıştırıp <b>Yayınla</b>'ya bas. İçinde senin hesap kimliğin var; yalnızca sen yönetici olursun.</p><div class="kv"><span>Hesap kimliğin</span><span class="mono">${esc(S.uid)}</span></div><pre class="adm-rules">${esc(rulesText([S.uid]))}</pre><button class="btn sec" data-adm="copyrules">${I("copy")}Kuralları kopyala</button></div>`;
