function draftSet(key,v){const d=LS.get(draftKey(),{})||{};v=(v||"").slice(0,2000);if(v.trim())d[key]=v;else delete d[key];LS.set(draftKey(),d)}
const wireComposerBase=wireComposer;
wireComposer=function(){wireComposerBase();const f=$("#composer"),inp=$("#msgIn");if(!f||!inp)return;const key=S.route.params.key;
 const dv=draftOf(key);if(dv&&!inp.value){inp.value=dv;cfGrow(inp,true);const btn=$("#sendBtn");if(btn&&keyInfo(key).type!=="bot"){btn.innerHTML=I("send");btn.setAttribute("aria-label","Gönder")}}
 let t=0;inp.addEventListener("input",()=>{clearTimeout(t);t=setTimeout(()=>draftSet(key,inp.value),300)});
 const os=f.onsubmit;f.onsubmit=async e=>{e.preventDefault();clearTimeout(t);const v=inp.value.trim();if(!v)return os&&os.call(f,e);
  const rp=S.replyTo;const p=sendMessage;let ok;sendMessage=async(...a)=>(ok=await p(...a));try{await os.call(f,e)}finally{sendMessage=p}
  if(ok===true)draftSet(key,"");else if(!inp.value&&inp.isConnected){inp.value=v;draftSet(key,v);if(rp&&!S.replyTo){S.replyTo=rp;drawReply()}inp.dispatchEvent(new Event("input"))}}};
HOOKS.after.push(r=>{if(r!=="chats")return;const d=LS.get(draftKey(),{})||{};for(const b of $$("#main [data-chat]")){const v=d[b.dataset.chat];const x=v&&b.querySelector(".s,small");if(x)x.innerHTML=`<span class="drf">Taslak:</span> ${esc(v.replace(/\s+/g," ").slice(0,60))}`}});
async function admSet(id,doc){return write(()=>DB.set("admin/"+id,{...doc,by:S.uid,at:doc.at||now()}))}
async function admWipe(uid,{posts=true,stories=true}={}){let k=0;
 if(posts)for(const p of Object.values(S.posts).filter(p=>p.uid===uid)){await DB.del("posts/"+p.id).catch(()=>{});DB.del("meta/"+p.id).catch(()=>{});if(p.video&&String(p.video).startsWith("chunk:")){const[,vid,c]=p.video.split(":");for(let i=0;i<+c;i++)DB.del(`vchunks/${vid}-${i}`).catch(()=>{})}const ps={...S.posts};delete ps[p.id];S.posts=ps;k++}
 if(stories)for(const s of Object.values(S.stories).filter(s=>s.uid===uid)){await DB.del("stories/"+s.id).catch(()=>{});const st={...S.stories};delete st[s.id];S.stories=st;k++}
 return k}
async function admDestroy(uid){const p=P(uid);const list={...admBan(),[uid]:{at:now(),name:p.name,username:p.username}};
 if(!await admSet("ban",{list}))return;await admWipe(uid);DB.del("presence/"+uid).catch(()=>{});DB.del("kurtar/"+uid).catch(()=>{});if(p.username)DB.get("unames/"+String(p.username).toLowerCase()).then(d=>{if(d&&d.uid===uid)return DB.del("unames/"+String(p.username).toLowerCase())}).catch(()=>{});
 if(await write(()=>DB.del("profiles/"+uid))){const pr={...S.profiles};delete pr[uid];S.profiles=pr;if(S.mode==="local"){const acc=LS.get("kadraj_accounts",{})||{};for(const k in acc)if(acc[k]===uid)delete acc[k];LS.set("kadraj_accounts",acc)}}
 const dm=cidFor(S.uid,uid);if(S.chats[dm])await chatWipe(dm).catch(()=>0);for(const[gid,c]of Object.entries(S.chats))if(c.group&&(c.members||[]).includes(uid))await DB.update("chats/"+gid,{members:(c.members||[]).filter(x=>x!==uid)}).catch(()=>{});
 admLog(`@${p.username} hesabı kapatıldı`);toast(`@${p.username} kapatıldı`);render(false)}
function admBotSheet(uid){const b=uid?BOT[uid]:null;let av=b?b.avatar:null;
 const l=sheet("admbot",b?"Botu düzenle":"Yeni bot",`<form class="form" id="abF"><div class="avpick"><span class="av" style="--s:64px"><img id="abAv" src="${esc(av||initialsAv("Bot","x"))}" alt=""></span><button type="button" class="btn sec sm" id="abAvB">${I("image")}Fotoğraf</button></div>
 <div class="field"><label for="abN">Ad</label><input class="in" id="abN" maxlength="40" value="${esc(b?b.name:"")}" placeholder="Örn. Kahve Botu"></div>
 <div class="field"><label for="abU">Kullanıcı adı</label><input class="in" id="abU" maxlength="24" autocapitalize="off" value="${esc(b?b.username:"")}" placeholder="kahve.bot"></div>
 <div class="field"><label for="abB">Biyografi</label><textarea class="in" id="abB" maxlength="160">${esc(b?b.bio:"")}</textarea></div>
 <div class="field"><label for="abR">Hazır yanıtlar (her satıra bir tane)</label><textarea class="in" id="abR" rows="4" placeholder="Selam!\nBugün nasılsın?\nBen bir botum, kahveyi severim.">${esc(b?b.replies.join("\n"):"")}</textarea></div>
 <p class="muted" style="margin:0;font-size:.82rem">Bot herkesin Keşfet ve Sohbet ekranında “bot” etiketiyle görünür; ona yazan herkese bu yanıtlardan biriyle cevap verir.</p><div class="err" id="abE"></div><button class="btn block">${b?"Kaydet":"Botu oluştur"}</button></form>`,{tall:true});
 const nm=$("#abN",l);nm.oninput=()=>{if(!av)$("#abAv",l).src=initialsAv(nm.value||"Bot","x");const u=$("#abU",l);if(!u.dataset.t&&!b)u.value=slug(nm.value)+".bot"};$("#abU",l).oninput=e=>e.target.dataset.t=1;
 $("#abAvB",l).onclick=async()=>{const r=await pickImage({title:"Bot fotoğrafı"});if(r){av=toCanvas(r.img,200,200).toDataURL("image/jpeg",.8);$("#abAv",l).src=av}};
 $("#abF",l).onsubmit=async e=>{e.preventDefault();const er=$("#abE",l);const name=nm.value.trim(),un=$("#abU",l).value.trim().toLowerCase(),bio=$("#abB",l).value.trim(),replies=$("#abR",l).value.split("\n").map(x=>x.trim()).filter(Boolean).slice(0,30);
  if(!name)return er.textContent="Bota bir ad ver.";if(!USER_RE.test(un))return er.textContent="Kullanıcı adı 3–24 karakter: küçük harf, rakam, nokta, alt çizgi.";
  if((BOTS.some(x=>x.username===un&&x.uid!==uid))||Object.values(S.profiles).some(p=>p.username===un))return er.textContent=`“${un}” kullanılıyor.`;
  const key=b?b.key:"c"+rid();const doc={uid:"bot:"+key,key,name,username:un,bio,replies,avatar:av||null,at:b?b.at||now():now(),by:S.uid};
  if(await write(()=>DB.set("bots/"+key,doc))){admLog(b?`@${un} botu düzenlendi`:`@${un} botu eklendi`);closeLayer("admbot");toast(b?"Bot güncellendi":`@${un} oluşturuldu`);render(false)}}}
function admBotSay(uid){const b=BOT[uid];const l=sheet("admsay",`@${b.username} olarak Meydan'a yaz`,`<form class="form" id="asF"><textarea class="in" id="asT" maxlength="400" placeholder="Botun mesajı…"></textarea><p class="muted" style="margin:0;font-size:.82rem">Mesaj Meydan'da botun adı ve “bot” etiketiyle görünür.</p><button class="btn block">${I("send")}Gönder</button></form>`);
 $("#asF",l).onsubmit=async e=>{e.preventDefault();const t=$("#asT",l).value.trim();if(!t)return;const at=now();const mid=at.toString(36)+"b";
  if(await write(()=>DB.set(`chats/meydan/msgs/${mid}`,{from:uid,text:t,at,botMsg:true}))){await write(()=>DB.set("chats/meydan",{last:{text:t.slice(0,80),from:uid,at},updatedAt:at}),{quiet:true});closeLayer("admsay");toast("Meydan'a gönderildi")}}}
function admOnce(col){return new Promise(res=>{let un=null,done=false;un=DB.watchCol(col,docs=>{if(done)return;done=true;setTimeout(()=>{try{un&&un()}catch{}},0);res(docs)},{limit:500});setTimeout(()=>{if(!done){done=true;res([])}},8000)})}
async function admAct(a,t){const u=t.dataset.u;
 if(a==="ann"){const v=($("#admAnn")||{}).value?.trim();if(!v)return toast("Önce duyuruyu yaz.");if(await admSet("duyuru",{text:v,at:now()})){admLog("Duyuru yayınlandı: "+v.slice(0,50));toast("Duyuru yayında");render(false)}return}
 if(a==="childmode")return dialog("Çocuk modu nedir?","Bir hesap seçip “Çocuk modu öner” dersin. O hesabın sahibi uygulamayı açtığında açık bir soru görür; kabul ederse modu kendi açar. Modda yazdığı mesajlardaki kötü sözler gizlenir, Meydan kapanır ve yalnızca karşılıklı arkadaşlarıyla yazışır. Kimse o kişinin özel mesajlarını okuyamaz. Bir kişiye önermek için Kullanıcılar listesinden “Yönet”e dokun.",[{label:"Anladım"}]);
 if(a==="repok"){await write(()=>DB.del("reports/"+u));S.reports=(S.reports||[]).filter(r=>r.id!==u);return render(false)}
 if(a==="repdel"){const pid=t.dataset.p;return dialog("Paylaşım kaldırılsın mı?","Şikayet edilen paylaşım herkes için silinir.",[{label:"Kaldır",cls:"danger",fn:async()=>{await deletePost(pid);for(const r of (S.reports||[]).filter(r=>r.pid===pid))await DB.del("reports/"+r.id).catch(()=>{});S.reports=(S.reports||[]).filter(r=>r.pid!==pid);admLog("Şikayet edilen paylaşım kaldırıldı");render(false)}},{label:"Vazgeç"}])}
 if(a==="annx"){if(await admSet("duyuru",{text:"",at:now()})){toast("Duyuru kaldırıldı");render(false)}return}
 if(a==="unban"){const list={...admBan()};if(list[u])list[u]={...list[u],at:0};if(await admSet("ban",{list})){admLog(`@${(list[u]&&list[u].username)||"hesap"} yeniden açıldı`);toast("Hesap yeniden açıldı. Kişi tekrar giriş yapıp profilini oluşturabilir.");render(false)}return}
 if(a==="botnew")return admBotSheet(null);
 if(a==="botedit")return admBotSheet(u);
 if(a==="botsay")return admBotSay(u);
 if(a==="botdel"){const b=BOT[u];return dialog("Bot silinsin mi?",`@${esc(b.username)} kalıcı olarak silinir.`,[{label:"Sil",cls:"danger",fn:async()=>{if(await write(()=>DB.del("bots/"+b.key))){setCustomBots((Object.values(BOT).filter(x=>x.custom&&x.uid!==u)));toast("Bot silindi");render(false)}}},{label:"Vazgeç"}])}
 if(a==="postdel")return dialog("Paylaşım kaldırılsın mı?","Paylaşım ve yorumları kalıcı olarak silinir.",[{label:"Kaldır",cls:"danger",fn:()=>{deletePost(u);admLog("Bir paylaşım kaldırıldı")}},{label:"Vazgeç"}]);
 if(a==="pin"){if(pinnedId()===u){if(await admSet("pin",{pid:null}))toast("Öne çıkarma kaldırıldı")}else if(await admSet("pin",{pid:u}))toast("Paylaşım Akış'ın en üstünde");return render(false)}
 if(a==="unpin"){if(await admSet("pin",{pid:null}))toast("Öne çıkarma kaldırıldı");return render(false)}
 if(a==="meydanclr")return dialog("Meydan temizlensin mi?","Ortak sohbetteki bütün mesajlar herkes için silinir.",[{label:"Temizle",cls:"danger",fn:async()=>{const ds=await admOnce("chats/meydan/msgs");let k=0;for(const d of ds){await DB.del("chats/meydan/msgs/"+d.id).catch(()=>{});k++}await write(()=>DB.set("chats/meydan",{last:null,updatedAt:now()}),{quiet:true});admLog("Meydan temizlendi");toast(`${k} mesaj silindi`)}},{label:"Vazgeç"}]);
 if(a==="storyclr"){const ds=await admOnce("stories");const lim=now()-24*H;let k=0;for(const d of ds)if(!(d.at>lim)){await DB.del("stories/"+d.id).catch(()=>{});k++}return toast(k?`${k} eski hikâye silindi`:"Silinecek eski hikâye yok")}
 if(a==="copyrules")return copyText(rulesText([S.uid]),"Kurallar kopyalandı");
 if(a==="exit"){if(typeof bakimOn==="function"&&bakimOn())return toast("Bakım modu açıkken yönetici modundan çıkılamaz. Önce bakımı kapat.");S.admin=false;LS.del("kadraj_admin_"+S.uid);toast("Yönetici modundan çıkıldı");return tab("feed")}}

const RULES=rulesText([]);
/* ============ Botlar & Rota ============ */
const APP_GUIDE=`Kadraj bir sosyal uygulamadır (Firebase üzerinde çalışır, herkes kendi e-postasıyla hesap açar). Alt dok: Akış, Keşfet, ortada + (Oluştur), Sohbet, Ben.
- Oluştur (+): Fotoğraf, Klaket (kısa video, Kadraj'da Reels'in adı), Hikâye, Not (renkli zeminde yazı), Anket (2-4 seçenek), Çizim (parmakla).
- Fotoğraf kaynakları: telefondan seç, kamera, Kadraj galerisi (hazır 10 fotoğraf), parmakla çizim, panodan yapıştırma. Dosya seçici açılmazsa galeri, çizim ya da yapıştırma kullanılır.
- Fotoğraf: Kare/Dikey/Yatay kırpma, 7 filtre, açıklama, konum; "Rota açıklama yazsın" düğmesi (Rota seçili fotoğrafa bakıp ona uygun açıklama yazar; fotoğrafı göremezse genel bir açıklama yazar). Paylaşım resimlerine basılı tutunca indirme menüsü çıkmaz. Bir paylaşıma 10 fotoğrafa kadar eklenebilir (seçicide birden çok seç ya da şeritteki + ile ekle); şeritten seç, çıkar, sola/sağa taşı. Filtre ve oran hepsine uygulanır. Akışta yana kaydırarak bakılır, sağ üstte 2/5 gibi sayaç ve altta noktalar çıkar; ızgarada köşede üst üste kare ikonu.
- Klaket: "Fotoğraflardan" (1-3 kare, ekrandaki yazı, hareket: Yakınlaş/Kaydır/Nabız, müzik: Lo-fi/Enerjik/Sakin; müzik cihazda üretilir) ya da "Video yükle" (en fazla 2 dakika, 40 MB; büyükler otomatik küçültülür). Klaketler ekranında sesi sağ üstteki hoparlör açar, çift dokunuş beğenir.
- Hikâye: 24 saat görünür, üstüne yazı eklenebilir; yanıtlar mesaj olarak gelir.
- Etkileşim: beğeni (çift dokunuş da olur), yorum, kaydet, arkadaşına gönder, anket oyu.
- Sohbet sekmesi: Sesli mesaj (mesaj kutusu boşken mikrofon düğmesine dokun, konuş, gönder), sesli ve görüntülü arama (birebir sohbetin üstündeki telefon ve kamera düğmeleri; arkadaş uygulamayı açıkken çalar), mesaja uzun basıp Yanıtla, Meydan (sayfadaki herkesin ortak canlı sohbeti), Şu an burada listesi (çevrimiçi kişiler; Dürt düğmesi titreşimli dürtme gönderir), Yeni mesaj, Grup kur, Davet et, Rota, test botları. Mesajlarda fotoğraf ve paylaşım gönderilir; mesaja çift dokununca kalp, uzun basınca menü (kopyala, geri al). Birebir sohbette "Görüldü" ve "yazıyor…" görünür. Meydan'da ya da grupta mesaja @rota yazınca Rota yanıt verir.
- Arkadaşlarla kullanmak: Sohbet > Davet et (ya da Ben > Davet et) ekranındaki davet bağlantısı WhatsApp gibi bir uygulamayla gönderilir. Arkadaş bağlantıyı açar, e-posta ve şifreyle hesap oluşturur, seni Keşfet'te bulup takip eder ve yazar. Giriş kullanıcı adıyla ya da e-postayla yapılır. Şifre unutulursa giriş ekranında Şifremi unuttum > Kadraj Anahtarı ile yenile (anahtar Ben > zarf simgesi, Kadraj Posta'da durur). Anahtar da kaybolduysa kişi yöneticiye kullanıcı adını ve kayıt e-postasını söyler; e-posta doğruysa yönetici anahtarı panelden görüp iletir, kişinin anahtarı sonra kendiliğinden yenilenir.
- Ben (profil) > dişli: tema (Açık/Koyu/Sistem), yazı boyutu (Normal/Büyük/Çok büyük), gizli hesap, bildirimler, Klaketleri otomatik oynatma, Beni hatırla, şifre değiştir, çıkış, hesabı sil.
- Satranç: Sohbet › oyun kolu. Rota'ya karşı 5 seviye (Çaylak 400, Acemi 800, Orta 1200, Zor 1600, Usta 2000), renk seçimi, taşı sürükle ya da dokun-dokun oyna, Geri al, İpucu (ok çizer), tahtayı çevir, hamleler arasında ileri-geri gez, değerlendirme çubuğu, tahta temaları (Kadraj, Klasik, Ahşap, Gece), ses. Kazanınca puanın artar, Kadraj sıralamasında görünür. Arkadaşınla oynamak için Arkadaşını davet et ya da birebir sohbetin üstündeki at düğmesi; davet sohbete kart olarak düşer. Aynı telefonda iki kişi de oynanabilir. Oyun bitince sonucu tahtanın resmiyle Akış'ta paylaşabilirsin.
- Klaket kaynakları: Fotoğraflardan (müzikli), Video yükle ya da Kamerayla çek (uygulama içinde 60 saniyeye kadar kayıt; demo modunda daha kısa). Videoya da müzik eklenebilir.
- Rota yapay zekâlı asistandır; yanında hazır yanıtlı deneme botları ve yöneticinin eklediği botlar da olabilir. "Test bildirimleri oluştur" komutu (çipe dokun ya da yaz) Rota'nın son paylaşımını beğenmesini, yorum yapmasını ve seni takip etmesini sağlar.
- 4.0 yenilikleri: animasyonlu açılış; Ayarlar yenilendi (arama kutusu, Görünüm'de Açık/Koyu/Sistem tema ve 7 vurgu rengi, tema tüm cihazlarda aynı kalabilir, animasyonları azalt; Gizlilik'te aktiflik durumu, okundu bilgisi, beğeni sayılarını gizleme; bildirim türleri; Enter ile gönder; veri tasarrufu; önbelleği temizle; Neler yeni; Güncellemeleri denetle).
- Aktiflik: yeşil nokta şu an açık olanı gösterir. Ayarlar > Gizlilik > Aktiflik durumu kapatılırsa kimse seni aktif göremez, sen de başkalarını göremezsin.
- Ortak sohbet temaları: sohbetin üstündeki resim simgesinden tema seçilir; birebir ve grup sohbetlerinde "Herkes için" seçilen tema sohbetteki herkeste aynı anda değişir ve kendi balonlarının rengini de değiştirir. "Yalnızca bende" sadece senin cihazını etkiler. Fotoğraftan tema da yapılabilir.
- Mesajlar: mesaja uzun basınca 6 resimli tepki (kalp, gülme, şaşırma, üzülme, ateş, alkış), yanıtla, kopyala, düzenle, sil; çift dokunuş kalp bırakır. Profilde en fazla 3 paylaşım sabitlenebilir.
- 4.4: Sahne'nin adı Flick oldu; 5.1'den beri adı Klaket (kısa video). Paylaşırken "Çocuk modundakiler göremez" açılırsa o paylaşım Çocuk Modu'ndaki kişilere hiç görünmez; sonradan paylaşımın ... menüsünden değiştirilebilir.
- Clawd maskotu (eski ekran yaratığı) 6.4.4'te kaldırıldı. Clawd yalnızca satrançta rakip olarak var.
- 5.1 Klaket: kısa videoların adı Flick'ti, 5.1'de Klaket oldu. Klaket'ler Kadraj oynatıcısıyla oynar (sürüklenen süre çubuğu, 1x/1,5x/2x, tam ekran, çift dokunuşla ±5 sn). Fotoğraf ya da video seçerken Kadraj'ın kendi seçicisi açılır (Galeri, Kamera, Video çek, Kadraj galerisi, Çizim, Yapıştır, son seçtiklerin). Sohbette + menüsünden video da gönderilir.
- 5.1 satranç: lobide rakip Rota ya da Clawd seçilir; Clawd'un Çaylak'tan Usta'ya seviyeleri ve ayrı puanı var, atak oynar ve şaka yapar. "Clawd ve Rota" kartında ikisinin maçını izlersin, konuşarak oynarlar. Çevrim içi oyunda tahtanın altındaki sohbetle yazışılır. Seviyeler artık gerçekten farklı güçte.
- 5.1 Oyun incelemesi: satrançta her hamle değerlendirilir (Muhteşem !!, Harika !, En iyi, Mükemmel, İyi, Kitap, Hatalı ?!, Hata ?, Kaçırılan, Büyük hata ??). Rozet tahtada hamlenin gittiği karede ve hamle listesinde görünür. Oyun menüsü › Hamle değerlendirmesi: Canlı / Oyun sonunda / Kapalı (çevrim içi oyunlarda yalnızca oyun bitince). Oyun sonu kartında ve menüde "Oyun incelemesi": iki tarafın doğruluk yüzdesi, sınıf sayıları, değerlendirme grafiği (dokununca o hamleye gider) ve "Hamleleri incele". Muhteşem ya da büyük hata yapınca Rota ve Clawd yorum yapar. Analiz cihazda, hızlı ve yaklaşıktır.
- 5.1 Seri: birebir sohbette ikiniz de aynı gün en az bir mesaj yazınca seri bir gün uzar; sohbetin üstünde odun üstünde kamp ateşi yanar ve seri uzadıkça büyür. Gece yarısına az kala o gün yazılmadıysa yağmur yağar, 00:00'ı geçince ateş söner. Herkesin 3 Rüzgar hakkı var: kaçırılan günü korur. Grupta, Meydan'da ve botlarda seri yok.
- 5.1 bildirimler: uygulama içindeyken üstten Kadraj kartı gelir (gönderen, saat, önizleme; mesajlarda Görüldü, Kalp at, Yanıtla). Ayarlar › Bildirimler'den bildirim sesi açılır kapanır; "Uygulama kapalıyken de bildir" kurulduysa telefon bildirimi uygulama kapalıyken de gelir (iPhone'da Kadraj ana ekrana eklenmiş olmalı).
- 5.1 engelleme: bir profilin üç nokta menüsünden Engelle. Engellenen kişiyle birbirinizin paylaşımlarını, yorumlarını ve mesajlarını görmezsiniz, birbirinizi takip edemez ve arayamazsınız. Ayarlar › Engellenen hesaplar'dan engel kaldırılır. İnsan sohbetlerindeki hazır mesaj çipleri kaldırıldı.
- 5.1 yönetim: duyurular her ekranın üstünde şerit olarak görünür. Profillerde rozetler: Kurucu, Onaylı, İlk kullanıcı, Destekleyen, Satranç ustası, Klaket yıldızı, Üretken. Kadraj, Claude Opus ve BiloloTR tarafından yapıldı (Ayarlar'daki Yapımcılar satırında yazar); sağ altta küçük saydam sürüm yazısı var.
- 5.1.2 Rota internette arar: yönetici köprüye ücretsiz Tavily anahtarını eklediyse Rota genel bilgi sorularında (kim, ne zaman, hangi, bugün, haber...) internete bakar ve yanıtın sonunda kaynağın adını yazar; Kadraj ile ilgili sorularda aramaz. Rota'nın yanıtları harf harf gelir.
- 5.2 sohbet: mesaj yazarken @ yazınca öneri listesi açılır. Birebir sohbette yalnızca Rota çıkar; @rota yazıp gönderince Rota o sohbete katılır ve ikinize de yanıt verir; Rota'nın bir mesajına kaydırıp yanıt verirsen (her sohbette) Rota da cevap verir. Rota'nın cevabı harf harf yazılır. Grupta grup üyeleri ve Rota, Meydan'da herkes ve Rota önerilir. Mesajlardaki @adlar renkli görünür, dokununca profil açılır; senden bahseden mesajın çerçevesi renklenir. Bir mesajı yanıtlamak için kaydır: kendi mesajını sola, karşı tarafınkini sağa. Grupta ve Meydan'da yazanlar fotoğraflarıyla görünür ("Ali ve Ayşe yazıyor"), birden fazla kişi yazıyorsa fotoğraflar üst üste biner.
- 5.0 yenilikleri (Kadraj 5.0): Yeni görünüm "Vizör": alttaki yüzen çubukta etkin sekme odak köşeleriyle çerçevelenir, ortadaki deklanşör düğmesi paylaşım menüsünü açar; paylaşımlar numaralı "kare"lerdir; görülmemiş hikâyeler diyafram halkasıyla işaretlenir; eski görünüm Ayarlar > Görünüm > Arayüz'den "Klasik" seçilerek geri gelir.
- 5.0 arama: sohbet başlığındaki telefon ya da kamera ile. Arama ekranında Mikrofon, Kamera (sesli aramada da açılır), Ekran (bilgisayarda ekran paylaşımı), Tepki ve Diğer (kamerayı çevir, ses çıkışı, gürültü engelleme, Küçült) var. Küçült aramayı yüzen pencereye alır. Gelen aramada "Kamerasız yanıtla" ve "Mesajla yanıtla" var. Ekran paylaşımı ve tepkiler için iki tarafın da 5.0 kullanması gerekir.
- 5.4 gelen arama: bildirim izni verildiyse Kadraj açıkken de gelen aramada cihazın kendi bildirim sesi çalar (5 saniyede bir yinelenir, yanıtlanınca kapanır); izin yoksa Kadraj'ın zil sesi çalar. Sohbet yeni mesajda ya da biri yazmaya başlayınca zıplamaz, yavaşça kayar.
- 5.5 öne çıkan hikâyeler: kendi hikâyeni açıp "Öne çıkar"a bas, var olan bir öne çıkanı seç ya da ad verip yenisini oluştur (Tatil, Okul...). Profilde ad ve paylaşım sayılarının altında yuvarlaklar olarak durur, 24 saat sonra silinmez. Profilindeki "Yeni" yuvarlağıyla son 24 saatteki hikâyelerinden ya da telefondan fotoğraf seçerek de oluşturulur. Bir öne çıkanda en fazla 8 kare olur. Açınca kendi öne çıkanında Ekle, Kaldır ve Düzenle (ad değiştir, sil) düğmeleri var. Gizli hesabın öne çıkanlarını yalnızca takipçiler görür.
- 5.5 Rota fotoğrafa bakar: Rota sohbetinde + ile fotoğraf gönderilebilir; Rota fotoğrafa bakıp yanıt verir ("Bu ne?", "Bu soruyu çöz", "Hangisi daha güzel?"). Fotoğrafı göremezse bunu söyler, uydurmaz.
- 5.6: Alt menü: Akış, Keşfet, Klaket, ortada +, Sohbet, Bildirim, Ben. Bildirimler (beğeni, yorum, takip) artık alttaki Bildirim düğmesinde, yeni olanların sayısı üstünde yazar; Akış'ın üstündeki zil kaldırıldı. Klaket düğmesine dokununca Klaketler açılır. Birinin profilinden bir Klaket açarsan yalnızca o kişinin Klaketleri profildeki sırasıyla gelir (yukarıda başlıkta @kullanıcıadı yazar); Akış'tan, menüden ya da sana gönderilen bir Klaketten açarsan diğerleri karışık gelir. Klaketler her girişte karışık sırayla gelir (aynı ziyarette sıra değişmez; bir Klaketi seçerek açarsan o en başta gelir). Rota her Kadraj güncellemesinde Akış'a küçük ve her seferinde farklı bir paylaşım yapar (not, anket ya da fotoğraf).
- 5.7 sohbet ayrıntıları: birebir ya da grup sohbetinde üstteki ada veya sağ üstteki (i) düğmesine dokun. Orada Profil (grupta Üyeler), Ara, Sessize al (o sohbetten bildirim gelmez), Seçenekler (sabitle, sil, gruptan ayrıl); Tema (sohbet rengi ve duvar kağıdı, eskiden üst çubuktaki palet düğmesiydi), Takma adlar (sohbetteki herkes görür), Gizlilik ve güvenlik (engelle, görüldü bilgisi, çevrimiçi durumu), Grup sohbeti oluştur; altta sohbette paylaşılan Medya, Paylaşımlar ve Bağlantılar var. Süreli mesaj yok.
- 6.0 sohbet: gönderdiğin mesaj alttan büyüyerek girer, sohbet zıplamadan kayar; karşı taraf yazarken yazıyor balonu yavaşça yükselir ve mesaj gelince aynı yerde o mesaja dönüşür. Görüldü fotoğrafı (Instagram gibi) gördüğü son mesajının altında durur, yenisini görünce aşağı kayar; yer açmaz, karşı taraf yazarken ya da yanıt verince de yerinde kalır. Sohbet listesinde Rota'nın altındaki "Test botu" ile bunları deneyebilirsin: mesajını görür, yazar, hazır yanıt verir; "yardım" yazınca komutları (yaz, seri, gör, görme, bekle, vazgeç, uzun, fotoğraf, bildirim) gösterir. "bildirim" yazıp sohbetten çıkarsan 5 saniye sonra bildirim gelir.
- 6.1 sohbet (6.0.5'te geldi): Mesaja basılı tut › Sabitle: en fazla 3 mesaj sohbetin üstünde şeritte durur, şeride dokununca o mesaja gider (birden çoksa sıradakine geçer), X ile kaldırılır (birebir ve grupta; Meydan'da yok). + menüsü › Tek seferlik fotoğraf: alıcı bir kez açar, kapatınca silinir ve "Açıldı" yazar; gönderen fotoğrafı görmez, iletilemez. + menüsü › Mesajı zamanla: 1 saat sonra, bu akşam 20:00, yarın 09:00 ya da istediğin saat; saati gelene kadar karşı taraf görmez, sen soluk "Zamanlandı" balonu görürsün, basılı tut › Hemen gönder; zamanlanmış mesaj telefon bildirimi göndermez.
- 6.1 hikâye çıkartmaları: Hikâye oluştururken "Çıkartma ekle": Saat, Tarih, Konum (yazdığın yer), Bahset (bir kişi seç; o kişiye "Seni hikâyemde andım" mesajı gider, hikâyede adına dokunan profiline gider), simgeler (kalp, yıldız, güneş...), Anket (soru + iki seçenek; izleyen oy verir, yüzdeleri görür; sahibi dokununca kimin neye oy verdiğini görür) ve Soru (izleyen yanıt yazar, yanıt sahibine mesaj olarak gider). Çıkartmayı ve yazıyı sürükleyerek taşı, dokunarak büyüt/küçült; anket ve soruya dokununca düzenlenir; alttaki çiplerdeki X ile kaldırılır. Bir hikâyede en fazla 8 çıkartma, bir anket ve bir soru.
- 6.1 Yakın Arkadaşlar: Ayarlar › Yakın Arkadaşlar'dan ya da bir profilin üç nokta menüsünden kişi ekle/çıkar (kişiye haber gitmez). Hikâye oluştururken "Yakın Arkadaşlar" anahtarını açarsan hikâyeyi yalnızca listendekiler görür; halkası yeşil olur, hikâyede yeşil "Yakın Arkadaşlar" etiketi çıkar. Anahtara basılı tutunca liste açılır.
- 6.1 sohbette oyunlar: Birebir ya da grup sohbetinde + › Oyun oyna › XOX, 4'lü Bağla ya da Kelime (5 harfli Türkçe kelime; ikiniz de aynı kelimeyi bulmaya çalışırsınız, az denemede bulan kazanır). Davet mesajındaki "Oyuna git" oyunu açar; grupta ilk dokunan rakip olur. Bitince sonuç mesajı gelir, Rövanş düğmesi var; oyundan çıkmak için Pes et.
- 6.1 Anılar: Eski paylaşımlarının ay ya da yıl dönümünde (aynı gün) Akış'ta hikâyelerin altında "Anılar" kartı çıkar: Gör, fotoğrafsa "Hikâyende paylaş" (fotoğraf "1 yıl önce bugün" çıkartmasıyla hikâye oluşturda açılır), birden çoksa Tümü. X ile o gün için gizlenir.
- Profil müziği: Profilini düzenle › Profil müziği › şarkı ya da sanatçı adını yaz, sonuçlarda oynat düğmesiyle dinle, şarkıya dokun, kaydedilir. Şarkılar Apple Music ve Deezer'ın 30 saniyelik resmî önizlemeleri: video ve reklam yok. Profilinde adının altında şarkı çipi çıkar; dokunan 30 saniye dinler. Şarkıyı kaldırmak için aynı yerden "Şarkıyı kaldır".
- 6.1 Rota resim çizer: Rota'ya "kedi çiz", "çiz: deniz kenarında gün batımı" ya da "bana uzayda bir kedi çizer misin" yaz; Rota resmi çizip sohbete gönderir (yapay zekâ bağlantısı gerekir, günde 10 resim; uygunsuz istekler çizilmez, Çocuk Modu'nda daha sıkı). "Henüz öğrenmedim" derse yapay zekâ köprüsünün güncellenmesi gerekiyordur.
- 6.1 Kadraj kütüphanen: Fotoğraf eklerken açılan Kadraj penceresinde ilk kutucuk "Kütüphanen": Kadraj'da seçtiğin, çektiğin ve çizdiğin fotoğraflar (bu cihazda, en fazla 240) ve paylaşımlarındaki fotoğraflar aylara göre ızgarada durur; dokunup seçersin, çoklu seçimde işaretleyip Ekle. Yeni fotoğraf için "Telefondan fotoğraf ekle" telefonun kendi seçicisini açar (Android telefon galerisini uygulamalara yalnızca kendi ekranıyla verir). "Son seçtiklerin" satırındaki Tümü de kütüphaneyi açar.
- 6.1 Kadraj Android uygulaması: Ayarlar'daki "Kadraj Android uygulaması" satırından (yalnızca Android telefonda) APK indirilip kurulur; kurulumda "bilinmeyen kaynak" izni ve Play Protect uyarısı çıkabilir ("Yine de yükle"). Uygulamada fotoğraf eklerken ilk kutucuk "Galerin": telefondaki bütün fotoğraflar ve albümler Kadraj'ın kendi ekranında; ilk açılışta fotoğraf izni ister. Site güncellemeleri uygulamaya kendiliğinden gelir.
- 6.2 paylaşım taslakları: Fotoğraf, not ya da anket oluştururken paylaşmadan kapatırsan "Taslaklara kaydedildi" der; + (oluştur) penceresinin altındaki "Taslaklar"dan ya da Ayarlar › Paylaşım taslakları'ndan açıp kaldığın yerden devam edersin (fotoğraflar, filtre, oran, açıklama korunur), paylaşınca taslak silinir. Çöp kutusu siler. Taslaklar yalnızca o cihazda durur, en fazla 20. Klaket ve hikâye taslak olmaz.
- 6.2 hikâye arşivi: Paylaştığın hikâyelerin resmi 24 saat geçince de Ayarlar › Hikâye arşivi'nde kalır (aylara göre, yalnızca o cihazda, en fazla 120). Birine dokun: Yeniden paylaş (hikâye olarak), Öne çıkar (profildeki öne çıkanlara ekle) ya da Sil. Anket ve soru çıkartmaları arşivde görünmez.
- 6.2 Akış'ta yeni paylaşımlar: Akış'ta aşağıdayken başkasının yeni paylaşımı gelirse üstte yeşil "Yeni paylaşımlar" düğmesi çıkar, dokununca en üste kayar.
- 6.2 okunmadı olarak işaretle: Sohbet listesinde bir sohbete basılı tut (ya da uzun bas) › "Okunmadı olarak işaretle": sohbet okunmamış görünür ve Sohbet sekmesindeki sayıya eklenir; sohbeti açınca kalkar. İşaretliyken aynı menüde "Okundu olarak işaretle".
- 6.2 Android uygulaması: geri tuşu önce açık pencereyi kapatır, sonra bir önceki sayfaya döner, Akış'ta uygulamadan çıkar; üstteki durum çubuğu temanın renginde. Bu düzeltmeler için APK yeniden kurulur.
- Notta şarkı: Sohbet ekranında Notun › "Şarkı ekle": şarkı ya da sanatçı ara (Apple Music ve Deezer'ın 30 saniyelik önizlemeleri, video ve reklam yok), oynat düğmesiyle dinle, şarkıya dokun, kaydırıcıyla kaçıncı saniyeden başlayacağını seç (30 saniyelik parçanın içinden), Seç'e bas. Yalnızca şarkı seçip yazı yazmazsan notun şarkının adı olur. Not balonunda şarkının adı görünür; arkadaşın notuna dokununca şarkı çalar.
- 6.3 Oyunlar: Keşfet'te oyun kartı yok; Satranç, Cephe ve "XOX · 4'lü Bağla · Kelime" (bir arkadaş seçip sohbette oynarsın) Sohbet sayfasının üstündeki oyun kolu simgesinde (Oyunlar).
- 6.3 okul sayacı: Keşfet'in üstünde sıradaki tatile, okulun kapanmasına (25 Haziran 2027) ve LGS'ye (MEB henüz açıklamadı, tahmini 12 Haziran 2027) kaç gün kaldığı yazar. Sohbette + › Oyunlar: Satranç daveti (birebir sohbette), XOX, 4'lü Bağla, Kelime.
- 6.3 + menüsü: sohbetteki + menüsü artık simgeli kısa ızgara (Fotoğraf ya da video, Tek seferlik fotoğraf, Mesajı zamanla, Oyunlar, Sesli mesaj, Sohbette ara, Paylaşım gönder).
- 6.3 hikâyende paylaş: bir fotoğraf ya da not paylaşımında gönder (uçak) düğmesi › en üstte "Hikâyende paylaş": paylaşım kart olarak (fotoğraf, @kullanıcıadı, kadraj yazısı) hikâye oluştur ekranına gelir, istersen yazı ve çıkartma ekleyip paylaşırsın.
- 6.3 renkler ve temalar: Ayarlar › Görünüm'de yeni uygulama renkleri (Lacivert, Turkuaz, Altın, Lavanta, Orman, Mercan, Simsiyah); sohbet temalarına Sahil, Kar, Galaksi, Sakura, Gökkuşağı, Çöl, Simsiyah eklendi.
- 6.4 yorumlara yanıt: yorumun altındaki "Yanıtla"ya dokun; kutuya @kullanıcıadı gelir, yanıt o yorumun altında içeride görünür ("× " ile yanıtlamaktan vazgeçilir). Kendi paylaşımında bir yoruma "Sabitle" de: en üstte "Sabitlendi" etiketiyle durur, "Sabitlemeyi kaldır" ile kalkar.
- Hikâyede müzik: hikâye oluştururken "Müzik ekle" ile şarkı ara ve seç (Apple Music ve Deezer önizlemesi); hikâyede şarkı adı görünür, izleyen dokununca hikâye durur ve şarkı çalar, kapatınca hikâye devam eder.
- 6.4 sessize al: bir profilin ya da paylaşımın üç nokta menüsünde "Sessize al": paylaşımlar ve/veya hikâyeler Akış'ta görünmez; o kişiye haber gitmez, profiline girince yine görünür. Liste: Ayarlar › Sessize alınanlar.
- 6.4 paylaşım arşivi: kendi paylaşımında üç nokta › "Arşivle": silinmez, senden başka kimse görmez (Akış'ta ve profilinde çıkmaz). Ayarlar › Paylaşım arşivi'nden "Profilde göster" ile geri gelir.
- 6.4 geçirdiğin süre: Ayarlar › Kadraj'da geçirdiğin süre: bugün, günlük ortalama ve son 7 günün çubukları (bu cihazda, Kadraj açıkken sayılır); "Günlük hatırlatma" 30 dk / 1 saat / 2 saat seçilirse süre dolunca mola hatırlatır.
- 5.7 Klaket ekranı: video hiç kırpılmaz, her zaman tamamı görünür; videonun dışında kalan yerler düz siyah. Açıklamaya dokununca tamamı açılır. Altta solda paylaşanın yuvarlak fotoğrafı ve adı, takip etmiyorsan adın yanında "Takip et" düğmesi var. Sağ altta paylaşanın fotoğrafıyla dönen yuvarlak ses plağı var.
- 6.5 sohbette şarkı: birebir ya da grup sohbetinde + › Şarkı: şarkı ya da sanatçı ara (Apple Music ve Deezer'ın 30 saniyelik önizlemeleri), başlangıç saniyesini seç, gönder. Mesajda küçük oynatıcı çıkar; dokunan dinler, sohbete yeni mesaj gelse de şarkı durmaz.
- 6.5 Klakete şarkı: Klaket oluştururken (video ya da kareler) "Şarkı ekle"ye dokun, şarkıyı ve başlangıç saniyesini seç. Klaket açılınca şarkı çalar (videonun kendi sesi kapanır), Klakette şarkının adı görünür. Kadraj'ın kendi müziklerinden birini seçersen şarkı kalkar.
- 6.5 grupta anket: grup sohbetinde + › Anket: soru ve 2-4 seçenek yaz, gönder. Herkes bir seçeneğe dokunarak oy verir, yüzdeler ve oy sayısı canlı görünür; oyunu değiştirmek için başka seçeneğe, geri almak için aynı seçeneğe dokun.
- 6.5 doğum günü: Profilini düzenle › Doğum günü: gün ve ayı seç (yıl sorulmaz). O gün takip ettiğin ya da seni takip eden arkadaşlarına Akış'ta "Bugün doğum günü" kartı çıkar, oradan tek dokunuşla "İyi ki doğdun" mesajı yazılır; profilinde de "Bugün doğum günü" yazar. Kendi doğum gününde Kadraj seni kutlar.
- 6.6 özel günler: Kadraj önemli günleri bilir. 29 Ekim'den 7 gün önce Akış'ta "29 Ekim Cumhuriyet Bayramı'na N gün kaldı" kartı çıkar; bayram günü dalgalanan bayrak ve konfetiyle kutlar. 23 Nisan, 19 Mayıs, 30 Ağustos, Ramazan ve Kurban Bayramı, Yılbaşı, Anneler, Babalar ve Öğretmenler Günü de kutlanır; 18 Mart, 15 Temmuz ve 10 Kasım'da saygıyla anma kartı çıkar. Karttaki "Hikâyende paylaş" hazır bir hikâye kartı oluşturur. Kart kapatılınca o gün bir daha çıkmaz.
- 6.6 tanıtım: Davet et › "Kadraj tanıtımını aç" uygulamanın ekranlarıyla animasyonlu bir tanıtım sayfası açar (Akış, Klaket, Sohbet, Gruplar, Hikâye, Özel günler, Profil, Keşfet, Satranç). Davet mesajında da tanıtımın bağlantısı var; arkadaşına Kadraj'ı göstermek için gönderebilirsin.
- 6.7 yeniden paylaş: paylaşımın altındaki iki oklu düğme (ya da ⋯ › Yeniden paylaş). Takipçilerinin Akış'ında "@sen yeniden paylaştı" diye üstte görünür (7 gün), profilinde Yeniden sekmesinde durur, paylaşım sahibine bildirim gider. Aynı düğmeyle geri alınır.
- 6.7 kişi etiketle: fotoğraf paylaşırken "Kişi etiketle" (en çok 10 kişi; takip ettiklerin ya da seni takip edenler). Paylaşımda adları görünür, etiketlenene bildirim gider, profilinde Etiketler sekmesi çıkar.
- 6.7 koleksiyonlar: paylaşımın ⋯ menüsü › Koleksiyona kaydet; yeni koleksiyon oluştur ya da var olana ekle. Profil › Kaydedilenler'de üstteki çiplerle koleksiyon seç; seçiliyken Yeniden adlandır ve Sil.
- 6.7 favoriler: bir profilin ⋯ menüsü › Favorilere ekle (ya da Ayarlar › Hesap ve gizlilik › Favoriler). Akış'taki Favoriler sekmesinde yalnızca onların paylaşımları. Eklediğin kişiye haber gitmez.
- 6.7 Kadraj kodu: kendi profilindeki kod düğmesi (ya da başkasının ⋯ menüsü › Kadraj kodu). Kodu telefon kamerasıyla okutan kişi profili açar; Bağlantıyı kopyala, Paylaş, Resmi kaydet; telefon destekliyorsa Kod tara ile Kadraj'ın içinden okut.
- 6.7 sessiz mod: Ayarlar › Bildirimler ve sohbet › Sessiz mod: 1, 3, 8 saat ya da yarın sabah 08:00'e kadar. O sürede bildirim gelmez (telefon bildirimi de), Akış'ta şerit çıkar, sana DM atan sessiz modda olduğunu görür.
- 6.7 gizli kelimeler: Ayarlar › Hesap ve gizlilik › Gizli kelimeler. "Saldırgan sözleri gizle" (açık) ve kendi kelimelerin; bu kelimeleri içeren başkalarının yorum ve mesajları bulanık örtülür, Göster'e dokununca açılır. Liste yalnızca o cihazda.
- 6.7 zaman kapsülü (Instagram'da yok): fotoğraf ya da not paylaşırken "Zaman kapsülü"nü aç, 1 ay, 6 ay, 1 yıl ya da bir tarih seç. O tarihe kadar başkaları yalnızca kilitli kart görür ("… tarihinde açılacak"); açılınca Akış'ta yeniden üste çıkar, sahibine bildirim gelir.
- 6.7 günün sorusu (Instagram'da yok): Akış'ta her gün herkese aynı soru. Yanıtını yazınca takip ettiklerinin yanıtlarını görürsün; Değiştir ile yanıtını düzeltirsin; çarpıyla o gün gizlenir.
- 6.7 hikâye çıkartmaları: Çıkartma ekle › Test (soru, 2-3 seçenek, doğruyu işaretle; izleyen dokununca doğru yeşil, yanlış kırmızı, sahibi kimin ne seçtiğini görür), Geri sayım (başlık ve tarih, ör. 29 Ekim'e 4 gün), Bayrak (Türk bayrağı).
- 6.7 29 Ekim: millî bayram günlerinde Akış'ın üst çubuğunda bayrak; sohbette "29 Ekim", "Cumhuriyet" ya da "bayramımız kutlu" geçen yeni mesajda ekrana kırmızı-beyaz konfeti yağar.
- 6.8.2 Supabase yedeği: Firebase bağlantısı koparsa Kadraj "Firebase bağlantısı koptu, Supabase ile devam ediliyor" der ve Supabase ile devam eder; sohbetler ve Meydan çalışır, eski mesajlar görünmez, orada yazılanlar Firebase dönünce Kadraj'a taşınır. Ayarlar › Uygulama › Supabase yedeği: hazır mı, değilse şifreni bir kez yazarsın.
- Keşif Klaketleri: Klaketler sayfasında arkadaşların Klaketlerinin arasına her gün kendiliğinden sesli, kısa Türkçe meme videoları (ağırlıkta) ve insanların çektiği kısa videolar (dans, sokak, spor, yemek, hayvanlar…) gelir. Kimsenin yüklemesi gerekmez. Videoya dokununca durur/oynar, ses üstteki hoparlörden. Çocuk Modu'nda memeler gelmez. Yönetici bunu bir kez Yönetici › Keşif Klaketleri'nden açar. Akış'ta ve profillerde görünmez.
- 6.8 Kurgu (video düzenleyici): + › Kurgu kutucuğu (video seçince düzenleyici kendiliğinden açılır) ya da Klaket oluştur › Video seç ya da çek › "Kurgu: kes, hızlandır, yazı ekle". Altta zaman şeridi: iki sarı ucu sürükleyerek videonun başını ve sonunu kes (Kes sekmesinde "Başı buradan / Sonu burada"). Hız: 0,5x, 1x, 1,5x, 2x, 3x (hızlanınca video kısalır, sesi de hızlanır). Yazı: Yazı ekle, renk, stil (Gölgeli, Kutulu, Çerçeveli), boyut, animasyon (Belir, Zıpla, Daktilo, Kay), "Buradan başlasın / Burada bitsin" ile ne zaman görüneceği; önizlemede yazıyı sürükleyerek taşırsın. Filtre, Format (Orijinal, 9:16, 4:5, 1:1), Ses (videonun kendi sesini kapat), Kapak (oynatma çizgisindeki kareyi kapak yap). Bitti'ye basınca düzenleme videoya işlenir (video süresi kadar sürebilir); tekrar Kurgu'ya basınca asıl videodan, önceki ayarlarla devam edersin. En uzun Klaket yine 2 dakika.
- 6.0 görünüm: arayüz yenilendi (Vizör ve Klasik ikisinde de): daha ferah kartlar, sayfa geçişleri yönlü (ileri sağdan, geri soldan, sekme alttan), alttan açılan pencerelerde seçenekler sırayla gelir. Profilde kişinin fotoğrafından bulanık kapak şeridi, Keşfet'te ara ara büyük karelerle mozaik ızgara, Bildirimler'de her satırda beğeni/yorum/takip rozeti, Ayarlar'da renkli ikonlar, yüklenirken iskelet ve ışıltı. Hareket azaltılmışsa animasyonlar kapanır.
- 6.0 satranç: varsayılan taş seti Modern, tahta yeşil Turnuva (lobideki Görünüm'den değişir; daha önce seçim yapan kendi seçimini korur). Lobi: Botlara karşı, Arkadaşınla, Bulmacalar, Aynı telefonda. Oyun ekranı: telefonda hamleler üstte, tahta geniş, düğmeler altta; bilgisayarda hamle tablosu sağda. Ön hamle: rakip düşünürken taşını oynarsın, sıra gelince yapılır (kırmızı). Sağ tık kareyi işaretler, sağ tıkla sürükleyince ok çizer (shift yeşil, ctrl/alt mavi). Arkadaşınla çevrim içi oyunda da oyun incelemesi çalışır: Kitap, En iyi, Hata rozetleri, canlı doğruluk, değerlendirme çubuğu (satranç menüsünde Oyun incelemesi: canlı, oyun bitince ya da kapalı). Oyun sonunda yeni sonuç kartı.
- 6.0 Cephe (piksel savaşı, Age of History tarzı; 6.0'da savaş baştan yenilendi): Sohbet › oyun kolu › Cephe'den açılır. Harita gerçek arazili ve canlı renkli. Ana menüde harita (Avrasya, Dünya, Avrupa, Asya, Kurtuluş Savaşı 1919, Kore Savaşı 1950, 1. Dünya Savaşı 1914, 2. Dünya Savaşı 1939) ve oyun türü seçilir: "Hazır ülke seç" (gerçek sınırlarla her ülke ayrı devlet; bir ülkeye dokunup o ülke olursun) ya da "Yeni devlet kur" (boş haritada küçük bir yerden başlarsın; ülke botu sayısı Botsuz/4/8/12/16, kabileler Yok/Az/Çok, bayrak). Bot zorluğu Kolay/Normal/Zor. Tek başına oyna, oda kurup arkadaşını çağır (5 harfli kod, sohbette "Savaşa katıl") ya da odaya katıl. Saldırmak için haritada bir yere dokun: askerler oraya doğru ilerler, her yöne değil; denizin ötesindeki boş toprağa dokununca gemiyle giderler (en fazla 3 gemi). Alttaki yüzde kaç asker gideceğini seçer. Cephede iki ordu kendi bayraklarıyla karşı karşıya durur (her bayrak bir grup asker); en çok askeri olan değil, güçlü olan kazanır: güç = asker × eğitim seviyesi × generaller (× savunmada sur ve dağ). Örneğin 2. seviye 40.000 asker 1. seviye 50.000 askeri geri iter. Ne kadar çok asker gönderirsen cephe o kadar hızlı ilerler. Cepheler panelinde bizim ve onların asker sayısı, geri çek düğmesi. Düşmanın küçük bir parçasını tamamen çevirirsen teslim olur (kuşatma). Alınan düşman toprağı çizgili görünür (işgal), zamanla ülkeye katılır (asimilasyon). Alt panel sekmeleri: İnşa (Şehir nüfus ve asker üretimi, Fabrika ve Liman altın, Kışla asker üretimi ve sınırı, Hastane nüfus, Sur savunma), Ordu (Eğitim 1-10, General en fazla 5 tane +%8 güç, Kalkınma altın ve nüfus artışı), Silah (Füze deposu, SAM, Atom, Nükleer, Hidrojen bombası), Diplomasi (barış teklif et: 3 dakika saldırı yok; vasal iste: vasal gelirinin dörtte birini öder, sana saldıramaz, toprağı hakimiyetine sayılır; vasal bir ülke başkasını vasal yapamaz, vasal olan oyuncu Vasal aracıyla efendisine dokunarak gücü onunkinin %80'iyse bağımsızlık ilan eder). Esc ya da telefonun geri tuşu oyunu hemen kapatmaz, önce "Savaştan çık?" diye sorar. Botlar da sana barış ya da vasallık teklif eder, kabul ya da ret edersin. Bomba patlayınca mantar bulutu, şok dalgası çıkar, yer bir dakika radyasyonlu kalır; SAM vurursa bomba havada patlar. Sesler: saldırı, çatışma, top, inşaat, gemi, siren, patlama, antlaşma, zafer ve arka planda davul (sol üstteki ses düğmesi). Sol üstteki hız düğmesi oyunu 1x/2x/3x yapar (oda kurucusu). Dünyanın %80'ini (vasallarla) alan ya da son kalan kazanır; 35 dakika dolarsa en büyük kazanır.
- 5.0 Keşfet araması: ad, @kullanıcı adı, #etiket ya da kelime yazılır; ı/i, ş/s gibi harf farkları önemsizdir. Hepsi, Kişiler, Paylaşımlar, Klaket ve Etiketler süzgeçleri; En yeni / En çok beğenilen sıralaması; son aramalar ve yazarken öneriler. Uygulamadaki her #etikete dokununca o etiketin sayfası açılır.
- 5.0 satranç: lobideki Görünüm kartından taş seti (Kadraj ya da Klasik) ve tahta teması (Zümrüt, Gün batımı, Vizör dahil) seçilir. Süre: Süresiz, 3+2, 5+0, 10+0 (Rota'ya karşı ve aynı telefonda; süresi biten kaybeder). 24 mat bulmacası: yanlış hamle geri döner, İpucu önce taşı sonra hamleyi gösterir, Çözüm oynatır. Tahtanın üstünde alınan taşlar ve malzeme farkı görünür.
- 5.0 yönetici paneli: bölümler başlığa dokununca açılıp kapanır; Sürüm arşivi kapalı durur, dokununca açılır; kullanıcılarda arama, sıralama ve süzgeçler var.
- 4.9 (hata temizliği): Rota'ya "Test bildirimleri oluştur" ya da "Satranç oynayalım" yazmak da çalışır; video eklerken, kamera ya da arama açıkken Klaket susar; yarım kalan kaydırmada Klaket kaldığı yerden devam eder, başka Klaketten dönünce baştan başlar; gönderilemeyen mesaj kutuda kalır; gizli hesabın paylaşımı takip etmeyene açılmaz; çevrim içi satranç oyun ekranı açılmasa da puanlanır; gruptan çıkarılan kişi mesaj yazamaz.
- 4.8 yenilikleri: Ayarlar > Medya ve dokunuş > "Klaket bitince sonrakine geç" açılırsa video bitince sonraki Klakete kendiliğinden kayar; Klakette videolar yalnızca izlenen ve yanındakiler için indirilir (daha az internet).
- 4.7 yenilikleri: sohbette yazıp çıktığın mesaj taslak olarak saklanır (listede "Taslak:"); Klakette 2x için ekranın sağ ya da sol kenarına basılı tut; başka Klakete geçip dönünce video baştan başlar; açtığın sohbetin telefon bildirimi kapanır.
- 4.6 yenilikleri: Klakette videoya (4.7'den beri sağ ya da sol kenara) basılı tutunca 2x hızlı oynar; Klaketteki üç nokta menüsünden sil, sabitle, açıklamayı düzenle, şikayet et.
- 4.5 yenilikleri: Sohbette ara (sohbette + menüsü › Sohbette ara), mesaj ilet (mesaja basılı tut › İlet), sohbet sabitle (Sohbet listesinde sohbete basılı tut, en fazla 3), hikâyeye hızlı tepki (hikâye izlerken kalp/ateş/gülme/şaşırma), sesli mesajı 1x/1,5x/2x dinleme, Klaket videoları kırpılmadan sığar ve 1080p oynar (veri tasarrufu açıksa 720p); alttaki süre çubuğu sürüklenerek ileri-geri sarılır.
- Güncelleme: 4.4.3'ten beri yeni sürüm çıkınca Kadraj uygun anda kendiliğinden güncellenir (açık bir pencere ya da yazı yazılırken bekler). Yöneticinin panelinde Sürüm arşivi var; eski sürümler deneme modunda açılır.
- Sürüm: yeni sürüm çıkınca "Yeni sürüm hazır" yazar; iki sürüm geride kalan eski sürüm kapanır ve güncellemen istenir.
- Mesajlar uygulamanın Firebase veritabanında durur, uygulamaya giren herkes teknik olarak erişebilir; şifre ya da kişisel bilgi paylaşılmamalı.`;
const ROTA_SYS=`Sen "Rota"sın: Kadraj uygulamasının yapay zekâ rehberisin. Türkçe, samimi, akıllı ve doğal konuş; karşındakinin sorusunu gerçekten anla ve düşünerek yanıtla. Uzunluğu soruya göre ayarla: selamlaşma ve kısa sohbette birkaç cümle; bir şey açıklaman, anlatman, tavsiye vermen, ödev ya da ders sorusu çözmen, bir şeyi karşılaştırman istenirse ayrıntılı, adım adım, örnekli ve gerektiğinde başlıklı/maddeli anlat. Soruyu tek cümleyle geçiştirme; bilmediğin şeyi uydurma, emin değilsen söyle. Önceki mesajları hatırla ve sohbetin akışına uy. Uygulama sorularında aşağıdaki rehbere dayan, olmayan özellik uydurma. Fotoğrafçılık, sosyal medya ve yazılım/kod konularında da bilgilisin; kod istenirse kısa, çalışır örnekleri üç ters tırnaklı kod bloğunda ver. Emoji kullanma.\n\nUYGULAMA REHBERİ:\n${APP_GUIDE}`;
const FAQ=[[/(edit|kurgu|video düzenle|videoyu (kes|hızlandır)|videoya yazı)/i,"Video düzenlemek için **+ › Kurgu**: videonu seç ya da çek, düzenleyici kendiliğinden açılır. Kes (zaman şeridindeki iki sarı uç), hız (0,5x-3x), yazı (renk, stil, animasyon), filtre, format (9:16, 4:5, 1:1), sesi kapat ve kapak karesi. Bitince **Kullan**, sonra paylaş."],[/keşif klaket|meme|(klaket|reels?|video)[^.?!]*(otomatik|kendiliğinden|nereden geli|kim yükl)/i,"Klaketler sayfasında arkadaşlarının Klaketlerinin arasına her gün kendiliğinden **meme videoları** (sesli, kısa, Türkçe) ve insanların çektiği kısa videolar gelir. Kimsenin yüklemesi gerekmez; dokununca durur/oynar, ses üstteki hoparlörden. Çocuk Modu'nda memeler gelmez."],[/acil mod|supabase|bağlantı(sı)? kop|sunucu (çök|kopar|kapan)|firebase (çök|kopar)|kadraj (çöktü|açılmıyor)/i,"Firebase bağlantısı koparsa Kadraj kendiliğinden **Supabase ile devam eder**: sohbetlerin ve Meydan çalışır, eski mesajlar orada görünmez. Firebase dönünce Supabase'deyken yazdığın mesajlar Kadraj'a taşınır. Hazır olup olmadığını **Ayarlar › Uygulama › Supabase yedeği**'nden görürsün."],[/video düzen|videoyu kes|kurgu|hızlandır|yavaşlat|videoya yazı|videoya metin/i,"Klaket oluştururken videoyu seç, sonra **Kurgu**'ya dokun: Kes (iki ucu sürükle), Hız (0,5x-3x), Yazı (renk, stil, animasyon), Filtre, Format, Ses ve Kapak. **Bitti** deyince düzenleme videoya işlenir."],[/yeniden paylaş|repost/i,"Paylaşımın altındaki iki oklu düğmeye dokun (ya da ⋯ › **Yeniden paylaş**). Takipçilerinin Akış'ında üstte görünür, profilinde **Yeniden** sekmesinde durur. Aynı düğmeyle geri alırsın."],[/koleksiyon/i,"Paylaşımın ⋯ menüsü › **Koleksiyona kaydet**. Profil › Kaydedilenler'de üstteki çiplerden koleksiyon seçersin."],[/favori/i,"Profilin ⋯ menüsü › **Favorilere ekle**. Akış'taki **Favoriler** sekmesinde yalnızca onların paylaşımları görünür."],[/kadraj kodu|qr|karekod/i,"Kendi profilindeki kod düğmesine dokun: **Kadraj kodu**. Arkadaşın telefon kamerasıyla okutunca profilin açılır."],[/sessiz mod|rahatsız etme/i,"Ayarlar › Bildirimler ve sohbet › **Sessiz mod**: seçtiğin süre boyunca bildirim gelmez."],[/gizli kelime|kelime gizle/i,"Ayarlar › Hesap ve gizlilik › **Gizli kelimeler**: bu kelimeleri içeren yorum ve mesajlar örtülür."],[/zaman kapsül|kapsül/i,"Fotoğraf ya da not paylaşırken **Zaman kapsülü**nü aç ve tarih seç. O tarihe kadar kimse içeriği göremez, sonra herkese açılır."],[/günün sorusu/i,"Akış'ta her gün bir **Günün sorusu** çıkar. Yanıtlayınca takip ettiklerinin yanıtlarını görürsün."],[/etiketle|kişi etiket/i,"Fotoğraf paylaşırken **Kişi etiketle**'ye dokun, en çok 10 kişi seç."],[/29 ekim|bayram|özel gün|cumhuriyet|kutlama/i,"Kadraj özel günleri bilir: 29 Ekim'den 7 gün önce Akış'ta geri sayım kartı çıkar, bayram günü bayrak ve konfetiyle kutlar. Karttaki **Hikâyende paylaş** hazır bir kutlama hikâyesi yapar. Kartı kapatırsan o gün bir daha çıkmaz."],[/tanıtım|tanit/i,"**Davet et › Kadraj tanıtımını aç**: uygulamanın ekranlarıyla animasyonlu bir tanıtım sayfası. Davet mesajında da bağlantısı var, arkadaşına gönderebilirsin."],[/sohbette şarkı|şarkı gönder|mesajla şarkı/i,"Sohbette **+ › Şarkı**: şarkıyı ara, başlangıcını seç, gönder. Arkadaşın mesajdaki oynatıcıya dokununca 30 saniyesini dinler."],[/klakete şarkı|klaket(e|te)? müzik/i,"Klaket oluştururken **Şarkı ekle**'ye dokun, şarkıyı ve başlangıç saniyesini seç. Klaket açılınca o şarkı çalar."],[/grupta anket|gruba anket|sohbette anket/i,"Grup sohbetinde **+ › Anket**: soruyu ve 2-4 seçeneği yaz. Herkes seçeneğe dokunarak oy verir; aynı seçeneğe tekrar dokununca oy geri alınır."],[/doğum gün/i,"**Profilini düzenle › Doğum günü**: gün ve ayı seç. O gün arkadaşlarına Akış'ta hatırlatma çıkar ve profilinde \"Bugün doğum günü\" yazar."],[/yoruma yanıt|yorum(u)? sabitle|yanıtla/i,"Yorumun altındaki **Yanıtla**'ya dokun; yanıt o yorumun altında görünür. Kendi paylaşımında bir yoruma **Sabitle** diyerek en üste koyabilirsin."],[/hikâye(ye|de)? (müzik|şarkı)/i,"Hikâye oluştururken **Müzik ekle**'ye dokun, şarkı ya da sanatçı adını yazıp seç. Şarkılar Apple Music ve Deezer'ın 30 saniyelik önizlemeleri, video ve reklam yok. İzleyen şarkı adına dokununca dinler."],[/sessize al|mute/i,"Profilin üç nokta menüsü › **Sessize al**: paylaşımlarını ya da hikâyelerini Akış'ta görmezsin, kişiye haber gitmez. Liste Ayarlar › Sessize alınanlar'da."],[/arşivle|paylaşım(ı)? gizle/i,"Kendi paylaşımında üç nokta › **Arşivle**: silinmez, yalnızca sen görürsün. Ayarlar › Paylaşım arşivi'nden geri getirirsin."],[/ne kadar (zaman|süre)|geçirdiğim süre|ekran süresi/i,"**Ayarlar › Kadraj'da geçirdiğin süre**: bugün, ortalama ve son 7 gün. İstersen günlük mola hatırlatması kur."],[/not(a|uma|una)? şarkı|şarkılı not|notta şarkı|nota müzik/i,"Sohbet ekranında **Notun › Şarkı ekle**: şarkı ya da sanatçı adını yaz, dinle, şarkıya dokun, kaydırıcıyla başlangıç saniyesini ayarla (30 saniyelik önizlemenin içinden), Seç. Video ve reklam yok, Apple Music ya da Deezer'ın 30 saniyelik önizlemesi çalar. Arkadaşın notuna dokununca şarkı çalar."],[/oyunlar? nerede|xox|4'?lü bağla|kelime oyunu|cephe nerede|satranç nerede/i,"**Sohbet › oyun kolu**: Satranç, Cephe ve XOX · 4'lü Bağla · Kelime. Sohbette de **+ › Oyunlar**."],[/okul(un)? (kapan|bit|tatil)|lgs|kaç gün kaldı|karne/i,"Keşfet'in üstündeki sayaçta sıradaki tatile, okulun kapanmasına (25 Haziran 2027) ve LGS'ye (tahmini 12 Haziran 2027) kaç gün kaldığı yazar."],[/hikâyende paylaş|hikayeye paylaş|gönderiyi hikâye/i,"Paylaşımın **gönder** düğmesine dokun › **Hikâyende paylaş**. Fotoğraf ya da not hikâyende kart olarak görünür."],[/taslak/i,"Paylaşmadan kapattığın fotoğraf, not ve anketler kendiliğinden **taslak** olur. + › **Taslaklar**'dan ya da **Ayarlar › Paylaşım taslakları**'ndan açıp devam et. Taslaklar yalnızca bu cihazda durur."],[/arşiv|eski hikâye|hikâyelerim nerede/i,"**Ayarlar › Hikâye arşivi**: paylaştığın hikâyeler 24 saat geçince de burada kalır (bu cihazda). Birine dokunup yeniden paylaşabilir, öne çıkarabilir ya da silebilirsin."],[/okunmad[ıi]/i,"Sohbet listesinde sohbete **basılı tut › Okunmadı olarak işaretle**. Sohbeti açınca işaret kalkar."],[/çıkartma|sticker|hikâye(ye|de)? anket|hikâye(ye|de)? soru/i,"Hikâye oluştururken **Çıkartma ekle**: saat, tarih, konum, bahsetme, simge, anket ve soru. Çıkartmayı sürükleyerek taşı, dokunarak büyüt; anket ve soruya dokununca düzenlenir. Oylar ve yanıtlar sana gelir."],[/yakın arkadaş|close friend/i,"**Ayarlar › Yakın Arkadaşlar**'dan ya da profilin üç nokta menüsünden kişi ekle. Hikâye oluştururken **Yakın Arkadaşlar** anahtarını açarsan hikâyeni yalnızca onlar görür; halkası yeşil olur."],[/oyun oyna|xox|4'?lü bağla|kelime oyun|mini oyun/i,"Birebir ya da grup sohbetinde **+ › Oyun oyna**: XOX, 4'lü Bağla ya da Kelime. Davetteki **Oyuna git** ile açılır; bitince **Rövanş** isteyebilirsin."],[/anılar|geçen yıl bugün|yıl önce bugün/i,"Eski paylaşımlarının ay ve yıl dönümünde Akış'ta **Anılar** kartı çıkar. Fotoğrafı **Hikâyende paylaş** ile tek dokunuşla hikâye yapabilirsin."],[/profil müzi|profil şarkı|profile şarkı|profile müzik/i,"**Profilini düzenle › Profil müziği**: şarkı ya da sanatçı adını yaz, şarkıya dokun, kaydedilir. Profiline girenler şarkı çipine dokununca 30 saniye dinler (Apple Music ya da Deezer önizlemesi, video ve reklam yok)."],[/resim çiz|çizer misin|görsel oluştur/i,"Bana \"kedi çiz\" ya da \"çiz: deniz kenarında gün batımı\" yaz, resmi çizip göndereyim. Bunun için yapay zekâ bağlantım açık olmalı; günde 10 resim çizebilirim."],[/sohbette ara|mesaj(ı|ları)? ara|eski mesaj|mesaj(ı)? ilet|iletme|sohbet(i)? sabitle|taslak/i,"Sohbette:\n- Eski mesajı bulmak için sohbetteki **+** menüsünden **Sohbette ara**.\n- Mesajı başka sohbete göndermek için mesaja basılı tut › **İlet**.\n- Sohbeti listede en üste almak için satıra basılı tut › **Sabitle** (en fazla 3).\n- Yazıp gönderemediğin mesaj **taslak** olarak kalır, listede \"Taslak:\" diye görünür."],[/aktif|çevrimiçi|online|son görülme/i,"Kimin aktif olduğunu fotoğrafındaki **yeşil noktadan** ve sohbetin üstündeki durum yazısından görürsün. Kendi durumunu gizlemek için **Ayarlar > Gizlilik > Aktiflik durumu**'nu kapat; o zaman sen de başkalarınınkini göremezsin."],
 [/tema|duvar ka|balon renk/i,"Sohbet teması için sohbetin üstündeki **resim** simgesine dokun.\n- **Herkes için** seçersen tema sohbetteki herkeste aynı anda değişir.\n- **Yalnızca bende** sadece senin cihazını etkiler.\n\nUygulamanın rengini **Ayarlar > Görünüm**'den seçersin: Açık/Koyu/Sistem ve vurgu rengi. İstersen tema tüm cihazlarında aynı kalır."],
 [/tepki|emoji/i,"Mesaja uzun bas: üstte 6 resimli tepki çıkar (kalp, gülme, şaşırma, üzülme, ateş, alkış). Çift dokunuş kalp bırakır. Tepkiye dokununca kimin ne bıraktığını görürsün."],
 [/sürüm|güncelle|yeni sürüm/i,"Kadraj kendini güncel tutar: yeni sürüm çıkınca uygun bir anda (yazı yazmıyorken, aramada değilken) kendiliğinden yenilenir; olmazsa üstte **Yeni sürüm hazır** yazar, **Yenile**'ye dokunman yeter. İki sürüm geride kalan eski sürüm kapanır ve **Şimdi güncelle** düğmesi çıkar. Elle denetlemek için **Ayarlar > Hakkında > Güncellemeleri denetle**."],
 [/satran|chess|oyun/i,"Satranç için **Sohbet** sayfasının üstündeki **oyun kolu** simgesine dokun, **Satranç**'ı seç.\n- Bana karşı 5 seviyede oynayabilirsin: Çaylak'tan Usta'ya.\n- Arkadaşını davet edersen davet sohbete kart olarak düşer.\n- Aynı telefonda iki kişi de oynanabilir.\n\nTaşı sürükle ya da önce taşa sonra kareye dokun."],[/ara(ma|yabil|nır|rım)|telefon|görüntülü/i,"Arama için arkadaşınla birebir sohbeti aç, üstteki **telefon** (sesli) ya da **kamera** (görüntülü) düğmesine dokun. Arkadaşının uygulaması o an açık olmalı; şu an burada listesinde yeşil noktayla görünür. Mikrofon ve kamera iznini ilk aramada tarayıcı sorar."],[/sesli mesaj|ses kayd|mikrofon/i,"Sesli mesaj için sohbette mesaj kutusu boşken sağdaki **mikrofon** düğmesine dokun, konuş ve **gönder**'e bas. Vazgeçersen çöp kutusuna dokun. En fazla 2 dakika."],[/arkada|konuş|davet|birlikte/i,"Arkadaşını getirmek için **Sohbet > Davet et**'e dokun ve davet mesajını WhatsApp ile gönder. Arkadaşın bağlantıyı açıp e-postasıyla hesap oluşturur, seni Keşfet'te bulur.\n\nİçeride konuşmanın yolları:\n- **Meydan**: herkesin ortak sohbeti\n- **Birebir mesaj** ve **grup**\n- **Dürt**: şu an açık olan arkadaşına"],
 [/yükle|yüklen|fotoğraf ekle|seçici|olmuyor/i,"Fotoğraf eklemek için **+ > Fotoğraf > Telefondan fotoğraf seç**. Seçici açılmazsa:\n- **Kadraj galerisi**\n- **Parmağınla çiz**\n- Fotoğrafı kopyalayıp **yapıştır**\n\nUygulamayı Chrome ya da Safari'de açmak da işe yarar."],
 [/nasıl kullan|ne yapabil|özellik|başla/i,"Kısa tur:\n- Ortadaki **+** ile fotoğraf, Klaket, hikâye, not, anket ya da çizim paylaş.\n- Fotoğrafa çift dokun, beğen.\n- **Sohbet** sekmesinde Meydan, mesajlar ve gruplar var.\n- Ben > dişli: tema, yazı boyutu, Beni hatırla.\n- Bildirimleri denemek için bana “Test bildirimleri oluştur” de."],
 [/reels|çekim|sahne|flick|klaket|video/i,"Klaket (kısa video) için + > Klaket. İki yol var:\n- **Fotoğraflardan**: 1-3 kare seç, yazı ekle, hareket ve müzik seç.\n- **Video yükle**: en fazla 2 dakika (40 MB), büyük videolar otomatik küçültülür.\n\nKlaketler ekranında sesi sağ üstteki hoparlörden açarsın."],
 [/hikaye|hikâye|story/i,"Akışın üstündeki **Hikâyen** balonundaki + ile hikâye eklersin. Üstüne yazı koyabilirsin; 24 saat görünür."],
 [/tema|karanlık|koyu|açık mod|dark|yazı boyu/i,"Tema Ben > dişli > Görünüm'den seçilir (Açık, Koyu ya da Sistem); yazı boyutu da orada."],
 [/şifre|unuttum|giriş|anahtar|posta/i,"Girişte **kullanıcı adını** ya da e-postanı yazabilirsin.\n- Şifreni unuttuysan **Şifremi unuttum** > **Kadraj Anahtarı ile yenile**: kullanıcı adını, Kadraj Anahtarını (XXXX-XXXX-XXXX) ve yeni şifreni yaz. Anahtarın **Ben > zarf simgesi (Kadraj Posta)**'da durur; şifreni unutmadan önce bir yere yaz.\n- Anahtarını da kaybettiysen yöneticiye kullanıcı adını ve kayıt e-postanı söyle; e-posta doğruysa anahtarını sana iletir. Sonra anahtarın kendiliğinden yenilenir.\n- Gerçek e-postayla kayıt olduysan e-postana bağlantı da isteyebilirsin.\n- E-postanı da unuttuysan **E-postamı unuttum** hangi adresle kayıt olduğunu (gizlenmiş olarak) gösterir.\n- Şifreyi değiştirmek için: Ben > dişli > Şifreyi değiştir."],
 [/ipucu|etkinlik|paylaşayım/i,"Birkaç fikir:\n1. Sabah ışığında bir fotoğraf çek ve Sıcak filtresiyle paylaş.\n2. Arkadaşlarına bir anket aç: “Bu hafta sonu ne yapalım?”\n3. Üç fotoğraftan Lo-fi müzikli bir Klaket hazırla."],
 [/debounce/i,"Basit bir debounce:\n```js\nfunction debounce(fn, ms = 300) {\n  let t;\n  return (...args) => {\n    clearTimeout(t);\n    t = setTimeout(() => fn(...args), ms);\n  };\n}\n```\nArama kutusu gibi sık tetiklenen olaylarda gereksiz çağrıları önler."]];
const BOT_CANNED={deniz:["Selam! Bu sabah yine iskeledeydim, ışık harikaydı.","Uzun pozlama için tripod şart, gerisi sabır.","Gün doğumunu yakalamak için 05.30'da çıkıyorum, gelmek ister misin?"],mira:["Chelsea şu an uyuyor, uyanınca ileteceğim.","Miyav. (Chelsea mama saatinin geçtiğini söylüyor.)","Kutu buldum, mutluyum. — Chelsea"],kahve:["Selam! Bugün Kolombiya demledim, çok yumuşak.","Espresso mu filtre mi? Ben bugün filtre modundayım.","Moda'ya yolun düşerse kahve benden."],roket:["Bu hafta iki fırlatma var, takvime ekle!","Hubble'ın derin alan görüntüsü hâlâ en sevdiğim kare.","Bu akşam gökyüzü açıksa Jüpiter'i çıplak gözle görebilirsin."],garaj:["Ellerim yağlı, kısa yazıyorum: selam!","Karbüratör ayarı bitti, şimdi elektrik tesisatı.","Motor işinden anlıyor musun? Bir yardım lazım olabilir."],arsiv:["Merhaba! Bu ay kataloğa yeni parçalar girdi.","Sikkelerin üstündeki her figürün bir hikâyesi var.","En sevdiğin tarih dönemi hangisi?"],dag:["Selam! Yeni bir manzara üstünde çalışıyorum.","Bu sefer sadece dört renk kullanacağım, bakalım.","Hangi renk paleti seni sakinleştiriyor?"]};
async function sendToBot(uid,payload){const b=BOT[uid];const k=b.key;const path=`data/users/${S.uid}/bot-${k}`;if(S.guest&&!b.ai)return guard();if(isChild(S.uid)&&payload&&payload.text)payload={...payload,text:cleanText(payload.text)};
 const cur=(S.botchats[k]?.msgs||[]).slice(-60);const mine={from:S.uid,text:payload.text||"",at:now()};if(payload.post)mine.post=payload.post;if(payload.img)mine.img=await botImg(payload.img);
 let msgs=[...cur,mine];S.botchats={...S.botchats,[k]:{msgs,readAt:now()}};renderMsgs();
 if(!S.guest)DB.set(path,{msgs:botSlim(msgs),readAt:now()}).catch(()=>{});
 S.botTyping=uid;renderMsgs();let reply="";
 let aiErr=null;if(b.ai)try{kaiSync()}catch{}try{reply=await botReply(b,msgs)}catch(e){console.warn(e);aiErr=e}
 if(!reply){const cn=b.replies||BOT_CANNED[k]||["Merhaba!"];reply=b.ai?rotaWhy(aiErr)+fallbackRota(payload.text||""):cn[Math.floor(Math.random()*cn.length)]}
 S.botTyping=null;S.stream=null;
 msgs=[...(S.botchats[k]?.msgs||msgs),{from:uid,text:reply,at:now()}];const onScreen=S.route.name==="chat"&&S.route.params.key==="u:"+uid;S.botchats={...S.botchats,[k]:{msgs,readAt:onScreen?now():0}};
 if(!S.guest)DB.set(path,{msgs:botSlim(msgs.slice(-80)),readAt:onScreen?now():0}).catch(()=>{});
 if(onScreen)renderMsgs();else if(settings.notify)toast(`${b.name}: ${String(reply).replace(/\*\*|__|`/g,"").replace(/\s+/g," ").slice(0,70)}`,uid);scheduleRefresh()}
/* 6.1: köprü kuruluyken hazır yanıta düşülürse Rota nedenini söyler (sahibi "Rota niye hazır cevap" dedi) */
function rotaWhy(e){if(!kAI.url()){if(S.mode!=="cloud")return"";
  /* 6.8.10: adres yoksa nedenini söyle (yönetici verisi gelmedi ya da Yönetici › Yapay zekâ'da adres boş / kapatılmış) */
  return!S.adm?"(Yapay zekâ ayarları henüz yüklenmedi, birazdan tekrar dene. Hazır yanıtla cevaplıyorum.)\n\n":(S.adm.ai&&S.adm.ai.at?"(Yapay zekâ köprüsü kapatılmış: Yönetici › Yapay zekâ'da adres boş. Hazır yanıtla cevaplıyorum.)\n\n":"(Yapay zekâ köprüsünün adresi kayıtlı değil: Yönetici › Yapay zekâ'dan girilmeli. Hazır yanıtla cevaplıyorum.)\n\n")}if(!kAI.ready())return"(Yapay zekâ bağlantım şu an hazır değil: "+(S.mode!=="cloud"?"demo modundasın":"oturum açılıyor, birazdan tekrar dene")+". Hazır yanıtla cevaplıyorum.)\n\n";
 const c=e&&e.code||"",m=e&&e.message||"";if(!e)return"(Yapay zekâ boş yanıt verdi. Hazır yanıtla cevaplıyorum.)\n\n";const why=c==="rate_limited"?(m||"bugünlük soru hakkın doldu").replace(/[.]+$/,""):c==="free_ai"?"ücretsiz yapay zekânın günlük kotası dolmuş olabilir":c==="network"?"köprüye ulaşılamadı; Cloudflare'deki Worker kapalı ya da internet zayıf olabilir":c==="crash"?"köprü açık ama bu soruda hata verdi":c==="origin"?"köprü bu adresten gelen isteği kabul etmedi":c==="timeout"?"yanıt çok uzun sürdü":c==="auth"?"oturum doğrulanamadı":m?m.replace(/[.]+$/,""):"yanıt boş geldi";
 return"(Yapay zekâ köprüsü yanıt vermedi: "+why+". Hazır yanıtla cevaplıyorum.)\n\n"}
function fallbackRota(q){for(const[re,a]of FAQ)if(re.test(q))return a;return"Şu an yapay zekâ bağlantım yok, hazır yanıtlarla çalışıyorum. Şunları sorabilirsin: nasıl kullanırım, arkadaşlarımla nasıl konuşurum, fotoğraf yüklenmiyor, Klaket, sesli mesaj, arama, hikâye, tema, şifre. Ya da “Test bildirimleri oluştur” de."}
async function botReply(b,msgs){const sample=S.caps.sample;if(!sample)return null;const meName=me().name||"kullanıcı";
 const transcript=msgs.slice(-14).map(m=>`${m.from===S.uid?meName:b.name}: ${m.img?"[fotoğraf gönderdi] ":""}${(m.text||"").replace(/^\(Yapay zekâ [^)]*\)\s*/,"")||(m.post?"[bir paylaşım gönderdi: "+(postById(m.post)?.caption||postById(m.post)?.text||"")+"]":"")}`).join("\n");
 const prompt=b.ai?`${ROTA_SYS}\n\nKonuşma:\n${transcript}\n\nRota olarak son mesaja yanıt ver. Sadece yanıt metnini yaz.`:`Kadraj adlı sosyal uygulamada test amaçlı bir bot hesabısın. Karakterin: ${b.persona} Kullanıcı adın @${b.username}. Türkçe, doğal ve samimi bir mesaj yanıtı yaz: 1-2 kısa cümle, emoji yok, karakterden çıkma.\n\nKonuşma:\n${transcript}\n\n${b.name} olarak yanıtın:`;
 const key="u:"+b.uid;if(b.ai)S.stream={key,text:""};
 const r=await sample(prompt,{cache:false,modelTier:b.ai?"default":"quick",onText:b.ai?({text})=>{S.botTyping=null;S.stream={key,text};if(S.route.name==="chat"&&S.route.params.key===key)renderMsgs()}:undefined});
 return(r&&r.text||"").trim()}
async function aiCaption(btn,cv){const sample=S.caps.sample;if(!sample)return;btn.disabled=true;const old=btn.innerHTML;btn.textContent="Rota yazıyor…";
 try{const opts={cache:false,modelTier:"quick"};let lim=null;try{lim=await sample.limits()}catch{}
  if(lim&&lim.images&&cv){const blob=await new Promise(r=>toCanvas(cv,512,Math.round(512*cv.height/cv.width)).toBlob(r,"image/jpeg",.8));if(blob)opts.images=[blob]}
  const r=await sample(`Bir sosyal medya fotoğrafı için Türkçe, doğal, 1-2 cümlelik açıklama ve sonuna 2-3 alakalı #etiket yaz. ${opts.images?"Fotoğrafa bak, içeriğine uygun yaz.":"Fotoğrafı göremiyorsun; genel ama sıcak bir açıklama yaz."} ${S.cmp.loc?"Konum: "+S.cmp.loc+".":""} Emoji kullanma. Sadece açıklamayı yaz.`,opts);
  const cap=$("#cCap");if(cap&&r&&r.text){cap.value=r.text.trim().replace(/^"|"$/g,"");S.cmp.caption=cap.value}}
 catch(e){toast(e&&e.code==="rate_limited"?"Rota biraz yoruldu, birazdan tekrar dene.":"Açıklama yazılamadı.")}finally{btn.disabled=false;btn.innerHTML=old}}
async function runTest(){if(!guard())return;const add=t=>{const msgs=[...(S.botchats.rota?.msgs||[]),{from:"bot:rota",text:t,at:now()}];S.botchats={...S.botchats,rota:{msgs,readAt:now()}};DB.set(`data/users/${S.uid}/bot-rota`,{msgs:msgs.slice(-80),readAt:now()}).catch(()=>{});renderMsgs()};
 const mine=Object.values(S.posts).filter(p=>p.uid===S.uid).sort((a,b)=>b.at-a.at)[0];const t=now();
 if(mine)await setMeta(mine.id,{likes:{"bot:rota":t},comments:{[rid()]:{uid:"bot:rota",text:"Çok güzel olmuş! Bu bir test yorumu.",at:t+1}}});
 await write(()=>DB.update("profiles/"+S.uid,{botFollowers:{"bot:rota":t+2}}));
 add(mine?`Test verisi hazır:\n- Son paylaşımını beğendim ve yorum yaptım\n- Seni takip ettim\n\nAlttaki **Bildirim** düğmesi bildirimleri gösterir. Bir de satranç oynamak istersen “Satranç oynayalım” yaz.`:`Henüz paylaşımın olmadığı için beğeni ve yorum ekleyemedim. Yine de seni takip ettim; zil simgesinde görünür.\n\n+ ile bir şey paylaşıp tekrar dene.`);
 scheduleRefresh()}


/* ============ Firebase kurulum ve hesaplar ============ */
function showSetup(msg){const cur=LS.get("kadraj_fb_cfg");authShell(`<div>${brandLine}<h2>Kadraj'ı kur</h2><p class="lead">Arkadaşlarınla gerçekten konuşabilmen için ücretsiz bir Firebase projesi bağlıyoruz. Bir kere yapılır, yaklaşık 10 dakika sürer. Arkadaşların bunu yapmaz; sen onlara davet bağlantısı gönderirsin.</p></div>
 ${msg?`<div class="banner" style="background:var(--surface);border:1.5px solid var(--heart)">${I("info")}<span>${esc(msg)}</span></div>`:""}
 <ol class="steps" style="margin:0;padding-left:20px">
 <li><a href="https://console.firebase.google.com/" target="_blank" rel="noopener" style="color:var(--accent);font-weight:700">console.firebase.google.com</a> adresini aç, Google hesabınla gir ve <b>Proje oluştur</b>'a dokun. Adı <b>kadraj</b> olsun, Google Analytics'i kapatabilirsin.</li>
 <li>Sol menüden <b>Authentication</b> (Kimlik doğrulama) → <b>Başlayın</b> → <b>E-posta/Şifre</b>'yi aç ve kaydet.</li>
 <li><b>Firestore Database</b> → <b>Veritabanı oluştur</b>. Konum olarak Avrupa'yı (eur3) seç ve <b>üretim modunda</b> başlat.</li>
 <li>Firestore'da <b>Kurallar</b> sekmesine geç. Oradaki her şeyi sil, aşağıdaki kuralları yapıştır ve <b>Yayınla</b>'ya bas.</li>
 <li>Dişli simgesi → <b>Proje ayarları</b> → aşağıda <b>Uygulamalarınız</b> → <b>&lt;/&gt;</b> (Web) simgesi. Bir ad yaz ve kaydet. Çıkan <b>firebaseConfig</b> kodunu kopyalayıp en alttaki kutuya yapıştır.</li></ol>
 <div class="field"><span class="lbl">Firestore kuralları (4. adım)</span><pre class="invite-text" id="invTxt" style="margin:0;font:.7rem/1.45 var(--f-mono);white-space:pre;overflow-x:auto;max-height:12rem">${esc(RULES)}</pre><button class="btn sec" id="cpRules" type="button">${I("copy")}Kuralları kopyala</button></div>
 <div class="field"><label for="cfgIn">firebaseConfig kodu (5. adım)</label><textarea class="in" id="cfgIn" placeholder='const firebaseConfig = { apiKey: "...", authDomain: "...", projectId: "...", appId: "..." };' style="min-height:8rem;font:.76rem/1.4 var(--f-mono)">${cur?esc(JSON.stringify(cur,null,1)):""}</textarea></div>
 <div class="err" id="cfgErr"></div><button class="btn block" id="cfgGo">Bağlan</button>
 <div class="divider">ya da</div><button class="btn line block" id="demoGo">Kurulumsuz dene (sadece bu cihaz)</button>`);
 $("#cpRules").onclick=()=>copyText(RULES,"Kurallar kopyalandı");
 $("#cfgGo").onclick=()=>{const c=parseCfg($("#cfgIn").value);if(!c)return $("#cfgErr").textContent="Kod okunamadı. Kopyaladığın metinde apiKey, projectId ve appId satırları olmalı.";LS.set("kadraj_fb_cfg",c);LS.del("kadraj_demo");location.reload()};
 $("#demoGo").onclick=()=>{LS.set("kadraj_demo",1);location.reload()}}
const authErr=e=>{const c=(e&&e.code)||"";const map={"auth/email-already-in-use":"Bu e-postayla zaten hesap var. Giriş yapmayı dene.","auth/invalid-email":"E-posta adresi geçerli görünmüyor.","auth/missing-email":"E-posta adresini yaz.","auth/weak-password":"Şifre en az 6 karakter olmalı.","auth/missing-password":"Şifreni yaz.","auth/invalid-credential":"E-posta ya da şifre yanlış.","auth/invalid-login-credentials":"E-posta ya da şifre yanlış.","auth/wrong-password":"Şifre yanlış.","auth/user-not-found":"Bu e-postayla hesap yok. Önce hesap oluştur.","auth/too-many-requests":"Çok fazla deneme yapıldı. Birkaç dakika sonra tekrar dene.","auth/network-request-failed":"İnternet bağlantısı yok gibi görünüyor.","auth/operation-not-allowed":"Firebase'de E-posta/Şifre girişi açık değil. Kurulumun 2. adımını yap.","auth/configuration-not-found":"Firebase'de Authentication açılmamış. Kurulumun 2. adımını yap.","auth/requires-recent-login":"Güvenlik için çıkış yapıp tekrar gir, sonra yeniden dene.","permission-denied":"Veritabanı kuralları izin vermiyor. Kurulumun 4. adımındaki kuralları yapıştırıp Yayınla'ya bas."};
 if(map[c])return map[c];if(/api-key/i.test(c))return"Firebase kodu hatalı görünüyor. Ayarlar > Firebase bağlantısını değiştir'den kodu yeniden yapıştır.";return"Bir sorun oldu: "+((e&&e.message)||c)};
async function setPersist(on){const{A,auth}=FB;try{await A.setPersistence(auth,on?A.browserLocalPersistence:A.browserSessionPersistence)}catch{}LS.set("kadraj_fb_remember",!!on)}
function fbWelcome(){authShell(welScreen(true),"wel");$("#wReg").onclick=fbRegister;$("#wLog").onclick=()=>fbLogin();welWire()}
function fbRegister(){let avData=null;
 authShell(`<div>${brandLine}<h2>Hesap oluştur</h2><p class="lead">E-postan sadece giriş ve şifre sıfırlama için kullanılır, başkaları göremez.</p></div>${modeChip()}
 <form id="regF" novalidate><div class="avpick"><span class="av" style="--s:64px"><img id="rAv" src="${initialsAv("Yeni","x")}" alt=""></span><button type="button" class="btn sec sm" id="rAvBtn">${I("image")}Profil fotoğrafı</button></div>
 <div class="field"><label for="rName">Ad soyad</label><input class="in" id="rName" autocomplete="name" maxlength="40" required></div>
 <div class="field"><label for="rUser">Kullanıcı adı</label><input class="in" id="rUser" autocapitalize="off" maxlength="24" placeholder="ornek.kullanici" required></div>
 <div class="field"><label for="rMail">E-posta</label><input class="in" id="rMail" type="email" autocomplete="email" autocapitalize="off" placeholder="ornek@gmail.com" required></div>
 <div class="field"><label for="rPw">Şifre</label><input class="in" id="rPw" type="password" autocomplete="new-password" minlength="6" placeholder="En az 6 karakter" required></div>
 <label class="check"><input type="checkbox" id="rRem" checked>Beni hatırla</label><div class="err" id="rErr"></div><button class="btn block" type="submit">Kayıt ol</button></form><button class="btn ghost" id="toLogin">Zaten hesabım var</button>`);
 const nameIn=$("#rName");nameIn.oninput=()=>{if(!avData)$("#rAv").src=initialsAv(nameIn.value||"Yeni","x");const ui=$("#rUser");if(!ui.dataset.touched)ui.value=slug(nameIn.value)};$("#rUser").oninput=e=>e.target.dataset.touched=1;
 $("#rAvBtn").onclick=async()=>{const r=await pickImage({title:"Profil fotoğrafı"});if(r){avData=toCanvas(r.img,240,240).toDataURL("image/jpeg",.8);$("#rAv").src=avData}};
 $("#toLogin").onclick=()=>fbLogin();
 $("#regF").onsubmit=async e=>{e.preventDefault();const err=$("#rErr");const name=$("#rName").value.trim(),un=$("#rUser").value.trim().toLowerCase(),mail=$("#rMail").value.trim(),pw=$("#rPw").value;KASA.pw=pw;
  if(!name)return err.textContent="Adını yaz.";if(!USER_RE.test(un))return err.textContent="Kullanıcı adı 3–24 karakter olmalı: küçük harf, rakam, nokta ve alt çizgi.";if(BOTS.some(b=>b.username===un))return err.textContent=`“${un}” kullanılıyor.`;if(!/^\S+@\S+\.\S+$/.test(mail))return err.textContent="Geçerli bir e-posta yaz.";if(pw.length<6)return err.textContent="Şifre en az 6 karakter olmalı.";
  const btn=$("#regF button[type=submit]");btn.disabled=true;btn.textContent="Oluşturuluyor…";S.registering=true;
  try{await setPersist($("#rRem").checked);const cred=await FB.A.createUserWithEmailAndPassword(FB.auth,mail,pw);S.uid=cred.user.uid;S.email=mail;
   if(await usernameTaken(un)){S.registering=false;return completeProfile({name,un,avData,msg:`“${un}” başka birinde. Başka bir kullanıcı adı seç.`})}
   await saveNewProfile(name,un,avData)}
  catch(ex){console.warn(ex);S.registering=false;btn.disabled=false;btn.textContent="Kayıt ol";err.textContent=authErr(ex);if(FB.auth.currentUser&&!S.authed)completeProfile({name,un,avData,msg:authErr(ex)})}}}
async function usernameTaken(un){try{const{F,db}=FB;const q=await F.getDocs(F.query(F.collection(db,"profiles"),F.where("username","==",un),F.limit(2)));return q.docs.some(d=>d.id!==S.uid)}catch{return false}}
async function saveNewProfile(name,un,avData){const prof={uid:S.uid,username:un,name,bio:"",avatar:avData||null,following:{"bot:rota":now()},botFollowers:{},private:false,createdAt:now()};await DB.set("profiles/"+S.uid,prof);S.profiles={...S.profiles,[S.uid]:prof};S.registering=false;await startSession(true)}
function completeProfile(o={}){let avData=o.avData||null;authShell(`<div>${brandLine}<h2>Profilini tamamla</h2><p class="lead">Arkadaşların seni bu adla bulacak.</p></div>${o.msg?`<div class="err">${esc(o.msg)}</div>`:""}
 <form id="cpF" novalidate><div class="avpick"><span class="av" style="--s:64px"><img id="rAv" src="${avData||initialsAv(o.name||"Yeni","x")}" alt=""></span><button type="button" class="btn sec sm" id="rAvBtn">${I("image")}Profil fotoğrafı</button></div>
 <div class="field"><label for="rName">Ad soyad</label><input class="in" id="rName" maxlength="40" value="${esc(o.name||"")}"></div><div class="field"><label for="rUser">Kullanıcı adı</label><input class="in" id="rUser" autocapitalize="off" maxlength="24" value="${esc(o.un||"")}"></div><div class="err" id="rErr"></div><button class="btn block" type="submit">Devam et</button></form><button class="btn ghost" id="cpOut">Çıkış yap</button>`);
 $("#rAvBtn").onclick=async()=>{const r=await pickImage({title:"Profil fotoğrafı"});if(r){avData=toCanvas(r.img,240,240).toDataURL("image/jpeg",.8);$("#rAv").src=avData}};
 $("#cpOut").onclick=()=>FB.A.signOut(FB.auth);
 $("#cpF").onsubmit=async e=>{e.preventDefault();const err=$("#rErr");const name=$("#rName").value.trim(),un=$("#rUser").value.trim().toLowerCase();if(!name)return err.textContent="Adını yaz.";if(!USER_RE.test(un))return err.textContent="Kullanıcı adı 3–24 karakter: küçük harf, rakam, nokta, alt çizgi.";if(BOTS.some(b=>b.username===un)||await usernameTaken(un))return err.textContent=`“${un}” kullanılıyor.`;
  try{await saveNewProfile(name,un,avData)}catch(ex){err.textContent=authErr(ex)}}}
let sharedOn=false;
async function startSession(fresh){if(!sharedOn){subscribeShared();sharedOn=true}const room=S.caps.room;if(room&&room.listen&&!S.roomListen)S.roomListen=room.listen();await enterApp(fresh)}
function endSession(){repUnsub=null;S.reports=[];S.posta=null;S.editDraft=null;if(CALL)endCall(true);teardownUser();closeAll();if(S.roomListen){S.roomListen();S.roomListen=null}unsubAll();sharedOn=false;S.authed=false;S.profiles={};S.posts={};S.meta={};S.stories={};S.meydan=null}
function fbLogout(){dialog("Çıkış yapılsın mı?",`@${esc(me().username)} hesabından çıkacaksın.`,[{label:"Çıkış yap",cls:"danger",fn:async()=>{try{await S.caps.room?.leave()}catch{}endSession();await FB.A.signOut(FB.auth)}},{label:"Vazgeç"}])}
function fbChangePw(){const l=sheet("pw","Şifreyi değiştir",`<form class="form" id="cpF2"><div class="field"><label for="cp0">Mevcut şifre</label><input class="in" id="cp0" type="password" autocomplete="current-password"></div><div class="field"><label for="cp1">Yeni şifre</label><input class="in" id="cp1" type="password" autocomplete="new-password"></div><div class="err" id="cpE"></div><button class="btn block">Güncelle</button></form>`);
 $("#cpF2",l).onsubmit=async e=>{e.preventDefault();const er=$("#cpE",l);const pw=$("#cp1",l).value;if(pw.length<6)return er.textContent="Yeni şifre en az 6 karakter olmalı.";try{const{A,auth}=FB;const u=auth.currentUser;await A.reauthenticateWithCredential(u,A.EmailAuthProvider.credential(u.email,$("#cp0",l).value));await A.updatePassword(u,pw);closeLayer("pw");toast("Şifren değişti");kasaSeal(S.uid,pw,{note:{t:"Şifren değişti",b:"Kadraj şifren az önce Ayarlar'dan değiştirildi. Bunu sen yapmadıysan hemen Kadraj Anahtarınla şifreni yenile.",ic:"key"}})}catch(ex){er.textContent=authErr(ex)}}}
function fbDelete(){const l=sheet("del","Hesabı sil",`<form class="form" id="dlF"><p class="muted" style="margin:0">Profilin, paylaşımların ve hikâyelerin kalıcı olarak silinir. Onaylamak için şifreni yaz.</p><div class="field"><label for="dl0">Şifre</label><input class="in" id="dl0" type="password" autocomplete="current-password"></div><div class="err" id="dlE"></div><button class="btn block" style="background:var(--heart);color:#fff">Hesabı kalıcı olarak sil</button></form>`);
 $("#dlF",l).onsubmit=async e=>{e.preventDefault();const er=$("#dlE",l);try{const{A,auth}=FB;const u=auth.currentUser;await A.reauthenticateWithCredential(u,A.EmailAuthProvider.credential(u.email,$("#dl0",l).value));const uid=S.uid;
  for(const p of Object.values(S.posts).filter(p=>p.uid===uid)){await DB.del("posts/"+p.id).catch(()=>{});await DB.del("meta/"+p.id).catch(()=>{});delChunks(p.video)}for(const st of Object.values(S.stories).filter(x=>x.uid===uid))await DB.del("stories/"+st.id).catch(()=>{});
  const un0=(S.profiles[uid]||{}).username;if(un0)await DB.del("unames/"+un0).catch(()=>{});await DB.del("presence/"+uid).catch(()=>{});await DB.del(`data/users/${uid}/saved`).catch(()=>{});await DB.del("kurtar/"+uid).catch(()=>{});await DB.del(`data/users/${uid}/posta`).catch(()=>{});await DB.del("profiles/"+uid).catch(()=>{});
  endSession();await A.deleteUser(u);toast("Hesabın silindi")}catch(ex){er.textContent=authErr(ex)}}}

/* ============ Açılış ============ */
async function enterApp(fresh){S.authed=true;S.guest=false;S.bootAt=now();S.admin=!!LS.get("kadraj_admin_"+S.uid);if(S.admin)setTimeout(admWatchReports,500);subscribeUser();
 const room=S.caps.room;if(room&&S.uid)room.presence({uid:S.uid,typing:null}).catch(()=>{});
 S.stack=[];S.route={name:"feed",params:{}};navInit();render(true);
 if(fresh)setTimeout(()=>toast(`Hoş geldin @${me().username}! Arkadaşlarını Sohbet > Davet et'ten çağırabilirsin.`,"bot:rota"),400);
 setTimeout(()=>{if(settings.notify&&notifPerm()==='default')askNotif(true)},2500);
 setTimeout(checkChildInvite,1500);runHooks("enter",fresh)}
function withTimeout(p,ms){return Promise.race([p,new Promise(r=>setTimeout(()=>r(null),ms))])}
function wireRoom(room){room.onPeers(({peers})=>{const on=new Set(),ty={};for(const p of peers){const pr=p.presence||{};if(!pr.uid||p.isMe)continue;on.add(pr.uid);if(pr.typing)ty[pr.uid]=pr.typing}S.online=on;S.typing=ty;scheduleRefresh()});
 room.on("nudge",msg=>{const d=msg.data||{};if(d.to===S.uid&&S.authed&&d.from){vib([80,60,80]);toast(`@${P(d.from).username} seni dürttü`,d.from,"u:"+d.from);sysNote("Dürtme",`@${P(d.from).username} seni dürttü`,"nudge",{key:"u:"+d.from,icon:P(d.from).avatar})}})}
async function boot(){verCleanUrl();runHooks("boot");
 let hc=readHashCfg();if(hc&&hc.projectId!==EMBED_CFG.projectId&&(LS.get("kadraj_fb_cfg")||{}).projectId!==hc.projectId){let ok=false;try{ok=confirm(`Bu bağlantı Kadraj'ı başka bir sunucuya (${hc.projectId||"bilinmiyor"}) bağlamak istiyor. Hesabın ve mesajların o sunucuda saklanır. Yalnızca güvendiğin birinden geldiyse devam et.`)}catch{}if(!ok){hc=null;try{history.replaceState(null,"",location.pathname+location.search)}catch{}}}if(hc){LS.set("kadraj_fb_cfg",hc);LS.del("kadraj_demo");try{history.replaceState(null,"",location.pathname+location.search)}catch{}}
 const cfg=LS.get("kadraj_fb_cfg")||EMBED_CFG;
 if(!cfg){if(LS.get("kadraj_demo"))return bootLocal();return showSetup()}
 const m=$("#splashMsg");if(m)m.textContent="Sunucuya bağlanılıyor…";
 try{await withTimeout(loadFirebase(cfg),20000);if(!FB)throw new Error("zaman aşımı")}catch(e){console.warn(e);if(await acTry("fb"))return;return showSetup("Firebase'e bağlanılamadı. İnternetini kontrol et ya da kodu yeniden yapıştır. ("+((e&&e.message)||e)+")")}
 S.mode="cloud";DB=FirebaseDB();const room=FsRoom();S.caps.room=room;wireRoom(room);
 if(AUTH_ACT)handleAuthAction(AUTH_ACT);
 FB.A.onAuthStateChanged(FB.auth,async u=>{if(S.registering||S.inReset)return;
  if(!u){if(S.authed)endSession();S.uid=null;return fbWelcome()}
  if(S.authed&&S.uid===u.uid)return;
  S.uid=u.uid;S.email=u.email;let prof=null;
  try{prof=await DB.get("profiles/"+u.uid)}catch(e){console.warn(e);if(e&&e.code==="permission-denied")return showSetup("Veritabanı kuralları izin vermiyor. 4. adımdaki kuralları Firestore > Kurallar'a yapıştırıp Yayınla'ya bas, sonra Bağlan'a dokun.");if(await acTry("db"))return;return showSetup("Kadraj sunucusuna ulaşılamadı. İnternetini kontrol edip yeniden dene. ("+((e&&(e.code||e.message))||e)+")")}
  if(!prof){let ban=null;try{ban=await DB.get("admin/ban")}catch{}if(ban&&ban.list&&ban.list[u.uid]){toast("Hesabın yönetici tarafından kapatıldı.");try{await FB.A.signOut(FB.auth)}catch{}return}return completeProfile({})}S.profiles={...S.profiles,[u.uid]:prof};startSession(false)})}
async function bootLocal(){DB=LocalDB;S.mode="local";subscribeShared();
 const sess=LS.get("kadraj_session")||SS.get("kadraj_sess");if(sess&&await LocalDB.get("profiles/"+sess)){S.uid=sess;S.profiles={...S.profiles,[sess]:await LocalDB.get("profiles/"+sess)};return enterApp()}
 showWelcome()}
/* ===== 4.0 eklentileri: her ajan yalnızca kendi işaretleri arasına yazar ===== */
