/* ---- A · ortak ---- */
Object.assign(IP,{
 k4pal:'<path d="M12 3a9 9 0 0 0 0 18c1.1 0 1.7-.8 1.7-1.7 0-.5-.2-.9-.5-1.2-.3-.3-.5-.7-.5-1.2 0-.9.7-1.6 1.6-1.6H16a5 5 0 0 0 5-5c0-4.1-4-7.3-9-7.3z"/><circle cx="7.6" cy="11.4" r="1.25" fill="currentColor" stroke="none"/><circle cx="10.2" cy="7.4" r="1.25" fill="currentColor" stroke="none"/><circle cx="14.8" cy="7.6" r="1.25" fill="currentColor" stroke="none"/>',
 k4act:'<path d="M2.5 12.5h4l2.6-6.5 5 12.5 2.7-6h4.7"/>',
 k4cal:'<rect x="3.5" y="5" width="17" height="15.5" rx="3"/><path d="M3.5 10h17M8 3v4M16 3v4"/><path d="m12 12.2 1 2 2.2.3-1.6 1.5.4 2.2-2-1-2 1 .4-2.2-1.6-1.5 2.2-.3z" fill="currentColor" stroke="none"/>'});
const k4rm=()=>{try{return document.documentElement.classList.contains("reduce-motion")||matchMedia("(prefers-reduced-motion: reduce)").matches}catch{return false}};

/* ---- A · Açılış animasyonu ---- */
const INTRO={t0:typeof window.__k0==="number"?window.__k0:0,ready:false,gone:false,timer:0,waiters:[]};
function introEl(){return document.getElementById("intro")}
/* İlk gerçek ekran çizildiğinde çağrılır (authShell, enterApp kancası, enterGuest). En az ~1,1 sn gösterir, sonra yumuşakça kaybolur. */
function introDone(){const el=introEl();if(!el||INTRO.gone){introLive();return}if(INTRO.ready)return;INTRO.ready=true;
 const wait=Math.max(0,1100-(performance.now()-INTRO.t0));clearTimeout(INTRO.timer);INTRO.timer=setTimeout(introExit,wait)}
function introLive(){document.documentElement.classList.add("k-live");const ws=INTRO.waiters.splice(0);for(const f of ws)try{f()}catch{}}
function introGone(){return new Promise(r=>{if(!introEl())return r();INTRO.waiters.push(r)})}
function introExit(){const el=introEl();if(!el){introLive();return}if(INTRO.gone)return;INTRO.gone=true;clearTimeout(INTRO.timer);
 const rm=k4rm();el.classList.add("out");el.style.pointerEvents="none";el.removeAttribute("aria-busy");
 document.documentElement.classList.add("k-live");
 /* oturum açıksa sayfa giriş animasyonunu perde kalkarken yeniden oynat */
 try{const m=$("#main");if(S.authed&&m&&!rm&&!["reels","chat","chessgame"].includes(S.route.name)&&m.children.length&&!m.querySelector(".empty .spin")){m.classList.remove("enter");void m.offsetWidth;m.classList.add("enter");clearTimeout(m._et);m._et=setTimeout(()=>m.classList.remove("enter"),800)}}catch{}
 let fin=false;const done=()=>{if(fin)return;fin=true;el.remove();introLive()};
 try{if(el.animate){const a=el.animate([{opacity:1},{opacity:0}],{duration:rm?200:460,easing:rm?"linear":"cubic-bezier(.4,0,.2,1)",fill:"forwards"});a.onfinish=done;
   const c=el.querySelector(".in-c");if(!rm&&c&&c.animate)c.animate([{transform:"scale(1)",filter:"blur(0)"},{transform:"scale(1.1)",filter:"blur(2px)"}],{duration:460,easing:"cubic-bezier(.4,0,.2,1)",fill:"forwards"})}}catch{}
 setTimeout(done,rm?260:620)}
(function introWire(){const el=introEl();if(!el)return;
 el.addEventListener("click",e=>{if(e.target.closest("#introRetry"))return;if(INTRO.ready)introExit()});
 const rb=document.getElementById("introRetry");if(rb){rb.innerHTML=I("rotate")+"Yeniden dene";rb.onclick=()=>location.reload()}
 setTimeout(()=>{const x=introEl();if(x&&!INTRO.gone)x.classList.add("slow")},Math.max(0,1500-(performance.now()-INTRO.t0)));
 /* takılı kalmasın: 12 sn sonra hâlâ açıksa ekran varsa kapat, yoksa yeniden deneme düğmesi göster */
 setTimeout(()=>{if(INTRO.ready||!introEl())return;const m=$("#main");if(m&&m.children.length)return introDone();
  const msg=document.getElementById("splashMsg");if(msg)msg.textContent="Bağlantı beklenenden uzun sürüyor.";if(rb)rb.hidden=false},12000)})();
