function welScreen(withLogin){
 return`${welArt()}<div class="wel-txt">${brandLine}<h2>Arkadaşlarınla anı paylaş, sohbet et.</h2>
 <div class="wel-feat" role="list" aria-label="Kadraj'da neler var">${WEL_FEATS.map((f,i)=>`<div class="wf${i?"":" on"}" role="listitem"><span class="ic">${I(f[0])}</span><span>${esc(f[1])}</span></div>`).join("")}</div>
 <div class="wel-dots" aria-hidden="true">${WEL_FEATS.map((f,i)=>`<i${i?"":' class="on"'}></i>`).join("")}</div></div>
 <div class="wel-cta">${modeChip()}<button class="btn block" id="wReg">Hesap oluştur</button>${withLogin?`<button class="btn line block" id="wLog">Giriş yap</button>`:""}</div>`}
function welWire(){const root=$(".auth.wel");if(!root)return;const art=$(".wel-art",root);
 const fs=$$(".wf",root),ds=$$(".wel-dots i",root);let k=0;
 const iv=setInterval(()=>{if(!root.isConnected)return clearInterval(iv);if(document.hidden||!document.documentElement.classList.contains("k-live"))return;
  const prev=fs[k];prev.classList.remove("on");prev.classList.add("off");setTimeout(()=>prev.classList.remove("off"),520);if(ds[k])ds[k].classList.remove("on");
  k=(k+1)%fs.length;fs[k].classList.add("on");if(ds[k])ds[k].classList.add("on")},2600);
 if(!art||k4rm())return;
 let raf=0,mx=0,my=0;const apply=()=>{raf=0;art.style.setProperty("--mx",mx.toFixed(3));art.style.setProperty("--my",my.toFixed(3))};
 const set=(x,y)=>{mx=Math.max(-1,Math.min(1,x));my=Math.max(-1,Math.min(1,y));if(!raf)raf=requestAnimationFrame(apply)};
 root.addEventListener("pointermove",e=>{const r=art.getBoundingClientRect();if(!r.width)return;set((e.clientX-r.left)/r.width*2-1,(e.clientY-r.top)/r.height*2-1)});
 root.addEventListener("pointerleave",()=>set(0,0));
 const ori=e=>{if(!root.isConnected)return removeEventListener("deviceorientation",ori);if(e.gamma==null)return;set(e.gamma/22,((e.beta||0)-45)/22)};
 addEventListener("deviceorientation",ori)}

/* ---- A · Sürüm denetimi ---- */
const VER={known:null,unsub:null,writes:0,chk:null,chkP:null,blocked:false,skip:false,lastEval:0};
const verStr=v=>{v=verNorm(v);return Math.floor(v/10000)+"."+(Math.floor(v/100)%100)+"."+(v%100)};
function verCleanUrl(){try{const q=new URLSearchParams(location.search);if(!q.has("v")&&!q.has("surum"))return;q.delete("v");q.delete("surum");const s=q.toString();history.replaceState(history.state,"",location.pathname+(s?"?"+s:"")+location.hash)}catch{}}
/* Yayındaki index.html'in yalnızca başını okuyup <meta name="kadraj-version"> değerini döndürür; hata olursa null. */
async function fetchRemoteVersion(){let rd=null,to=0;
 try{const ctl=typeof AbortController==="function"?new AbortController():null;to=setTimeout(()=>{try{ctl&&ctl.abort()}catch{}},9000);
  const res=await fetch(location.pathname+"?surum="+now(),{cache:"no-store",headers:{Range:"bytes=0-16383"},signal:ctl?ctl.signal:undefined});
  if(!res||!(res.ok||res.status===206))return null;
  const re=/name=["']kadraj-version["']\s+content=["'](\d+)["']/;let txt="";
  if(res.body&&res.body.getReader&&typeof TextDecoder==="function"){rd=res.body.getReader();const dec=new TextDecoder();let n=0;
   while(n<65536){const{done,value}=await rd.read();if(done)break;n+=value.length;txt+=dec.decode(value,{stream:true});const m=txt.match(re);if(m)return verNorm(+m[1]);if(/<\/head>/i.test(txt))break}}
  else txt=(await res.text()).slice(0,65536);
  const m=txt.match(re);return m?verNorm(+m[1]):null}
 catch(e){return null}
 finally{clearTimeout(to);if(rd)try{rd.cancel().catch(()=>{})}catch{}setTimeout(verTidyCache,4000)}}
/* Sürüm sorguları ve ?v= ile açılan sayfalar önbellekte ayrı kayıt bırakmasın */
async function verTidyCache(){try{if(!window.caches||!caches.keys)return;for(const k of await caches.keys()){const c=await caches.open(k);for(const req of await c.keys()){const u=new URL(req.url);const q=u.searchParams;if(!q.has("v")&&!q.has("surum"))continue;if(/\/app\.(js|css)$/.test(u.pathname)&&!q.has("surum"))continue;
  if(q.has("v")&&!q.has("surum")){const res=await c.match(req);q.delete("v");const s=q.toString();if(res&&res.ok)await c.put(new Request(u.origin+u.pathname+(s?"?"+s:"")),res).catch(()=>{})}await c.delete(req)}}}catch{}}
async function hardReload(btn){if(VER.reloading)return;VER.reloading=true;
 if(btn&&btn.tagName){btn.disabled=true;btn.innerHTML=`${I("rotate")}Güncelleniyor…`}
 const work=(async()=>{try{if(window.caches&&caches.keys){const ks=await caches.keys();await Promise.all(ks.map(k=>caches.delete(k).catch(()=>{})))}}catch{}
  try{const sw=navigator.serviceWorker;if(sw&&sw.getRegistrations){const rs=await sw.getRegistrations();await Promise.all(rs.map(r=>r.update().catch(()=>{})))}}catch{}})();
 await Promise.race([work,new Promise(r=>setTimeout(r,4000))]);
 VER.nav(location.pathname+"?v="+now())}
VER.nav=u=>location.replace(u);
function verWatch(){if(VER.unsub){try{VER.unsub()}catch{}VER.unsub=null}
 if(S.mode!=="cloud"||!DB||!S.authed||S.guest||VER.blocked)return;
 try{VER.unsub=DB.watchDoc("meta/_surum",verOnDoc)}catch(e){console.warn("sürüm",e)}}
function verOnDoc(d){const raw=d&&d.v;const v=typeof raw==="number"&&isFinite(raw)?verNorm(raw):null;
 if(v!=null&&verGap(v)>20){if(S.mode==="cloud"&&S.authed&&!S.guest&&S.uid&&VER.writes<3){VER.writes++;write(()=>DB.set("meta/_surum",{v:APP_V,ver:APP_VER,at:now(),by:S.uid}),{quiet:true})}return}
 if(v==null||v<APP_V){VER.known=APP_V;verBar(null);
  if(S.mode==="cloud"&&S.authed&&!S.guest&&S.uid&&VER.writes<3){VER.writes++;write(()=>DB.set("meta/_surum",{v:APP_V,ver:APP_VER,at:now(),by:S.uid}),{quiet:true})}return}
 VER.known=v;verEvaluate()}
async function verVerify(v){const c=VER.chk;if(c&&c.v===v&&now()-c.at<10*60e3)return c.r;if(VER.chkP)return VER.chkP;
 VER.chkP=fetchRemoteVersion().then(r=>{VER.chk={v,at:now(),r};VER.chkP=null;return r});return VER.chkP}
/* Son bilinen sürüm değerine göre çubuk ya da engel ekranı */
async function verEvaluate(v=VER.known){VER.lastEval=now();if(VER.blocked)return;
 if(v==null)return;if(v<=APP_V)return verBar(null);
 if(verGap(v)>=2){const r=await verVerify(v);if(VER.known!==v&&VER.known!=null&&VER.known<v)return;
  if(r!=null&&verGap(r)>=2)return showVersionBlock(r);if(r==null)return verBar(v);return verBar(r>APP_V?r:null)}
 verBar(v)}
function verBar(v,force){let el=$("#verBar");
 if(v==null||v<=APP_V||VER.blocked){if(el)el.remove();return}
 if(!force&&+(SS.get("kadraj_verbar_off")||0)>=v){if(el)el.remove();return}
 if(el&&+el.dataset.v===v)return;
 if(!el){el=document.createElement("div");el.id="verBar";el.setAttribute("role","status");document.body.appendChild(el)}
 el.dataset.v=v;el.innerHTML=`<span class="vb-ic">${I("spark")}</span><span class="vb-t">Yeni sürüm hazır · <b>Kadraj ${verStr(v)}</b></span><button type="button" class="vb-go">${I("rotate")}Yenile</button><button type="button" class="vb-x" aria-label="Kapat">${I("close")}</button>`;
 const go=el.querySelector(".vb-go");go.onclick=()=>hardReload(go);
 el.querySelector(".vb-x").onclick=()=>{SS.set("kadraj_verbar_off",String(v));el.classList.add("bye");setTimeout(()=>el.remove(),260)}}
const VB_ART=`<svg viewBox="0 0 176 150" aria-hidden="true"><circle class="a1" cx="88" cy="78" r="64"/>
 <path class="a8 tw" d="M26 34l2.4 6 6 2.4-6 2.4-2.4 6-2.4-6-6-2.4 6-2.4z"/><path class="a5 tw" style="animation-delay:.7s" d="M150 46l1.8 4.4 4.4 1.8-4.4 1.8-1.8 4.4-1.8-4.4-4.4-1.8 4.4-1.8z"/><circle class="a9 tw" style="animation-delay:1.2s" cx="152" cy="130" r="3.5"/><circle class="a5 tw" style="animation-delay:.3s" cx="30" cy="110" r="3"/>
 <rect class="a2" x="58" y="18" width="60" height="108" rx="15"/><rect class="a3" x="77" y="25" width="22" height="4.5" rx="2.25"/>
 <svg x="68" y="50" width="40" height="40" viewBox="0 0 24 24"><path class="a4" d="M2.5 8V5a2.5 2.5 0 0 1 2.5-2.5h3M16 2.5h3A2.5 2.5 0 0 1 21.5 5v3M21.5 16v3a2.5 2.5 0 0 1-2.5 2.5h-3M8 21.5H5A2.5 2.5 0 0 1 2.5 19v-3"/><circle class="a5" cx="12" cy="12" r="3.4"/></svg>
 <rect class="a3" x="72" y="101" width="32" height="5" rx="2.5"/><rect class="a3" x="78" y="111" width="20" height="5" rx="2.5"/>
 <circle class="a6" cx="118" cy="110" r="22"/><svg x="104" y="96" width="28" height="28" viewBox="0 0 24 24"><g class="bob"><path class="a7" d="M12 18.5V6M6.5 11.5 12 6l5.5 5.5"/></g></svg></svg>`;
function showVersionBlock(r){if(VER.skip)return;VER.blocked=true;verBar(null);if(VER.unsub){try{VER.unsub()}catch{}VER.unsub=null}
 const n=Math.max(2,verGap(r));const behind=n===2?"iki":n===3?"üç":"birkaç";
 let el=$("#verBlock");if(!el){el=document.createElement("div");el.id="verBlock";el.setAttribute("role","alertdialog");el.setAttribute("aria-modal","true");el.setAttribute("aria-labelledby","vbT");document.body.appendChild(el)}
 el.innerHTML=`<div class="vb-card"><div class="vb-art">${VB_ART}</div><h2 id="vbT">Bu sürüm artık kullanılmıyor</h2><p>Kadraj ${verStr(r)} yayında. Kullandığın ${esc(APP_VER)} sürümü ${behind} sürüm geride kaldığı için kapatıldı. Devam etmek için güncelle.</p>
 <div class="vb-vers" aria-hidden="true"><span class="old">${esc(APP_VER)}</span>${I("next")}<span class="new">${verStr(r)}</span></div>
 <button type="button" class="btn block" id="vbGo">${I("rotate")}Şimdi güncelle</button>${S.admin?`<button type="button" class="btn ghost block" id="vbSkip">Yönetici olarak devam et</button>`:""}</div>`;
 for(const s of["#shell","#overlay"]){const x=$(s);if(x)x.inert=true}
 try{document.activeElement&&document.activeElement.blur&&document.activeElement.blur()}catch{}
 const go=$("#vbGo",el);go.onclick=()=>hardReload(go);
 const sk=$("#vbSkip",el);if(sk)sk.onclick=()=>{VER.skip=true;VER.blocked=false;for(const s of["#shell","#overlay"]){const x=$(s);if(x)x.inert=false}el.remove();toast(`Yönetici olarak ${APP_VER} sürümünde devam ediyorsun`);verBar(r,true)};
 vib(30)}
/* Elle (Ayarlar'dan) ya da arka planda sürüm denetimi */
async function checkVersion(manual){
 if(!manual)return verEvaluate();
 const r=await fetchRemoteVersion();
 if(r==null){toast("Sürüm denetlenemedi. İnternet bağlantını kontrol et.");return null}
 if(verGap(r)>=2){VER.skip=false;showVersionBlock(r);return r}
 if(r>APP_V){VER.known=Math.max(VER.known||0,r);SS.del("kadraj_verbar_off");verBar(r,true);toast(`Kadraj ${verStr(r)} hazır. Yenile'ye dokun.`);return r}
 toast(`Kadraj güncel (${APP_VER})`);return r}
HOOKS.enter.push(()=>verWatch());
document.addEventListener("visibilitychange",()=>{if(document.visibilityState==="visible"&&S.authed&&now()-VER.lastEval>10*60e3)checkVersion(false)});
setTimeout(verTidyCache,9000);

