function showWhatsNew(force){if($('#overlay [data-layer="whatsnew"]'))return;if(!force&&verLvl(LS.get("kadraj_seen_ver",0)||0)>=verLvl(APP_V))return;
 const items=WN_ITEMS.filter(x=>verLvl(x.v)===verLvl(APP_V)).map((x,i)=>`<button type="button" class="wn-item" data-act="wnGo" data-r="${x.go}" style="--i:${i};--g:${x.g}"><span class="wn-ic">${I(x.ic)}</span><span class="wn-t"><b>${esc(x.t)}</b><span>${esc(x.d)}</span></span>${I("next")}</button>`).join("");
 openLayer("whatsnew",`<div class="full wn" role="dialog" aria-modal="true" aria-label="Kadraj ${esc(APP_VER)} ile gelenler"><button class="ib plain wn-x" data-act="close" aria-label="Kapat">${I("close")}</button>
 <div class="body"><div class="wn-hero"><i class="wn-blob b1"></i><i class="wn-blob b2"></i><i class="wn-blob b3"></i>${WN_MARK}<div class="wn-badge">Yeni sürüm</div><h2 class="wn-title">Kadraj ${esc(APP_VER)}</h2>${APP_NAME?`<div class="wn-name">${esc(APP_NAME)} güncellemesi</div>`:""}<p class="wn-sub">Bu sürümle gelenler:</p></div>
 <div class="wn-list">${items}</div></div>
 <div class="wn-foot"><button type="button" class="btn block" data-act="wnOk">Hadi başlayalım${I("next")}</button></div></div>`,{noScrim:true,onClose:()=>LS.set("kadraj_seen_ver",APP_V)})}
ACT.wnOk=()=>{vib(12);closeLayer("whatsnew")};
ACT.wnGo=(t,d)=>{closeLayer("whatsnew");const r=d.r;if(!S.authed)return;if(r==="profile"&&S.guest)return go("invite");if(["feed","explore","reels","chats","profile","settings"].includes(r))return tab(r);go(r)};
/* Otomatik test tarayıcılarında (navigator.webdriver) kendiliğinden açılmaz; testte window.KADRAJ_TEST_WN=true ile açılır. */
function wnAuto(fresh){if(verLvl(LS.get("kadraj_seen_ver",0)||0)>=verLvl(APP_V))return;if(fresh){LS.set("kadraj_seen_ver",APP_V);return}if(navigator.webdriver&&!window.KADRAJ_TEST_WN)return;
 const uid=S.uid,t0=now();
 introGone().then(()=>{const tryShow=n=>{if(!S.authed||S.guest||S.uid!==uid||VER.blocked)return;if(verLvl(LS.get("kadraj_seen_ver",0)||0)>=verLvl(APP_V))return;
  if($("#overlay .layer")){if(n<8)setTimeout(()=>tryShow(n+1),1500);return}showWhatsNew(false)};
  setTimeout(()=>tryShow(0),Math.max(450,1200-(now()-t0)))})}
HOOKS.enter.push(fresh=>wnAuto(fresh));
