/* ---------- vurgu renkleri ---------- */
/* l/d: [accent, accent-ink, accent-soft] (açık / koyu). Yazı ile zemin kontrastı her ikisinde en az 4.5. h/m: zemin tonları için renk açısı ve doygunluk çarpanı. */
function accentPal(){return accentPal.t||(accentPal.t={
 kadraj:{n:"Kadraj",h:160,m:1,keep:1,l:["#0C7A63","#FFFFFF","#D9F0E8"],d:["#3FD3AB","#04140F","#12302A"]},
 okyanus:{n:"Okyanus",h:214,m:1,l:["#1A5FD0","#FFFFFF","#DDE8FA"],d:["#6CB4FF","#03121F","#10243D"]},
 gunbatimi:{n:"Gün batımı",h:22,m:.62,l:["#C2410C","#FFFFFF","#FCE6D8"],d:["#FF9A5A","#1F0D02","#3A2214"]},
 mor:{n:"Mor",h:262,m:.85,l:["#6D28D9","#FFFFFF","#ECE3FD"],d:["#B794FF","#170B2E","#261C42"]},
 pembe:{n:"Pembe",h:330,m:.66,l:["#BE185D","#FFFFFF","#FCE0EC"],d:["#FF7EB6","#2A0716","#3D1629"]},
 kiraz:{n:"Kiraz",h:352,m:.58,l:["#C81E3A","#FFFFFF","#FBE0E4"],d:["#FF6B7D","#2B0409","#3D1519"]},
 grafit:{n:"Grafit",h:220,m:.3,l:["#1F2937","#FFFFFF","#E6E8EC"],d:["#E5E7EB","#111827","#262A31"]}})}
function kbHex(h,s,l){s/=100;l/=100;const k=n=>(n+h/30)%12,a=s*Math.min(l,1-l),f=n=>l-a*Math.max(-1,Math.min(k(n)-3,9-k(n),1));return"#"+[f(0),f(8),f(4)].map(x=>Math.round(x*255).toString(16).padStart(2,"0")).join("")}
/* geçerli vurgu: kullanıcının seçimi; "auto" ise yöneticinin ortak teması (ilk anlık görüntü gelene kadar son bilinen değer) */
function effAccent(){const pal=accentPal();const a=settings.accent||"auto";if(a!=="auto")return pal[a]?a:"kadraj";const c=communityAccent();return c&&pal[c]?c:"kadraj"}
function communityAccent(){if(S.adm){const t=S.adm.tema;return(t&&t.accent)||""}return settings.commAccent||""}
function accentVars(id,dark){const p=accentPal()[id]||accentPal().kadraj;const c=dark?p.d:p.l;const v={"--accent":c[0],"--accent-ink":c[1],"--accent-soft":c[2]};
 if(!p.keep){const h=p.h,m=p.m;if(dark)Object.assign(v,{"--bg":kbHex(h,26*m,5.4),"--surface":kbHex(h,22*m,8.8),"--surface-2":kbHex(h,19*m,12.8),"--line":kbHex(h,16*m,18),"--fg":kbHex(h,22*m,92.5),"--muted":kbHex(h,11*m,61)});
  else Object.assign(v,{"--bg":kbHex(h,18*m,95.6),"--surface-2":kbHex(h,22*m,92.2),"--line":kbHex(h,18*m,86.6),"--fg":kbHex(h,34*m,10),"--muted":kbHex(h,10*m,38)})}
 return v}
function applyAccent(){const r=document.documentElement;const dark=isDark();const id=effAccent();const v=accentVars(id,dark);
 for(const k of["--accent","--accent-ink","--accent-soft","--bg","--surface","--surface-2","--line","--fg","--muted"]){if(v[k])r.style.setProperty(k,v[k]);else r.style.removeProperty(k)}
 r.setAttribute("data-accent",id);r.setAttribute("data-mode",dark?"dark":"light");r.classList.toggle("reduce-motion",settings.reduceMotion===true);
 const m=document.querySelector('meta[name="theme-color"]');if(m)m.setAttribute("content",v["--bg"]||(dark?"#0A110F":"#F2F5F2"))}
/* sistem teması değişince (Sistem seçiliyse) hemen uygula */
try{const mq=matchMedia("(prefers-color-scheme: dark)");const f=()=>{if((settings.theme||"system")==="system")themeSwitch(()=>{applyTheme();if(S.authed){renderTop();if(S.route.name==="settings")render(false)}},{fade:true})};if(mq.addEventListener)mq.addEventListener("change",f);else if(mq.addListener)mq.addListener(f)}catch{}

/* ---------- yumuşak geçiş ---------- */
let kbPtr=null;
document.addEventListener("pointerdown",e=>{kbPtr={x:e.clientX,y:e.clientY,t:Date.now()}},true);
function kbReduce(){if(settings.reduceMotion===true)return true;try{return matchMedia("(prefers-reduced-motion: reduce)").matches}catch{return false}}
/* fn: arayüzü yeni temaya geçiren işlev. opts.fade: çapraz geçiş (uzaktan gelen değişiklikler), yoksa son dokunulan noktadan büyüyen daire. */
function themeSwitch(fn,o={}){const run=()=>{try{fn()}catch(e){console.warn("tema",e)}};const r=document.documentElement;
 if(kbReduce()||document.visibilityState==="hidden"){run();return}
 const tok=themeSwitch.n=(themeSwitch.n||0)+1;const clean=()=>{if(themeSwitch.n===tok)r.classList.remove("vt-circle","vt-fade","th-anim","theme-fade")};
 if(typeof document.startViewTransition==="function"){const circle=!o.fade;
  let p=null;if(circle)p=o.x!=null?{x:o.x,y:o.y}:(kbPtr&&Date.now()-kbPtr.t<2500?kbPtr:{x:innerWidth-40,y:40});
  r.classList.remove("vt-circle","vt-fade");r.classList.add(circle?"vt-circle":"vt-fade","th-anim");
  let vt;try{vt=document.startViewTransition(run)}catch(e){clean();run();return}
  vt.ready.then(()=>{if(!circle)return;const R=Math.hypot(Math.max(p.x,innerWidth-p.x),Math.max(p.y,innerHeight-p.y))+8;
   try{r.animate({clipPath:[`circle(0px at ${p.x}px ${p.y}px)`,`circle(${R}px at ${p.x}px ${p.y}px)`]},{duration:560,easing:"cubic-bezier(.4,0,.2,1)",pseudoElement:"::view-transition-new(root)"})}catch{}}).catch(()=>{});
  vt.finished.then(()=>setTimeout(clean,60),()=>setTimeout(clean,60));if(vt.updateCallbackDone)vt.updateCallbackDone.catch(()=>{});return}
 r.classList.add("theme-fade","th-anim");run();setTimeout(clean,380)}

/* ---------- tema tercihleri ve cihazlar arası eşitleme ---------- */
const KB_THEMES=["light","dark","system"],KB_SCALES=[1,1.1,1.2];
function pushPrefs(){if(settings.themeSync===false||!S.authed||S.guest||!S.uid||!S.profiles[S.uid])return Promise.resolve(false);
 const prefs={theme:settings.theme||"system",accent:settings.accent||"auto",scale:+settings.scale||1,at:settings.prefsAt||now()};
 S.profiles={...S.profiles,[S.uid]:{...S.profiles[S.uid],prefs}};return write(()=>DB.update("profiles/"+S.uid,{prefs}),{quiet:true})}
/* kullanıcı bu cihazda tema/vurgu/yazı boyutunu değiştirdi */
function setThemePref(patch,o={}){let ch=false;for(const[k,v]of Object.entries(patch))if(settings[k]!==v){settings[k]=v;ch=true}if(!ch)return;
 settings.prefsAt=now();saveSettings();vib(8);
 themeSwitch(()=>{applyTheme();renderTop();if(S.route.name==="settings")render(false)},o);pushPrefs()}
/* profilde daha yeni tercih varsa (başka cihazda değişti) uygula */
function pullPrefs(p,instant){if(!p||!p.prefs||settings.themeSync===false||!S.authed||S.guest)return;const pr=p.prefs;if(!((+pr.at||0)>(settings.prefsAt||0)))return;
 const patch={};if(KB_THEMES.includes(pr.theme))patch.theme=pr.theme;if(pr.accent==="auto"||accentPal()[pr.accent])patch.accent=pr.accent;if(KB_SCALES.includes(+pr.scale))patch.scale=+pr.scale;
 const ch=Object.keys(patch).some(k=>settings[k]!==patch[k]);Object.assign(settings,patch);settings.prefsAt=+pr.at;saveSettings();if(!ch)return;
 const go=()=>{applyTheme();renderTop();if(S.route.name==="settings")scheduleRefresh()};if(instant)go();else themeSwitch(go,{fade:true})}
HOOKS.profiles.push(m=>{if(S.uid)pullPrefs(m[S.uid])});
HOOKS.enter.push(()=>{const p=S.profiles[S.uid];const at=(p&&p.prefs&&+p.prefs.at)||0;if(at>(settings.prefsAt||0))pullPrefs(p,true);else if((settings.prefsAt||0)>at)pushPrefs()});

/* ---------- topluluk teması (yönetici: admin/tema) ---------- */
/* admSubscribe her anlık görüntüde çağırır */
function temaSnap(o,n){const oa=(o&&o.accent)||"",na=(n&&n.accent)||"";const first=!temaSnap.init;temaSnap.init=true;
 if((settings.commAccent||"")!==na){settings.commAccent=na;saveSettings()}
 if((settings.accent||"auto")!=="auto")return;
 if(document.documentElement.getAttribute("data-accent")===effAccent())return;
 const go=()=>{applyTheme();if(S.authed){renderTop();if(S.route.name==="settings")scheduleRefresh()}};
 if(first){go();return}
 themeSwitch(go,{fade:true});
 if(oa!==na&&S.authed&&!(n&&n.by===S.uid))toast(na?"Kadraj'ın ortak teması değişti":"Kadraj'ın ortak teması kaldırıldı")}
function admTemaRow(){const t=S.adm&&S.adm.tema;const p=t&&t.accent&&accentPal()[t.accent];return`<button class="srow" data-act="admtema">${I("palette")}<span class="t">Ortak tema<small>${p?"Şu an: "+esc(t.title||p.n):"Herkesin vurgu rengini aynı anda değiştir"}</small></span></button>`}
ACT.admtema=()=>{if(!S.admin)return;const pal=accentPal();const cur=(S.adm&&S.adm.tema)||{};let sel=pal[cur.accent]?cur.accent:"okyanus";const dark=isDark();
 const ago2=t=>{const a=ago(t||now());return a==="şimdi"?"az önce":a+" önce"};
 const l=sheet("admtema","Ortak tema",`<p class="muted" style="margin:0 18px 12px;font-size:.86rem;line-height:1.4">Seçtiğin renk, vurgu rengi <b>Otomatik</b> olan herkeste aynı anda değişir. Kendi rengini seçenler etkilenmez.</p>
 ${pal[cur.accent]?`<div class="adm-cur" style="margin:0 16px 14px">${I("palette")}<span>Şu an: <b>${esc(cur.title||pal[cur.accent].n)}</b><small>${ago2(cur.at)} · @${esc(P(cur.by).username)}</small></span></div>`:""}
 <div class="accg">${Object.entries(pal).map(([k,p])=>`<button type="button" data-ac="${k}" aria-pressed="${sel===k}"><span class="dot" style="--sw:${dark?p.d[0]:p.l[0]};--si:${dark?p.d[1]:p.l[1]}">${I("check")}</span><span>${esc(p.n)}</span></button>`).join("")}</div>
 <div class="form" style="padding-top:6px"><div class="field"><label for="admTmT">Başlık (isteğe bağlı)</label><input class="in" id="admTmT" maxlength="40" placeholder="Örn. Bahar teması" value="${esc(cur.title&&pal[cur.accent]&&cur.title!==pal[cur.accent].n?cur.title:"")}"></div>
 <button class="btn block" type="button" id="admTmGo">${I("users")}Herkese uygula</button>${pal[cur.accent]?`<button class="btn sec block" type="button" id="admTmX">Ortak temayı kaldır</button>`:""}</div>`);
 $$("[data-ac]",l).forEach(b=>b.onclick=()=>{sel=b.dataset.ac;vib(8);$$("[data-ac]",l).forEach(x=>x.setAttribute("aria-pressed",x===b))});
 $("#admTmGo",l).onclick=async()=>{const title=($("#admTmT",l).value||"").trim().slice(0,40)||pal[sel].n;if(await admSet("tema",{accent:sel,title})){admLog("Ortak tema: "+title);closeLayer("admtema");toast("Ortak tema herkese uygulandı");if(S.route.name==="admin")render(false)}};
 const x=$("#admTmX",l);if(x)x.onclick=async()=>{if(await admSet("tema",{accent:"",title:""})){admLog("Ortak tema kaldırıldı");closeLayer("admtema");toast("Ortak tema kaldırıldı");if(S.route.name==="admin")render(false)}}};

/* ---------- ortak sohbet temaları ---------- */
/* bub: benim balonum (renk ya da degrade), c: düz renk karşılığı, ink: balon yazısı. dark: koyu zemin. 3.9 kimlikleri (none, dusk, ocean, mint, night, dots, grid, hearts) korunur. */
function chatThemes(){if(chatThemes.t)return chatThemes.t;const hz=`url("${WP_HEART}") 0 0/56px 56px`;return chatThemes.t=[
 {id:"none",label:"Yok",bg:""},
 {id:"ocean",label:"Okyanus",bg:"linear-gradient(180deg,rgba(0,150,255,.26),rgba(0,210,190,.22))",bub:"linear-gradient(150deg,#1366D6,#0B6FA0)",c:"#1366D6",ink:"#fff"},
 {id:"dusk",label:"Gün batımı",bg:"linear-gradient(160deg,rgba(255,94,98,.32),rgba(255,153,102,.2) 50%,rgba(120,80,220,.3))",bub:"linear-gradient(135deg,#D62B55,#6A35D9)",c:"#A0309A",ink:"#fff"},
 {id:"mint",label:"Nane",bg:"radial-gradient(circle at 20% 10%,rgba(120,230,170,.42),transparent 60%),radial-gradient(circle at 90% 90%,rgba(80,170,255,.36),transparent 55%)",bub:"#0B7A5E",c:"#0B7A5E",ink:"#fff"},
 {id:"night",label:"Gece",dark:1,bg:"radial-gradient(rgba(255,255,255,.5) 1px,transparent 1.6px) 0 0/44px 44px,radial-gradient(rgba(255,255,255,.28) 1px,transparent 1.6px) 22px 22px/44px 44px,linear-gradient(180deg,#0f1530,#2a1b4a)",bub:"linear-gradient(135deg,#4F46E5,#7C3AED)",c:"#5B3FE8",ink:"#fff"},
 {id:"lavender",label:"Lavanta",bg:"linear-gradient(165deg,rgba(167,139,250,.36),rgba(244,114,182,.18))",bub:"#6B3FD0",c:"#6B3FD0",ink:"#fff"},
 {id:"hearts",label:"Aşk",bg:`${hz},linear-gradient(180deg,rgba(255,94,138,.2),rgba(255,154,190,.1))`,bub:"linear-gradient(135deg,#C2185B,#D81B60)",c:"#C2185B",ink:"#fff"},
 {id:"forest",label:"Orman",bg:"radial-gradient(circle at 15% 0%,rgba(74,222,128,.26),transparent 55%),linear-gradient(180deg,rgba(22,101,52,.18),rgba(20,83,45,.36))",bub:"#2F6B3A",c:"#2F6B3A",ink:"#fff"},
 {id:"coffee",label:"Kahve",bg:"radial-gradient(circle at 80% 8%,rgba(255,214,170,.35),transparent 50%),linear-gradient(170deg,rgba(196,148,104,.34),rgba(120,78,46,.24))",bub:"#7A4A2A",c:"#7A4A2A",ink:"#fff"},
 {id:"neon",label:"Neon",dark:1,bg:"radial-gradient(circle at 18% 12%,rgba(0,213,255,.38),transparent 42%),radial-gradient(circle at 86% 88%,rgba(184,77,255,.45),transparent 48%),#0a0a1f",bub:"linear-gradient(135deg,#00D5FF,#B84DFF)",c:"#5FA0FF",ink:"#0A0A1F"},
 {id:"candy",label:"Pamuk şeker",bg:"linear-gradient(160deg,rgba(255,143,199,.38),rgba(143,184,255,.38))",bub:"linear-gradient(135deg,#FF8FC7,#8FB8FF)",c:"#C7A3E3",ink:"#2A1033"},
 {id:"dots",label:"Noktalı",bg:"radial-gradient(rgba(127,127,127,.32) 1.4px,transparent 1.7px) 0 0/18px 18px"},
 {id:"grid",label:"Kareli",bg:"linear-gradient(rgba(127,127,127,.16) 1px,transparent 1px) 0 0/22px 22px,linear-gradient(90deg,rgba(127,127,127,.16) 1px,transparent 1px) 0 0/22px 22px"}]}
const kbThLabel=id=>id==="photo"?"Fotoğraf":(chatThemes().find(t=>t.id===id)||{label:"Yok"}).label;
const kbPhotoBg=d=>d?`linear-gradient(rgba(0,0,0,.12),rgba(0,0,0,.12)),url("${d}") center/cover no-repeat`:"";
/* başkasının yazdığı veriyi stile koymadan önce denetle */
const kbOkImg=d=>typeof d==="string"&&d.length<1e6&&/^data:image\/(jpeg|png|webp);base64,[A-Za-z0-9+/=]+$/.test(d)?d:null;
const kbOkHex=c=>typeof c==="string"&&/^#[0-9a-fA-F]{6}$/.test(c)?c:null;
function kbLum(hex){const [r,g,b]=[1,3,5].map(i=>parseInt(hex.slice(i,i+2),16)/255).map(v=>v<=.03928?v/12.92:Math.pow((v+.055)/1.055,2.4));return .2126*r+.7152*g+.0722*b}
/* fotoğraftan balon rengi: doygun bölgelerin ortalaması, beyaz yazıyla en az 4.6 kontrast olacak kadar koyu */
function kbTone(img){try{const c=document.createElement("canvas");c.width=c.height=16;const x=c.getContext("2d");coverDraw(x,img,16,16);const d=x.getImageData(0,0,16,16).data;let R=0,G=0,B=0,W=0;
 for(let i=0;i<d.length;i+=4){const r=d[i],g=d[i+1],b=d[i+2];const mx=Math.max(r,g,b),mn=Math.min(r,g,b);const w=Math.pow((mx-mn)/255,2)+.03;R+=r*w;G+=g*w;B+=b*w;W+=w}
 const r=R/W/255,g=G/W/255,b=B/W/255;const mx=Math.max(r,g,b),mn=Math.min(r,g,b);let h=0,sat=0,l=(mx+mn)/2;
 if(mx!==mn){const dd=mx-mn;sat=l>.5?dd/(2-mx-mn):dd/(mx+mn);h=mx===r?(g-b)/dd+(g<b?6:0):mx===g?(b-r)/dd+2:(r-g)/dd+4;h*=60}
 sat=Math.max(Math.min(sat,.75),.32);l=Math.min(l,.46);let hex=kbHex(h,sat*100,l*100);while(1.05/(kbLum(hex)+.05)<4.6&&l>.1){l-=.03;hex=kbHex(h,sat*100,l*100)}return hex}catch(e){return null}}
/* fotoğraflı ortak tema önbelleği: bellekte + (bulutta) localStorage kadraj_wpc_<cid> {at,d,t}; en fazla 4 sohbet */
const KB_WPC={},KB_WPC_ING={};
function wpcGet(cid,sh){if(!sh||typeof sh.ref!=="string"||!/^wp-[\w-]{1,80}$/.test(sh.ref))return null;const m=KB_WPC[cid];if(m&&m.at===sh.at)return m.d;
 if(S.mode!=="local"){const c=LS.get("kadraj_wpc_"+cid);if(c&&c.at===sh.at&&kbOkImg(c.d)){KB_WPC[cid]=c;return c.d}}
 const tag=cid+":"+sh.at;const ing=KB_WPC_ING[tag];if(!ing||now()-ing>30e3){KB_WPC_ING[tag]=now();
  Promise.resolve().then(()=>DB.get("vchunks/"+sh.ref)).then(doc=>{const d=doc&&kbOkImg(doc.d);if(!d)return;wpcPut(cid,sh.at,d);wpReapply(cid)}).catch(e=>console.warn("tema fotoğrafı",e))}
 return null}
function wpcPut(cid,at,d){KB_WPC[cid]={at,d};if(S.mode==="local")return;const key="kadraj_wpc_"+cid;const v={at,d,t:now()};if(LS.set(key,v)){wpcTrim(key,3);return}wpcTrim(key,0);LS.set(key,v)}
function wpcTrim(keep,max){try{const ks=[];for(let i=0;i<localStorage.length;i++){const k=localStorage.key(i);if(k&&k.startsWith("kadraj_wpc_")&&k!==keep)ks.push(k)}if(ks.length<=max)return;ks.map(k=>[k,(LS.get(k)||{}).t||0]).sort((a,b)=>b[1]-a[1]).slice(max).forEach(([k])=>LS.del(k))}catch{}}
function wpReapply(cid){const box=$("#msgs");if(!box||S.route.name!=="chat")return;const key=S.route.params.key;let k=null;try{k=keyInfo(key)}catch{}if(k&&k.cid===cid)applyWp(box,key)}
function kbTheme(id,ctx){if(id==="photo"){const d=kbOkImg(ctx.src==="shared"?wpcGet(ctx.cid,ctx.sh):LS.get(wpLsKey(ctx.src==="*"?"*":ctx.src)));
  const tone=kbOkHex(ctx.src==="shared"?ctx.sh&&ctx.sh.c:(settings.wpTone||{})[ctx.src==="*"?"*":ctx.src]);
  return{id:"photo",label:"Fotoğraf",bg:kbPhotoBg(d),img:d,dark:1,src:ctx.src,bub:tone||"",c:tone||"",ink:"#fff",key:`photo:${ctx.src}:${ctx.sh?ctx.sh.at:""}:${d?d.length:0}:${tone||""}`}}
 const t=chatThemes().find(x=>x.id===id)||chatThemes()[0];return{...t,src:ctx.src,key:t.id==="none"?"none":`${t.id}:${ctx.sh?ctx.sh.at:""}`}}
/* geçerli tema. Ortak tema (DM/grup) bu sohbet için cihaza özel seçimden yeniyse o kazanır; "Yalnızca bende" daha yeni seçildiyse kişisel tema görünür.
   3.9'dan kalan (zamansız) kişisel seçimler ortak temanın gerisinde kalır. Sıra: ortak > sohbete özel > varsayılan "*". */
function chatThemeOf(key){const w=settings.wp||{},wa=settings.wpAt||{};let k=null;if(key&&key!=="*"){try{k=keyInfo(key)}catch{}}
 const sh=k&&(k.type==="dm"||k.type==="group")&&S.chats[k.cid]&&S.chats[k.cid].theme;const per=key!=="*"&&w[key]?{id:w[key],at:+wa[key]||0}:null;
 if(sh&&sh.id&&(!per||per.at<=(+sh.at||0))){if(sh.id!=="none")return kbTheme(sh.id,{src:"shared",cid:k.cid,sh});return w["*"]?kbTheme(w["*"],{src:"*"}):kbTheme("none",{src:"shared"})}
 if(per)return kbTheme(per.id,{src:key});if(w["*"])return kbTheme(w["*"],{src:"*"});return kbTheme("none",{src:""})}
/* renderMsgs her çizimde çağırır; değişiklik varsa (karşı taraf temayı değiştirdiyse) yumuşak geçişle uygular */
function applyWp(box,key){const w=chatThemeOf(key);if(box.dataset.wp===w.key)return;const first=!box.dataset.wp;box.dataset.wp=w.key;
 const set=()=>{box.style.background=w.bg||"";box.classList.toggle("wp",!!w.bg);box.toggleAttribute("data-dk",!!(w.dark&&w.bg));const cp=box.id==="msgs"?$("#composer"):null;
  for(const el of[box,cp]){if(!el)continue;if(w.bub){el.dataset.bub=w.id;el.style.setProperty("--bub",w.bub);el.style.setProperty("--bub-c",w.c||"#333");el.style.setProperty("--bub-ink",w.ink||"#fff")}
   else{delete el.dataset.bub;for(const p of["--bub","--bub-c","--bub-ink"])el.style.removeProperty(p)}}};
 if(first)set();else themeSwitch(set,{fade:true})}
/* 4.4.3: çocuk modu yalnızca çocuğun kendi gönderdiğini denetliyordu. Artık tanımadığı biri Çocuk Modu'ndaki kişiye yazamaz,
   çocuk Meydan'a (paylaş yoluyla da) gönderemez; gruptan çıkarılan biri gruba yazamaz. */
const sendMessageBase=sendMessage;
sendMessage=async function(key,payload){let k=null;try{k=keyInfo(key)}catch{}
 if(k&&!S.admin){if(k.type==="meydan"&&isChild(S.uid)){toast("Çocuk modunda Meydan kapalı.");return}
  if(k.type==="dm"&&!BOT[k.uid]&&isChild(k.uid)&&!isChild(S.uid)&&!(isFollowing(S.uid,k.uid)&&isFollowing(k.uid,S.uid))){toast("Bu kişi Çocuk Modu'nda; ona yalnızca karşılıklı arkadaşları yazabilir.");return}
  if(k.type==="group"){const gc=S.chats[k.cid];if(gc?(Array.isArray(gc.members)&&!gc.members.includes(S.uid)):S._chatsIn){toast("Bu grubun üyesi değilsin.");return}}}
 return sendMessageBase(key,payload)};
/* 4.4.1 klavye: klavye açılınca yalnızca görünür alan küçülür (iOS ve yeni Android); sayfa yukarı kaymasın, üst çubuk (grup adı) yerinde kalsın */
(function(){const vv=window.visualViewport;if(!vv)return;let q=0;const fit=()=>{q=0;document.documentElement.style.setProperty("--vvh",Math.round(vv.height)+"px");if(vv.offsetTop>0||window.scrollY>0)window.scrollTo(0,0);const b=document.getElementById("msgs");if(b&&b._pin)msgsPin(b)};
 const k=()=>{if(!q)q=requestAnimationFrame(fit)};vv.addEventListener("resize",k);vv.addEventListener("scroll",k);fit()})();
/* ortak temayı değiştir: önce sohbete küçük bir not (DM'de sohbet belgesini de oluşturur), sonra chats/{cid}.theme */
async function setSharedTheme(key,id,photo,tone){let k=null;try{k=keyInfo(key)}catch{}if(!k||!(k.type==="dm"||k.type==="group"))return false;if(!guard())return false;
 const at=now();let ref=null;const prev=(S.chats[k.cid]||{}).theme;
 if(id==="photo"){if(!photo)return false;ref="wp-"+k.cid;if(!await write(()=>DB.set("vchunks/"+ref,{d:photo,at,by:S.uid})))return false;wpcPut(k.cid,at,photo)}
 const nm=(me().name||me().username||"").trim();
 const theme={id,by:S.uid,at,ref:ref||null,c:id==="photo"&&kbOkHex(tone)||null};
 const ok=await write(async()=>{try{await DB.update("chats/"+k.cid,{theme})}catch(e){const c=e&&e.code;if(k.type==="dm"&&(c==="invalid_argument"||c==="not-found"))await DB.set("chats/"+k.cid,{members:[S.uid,k.uid].sort(),updatedAt:at,reads:{[S.uid]:at},theme});else throw e}});
 if(!ok)return false;
 const c=S.chats[k.cid]||{};S.chats={...S.chats,[k.cid]:{...c,theme}};
 Promise.resolve().then(()=>sendMessage(key,{text:id==="none"?`${nm} sohbet temasını kaldırdı`:`${nm} sohbet temasını “${kbThLabel(id)}” yaptı`,sys:"theme"})).catch(()=>{});
 if(id!=="photo"&&prev&&prev.ref)DB.del("vchunks/"+prev.ref).catch(()=>{});
 if(settings.wp&&settings.wp[key]){const w={...settings.wp},wa={...(settings.wpAt||{})};delete w[key];delete wa[key];settings.wp=w;settings.wpAt=wa;saveSettings()}
 return true}
/* tema seçici: canlı önizleme, tema ızgarası, fotoğraf; DM/grupta "Herkes için" / "Yalnızca bende". key "*" = varsayılan tema (Ayarlar). */
function wallpaperMenu(key){key=typeof key==="string"&&key?key:(S.route.params&&S.route.params.key);if(!key)return;
 const def=key==="*";let k=null;if(!def){try{k=keyInfo(key)}catch{}}const canShare=!!k&&(k.type==="dm"||k.type==="group");
 const cur=chatThemeOf(key);const sh=canShare?(S.chats[k.cid]||{}).theme:null;
 const st={sel:cur.id,photo:null,img:cur.img||null,tone:cur.id==="photo"?cur.c||null:null,mode:canShare&&cur.src!==key?"all":"me"};
 const list=[...chatThemes(),{id:"photo",label:"Fotoğraf"}];
 const tile=t=>{const img=t.id==="photo"?(st.photo||st.img):null;const bg=t.id==="photo"?(img?`url("${img}") center/cover no-repeat`:""):t.bg;
  return`<button type="button" data-th="${t.id}" aria-pressed="${st.sel===t.id}" aria-label="${t.id==="photo"?"Fotoğraftan seç":esc(t.label)}"><span class="tw ${t.id==="photo"?"ph":""}"><span class="twb" style="background:${esc(bg||"")}"></span>${t.id==="none"?I("close"):t.id==="photo"?I(img?"edit":"image"):`<i style="background:${esc(t.bub||"var(--accent)")}"></i>`}</span><span class="lb">${esc(t.label)}</span></button>`};
 const l=sheet("wp",def?"Varsayılan sohbet teması":"Sohbet teması",`<div class="thtop"><div class="thpv" id="thPv"><span class="thbg"></span><span class="b">Yeni temayı gördün mü?</span><span class="b me">Bayıldım, çok yakışmış!</span><span class="b" id="thPv3"></span></div>
  ${canShare?`<div class="seg thseg" role="group" aria-label="Kim görsün"><button type="button" data-thm="all">${I("users")}Herkes için</button><button type="button" data-thm="me">${I("lock")}Yalnızca bende</button></div>`:""}<p class="thhint" id="thHint"></p>${!def&&!canShare?`<label class="check thall"><input type="checkbox" id="wpAll"> Bütün sohbetlerde kullan</label>`:""}</div>
  <div class="thgrid" id="thGrid">${list.map(tile).join("")}</div>
  <div class="thfoot"><button class="btn block" type="button" id="thGo">Uygula</button></div>`);
 const shEl=l.querySelector(".sheet");if(shEl)shEl.classList.add("thsheet");
 const draw=()=>{const t=st.sel==="photo"?{bg:kbPhotoBg(st.photo||st.img),dark:1,bub:st.tone||"",ink:"#fff"}:(list.find(x=>x.id===st.sel)||list[0]);const pv=$("#thPv",l);
  pv.querySelector(".thbg").style.background=t.bg||"";pv.style.setProperty("--pb",t.bub||"var(--accent)");pv.style.setProperty("--pi",t.ink||"var(--accent-ink)");
  $$("[data-th]",l).forEach(b=>b.setAttribute("aria-pressed",b.dataset.th===st.sel));$$("[data-thm]",l).forEach(b=>b.setAttribute("aria-pressed",b.dataset.thm===st.mode));
  const all=canShare&&st.mode==="all";$("#thPv3",l).textContent=all?"Herkes aynı anda görüyor":def?"Bütün sohbetlerinde":"Yalnızca sende görünüyor";
  $("#thHint",l).textContent=def?"Ortak teması olmayan sohbetlerde görünür. Yalnızca bu cihazda saklanır.":all?`Sohbetteki ${k.type==="group"?"herkes":"ikiniz de"} yeni temayı aynı anda görür; sohbete küçük bir not düşer.`:canShare?"Yalnızca bu cihazda değişir, karşı taraf görmez.":"Yalnızca senin cihazında görünür.";
  $("#thGo",l).textContent=all?"Herkes için uygula":"Uygula"};
 const pickPhoto=async()=>{const r=await pickImage({title:"Tema fotoğrafı",draw:false});if(!r||!r.img)return;const img=r.img;const ratio=(img.naturalWidth||img.width)/(img.naturalHeight||img.height)||.56;const w=720,hh=Math.round(w/Math.min(Math.max(ratio,.4),1.2));
  let d;try{d=encode(toCanvas(img,w,hh),300000,.8)}catch(e){console.warn(e);return toast("Fotoğraf hazırlanamadı. Başka bir fotoğraf dene.")}st.photo=d;st.tone=kbTone(img);st.sel="photo";
  const pb=$('[data-th="photo"]',l);if(pb){pb.outerHTML=tile({id:"photo",label:"Fotoğraf"});wire()}draw()};
 const wire=()=>$$("[data-th]",l).forEach(b=>b.onclick=()=>{const id=b.dataset.th;vib(8);if(id==="photo"&&(st.sel==="photo"||!(st.photo||st.img)))return pickPhoto();st.sel=id;draw()});
 wire();$$("[data-thm]",l).forEach(b=>b.onclick=()=>{st.mode=b.dataset.thm;draw()});
 $("#thGo",l).onclick=async e=>{const b=e.currentTarget;if(b.disabled)return;const img=st.photo||st.img;if(st.sel==="photo"&&!img)return pickPhoto();
  if(canShare&&st.mode==="all"){if(sh&&sh.id===st.sel&&cur.src==="shared"&&!st.photo){closeLayer("wp");return}
   b.disabled=true;b.textContent="Uygulanıyor…";const ok=await setSharedTheme(key,st.sel,st.sel==="photo"?img:null,st.tone);
   if(!ok){b.disabled=false;draw();return}closeLayer("wp");vib(15);const box=$("#msgs");if(box)applyWp(box,key);return}
  const allEl=$("#wpAll",l);const target=def||(allEl&&allEl.checked)?"*":key;
  if(st.sel==="photo"){if(!LS.set(wpLsKey(target),img))return toast("Fotoğraf çok büyük, kaydedilemedi.");settings.wpTone={...(settings.wpTone||{}),[target]:st.tone||null}}
  const w={...(settings.wp||{})},wa={...(settings.wpAt||{})};if(target==="*"){w["*"]=st.sel;if(!def){delete w[key];delete wa[key]}}else{w[key]=st.sel;wa[key]=now()}
  settings.wp=w;settings.wpAt=wa;saveSettings();closeLayer("wp");vib(12);const box=$("#msgs");if(box&&!def)applyWp(box,key);if(S.route.name==="settings")render(false);
  toast(def?"Varsayılan sohbet teması kaydedildi":st.sel==="none"?"Sohbet teması kaldırıldı":canShare?"Tema yalnızca sende değişti":"Sohbet teması değişti")};
 draw()}
/* 4.4.1: sohbet teması yalnızca arka planı değil her yeri boyar (üst çubuk/grup adı, gelen-giden balonlar, yazma çubuğu, çipler).
   Renkler temanın tonundan üretilir ve sohbet açıkken #shell'e yazılır; sohbetten çıkınca silinir. Katmanlar (#overlay) uygulama temasında kalır. */
const KB_HUE={ocean:[205,1],dusk:[340,.8],mint:[158,.9],night:[235,.9],lavender:[265,.9],hearts:[338,.85],forest:[135,.7],coffee:[28,.6],neon:[268,1],candy:[300,.7]};
const CT_PROPS=["--bg","--surface","--surface-2","--line","--fg","--muted","--in","--in-ink","--accent","--accent-ink","--accent-soft"];
function kbHue(hex){const [r,g,b]=[1,3,5].map(i=>parseInt(hex.slice(i,i+2),16)/255);const mx=Math.max(r,g,b),mn=Math.min(r,g,b),d=mx-mn;if(!d)return 0;let h=mx===r?(g-b)/d+(g<b?6:0):mx===g?(b-r)/d+2:(r-g)/d+4;return h*60}
function chatVars(w){let hm=w&&KB_HUE[w.id];if(!hm&&w&&w.id==="photo"&&kbOkHex(w.c))hm=[kbHue(w.c),.45];if(!hm)return null;
 const [h,m]=hm;const dk=isDark()||!!w.dark;const X=(s,l)=>kbHex(h,Math.min(100,s*m),l);
 return dk?{"--bg":X(30,7.5),"--surface":X(26,12),"--surface-2":X(22,16),"--line":X(18,22),"--fg":X(25,93),"--muted":X(12,66),"--in":X(28,19),"--in-ink":X(20,94),"--accent":X(80,70),"--accent-ink":X(40,8),"--accent-soft":X(35,20),dk:1}
  :{"--bg":X(40,95.5),"--surface":X(50,99),"--surface-2":X(35,91),"--line":X(25,85),"--fg":X(40,11),"--muted":X(14,36),"--in":X(55,92),"--in-ink":X(45,12),"--accent":kbOkHex(w.c)||X(70,38),"--accent-ink":kbOkHex(w.ink)||"#ffffff","--accent-soft":X(55,90),dk:0}}
function chatShell(w){const sh=$("#shell");if(!sh)return;const v=w?chatVars(w):null;const k=v?w.key+(v.dk?":d":":l"):"";if((sh.dataset.ctk||"")===k)return;sh.dataset.ctk=k;
 const mt=document.querySelector('meta[name="theme-color"]');
 if(!v){for(const p of CT_PROPS)sh.style.removeProperty(p);delete sh.dataset.ct;sh.removeAttribute("data-cdk");if(mt&&sh.dataset.tc){mt.setAttribute("content",sh.dataset.tc);delete sh.dataset.tc}return}
 for(const p of CT_PROPS)sh.style.setProperty(p,v[p]);sh.dataset.ct=w.id;sh.toggleAttribute("data-cdk",!!v.dk);if(mt){if(!sh.dataset.tc)sh.dataset.tc=mt.getAttribute("content")||"";mt.setAttribute("content",v["--bg"])}}
const applyWpBase=applyWp;
applyWp=function(box,key){applyWpBase(box,key);if(box&&box.id==="msgs")chatShell(chatThemeOf(key))};
HOOKS.after.push(r=>{if(r!=="chat")chatShell(null)});

