function kbFilterSettings(){const q=kbFold(S.setQ||"").trim();const words=q?q.split(/\s+/):[];let any=false;
 for(const s of $$("#main .sxs")){const tm=!!q&&(s.dataset.t||"").includes(q);let vis=0;for(const r of $$("[data-k]",s)){const ok=!q||tm||words.every(w=>r.dataset.k.includes(w));r.hidden=!ok;if(ok)vis++}s.hidden=!vis;if(vis)any=true}
 const pc=$("#main .setprof");if(pc){const ok=!q||words.every(w=>pc.dataset.k.includes(w));pc.hidden=!ok;if(ok)any=true}
 const e=$("#setEmpty");if(e){e.hidden=any||!q;const eq=$("#setEmptyQ");if(eq)eq.textContent=(S.setQ||"").trim()}
 const f=$("#main .setfoot");if(f)f.hidden=!!q}
async function kbFillStorage(){const c=S._stUse;if(c&&now()-c.t<20e3){const el=$("#stUse");if(el)el.textContent=c.s;return}
 let s="Bilinmiyor";try{let n=0;try{for(let i=0;i<localStorage.length;i++){const k=localStorage.key(i);n+=(k.length+(localStorage.getItem(k)||"").length)*2}}catch{}if(navigator.storage&&navigator.storage.estimate){const e=await navigator.storage.estimate();n+=e.usage||0}s=kbMB(n)}catch{}
 S._stUse={t:now(),s};const el=$("#stUse");if(el)el.textContent=s}
function kbOnFlag(f,v){settings[f]=v;saveSettings();
 if(f==="reduceMotion")document.documentElement.classList.toggle("reduce-motion",v);
 else if(f==="showActive"){try{const r=S.caps.room;if(r&&r.presence)Promise.resolve(r.presence({})).catch(()=>{})}catch{}setTimeout(scheduleRefresh,300);toast(v?"Aktiflik durumun yeniden görünür":"Aktiflik durumun gizlendi")}
 else if(f==="themeSync"){if(v){settings.prefsAt=now();saveSettings();pushPrefs();toast("Tema artık bütün cihazlarında aynı")}}
 else if(f==="haptics"&&v)vib(25)}
HOOKS.after.push(r=>{if(r!=="settings"){S.setQ="";return}
 for(const el of $$("#main input[data-set]"))el.onchange=()=>kbOnFlag(el.dataset.set,el.checked);
 const n=$("#setNotify");if(n)n.addEventListener("change",()=>{const g=n.closest(".ngrp");if(!g)return;g.classList.toggle("off",!n.checked);$$("input[data-set]",g).forEach(i=>i.disabled=!n.checked)});
 const q=$("#setQ");if(q){q.value=S.setQ||"";q.oninput=()=>{S.setQ=q.value;kbFilterSettings()};if(S.setQ)kbFilterSettings()}
 kbFillStorage()});
