async function kpReauth(pw){const{A,auth}=FB;const u=auth.currentUser;await A.reauthenticateWithCredential(u,A.EmailAuthProvider.credential(u.email,pw))}
function kpConfirm(title,text,fn){const l=sheet("kpc",title,`<form class="form" id="kcF"><p class="muted" style="margin:0">${esc(text)}</p>${pwField("kcPw","Şifren","current-password")}<div class="err" id="kcErr"></div><button class="btn block">Onayla</button></form>`);
 $("#kcF",l).onsubmit=async e=>{e.preventDefault();const pw=$("#kcPw",l).value;try{await kpReauth(pw);closeLayer("kpc");await fn(pw)}catch(ex){$("#kcErr",l).textContent=authErr(ex)}}}
/* Şifremi unuttum > Kadraj Anahtarı ile yenile */
function fbKey(prefill){S.inReset=false;authShell(`<div>${brandLine}<h2>Kadraj Anahtarı ile yenile</h2><p class="lead">Kullanıcı adını, Kadraj Anahtarını ve yeni şifreni yaz. E-posta gerekmez.</p></div>
 <form id="fkF" novalidate><div class="field"><label for="fkUn">Kullanıcı adı</label><input class="in" id="fkUn" autocapitalize="off" spellcheck="false" placeholder="ornek.kullanici" value="${esc(prefill&&!prefill.includes("@")?prefill.replace(/^@/,""):"")}"></div>
 <div class="field"><label for="fkCode">Kadraj Anahtarı</label><input class="in kcode" id="fkCode" autocapitalize="characters" autocomplete="off" spellcheck="false" placeholder="XXXX-XXXX-XXXX" maxlength="14"></div>
 ${pwField("fk1","Yeni şifre","new-password")}${pwField("fk2","Yeni şifre (tekrar)","new-password")}<div class="err" id="fkErr"></div><button class="btn block" type="submit">${I("key")}Şifremi yenile ve giriş yap</button></form>
 <p class="muted" style="margin:0;font-size:.85rem">Anahtarın, Kadraj'da <b>Ben › zarf simgesi (Kadraj Posta)</b> içinde durur. Anahtarını da kaybettiysen uygulamanın yöneticisine kullanıcı adını ve kayıt olduğun e-postayı söyle; e-posta doğruysa anahtarını sana iletebilir. Gerçek bir e-postayla kayıt olduysan e-postana bağlantı da isteyebilirsin.</p>
 <button class="btn ghost" id="fkMail">E-postama bağlantı gönder</button><button class="btn ghost" id="fkBack">Girişe dön</button>`);
 const ci=$("#fkCode");ci.oninput=()=>{const p=ci.selectionStart;const v=kaFmt(ci.value).slice(0,14);ci.value=v;try{ci.setSelectionRange(v.length,v.length)}catch{}};
 $("#fkBack").onclick=()=>fbLogin();$("#fkMail").onclick=()=>fbForgot($("#fkUn").value.trim());
 $("#fkF").onsubmit=async e=>{e.preventDefault();const err=$("#fkErr");err.textContent="";const un=$("#fkUn").value.trim().replace(/^@/,"").toLowerCase();const code=kaNorm($("#fkCode").value);const a=$("#fk1").value,b=$("#fk2").value;
  if(!un)return err.textContent="Kullanıcı adını yaz.";if(code.length!==12)return err.textContent="Kadraj Anahtarı 12 karakter olmalı (XXXX-XXXX-XXXX).";if(a.length<6)return err.textContent="Yeni şifre en az 6 karakter olmalı.";if(a!==b)return err.textContent="İki şifre aynı değil.";
  const btn=$("#fkF button[type=submit]");btn.disabled=true;btn.textContent="Denetleniyor…";const fail=t=>{S.inReset=false;err.textContent=t;btn.disabled=false;btn.innerHTML=`${I("key")}Şifremi yenile ve giriş yap`};
  let d=null;try{d=await DB.get("unames/"+un)}catch{return fail("Bu özellik henüz açık değil. Uygulamanın sahibi Firebase kurallarını güncellemeli.")}
  if(!d||!d.email)return fail("Bu kullanıcı adı bulunamadı.");if(!d.rk)return fail("Bu hesapta Kadraj Anahtarı henüz etkin değil. Hesap sahibi bir kez giriş yapmış olmalı.");
  let old=null;try{old=await kaUnlock(code,d.rk)}catch{return fail("Kadraj Anahtarı yanlış. Harfleri kontrol et.")}
  S.inReset=true;let cr=null;try{await setPersist(true);cr=await FB.A.signInWithEmailAndPassword(FB.auth,d.email,old)}catch(ex){return fail("Anahtar doğru ama eski kalmış: şifren anahtar oluşturulduktan sonra başka bir yoldan değişmiş. Son şifrenle giriş yapmayı dene.")}
  try{await FB.A.updatePassword(cr.user,a);await kasaSeal(cr.user.uid,a,{create:false,note:{t:"Şifren Kadraj Anahtarı ile yenilendi",b:"Şifren az önce Kadraj Anahtarınla yenilendi. Bunu sen yapmadıysan anahtarını yenile: Kadraj Posta › Yeni anahtar oluştur.",ic:"key"}}).catch(()=>{});
   LS.set("kadraj_reset_ok",1);location.replace(location.pathname)}catch(ex){fail(authErr(ex))}}}
