 const html=d.innerHTML;if(old&&old._vz===html&&old.querySelector(".vz-focus")){d.replaceChildren(old);return}
 const nav=d.firstElementChild;if(!nav)return;nav._vz=html;
 const fi=nav.querySelector('[data-tab="feed"] svg.i');if(fi)fi.innerHTML=IP.vzfeed;
 const ei=nav.querySelector('[data-tab="explore"] svg.i');if(ei)ei.innerHTML=IP.vzlens;
