/* --- üst çubuk: HUD etiketi --- */
function vzMeta(r){const up=s=>String(s).toLocaleUpperCase("tr");const pr=S.route.params||{};try{
 if(r==="feed")return up(`Akış · ${allPosts().filter(canSee).length} kare`);
 if(r==="explore")return"KİŞİ · ETİKET · KARE";
 if(r==="chats"){const u=+unreadCount()||0;const a=activeUsers().length;return up((u?`${u} okunmamış`:"Hepsi okundu")+(a?` · ${a} aktif`:""))}
 if(r==="profile"){if(pr.uid===S.uid)return"SENİN KADRAJIN";return up(activeLabel(pr.uid)||"Profil")}
 if(r==="post"){const p=postById(pr.id);return p?up("Kare · "+ago(p.at)):""}
 if(r==="activity")return"BEĞENİ · YORUM · TAKİP";
 if(r==="settings")return up("Kadraj "+APP_VER);
 if(r==="edit")return"AD · KULLANICI ADI · BİYOGRAFİ";
 if(r==="people")return pr.type==="followers"?"TAKİPÇİLER":"TAKİP EDİLENLER";
 if(r==="invite")return"BAĞLANTI · DAVET MESAJI";
 if(r==="admin")return"YÖNETİM PANELİ"}catch{}return""}
