const ar5X=c=>c.x5||(c.x5={rs:{known:false,cam:false,share:false,mic:true},peerV:0,q:0,ns:true,sink:"",sinkLabel:"",tray:false,swap:false,idle:false,lvl:0,llv:0,spk:false,shown:{}});
