/* ---- arama başlatma ve yanıtlama (5.0) ---- */
startCall=async function(uid,video){
 if(CALL){if(!$("#callBox"))return ar5Restore();return toast("Zaten bir aramadasın.")}
 if(!guard())return;if(S.mode!=="cloud")return toast("Arama için Firebase bağlantısı gerekiyor.");if(!callSupported())return toast("Bu tarayıcı aramayı desteklemiyor. Chrome ya da Safari'yi dene.");if(BOT[uid])return toast("Botlar aranamaz.");
 if(typeof childGate==="function"&&!childGate(uid))return;
 if(AR5.starting)return;AR5.starting=true;let stream;
 try{stream=await getMedia(video)}catch(e){if(!video){AR5.starting=false;return mediaErr(e)}try{stream=await getMedia(false);video=false;toast("Kamera açılamadı, sesli arama başlatılıyor.")}catch(e2){AR5.starting=false;return mediaErr(e2)}}
 AR5.starting=false;if(CALL){stream.getTracks().forEach(t=>t.stop());return toast("Zaten bir aramadasın.")}
 const{F,db}=FB;const ref=F.doc(F.collection(db,"calls"));const id=ref.id;
 const c=CALL={id,ref,peer:uid,video:!!video,role:"caller",status:"ringing",stream,unsubs:[],start:0,mic:true,cam:!!video,facing:"user",pend:[]};const x=ar5X(c);
 const pc=newPC(id);c.pc=pc;const at=stream.getAudioTracks()[0],vt=stream.getVideoTracks()[0];
 if(at)pc.addTrack(at,stream);
 try{x.vtx=vt?pc.addTransceiver(vt,{direction:"sendrecv",streams:[stream]}):pc.addTransceiver("video",{direction:"sendrecv",streams:[stream]})}catch(e){console.warn(e);if(vt)pc.addTrack(vt,stream)}
 try{ar5WireDC(c,pc.createDataChannel("kadraj",{ordered:true}))}catch(e){console.warn(e)}
 showCallUI();listenCands();
 try{const offer=await pc.createOffer();await pc.setLocalDescription(offer);await F.setDoc(ref,{from:S.uid,to:uid,video:!!video,status:"ringing",offer:{type:offer.type,sdp:offer.sdp},at:Date.now(),v:APP_V})}catch(e){console.warn(e);c.outcome="failed";return endCall(false,e&&e.code==="permission-denied"?"Arama kuralları eksik. Firestore kurallarını güncelle.":"Arama başlatılamadı.")}
 if(CALL!==c)return;startTone("back");
 c.unsubs.push(F.onSnapshot(ref,async s=>{if(CALL!==c)return;const d=s.exists()?s.data():null;if(!d){endCall(false);return}
  if(d.av)x.peerV=+d.av||x.peerV;
  if(d.answer&&!x.ans&&!pc.currentRemoteDescription){x.ans=true;try{await pc.setRemoteDescription(d.answer);flushCands();if(CALL===c&&c.status==="ringing"){c.status="connecting";stopTone();renderCall()}}catch(e){x.ans=false;console.warn(e)}}
  if(d.status==="declined"){c.outcome="declined";endCall(false,"Arama reddedildi.")}else if(d.status==="ended")endCall(false,"Arama bitti.")}));
 c.noAns=setTimeout(()=>{if(CALL===c&&c.status==="ringing"){c.outcome="missed";F.updateDoc(ref,{status:"missed"}).catch(()=>{});endCall(false,"Cevap yok.")}},40000)};
function ar5PrepVideo(c){const x=ar5X(c);let ts=[];try{ts=c.pc.getTransceivers()}catch{}
 const t=ts.find(t=>t.receiver&&t.receiver.track&&t.receiver.track.kind==="video"&&!t.stopped&&t.currentDirection!=="stopped");if(!t)return;x.vtx=t;
 /* izsiz video satırını gönderebilir yap: akış eşlemesi (setStreams) varsa eski arayan da sesini kaybetmez */
 if(t.direction==="recvonly"&&!t.sender.track){const ss=typeof t.sender.setStreams==="function";if(ss){try{t.sender.setStreams(c.stream)}catch{}}if(ss||x.peerV>=50000)t.direction="sendrecv"}}
acceptCall=async function(opts){const c=CALL;if(!c||c.status!=="incoming")return;const x=ar5X(c);stopTone();vibStop();c.status="connecting";c.cam=!!(c.video&&!(opts&&opts.noCam));renderCall();
 let stream;try{stream=await getMedia(c.cam)}catch(e){if(!c.cam){mediaErr(e);return declineCall()}try{stream=await getMedia(false);c.cam=false;toast("Kamera açılamadı, sesli devam ediyorsun.")}catch(e2){mediaErr(e2);return declineCall()}}
 if(CALL!==c){stream.getTracks().forEach(t=>t.stop());return}
 stream.getAudioTracks().forEach(t=>t.enabled=c.mic!==false);
 c.stream=stream;const pc=newPC(c.id);c.pc=pc;stream.getTracks().forEach(t=>pc.addTrack(t,stream));listenCands();
 try{await pc.setRemoteDescription(c.offer);ar5PrepVideo(c);flushCands();const ans=await pc.createAnswer();await pc.setLocalDescription(ans);await FB.F.updateDoc(c.ref,{answer:{type:ans.type,sdp:ans.sdp},status:"accepted",av:APP_V})}catch(e){console.warn(e);return endCall(true,"Arama bağlanamadı.")}
 renderCall()};
incomingCall=function(id,d){incomingCall47(id,d);const c=CALL;if(!c||c.id!==id)return;const x=ar5X(c);x.peerV=+(d&&d.v)||0;
 if(document.visibilityState!=="visible"){const p=P(d.from);try{sysNote(p.name+" arıyor",(d.video?"Görüntülü arama":"Sesli arama")+" · yanıtlamak için Kadraj'ı aç","call-"+id,{icon:p.avatar})}catch{}}};
callAction=async function(a){const c=CALL;if(!c||typeof a!=="string")return;const x=ar5X(c);ar5Poke(c);
 if(a==="flip"||a==="swap"||a==="spk"||a==="mini")closeLayer("callmore");
 switch(a){
  case"accept":return acceptCall();
  case"nocam":return acceptCall({noCam:true});
  case"decline":return declineCall();
  case"end":if(c.role==="caller"&&c.status==="ringing")c.outcome="canceled";ar5Send(c,{t:"bye"});return endCall(true);
  case"mic":return ar5MicToggle();
  case"cam":return ar5CamToggle();
  case"flip":return ar5Flip();
  case"share":return ar5Share();
  case"tray":x.tray=!x.tray;return renderCall();
  case"more":return ar5More();
  case"mini":return closeLayer("call");
  case"quick":return ar5Quick();
  case"qinfo":return toast(ar5QText(c));
  case"spk":return ar5Speaker();
  case"swap":x.swap=!x.swap;return renderCall()}
 if(a.startsWith("rx:"))return ar5React(a.slice(3));
 return callAction49(a)};

