/* ===== 5.0: yapay zekâ köprüsü (Cloudflare Worker → Claude API) =====
   Adres yönetici panelinden girilir ve admin/ai belgesinde durur ({url, at, by}). API anahtarı sitede yok; Worker'da gizli.
   Kullanım: kAI.ready() → bool; await kAI.ask({system, messages:[{role,content}], search}) → {text, sources, refusal}
   Hata: Error {code, message} — code: off | auth | rate_limited | timeout | network | api_key | api_billing | refusal | ... */
const kAI={
 url(){const u=((S.adm&&S.adm.ai&&S.adm.ai.url)||"").trim();return /^https:\/\/[^\s/]+(\/[^\s]*)?$/i.test(u)?u.replace(/\/+$/,""):""},
 ready(){return !!(this.url()&&S.mode==="cloud"&&FB&&FB.auth&&FB.auth.currentUser&&S.authed&&!S.guest)},
 last:null,
 err(code,message){const e=new Error(message);e.code=code;return e},
 async ask({system,messages,search=false,timeout=90000}={}){
  if(!this.ready())throw this.err("off","Yapay zekâ bağlantısı kurulmamış.");
  let tok="";try{tok=await FB.auth.currentUser.getIdToken()}catch{throw this.err("auth","Oturum doğrulanamadı, yeniden giriş yap.")}
  const ac=new AbortController();const t=setTimeout(()=>ac.abort(),timeout);let r;
  const body=JSON.stringify({system,messages,search:typeof search==="string"?search.slice(0,400):!!search});
  /* 6.8.8: ağ hatasında bir kez daha dener; yine olmazsa /health ile köprü kapalı mı yoksa soruda mı çöktü ayırt edilir */
  try{for(let i=0;;i++){try{r=await fetch(this.url()+"/ask",{method:"POST",headers:{"Content-Type":"application/json",Authorization:"Bearer "+tok},body,signal:ac.signal});break}
   catch(e){if(e&&e.name==="AbortError")throw this.err("timeout","Yanıt çok uzun sürdü.");if(i>=1){const h=await this.ping();this.last={ok:false,at:now(),code:h?"crash":"network"};throw h?this.err("crash","Köprü açık ama bu soruda hata verdi."):this.err("network","Yapay zekâ köprüsüne ulaşılamadı.")}await sleep(1500)}}}
  finally{clearTimeout(t)}
  let d=null;try{d=await r.json()}catch{}
  if(!r.ok){this.last={ok:false,at:now(),code:(d&&d.error)||String(r.status)};throw this.err((d&&d.error)||"http_"+r.status,(d&&d.message)||"Yapay zekâ yanıt vermedi.")}
  this.last={ok:true,at:now()};
  if(d&&d.refusal)return{text:"",sources:[],refusal:true};
  return{text:String((d&&d.text)||""),sources:Array.isArray(d&&d.sources)?d.sources:[],refusal:false,provider:(d&&d.provider)||"claude",model:(d&&d.model)||""}},
 async ping(){try{const ac=new AbortController(),t=setTimeout(()=>ac.abort(),8000);const r=await fetch(this.url()+"/health",{cache:"no-store",signal:ac.signal});clearTimeout(t);return r.ok}catch{return false}},
 async health(){const u=this.url();if(!u)return{ok:false,message:"Adres girilmemiş."};
  try{const r=await fetch(u+"/health");const d=await r.json();this.provider=(d&&d.provider)||"";return{ok:!!(d&&d.ok&&d.key),key:!!(d&&d.key),model:d&&d.model,provider:d&&d.provider,message:d&&d.ok?(d.key?(d.provider==="free"?"Köprü çalışıyor (ücretsiz model).":"Köprü çalışıyor (Claude)."):"Köprü çalışıyor ama ne API anahtarı ne de ücretsiz model bağlı."):"Köprü yanıt vermedi."}}
  catch{return{ok:false,message:"Köprüye ulaşılamadı. Adresi ve Worker'ın yayında olduğunu kontrol et."}}}
};
/* uygulamanın eski yapay zekâ arayüzü (S.caps.sample): Rota, fotoğraf açıklaması ve Meydan'da @rota bunu kullanır */
async function kaiBlobB64(b){const buf=new Uint8Array(await b.arrayBuffer());let s="";for(let i=0;i<buf.length;i+=32768)s+=String.fromCharCode.apply(null,buf.subarray(i,i+32768));return btoa(s)}
function kaiSample(){const f=async(prompt,opts={})=>{const content=[];
  for(const b of(opts.images||[]).slice(0,2)){try{if(b&&b.size<=1100000)content.push({type:"image",source:{type:"base64",media_type:/^image\/(jpeg|png|webp|gif)$/.test(b.type)?b.type:"image/jpeg",data:await kaiBlobB64(b)}})}catch{}}
  content.push({type:"text",text:String(prompt||"")});
  const r=await kAI.ask({messages:[{role:"user",content}],search:typeof opts.search==="string"?opts.search:!!opts.search});
  const text=r.refusal?"Bu konuda yardımcı olamıyorum.":r.text;
  if(typeof opts.onText==="function"){try{opts.onText({text})}catch{}}
  return{text}};
 f.limits=async()=>({images:true});f.kadraj=true;return f}
function kaiSync(){const on=kAI.ready();const cur=S.caps&&S.caps.sample;
 if(on&&!cur){S.caps={...(S.caps||{}),sample:kaiSample()};scheduleRefresh()}
 else if(!on&&cur&&cur.kadraj){const c={...S.caps};delete c.sample;S.caps=c;scheduleRefresh()}}
HOOKS.enter.push(()=>setTimeout(kaiSync,600));
HOOKS.after.push(()=>{if(S.authed)kaiSync()});
