 for(let y=0;y<CW_GH;y++){let x=0;while(x<CW_GW){const c=g[y][x];if(!c){x++;continue}let e=x+1;while(e<CW_GW&&g[y][e]===c)e++;r+=`<rect x="${x}" y="${y}" width="${e-x}" height="1" fill="${CW_COL[c]}"/>`;x=e}}
