/* Rota'nın ortak koddaki hazır cümleleri (chUser, geri al, ipucu, oyun sonu) Clawd'unkine çevrilir */
const CHC_MAP=[[["Şah mı? Bakalım…","Ah, şah! Düşünmem lazım.","Şah çektin, cesursun."],"checked"],[["Tamam, geri alalım.","Bir şans daha!","Peki, tekrar düşün."],"undo"],[["Bir bakayım…"],"hintq"],
 [["Berabere! Güzel mücadeleydi."],"draw"],[["Tebrikler, beni yendin!","İyi oyundu, bu sefer sen kazandın."],"lose"],[["İyi oyundu! Rövanş?","Bu sefer ben kazandım. Bir daha?"],"win"]];
function chcMap(t){for(const[a,k]of CHC_MAP)if(a.includes(t))return pick(CHC_L[k]);const m=/^Ben olsam (.+) oynardım\.$/.exec(t||"");if(m)return chFill(pick(CHC_L.hint),{san:m[1]});return t}

/* --- durum, kayıt ve puan --- */
const chNewBase51=chNew;
chNew=function(mode,o={}){const opp=mode==="bot"?(o.opp||CHC.carry||"rota"):null;const r=chNewBase51(mode,o);if(mode==="bot"&&r)r.opp=opp;return r};
const chcKey=()=>"kadraj_chess_clawd_"+S.uid;
function chcSave(){const k=chcKey();if(CH.over&&CH.rated){LS.del(k);return}const d={moves:CH.moves.map(x=>x.u),my:CH.my,level:CH.level,eval:CH.eval,flip:CH.flip,rated:!!CH.rated};
 if(clkOn()){d.tc=CH.tc.k;d.clk={0:Math.round(clkLeft(0)),8:Math.round(clkLeft(8)),run:CH.clk.run}}LS.set(k,d)}
function chcLoad(){const d=LS.get(chcKey());if(!d||!Array.isArray(d.moves))return null;chNew("bot",{my:d.my===8?8:0,level:chLvClamp(d.level),opp:"clawd"});CH.flip=!!d.flip;chReplay(d.moves);CH.eval=+d.eval||0;CH.rated=!!d.rated;
 const tc=tcParse(d.tc);if(tc&&d.clk){CH.tc=tc;CH.clk={0:Math.max(0,+d.clk[0]||0),8:Math.max(0,+d.clk[8]||0),run:d.clk.run===0||d.clk.run===8?d.clk.run:-1,at:0}}else{delete CH.tc;delete CH.clk}return CH}
const chSaveBase51=chSave;
chSave=function(...a){if(chwOn())return;if(chcOn())return chcSave();return chSaveBase51(...a)};
function chcStats(uid){const c=(S.profiles[uid]||{}).chessCw||{};return{r:c.r||800,w:c.w||0,l:c.l||0,d:c.d||0,g:c.g||0}}
async function chcRate(score){if(S.guest||!S.canWrite)return 0;const st=chcStats(S.uid);const opp=(CHC_LV[CH.level]||CHC_LV[1]).r;const exp=1/(1+Math.pow(10,(opp-st.r)/400));const K=st.g<10?40:24;const nr=Math.max(100,Math.round(st.r+K*(score-exp)));
 const c={r:nr,w:st.w+(score===1?1:0),l:st.l+(score===0?1:0),d:st.d+(score===.5?1:0),g:st.g+1};S.profiles={...S.profiles,[S.uid]:{...S.profiles[S.uid],chessCw:c}};
 write(()=>DB.update("profiles/"+S.uid,{chessCw:c}),{quiet:true});return nr-st.r}
const chRateBase51=chRate;
chRate=function(opp,score){if(CHC.rateCw&&chcOn()){CHC.rateCw=false;return chcRate(score)}return chRateBase51(opp,score)};
const chOverBase51=chOver;
chOver=async function(...a){if(chwOn())return chwEnd();if(!chcOn())return chOverBase51.apply(this,a);
 const bk="kadraj_chess_bot_"+S.uid,keep=LS.get(bk),tok=CH;let r;
 /* chRate, sarmalardan geçip eşzamanlı çağrılır; bayrak yalnızca o çağrı için açık */
 CHC.rateCw=!CH.rated;try{const p=chOverBase51.apply(this,a);CHC.rateCw=false;r=await p}finally{CHC.rateCw=false;if(keep&&!LS.get(bk))LS.set(bk,keep)}
 if(CH===tok){const sp=$("#cOv .cend>span");if(sp)sp.textContent=sp.textContent.replace("· puan ","· Clawd puanı ")}return r};

/* --- Clawd'un oyun ekranı --- */
const chcState=()=>CH.thinking?"think":(CH._talk||0)>Date.now()?"talk":"idle";
function chcPaint(){if(!chcOn())return;for(const el of $$('[data-cwav="g"]')){el.className=`cbotav cwav ${CH.mood||""}`;el.innerHTML=chcFace(46,CH.mood,chcState())}}
function chcTalk(){if(!chcOn())return;CH._talk=Date.now()+1300;chcPaint();const tok=CH;clearTimeout(CH._tt);CH._tt=setTimeout(()=>{if(CH===tok)chcPaint()},1350)}
const chBubbleBase51=chBubble;
chBubble=function(t,ms){if(chcOn())t=chcMap(t);const r=chBubbleBase51(t,ms);if(chcOn())chcTalk();return r};
const chMoodBase51=chMood;
chMood=function(m){const r=chMoodBase51(m);if(chcOn())chcPaint();return r};
function chcUserBar(side){const g=CH.g;const mat=chMaterial(chViewGame());const caps=mat.capBy(side);const adv=side===0?mat.diff:-mat.diff;const turn=!CH.over&&g.turn===side&&CH.view==null;
 return`<div class="cpl-in ${turn?"turn":""}">${avatar(S.uid,46,{click:false,ring:false})}<div class="cwho"><div><b>Sen</b> <span class="crt">${chcStats(S.uid).r}</span></div>${chTray(side,caps,adv)}</div>${clkHtml(side)}</div>`}
function chcBar(side){const g=CH.g;const mat=chMaterial(chViewGame());const caps=mat.capBy(side);const adv=side===0?mat.diff:-mat.diff;const turn=!CH.over&&g.turn===side&&CH.view==null;const L=CHC_LV[CH.level]||CHC_LV[1];
 const dots=turn&&CH.thinking?'<span class="cdots"><i></i><i></i><i></i></span>':"";
 return`<div class="cpl-in ${turn?"turn":""}"><span class="cbotav cwav ${CH.mood||""}" data-cwav="g">${chcFace(46,CH.mood,chcState())}</span><div class="cwho"><div><b>Clawd</b><span class="tag cwtag">${I("clawd")}Piksel</span> <span class="crt">${L.n} · ${L.r}</span></div>${chTray(side,caps,adv)}</div>${dots}${clkHtml(side)}</div><div class="cbub ${CH.bubble?"show":""}" id="cBub">${esc(CH.bubble||"")}</div>`}
const chPlayerBarBase51=chPlayerBar;
chPlayerBar=function(side){try{if(chwOn())return chwBar(side);if(chcOn())return side===CH.my?chcUserBar(side):chcBar(side)}catch(e){console.warn("chs51",e)}return chPlayerBarBase51(side)};
function chcSay(t,ms){if(chcOn())chBubble(t,ms)}
/* Clawd'un hamlesi (chBot'un Clawd hâli) */
async function chcBot(){if(!chcOn()||CH.over||CH.g.turn===CH.my||CH.thinking)return;const tok=CH;CH.thinking=true;chUI();const L=CHC_LV[CH.level]||CHC_LV[1];const t0=Date.now();
 const before=CH.my===0?CH.eval:-CH.eval;let r;
 try{r=await chPickMove(L,CC.toFen(CH.g),CH.keys,L.agg)}catch(e){console.warn("chs51",e);r={u:null}}
 await sleep(Math.max(0,(L.all?700:320)+Math.random()*600-(Date.now()-t0)));
 if(CH!==tok||CH.over||CH.g.turn===CH.my){if(CH===tok){CH.thinking=false;chUI()}return}
 CH.thinking=false;const u=r.u,score=r.score;const m=u&&CC.fromUci(CH.g,u);if(!m){chUI();return}
 const after=-r.top;let said=false;const pm=CH.moves[CH.moves.length-1];
 if(pm&&CH.moves.length>2&&Math.abs(before)<CC.MATE-1000&&Math.abs(after)<CC.MATE-1000){const d=after-before;
  if(d<-260){pm.q="??";chMood("happy");chcSay(pick(CHC_L.blunder));said=true}
  else if(d<-120){pm.q="?";chcSay(pick(CHC_L.mistake));said=true}
  else if(d>180){pm.q="!";chMood("sad");chcSay(pick(CHC_L.good));said=true}}
 else if(pm&&after>CC.MATE-1000&&before<CC.MATE-1000){pm.q="!!";chMood("sad");chcSay(pick(CHC_L.mateSeen));said=true}
 if(CH.view!=null){CH.view=null;chDraw()}const st=chApply(m);chAnim(m);chSoundFor(m,st);chMarks();
 CH.eval=(CH.my^8)===0?score:-score;
 if(!said){if(st.check)chcSay(pick(CHC_L.check));else if(m.c&&((m.c&7)>=3||Math.random()<.35))chcSay(chFill(pick(CHC_L.cap),{p:PNAME[m.c&7]}));else if(m.fl&2)chcSay(pick(CHC_L.castle));else if(m.pr)chcSay(pick(CHC_L.promo));else if(CH.moves.length<=2)chcSay(pick(CHC_L.open));else if(Math.random()<.18)chcSay(pick(CHC_L.idle),4800)}
 if(!CH.over)chMood(score>CC.MATE-1000||score>260?"happy":score<-260?"sad":(st.check?"":CH.mood==="surp"?"":CH.mood));
 chUI();chSave();if(CH.over)setTimeout(chOver,400)}
const chBotBase51=chBot;
chBot=function(...a){if(chcOn())return chcBot();if(chwOn())return;return chBotBase51(...a)};
function chcStart(){const lv=chcLv();let col=settings.chessColor||"w";if(col==="r")col=Math.random()<.5?"w":"b";
 chNew("bot",{my:col==="b"?8:0,level:lv,opp:"clawd"});chSave();chOpen();
 setTimeout(()=>{if(!chcOn())return;chcSay(chFill(pick(CHC_L.start),{lv:CHC_LV[lv].n}));if(CH.my===8)setTimeout(chBot,500)},350)}
function chcUI(){const mv=$("#cMoves");if(mv&&!CH.moves.length){const s=mv.querySelector(".muted");if(s)s.textContent="İlk hamle "+(CH.my===0?"senden":"Clawd'dan")}}

/* --- paylaşım resmi (Clawd ve izleme) --- */
async function chcShareRaw(){if(!guard())return;const W=1080;const cv=document.createElement("canvas");cv.width=W;cv.height=1350;const x=cv.getContext("2d");const th=CTHEMES[settings.board||"kadraj"]||CTHEMES.kadraj;const z=W/8;const g=CH.g;
 x.fillStyle="#0f1f1a";x.fillRect(0,0,W,1350);for(let r=0;r<8;r++)for(let f=0;f<8;f++){x.fillStyle=(r+f)%2?th[1]:th[0];x.fillRect(f*z,r*z,z,z)}
 if(CH.last){x.fillStyle="rgba(255,214,10,.42)";for(const s of[CH.last.f,CH.last.t]){const[a,b]=sqXY(s);x.fillRect(a*z,b*z,z,z)}}
 try{const imgs={};for(let s=0;s<64;s++){const p=g.b[s];if(!p)continue;imgs[p]=imgs[p]||await loadImg(PIMG[p]);const[a,b]=sqXY(s);x.drawImage(imgs[p],a*z+4,b*z+4,z-8,z-8)}cv.toDataURL("image/jpeg",.5)}
 catch{for(let s=0;s<64;s++){const p=g.b[s];if(!p)continue;const[a,b]=sqXY(s);x.fillStyle=p&8?"#26332e":"#fbfaf5";x.beginPath();x.arc(a*z+z/2,b*z+z/2,z*.36,0,7);x.fill();x.fillStyle=p&8?"#fff":"#111";x.font=`700 ${z*.38}px sans-serif`;x.textAlign="center";x.textBaseline="middle";x.fillText(" PAFKVŞ"[p&7],a*z+z/2,b*z+z/2)}}
 const res=CH.over?CH.over.result:null;const n=Math.ceil(CH.moves.length/2);let line,cap;
 if(chwOn()){const cWin=!!res&&res!=="1/2"&&((res==="1-0")===(CH.wv.cw===0));const s=chwScore();
  line=!res?"Clawd – Rota":res==="1/2"?"Clawd ile Rota berabere":cWin?"Clawd, Rota'yı yendi":"Rota, Clawd'u yendi";
  cap=!res?"Clawd ile Rota'nın satranç maçını izliyorum. #satranç":`${line}! ${n} hamle sürdü. Skor: Clawd ${s.c} – ${s.r} Rota. #satranç`}
 else{const myWin=res&&((res==="1-0"&&CH.my===0)||(res==="0-1"&&CH.my===8));const opp=`Clawd (${(CHC_LV[CH.level]||CHC_LV[1]).n})`;
  line=!res?"Kadraj satranç":res==="1/2"?`${opp} ile berabere`:myWin?`${opp} karşısında galibiyet`:`${opp} karşısında mağlubiyet`;
  cap=!res?"Kadraj'da Clawd'la satranç oynuyorum. #satranç":res==="1/2"?`${opp} ile berabere kaldık. #satranç`:myWin?`${opp} karşısında kazandım! ${n} hamle sürdü. #satranç`:`${opp} bu sefer kazandı, rövanş yakında. #satranç`}
 x.fillStyle="#fff";x.font="700 60px Unbounded, 'Avenir Next', sans-serif";x.textAlign="center";x.textBaseline="middle";x.fillText(line,W/2,W+105,W-100);x.fillStyle="#ff9a6b";x.font="600 38px 'Avenir Next', sans-serif";x.fillText(`${n} hamle · ${REASON[CH.over?.reason]||"oyun sürüyor"} · kadraj`,W/2,W+185,W-100);
 S.cmp={kind:"photo",filter:0,ar:"4/5",slides:[],fx:"zoom",music:"lofi",text:"",bg:0,options:["",""],mode:"slides",img:cv,caption:cap,loc:""};drawComposer()}
const chShareBase51=chShare;
chShare=async function(...a){if(!chcOn()&&!chwOn())return chShareBase51(...a);if(chPsKey()==="klasik")return chcShareRaw();const keep={...PIMG};Object.assign(PIMG,PSETS[chPsKey()].img);try{return await chcShareRaw()}finally{Object.assign(PIMG,keep)}};

