/* ---------- 2 · Rozetler ---------- */
const RZ=[
 {id:"kurucu",t:"Kurucu",d:"Kadraj'ı kuran ve geliştiren kişi.",ic:"rzcrown",c:"#C99A06",man:1},
 {id:"onayli",t:"Onaylı",d:"Kimliği yönetici tarafından onaylanan hesap.",ic:"check",c:"#1D9BF0"},
 {id:"ilk",t:"İlk kullanıcı",d:()=>`Kadraj'a katılan ilk ${rzIlkN()} kişiden biri.`,ic:"rzseed",c:"#0C7A63",man:1,auto:1},
 {id:"destek",t:"Destekleyen",d:"Kadraj'a destek olan, büyümesine katkı veren kişi. Yönetici verir.",ic:"heart",c:"#E11D48",man:1},
 {id:"satranc",t:"Satranç ustası",d:"Kadraj Satrancı'nda 1500 puanı geçen oyuncu (en az 10 oyun).",ic:"knight",c:"#475569",man:1,auto:1},
 {id:"klaket",t:"Klaket yıldızı",d:"Klaketleri toplamda 25'ten fazla beğeni alan kişi.",ic:"rzclap",c:"#DB2777",man:1,auto:1},
 {id:"uretken",t:"Üretken",d:"20 ya da daha fazla paylaşım yapan kişi.",ic:"spark",c:"#7C3AED",man:1,auto:1}];
const RZM=Object.fromEntries(RZ.map(b=>[b.id,b]));
const rzDesc=b=>typeof b.d==="function"?b.d():b.d;
const rzIlkN=()=>{const n=+k51Doc("rozet").ilkN;return n>0&&n<=1000?n:50};
const rzManual=()=>{const l=k51Doc("rozet").list;return l&&typeof l==="object"?l:{}};
let RZC=null;
function rzCache(){const c=RZC;if(c&&c.p===S.profiles&&c.po===S.posts&&c.me===S.meta&&c.a===S.adm)return c;
 const users=Object.values(S.profiles).filter(p=>p&&p.uid&&!String(p.uid).startsWith("bot:")&&p.createdAt).sort((a,b)=>a.createdAt-b.createdAt);
 const early=new Set(users.slice(0,rzIlkN()).map(p=>p.uid));const st={};
 for(const p of Object.values(S.posts||{})){if(!p||!p.uid)continue;const x=st[p.uid]||(st[p.uid]={n:0,rl:0});x.n++;if(p.kind==="reel"){const lk=((S.meta||{})[p.id]||{}).likes||{};for(const v of Object.values(lk))if(v)x.rl++}}
 return RZC={p:S.profiles,po:S.posts,me:S.meta,a:S.adm,early,st,m:new Map()}}
function rzOf(uid){if(!uid||BOT[uid])return[];const c=rzCache();if(c.m.has(uid))return c.m.get(uid);
 const p=S.profiles[uid];const out=new Set((Array.isArray(rzManual()[uid])?rzManual()[uid]:[]).filter(x=>RZM[x]&&x!=="onayli"));
 if(p&&String(p.username||"").toLowerCase()===K51_OWNER)out.add("kurucu");
 if(isVerified(uid))out.add("onayli");
 if(c.early.has(uid))out.add("ilk");
 if(p&&p.chess&&(+p.chess.r||0)>=1500&&(+p.chess.g||0)>=10)out.add("satranc");
 const s=c.st[uid];if(s){if(s.rl>25)out.add("klaket");if(s.n>=20)out.add("uretken")}
 const arr=RZ.map(b=>b.id).filter(id=>out.has(id));c.m.set(uid,arr);return arr}
const rzAuto=(uid,id)=>{const b=RZM[id];if(!b)return false;if(id==="onayli")return false;const man=(rzManual()[uid]||[]).includes(id);return!man};
const rzIc=(id,cls="")=>{const b=RZM[id];return b?`<i class="rz${cls?" "+cls:""}" style="--c:${b.c}">${I(b.ic)}</i>`:""};
const badgeOld51=badge;
badge=function(uid){const base=badgeOld51(uid);try{if(!uid||BOT[uid])return base;const ids=rzOf(uid).filter(x=>x!=="onayli");if(!ids.length)return base;
 const show=ids.slice(0,2),more=ids.length-show.length;const names=ids.map(x=>RZM[x].t).join(", ");
 return base+`<span class="rzs" data-rzu="${esc(uid)}" title="${esc(names)}" aria-label="Rozetler: ${esc(names)}">${show.map(x=>rzIc(x)).join("")}${more>0?`<i class="rzm">+${more}</i>`:""}</span>`}catch(e){console.warn("rozet",e);return base}};
function rzStrip(uid){const ids=rzOf(uid);if(!ids.length)return"";
 return`<div class="rzstrip" role="list" aria-label="Rozetler">${ids.map(id=>`<button type="button" class="rzchip" role="listitem" data-rzu="${esc(uid)}" style="--c:${RZM[id].c}">${rzIc(id)}<span>${esc(RZM[id].t)}</span></button>`).join("")}</div>`}
function rzSheet(uid){const p=P(uid);const ids=rzOf(uid);const rest=RZ.filter(b=>!ids.includes(b.id));
 const row=(b,on)=>`<div class="rzrow${on?"":" off"}">${rzIc(b.id,"lg")}<div class="t"><b>${esc(b.t)}${on&&b.id!=="onayli"?`<small>${rzAuto(uid,b.id)&&b.auto?"otomatik":b.id==="kurucu"&&rzAuto(uid,b.id)?"kurucu hesap":"yönetici verdi"}</small>`:""}</b><span>${esc(rzDesc(b))}</span></div></div>`;
 sheet("rz",ids.length?`@${p.username} rozetleri`:"Rozetler",`<div class="rzsh">${ids.length?ids.map(id=>row(RZM[id],true)).join(""):`<p class="muted rznone">@${esc(p.username)} henüz rozet kazanmadı.</p>`}
 ${rest.length?`<div class="adm5-sub rzsub">Diğer rozetler</div>${rest.map(b=>row(b,false)).join("")}`:""}
 ${S.admin&&!BOT[uid]?`<button class="opt" data-act="k51rzedit" data-u="${esc(uid)}">${I("edit")}Yönetici: rozetleri düzenle</button>`:""}</div>`)}
ACT.k51rzedit=(t)=>{closeLayer("rz");admRozetSheet(t.dataset.u)};
/* rozete dokununca açıklama (satır/profil düğmesine gitmeden) */
document.addEventListener("click",e=>{const b=e.target&&e.target.closest&&e.target.closest("[data-rzu]");if(!b)return;e.preventDefault();e.stopPropagation();vib(6);rzSheet(b.dataset.rzu)},true);
const vProfile51=vProfile;
vProfile=function(uid){const h=vProfile51.apply(this,arguments);try{const s=rzStrip(uid);if(!s)return h;const i=h.indexOf('<b style="font:600 1.05rem/1.3 var(--f-display)">');const j=i<0?-1:h.indexOf("</div>",i);if(j<0)return h;return h.slice(0,j+6)+s+h.slice(j+6)}catch(e){console.warn("rozet",e);return h}};
const renderComments51=renderComments;
renderComments=function(...a){const r=renderComments51.apply(this,a);try{for(const b of $$("#cmtList .cmt .t>button[data-prof]")){if(b.nextElementSibling&&b.nextElementSibling.matches(".rzs,.vbadge,.tag"))continue;const h=badge(b.dataset.prof);if(h)b.insertAdjacentHTML("afterend",h)}}catch(e){console.warn("rozet",e)}return r};
/* kurucu hesabın kimliği rozet belgesine bir kez yazılır (kullanıcı adı değişse de kalır) */
function rzOwnerSync(){if(!S.admin||!S.uid||S._rzOwn)return;const p=S.profiles[S.uid];if(!p||String(p.username||"").toLowerCase()!==K51_OWNER)return;if(!S.adm||S.admRulesOk===false)return;
 const l=rzManual();if((l[S.uid]||[]).includes("kurucu")){S._rzOwn=1;return}S._rzOwn=1;const d=k51Doc("rozet");
 admSet("rozet",{...d,list:{...l,[S.uid]:[...new Set([...(l[S.uid]||[]),"kurucu"])]},at:now()}).catch(()=>{})}

/* ---------- 3 · Askıya alma, susturma dışı kısıtlar ---------- */
const k51SusOf=uid=>{const l=k51Doc("askiya").list;const s=l&&l[uid];return s&&s.until>now()?s:null};
function k51SusHtml(){const s=k51SusOf(S.uid)||{};const inf=s.until>now()+3650*24*H;
 return`<div class="empty k51sus"><span class="ic">${I("k51susp")}</span><b>Hesabın geçici olarak askıda</b><span>${inf?"Yönetici hesabını süresiz askıya aldı.":`Askı ${esc(k51When(s.until))} tarihinde kendiliğinden kalkar (${esc(k51Left(s.until))} kaldı).`}</span>${s.reason?`<p class="k51sus-r"><small>Sebep</small>${esc(s.reason)}</p>`:""}<span class="muted k51sus-n">Bu sürede paylaşım yapamaz, mesaj gönderemez ve Kadraj'ı gezemezsin.</span><div class="k51sus-b"><button class="btn sec" data-go="settings">${I("gear")}Ayarlar</button><button class="btn ghost" data-act="logout">${I("logout")}Çıkış yap</button></div></div>`}
