/* ---------- 6 · Kurallar ---------- */
const rulesText51=rulesText;
rulesText=function(ids=[]){let t=rulesText51(ids);
 const a="allow create, update: if girdi() && request.auth.uid == uid; allow delete: if girdi() && (request.auth.uid == uid || yonetici()); }";
 if(t.includes(a))t=t.replace(a,"allow create: if girdi() && request.auth.uid == uid; allow update: if girdi() && (request.auth.uid == uid || yonetici()); allow delete: if girdi() && (request.auth.uid == uid || yonetici()); }");
 const b="    match /admin/{id} {";if(t.includes(b)&&!t.includes("match /acik/"))t=t.replace(b,"    match /acik/{id} { allow get: if true; allow list: if false; allow write: if yonetici(); }\n"+b);
 return t};

/* ---------- 7 · Profil düzeltme kuyruğu: kişinin kendi cihazı uygular ---------- */
function duzeltApply(){if(!S.authed||!S.uid||S.guest)return;const l=k51Doc("duzelt").list;const e=l&&l[S.uid];const p=S.profiles[S.uid];if(!e||!e.at||!p)return;
 if((p.fixAt||0)>=e.at||S._dzAt===e.at)return;S._dzAt=e.at;const patch={fixAt:e.at};
 if(typeof e.name==="string"&&e.name.trim())patch.name=e.name.trim().slice(0,40);if(e.avatar)patch.avatar=null;if(e.bio)patch.bio="";if(e.note)patch.note=null;
 write(()=>DB.update("profiles/"+S.uid,patch),{quiet:true}).then(ok=>{if(ok){S.profiles={...S.profiles,[S.uid]:{...S.profiles[S.uid],...patch}};scheduleRefresh()}})}

