/* ---------- 8 · Keşfet'ten gizleme ---------- */
const k51Hidden=()=>{const l=k51Doc("gizle").list;return l&&typeof l==="object"?l:{}};
const k51IsHid=id=>!!k51Hidden()[id];
const srCtx51=srCtx;
srCtx=function(){const c=srCtx51();try{const hid=k51Hidden();if(!Object.keys(hid).length)return c;const posts=c.posts.filter(p=>!hid[p.id]);
 for(const[t,e]of[...c.idx]){e.ps=e.ps.filter(p=>!hid[p.id]);e.n=e.ps.length;if(!e.n)c.idx.delete(t);else e.at=Math.max(0,...e.ps.map(p=>p.at||0))}return{...c,posts}}catch(e){console.warn(e);return c}};
async function k51HideToggle(pid){const l={...k51Hidden()};const p=postById(pid);const un=p?k51Un(p.uid)+" ":"";const on=!l[pid];if(on)l[pid]=now();else delete l[pid];
 for(const k of Object.keys(l))if(!S.posts[k]&&k!==pid&&now()-l[k]>30*24*H)delete l[k];
 if(await admSet("gizle",{list:l})){S.adm={...(S.adm||{}),gizle:{list:l}};admLog(`${un}paylaşımı Keşfet'ten ${on?"gizlendi":"yeniden gösterildi"}`,"icerik");toast(on?"Keşfet'ten gizlendi":"Keşfet'te yeniden görünüyor");return true}return false}
const postMenu51=postMenu;
postMenu=function(id,...r){const out=postMenu51.call(this,id,...r);try{if(!S.admin||!S.posts[id])return out;const l=$('#overlay [data-layer="menu"]');if(!l)return out;const anc=$("#mPin",l);if(!anc)return out;
 anc.insertAdjacentHTML("afterend",`<button class="opt" id="mK51H">${I("k51eyeoff")}${k51IsHid(id)?"Yönetici: Keşfet'te yeniden göster":"Yönetici: Keşfet'ten gizle"}</button>`);
 $("#mK51H",l).onclick=()=>{closeLayer("menu");k51HideToggle(id).then(ok=>{if(ok)render(false)})}}catch(e){console.warn(e)}return out};

/* ---------- 9 · İşlem kaydı: 100 kayıt, tür etiketi ---------- */
admLog=function(text,kind){if(!S.admin)return;const items=[{t:now(),x:String(text||"").slice(0,220),by:S.uid,...(kind?{k:String(kind).slice(0,12)}:{})},...admLogItems()].slice(0,100);
 S.adm={...(S.adm||{}),log:{items}};DB.set("admin/log",{items,at:now(),by:S.uid}).catch(()=>{})};
const K51_LK=[["all","Tümü"],["kullanici","Kullanıcı"],["icerik","İçerik"],["duyuru","Duyuru"],["sistem","Sistem"]];
function k51LogKind(x){if(x.k)return x.k;const s=String(x.x||"");if(/duyuru/i.test(s))return"duyuru";if(/paylaşım|hikâye|klaket|flick|öne çıkar|keşfet/i.test(s))return"icerik";if(/bakım|meydan|tema|anahtar|kural|kayıt|bot/i.test(s))return"sistem";if(/@/.test(s))return"kullanici";return"sistem"}
function k51LogRows(){const q=kbFold((S.k51LogQ||"").trim());const f=S.k51LogF||"all";const lg=admLogItems().filter(x=>(f==="all"||k51LogKind(x)===f)&&(!q||kbFold(String(x.x||"")+" "+(x.by?P(x.by).username:"")).includes(q)));
 if(!lg.length)return`<p class="adm5-note">${admLogItems().length?"Bu aramaya uyan kayıt yok.":"Henüz kayıtlı işlem yok."}</p>`;
 const day=t=>{const d=new Date(t);d.setHours(0,0,0,0);const t0=new Date();t0.setHours(0,0,0,0);const df=Math.round((t0-d)/864e5);return df===0?"Bugün":df===1?"Dün":d.toLocaleDateString("tr-TR",{day:"numeric",month:"long",year:"numeric"})};
 let cur="",h="";for(const x of lg){const dy=day(x.t);if(dy!==cur){cur=dy;h+=`<div class="adm5-sub k51lgday">${esc(dy)}</div>`}
  h+=`<div class="adm5-lg k51lg k-${esc(k51LogKind(x))}"><i></i><div class="t"><div>${esc(x.x||"")}</div><div class="s">${new Date(x.t).toLocaleTimeString("tr-TR",{hour:"2-digit",minute:"2-digit"})}${x.by&&x.by!==S.uid?" · "+esc(k51Un(x.by)):""}</div></div></div>`}
 return`<div class="adm5-list k51lgl">${h}</div>`}
function k51KayitHtml(){const f=S.k51LogF||"all";return`<div class="search adm5-uq"><input class="in" id="k51LogQ" type="search" placeholder="Kayıtlarda ara" value="${esc(S.k51LogQ||"")}" autocomplete="off" aria-label="İşlem kaydında ara"></div>
 <div class="adm5-fl" role="group" aria-label="Tür">${K51_LK.map(([k,l])=>`<button type="button" class="chip" data-adm="k51lf" data-v="${k}" aria-pressed="${f===k}">${l}</button>`).join("")}</div><div id="k51LgB">${k51LogRows()}</div>`}
function k51KayitWire(el){const q=$("#k51LogQ",el);if(q)q.oninput=()=>{S.k51LogQ=q.value;clearTimeout(q._t);q._t=setTimeout(()=>{const b=$("#k51LgB");if(b)b.innerHTML=k51LogRows()},120)}}

