/* Duyuru: seviye, başlık, süre ve canlı önizleme */
const k51AnD=()=>S.k51AnD||(S.k51AnD={title:"",lv:"bilgi",ex:0});
function k51DuyuruHtml(){const a=S.adm&&S.adm.duyuru;const live=annCur();const d=k51AnD();const txt=S.admAnnDraft||"";
 const expired=a&&a.text&&a.until&&a.until<=now();
 const cur=a&&a.text&&String(a.text).trim()?`<div class="adm5-sub">Yayındaki duyuru</div><div class="k51ann lv-${annLv(a)} preview${expired?" dim":""}">${annBarHtml(a,{preview:true})}</div>
  <div class="adm5-row"><small class="adm5-note">${expired?"Süresi doldu, kimse görmüyor":"Herkes görüyor"} · ${admAgo(a.at)} yayınlandı${a.by&&a.by!==S.uid?" · "+esc(k51Un(a.by)):""}</small><button type="button" class="btn sm sec" data-adm="annx">Kaldır</button></div>`:`<p class="adm5-note">Şu an yayında duyuru yok. Duyuru her ekranın üstünde şerit olarak görünür; herkes kendi cihazında kapatabilir.</p>`;
 return`${cur}<div class="adm5-sub">${live?"Yeni duyuru":"Duyuru yaz"}</div>
 <div class="field"><label for="k51AnT">Başlık (isteğe bağlı)</label><input class="in" id="k51AnT" maxlength="50" placeholder="Yönetici duyurusu" value="${esc(d.title)}"></div>
 <div class="field"><label for="admAnn">Metin</label><textarea class="in" id="admAnn" maxlength="300" rows="3" placeholder="Herkesin her ekranda göreceği duyuru…">${esc(txt)}</textarea></div>
 <div class="k51f"><span class="k51fl">Seviye</span><div class="seg k51seg" role="group" aria-label="Seviye">${Object.entries(ANN_LV).map(([k,v])=>`<button type="button" data-k51lv="${k}" aria-pressed="${d.lv===k}">${v.t}</button>`).join("")}</div></div>
 <div class="k51f"><span class="k51fl">Süre</span><div class="seg k51seg" role="group" aria-label="Süre">${ANN_EX.map(([v,l])=>`<button type="button" data-k51ex="${v}" aria-pressed="${d.ex===v}">${l}</button>`).join("")}</div></div>
 <div class="adm5-sub">Önizleme</div><div class="k51ann lv-${d.lv} preview" id="k51AnPv" aria-live="polite">${annBarHtml({text:txt,title:d.title,level:d.lv,until:d.ex?now()+d.ex:0},{preview:true})}</div>
 <div class="adm5-row"><small class="adm5-cnt" id="admAnnN">${txt.length}/300</small><button type="button" class="btn sm" data-adm="ann">${I("send")}Yayınla</button></div>`}
function k51DuyuruWire(el){const ta=$("#admAnn",el),ti=$("#k51AnT",el),n=$("#admAnnN",el),pv=$("#k51AnPv",el);if(!ta)return;const d=k51AnD();
 const paint=()=>{if(pv){pv.className=`k51ann lv-${d.lv} preview`;pv.innerHTML=annBarHtml({text:ta.value,title:d.title,level:d.lv,until:d.ex?now()+d.ex:0},{preview:true})}};
 ta.oninput=()=>{S.admAnnDraft=ta.value;if(n)n.textContent=ta.value.length+"/300";paint()};if(ti)ti.oninput=()=>{d.title=ti.value;paint()};
 $$("[data-k51lv]",el).forEach(b=>b.onclick=()=>{d.lv=b.dataset.k51lv;$$("[data-k51lv]",el).forEach(x=>x.setAttribute("aria-pressed",x===b));paint()});
 $$("[data-k51ex]",el).forEach(b=>b.onclick=()=>{d.ex=+b.dataset.k51ex;$$("[data-k51ex]",el).forEach(x=>x.setAttribute("aria-pressed",x===b));paint()})}
{const s=admSecById("duyuru");if(s){s.desc="Her ekranda şerit; seviye, süre, önizleme";s.html=k51DuyuruHtml;s.wire=k51DuyuruWire;
 s.count=()=>{const a=S.adm&&S.adm.duyuru;if(!(a&&a.text&&String(a.text).trim()))return{t:"Yok",c:"dim"};if(a.until&&a.until<=now())return{t:"Süresi doldu",c:"dim"};return{t:ANN_LV[annLv(a)].t,c:annLv(a)==="bilgi"?"on":"hot"}}}}
/* İçerik: seçip toplu silme, Keşfet'ten gizleme, tür süzgeci */
const K51_KF=[["all","Hepsi"],["photo","Fotoğraf"],["reel","Klaket"],["note","Not"],["poll","Anket"]];
const k51Kind=p=>({reel:"Klaket",photo:"Fotoğraf",note:"Not",poll:"Anket"}[p.kind]||"Paylaşım");
function k51IcerikHtml(){const pin=pinnedId();const pp=pin&&postById(pin);const kf=S.k51KF||"all";const sel=S.k51Sel||(S.k51Sel=new Set());const sm=!!S.k51SM;
 const all=Object.values(S.posts).filter(p=>S.profiles[p.uid]).sort((a,b)=>(b.at||0)-(a.at||0));const posts=all.filter(p=>kf==="all"||p.kind===kf);
 for(const id of[...sel])if(!S.posts[id])sel.delete(id);const hid=k51Hidden();
 const row=p=>{const th=postThumb(p);const on=pin===p.id;const h=!!hid[p.id];const ck=sel.has(p.id);const cap=String(p.caption||p.text||p.question||"").replace(/\s+/g," ").slice(0,70)||k51Kind(p);
  return`<div class="adm5-pr k51pr${ck?" sel":""}">${sm?`<button type="button" class="k51ck" data-adm="k51sel" data-u="${esc(p.id)}" aria-pressed="${ck}" aria-label="Seç">${I("check")}</button>`:""}<button type="button" class="adm-th" data-open="${esc(p.id)}" aria-label="Paylaşımı aç">${th?`<img src="${esc(th)}" alt="">`:I(p.kind==="poll"?"poll":"type")}</button><div class="t"><div><b>${esc(k51Un(p.uid))}</b>${on?'<span class="tag">öne çıkan</span>':""}${h?'<span class="tag k51hid">Keşfet\'te gizli</span>':""}</div><div class="s">${esc(cap)} · ${admAgo(p.at)}</div></div>${sm?"":`<button type="button" class="ib${on?" on":""}" data-adm="pin" data-u="${esc(p.id)}" aria-pressed="${on}" aria-label="${on?"Öne çıkarmayı kaldır":"Akış'ta öne çıkar"}">${I("spark")}</button><button type="button" class="ib${h?" on":""}" data-adm="k51hid" data-u="${esc(p.id)}" aria-pressed="${h}" aria-label="${h?"Keşfet'te yeniden göster":"Keşfet'ten gizle"}">${I("k51eyeoff")}</button><button type="button" class="ib" data-adm="postdel" data-u="${esc(p.id)}" aria-label="Paylaşımı kaldır">${I("trash")}</button>`}</div>`};
 let h=`<div class="adm5-sub">Öne çıkan</div>`;
 if(pp)h+=`<div class="adm5-list">${row(pp)}</div>`;else if(pin)h+=`<div class="adm5-empty">${I("info")}<span><b>Öne çıkan paylaşım silinmiş.</b><small>Akış'ta görünmüyor; kaydı temizleyebilirsin.</small></span><button type="button" class="btn sm sec" data-adm="unpin">Temizle</button></div>`;
 else h+=`<p class="adm5-note">Öne çıkan paylaşım yok. Listede ${I("spark")} ile bir paylaşımı Akış'ın en üstüne taşı; ${I("k51eyeoff")} ile Keşfet'ten gizle.</p>`;
 const lim=S.k51PN||30;
 h+=`<div class="adm5-row k51ph"><div class="adm5-sub" style="margin:0">Son paylaşımlar · ${fmt(posts.length)}</div><button type="button" class="btn sm ${sm?"":"sec"}" data-adm="k51sm" aria-pressed="${sm}">${I(sm?"close":"check")}${sm?"Seçimi bitir":"Seç"}</button></div>
 <div class="adm5-fl" role="group" aria-label="Tür">${K51_KF.map(([k,l])=>`<button type="button" class="chip" data-adm="k51kf" data-v="${k}" aria-pressed="${kf===k}">${l}<span>${k==="all"?all.length:all.filter(p=>p.kind===k).length}</span></button>`).join("")}</div>`;
 if(sm)h+=`<div class="k51bulk" role="group" aria-label="Toplu işlem"><span><b>${fmt(sel.size)}</b> seçili</span><button type="button" class="btn sm sec" data-adm="k51selall">${posts.slice(0,lim).every(p=>sel.has(p.id))&&posts.length?"Seçimi temizle":"Görünenleri seç"}</button><button type="button" class="btn sm sec" data-adm="k51bhide"${sel.size?"":" disabled"}>${I("k51eyeoff")}Gizle</button><button type="button" class="btn sm adm5-del" data-adm="k51bdel"${sel.size?"":" disabled"}>${I("trash")}Sil</button></div>`;
 h+=posts.length?`<div class="adm5-list">${posts.slice(0,lim).map(row).join("")}</div>${posts.length>lim?`<button type="button" class="btn sec sm block" data-adm="k51pmore">${fmt(posts.length-lim)} paylaşım daha</button>`:""}`:`<p class="adm5-note">Bu türde paylaşım yok.</p>`;
 const hl=Object.keys(hid).filter(id=>S.posts[id]);
 if(hl.length)h+=`<div class="adm5-sub">Keşfet'ten gizlenenler · ${hl.length}</div><p class="adm5-note">Bu paylaşımlar Keşfet'te ve #etiket sayfalarında görünmez; sahibinin profilinde ve takipçilerinin Akış'ında durur.</p>`;
 h+=`<div class="adm5-sub">Temizlik</div><div class="adm5-set"><button type="button" class="srow" data-adm="meydanclr">${I("globe")}<span class="t">Meydan'ı temizle<small>Ortak sohbetteki tüm mesajlar herkes için silinir</small></span></button><button type="button" class="srow" data-adm="storyclr">${I("eye")}<span class="t">Eski hikâyeleri temizle<small>24 saati geçmiş hikâyeleri veritabanından siler</small></span></button></div>`;
 return h}
