/* silme: hata sayılır, öne çıkan ve şikayetler de temizlenir */
async function k51DelPosts(ids){let k=0,f=0;let unpin=false;
 for(const id of ids){const p=S.posts[id];if(!p)continue;try{await DB.del("posts/"+id)}catch(e){f++;continue}DB.del("meta/"+id).catch(()=>{});
  if(p.video&&String(p.video).startsWith("chunk:")){const[,vid,c]=String(p.video).split(":");for(let i=0;i<+c;i++)DB.del(`vchunks/${vid}-${i}`).catch(()=>{})}
  const ps={...S.posts};delete ps[id];S.posts=ps;k++;if(pinnedId()===id)unpin=true;if((S.reports||[]).some(r=>r.pid===id))await admRepClear(id).catch(()=>0)}
 if(unpin)await admSet("pin",{pid:null});if(S.k51Sel)for(const id of ids)if(!S.posts[id])S.k51Sel.delete(id);return{k,f}}
/* İstatistik */
function k51Days(n){const d0=new Date();d0.setHours(0,0,0,0);const out=[];for(let i=n-1;i>=0;i--){const s=new Date(d0);s.setDate(d0.getDate()-i);const e=new Date(s);e.setDate(s.getDate()+1);out.push({s:s.getTime(),e:e.getTime(),n:0})}return out}
function k51Bucket(ts,n=14){const ds=k51Days(n);for(const t of ts){if(!t)continue;for(const d of ds)if(t>=d.s&&t<d.e){d.n++;break}}return ds}
function k51Spark(ds,label){const max=Math.max(1,...ds.map(d=>d.n));const W=10,G=2,HH=40;const tot=ds.reduce((a,d)=>a+d.n,0);const fd=t=>new Date(t).toLocaleDateString("tr-TR",{day:"numeric",month:"short"});
 const bars=ds.map((d,i)=>{const h=d.n?Math.max(3,d.n/max*(HH-2)):1.5;const x=i*(W+G);return`<g><rect class="hit" x="${x-1}" y="0" width="${W+G}" height="${HH}"/><rect class="b${d.n?"":" z"}${i===ds.length-1?" now":""}" x="${x}" y="${HH-h}" width="${W}" height="${h}" rx="${d.n?2:.75}"/><title>${fd(d.s)}: ${d.n} ${label}</title></g>`}).join("");
 return`<div class="k51sp"><div class="k51sph"><b>${fmt(tot)}</b><span>${esc(label)} · 14 gün</span><em>bugün ${fmt(ds[ds.length-1].n)}</em></div><svg viewBox="0 0 ${ds.length*(W+G)-G} ${HH}" preserveAspectRatio="none" role="img" aria-label="${esc(label)}: son 14 günde ${tot}, bugün ${ds[ds.length-1].n}">${bars}</svg><div class="k51spx" aria-hidden="true"><span>${fd(ds[0].s)}</span><span>bugün</span></div></div>`}
function k51Active(days=7){const lim=now()-days*24*H;const sc={};const add=(u,k)=>{if(!u||BOT[u]||!S.profiles[u])return;const x=sc[u]||(sc[u]={p:0,c:0,l:0});x[k]++};
 for(const p of Object.values(S.posts||{}))if((p.at||0)>lim)add(p.uid,"p");
 for(const m of Object.values(S.meta||{})){for(const c of Object.values((m&&m.comments)||{}))if(c&&(c.at||0)>lim)add(c.uid,"c");for(const[u,t]of Object.entries((m&&m.likes)||{}))if(t&&t>lim)add(u,"l")}
 return Object.entries(sc).map(([u,x])=>({u,...x,s:x.p*5+x.c*2+x.l})).sort((a,b)=>b.s-a.s).slice(0,5)}
function k51StatHtml(){const users=admUsers();const posts=Object.values(S.posts||{});const ls=S.lastSeen||{};
 const seen=lim=>users.filter(p=>p.uid===S.uid||S.online.has(p.uid)||(ls[p.uid]||0)>now()-lim).length;
 const top=k51Active(7);const mx=Math.max(1,...top.map(x=>x.s));
 return`<div class="adm5-stats k51st3"><div class="adm5-st"><b>${fmt(seen(24*H))}</b><span>aktif · 24 sa</span></div><div class="adm5-st"><b>${fmt(seen(7*24*H))}</b><span>aktif · 7 gün</span></div><div class="adm5-st"><b>${fmt(users.length)}</b><span>toplam üye</span></div></div>
 <div class="k51sps">${k51Spark(k51Bucket(users.map(p=>p.createdAt)),"yeni üye")}${k51Spark(k51Bucket(posts.map(p=>p.at)),"paylaşım")}</div>
 <div class="adm5-sub">En etkin kişiler · 7 gün</div>${top.length?`<div class="adm5-list">${top.map((x,i)=>`<button type="button" class="adm5-u k51top" data-admu="${esc(x.u)}"><span class="k51rk">${i+1}</span>${avatar(x.u,36,{click:false,ring:false,online:false})}<span class="t"><span class="n"><b>${esc(P(x.u).name||P(x.u).username)}</b></span><span class="s">${[x.p&&x.p+" paylaşım",x.c&&x.c+" yorum",x.l&&x.l+" beğeni"].filter(Boolean).join(" · ")}</span><span class="k51meter" aria-hidden="true"><i style="width:${Math.round(x.s/mx*100)}%"></i></span></span></button>`).join("")}</div>`:`<p class="adm5-note">Son 7 günde paylaşım, yorum ya da beğeni yok.</p>`}
 <p class="adm5-note">Sayılar bu cihaza yüklü veriden hesaplanır (son 300 paylaşım, 500 üye). Etkinlik çevrimiçi kayıtlarından gelir.</p>`}
/* Rozetler bölümü */
function k51RozetHtml(){const n=rzIlkN();const users=admUsers();const cnt={};for(const p of users)for(const id of rzOf(p.uid))cnt[id]=(cnt[id]||0)+1;
 return`<p class="adm5-note">Rozetler adların yanında küçük simgeler olarak görünür; dokununca açıklaması açılır. Otomatik olanlar kendiliğinden gelir, diğerlerini <b>Kullanıcılar › kişi › Rozetler</b>'den verirsin.</p>
 <div class="adm5-list">${RZ.map(b=>`<div class="rzrow adm">${rzIc(b.id,"lg")}<div class="t"><b>${esc(b.t)}<small>${b.id==="onayli"?"Onaylı rozetiyle":b.id==="kurucu"?"@bilolotr + elle":b.auto?"otomatik + elle":"elle"}</small></b><span>${esc(rzDesc(b))}</span></div><span class="adm5-n${cnt[b.id]?" on":" dim"}">${fmt(cnt[b.id]||0)}</span></div>`).join("")}</div>
 <div class="k51f"><span class="k51fl">İlk kullanıcı sayısı</span><div class="seg k51seg" role="group" aria-label="İlk kullanıcı sayısı">${[25,50,100,250].map(v=>`<button type="button" data-adm="k51ilk" data-v="${v}" aria-pressed="${n===v}">İlk ${v}</button>`).join("")}</div></div>`}
/* Uygulama anahtarları ve Meydan */
function k51AnahtarHtml(){const md=k51Mdn();const fl=(f,ic,t,s)=>`<label class="srow">${I(ic)}<span class="t">${t}<small>${s}</small></span><span class="sw"><input type="checkbox" data-k51f="${f}"${k51Flag(f)?" checked":""} aria-label="${esc(t)}"><span></span></span></label>`;
 const lk=md.lock?(md.lock>now()+3650*24*H?"Süresiz salt okunur":`${k51When(md.lock)} tarihine kadar salt okunur`):"Herkes yazabilir";
 return`<div class="adm5-set">${fl("reelOff","reels","Klaket yüklemeyi kapat","Açıkken yalnızca yönetici yeni Klaket yükleyebilir")}${fl("storyOff","eye","Hikâye paylaşımını kapat","Açıkken yeni hikâye eklenemez")}${fl("signupOff","users","Yeni kayıtları kapat",S.mode==="cloud"?"Kayıt ekranında “şu an kapalı” yazar. Bulutta kuralların güncel olması gerekir.":"Kayıt ekranında “şu an kapalı” yazar")}</div>
 <div class="adm5-sub">Meydan</div><p class="adm5-note">${I(md.lock?"lock":"globe")} ${esc(lk)}${md.slow?` · yavaş mod ${md.slow<60?md.slow+" sn":Math.round(md.slow/60)+" dk"}`:""}</p>
 <div class="k51f"><span class="k51fl">Salt okunur</span><div class="seg k51seg" role="group" aria-label="Meydan salt okunur">${[[0,"Kapalı"],[30*60e3,"30 dk"],[H,"1 saat"],[24*H,"1 gün"],[1e13,"Süresiz"]].map(([v,l])=>`<button type="button" data-adm="k51lock" data-v="${v}" aria-pressed="${v===0?!md.lock:false}">${l}</button>`).join("")}</div></div>
 <div class="k51f"><span class="k51fl">Yavaş mod</span><div class="seg k51seg" role="group" aria-label="Yavaş mod">${[[0,"Kapalı"],[10,"10 sn"],[30,"30 sn"],[60,"1 dk"],[300,"5 dk"]].map(([v,l])=>`<button type="button" data-adm="k51slow" data-v="${v}" aria-pressed="${md.slow===v}">${l}</button>`).join("")}</div></div>`}
function k51AnahtarWire(el){$$("[data-k51f]",el).forEach(c=>c.onchange=async()=>{const f=c.dataset.k51f,v=c.checked;c.checked=!v;
 const go=async()=>{c.disabled=true;const d={...k51Doc("bayrak"),[f]:v};delete d.by;delete d.at;
  if(await admSet("bayrak",d)){S.adm={...(S.adm||{}),bayrak:{...d,at:now(),by:S.uid}};const names={reelOff:"Klaket yükleme",storyOff:"Hikâye paylaşımı",signupOff:"Yeni kayıtlar"};
   admLog(`${names[f]} ${v?"kapatıldı":"yeniden açıldı"}`,"sistem");toast(`${names[f]} ${v?"kapalı":"açık"}`);
   if(f==="signupOff"&&S.mode==="cloud"&&!await write(()=>DB.set("acik/durum",{signupOff:v,at:now()}),{quiet:true}))toast("Kayıt ekranı bu ayarı göremiyor: Bakım ve sistem › kuralları kopyalayıp yeniden yayınla.");render(false)}else if(c.isConnected)c.disabled=false};
 if(v&&f==="signupOff")return k51Confirm("Yeni kayıtlar kapatılsın mı?","Kimse yeni hesap açamaz; mevcut hesaplar giriş yapmaya devam eder.","Kapat",go);return go()})}
