async function k51KickGroups(uid,{quiet=false}={}){const un=P(uid).username||"hesap";let ds=await admOnceW("chats",{where:["members","array-contains",uid],limit:200});
 if(!ds)ds=Object.entries(S.chats||{}).map(([id,c])=>({id,...c})).filter(c=>(c.members||[]).includes(uid));
 const gs=ds.filter(d=>d&&d.group&&String(d.id).startsWith("gr-"));let k=0,f=0;
 for(const g of gs){const members=(g.members||[]).filter(x=>x!==uid);const patch={members,updatedAt:now()};if(g.createdBy===uid)patch.createdBy=members[0]||null;
  try{await DB.update("chats/"+g.id,patch);k++;const at=now();DB.set(`chats/${g.id}/msgs/${at.toString(36)}a${rid().slice(0,4)}`,{from:S.uid,at,text:`@${un} yönetici tarafından gruptan çıkarıldı`,sys:"admin"}).catch(()=>{})}catch(e){f++}}
 if(!quiet){if(k)admLog(`@${un} ${k} gruptan çıkarıldı`,"kullanici");toast(gs.length?(f?`${k} gruptan çıkarıldı, ${f} tanesinde olmadı.`:`@${un} ${k} gruptan çıkarıldı`):`@${un} hiçbir grupta değil`)}return{k,f,n:gs.length}}
