async function k51Fix(uid,patch,label){const p=P(uid);let ok=await write(()=>DB.update("profiles/"+uid,patch),{quiet:true});
 const q={...(k51Doc("duzelt").list||{})};const e={...(q[uid]||{}),at:now()};if("name"in patch)e.name=patch.name;if("avatar"in patch)e.avatar=1;if("bio"in patch)e.bio=1;if("note"in patch)e.note=1;q[uid]=e;
 for(const k of Object.keys(q))if(now()-(q[k].at||0)>60*24*H)delete q[k];
 const queued=await admSet("duzelt",{list:q});
 if(ok)S.profiles={...S.profiles,[uid]:{...S.profiles[uid],...patch}};
 if(ok||queued){admLog(`@${p.username} ${label}`,"kullanici");toast(ok?"Profil düzeltildi":"Kuralların eski: kişi uygulamayı açınca düzelir. Hemen olsun diye kuralları yeniden yayınla.");render(false)}}
