document.addEventListener("pointermove",e=>{if(e.pointerType!=="mouse")return;const b=kvpBoxOf(e);if(b&&!b._scrub){const n=now();if(!b._mvT||n-b._mvT>250){b._mvT=n;kvpUi(b)}}},{passive:true});
document.addEventListener("contextmenu",e=>{const b=kvpBoxOf(e);if(b&&!b.closest(".msg"))e.preventDefault()});
document.addEventListener("keydown",e=>{const b=kvpBoxOf(e);if(!b||e.ctrlKey||e.metaKey||e.altKey)return;const k=e.key;const self=e.target===b,sc=e.target.matches&&e.target.matches('[data-kv="sc"]');
 if(((k===" "||k==="Enter")&&self)||k==="k"||k==="K"){e.preventDefault();kvpToggle(b)}
 else if((k==="ArrowLeft"&&(self||sc))||k==="j"||k==="J"){e.preventDefault();kvpSkip(b,-5)}
 else if((k==="ArrowRight"&&(self||sc))||k==="l"||k==="L"){e.preventDefault();kvpSkip(b,5)}
 else if(k==="m"||k==="M"){e.preventDefault();kvpMute(b)}
 else if(k==="f"||k==="F"){e.preventDefault();kvpFs(b)}
 else return;kvpUi(b)});
/* yeniden çizimde oynayan (ya da başlatılmış) oynatıcıyı koru */
function kvpKeep(root){const m=new Map();if(!root)return m;for(const b of root.querySelectorAll(".kvp[data-kvid]")){const v=kvpV(b);if(v&&v.getAttribute("src")&&(!v.paused||v.currentTime>0))m.set(b.dataset.kvid,b)}return m}
function kvpPut(root,m){if(!root||!m||!m.size)return;for(const[id,old]of m){if(old.isConnected)continue;const nb=root.querySelector(`.kvp[data-kvid="${CSS.escape(id)}"]`);if(nb&&nb!==old){nb.replaceWith(old);kvpSync(old)}}}
