const KVU=[];let kvuBusy=false;
/* gönderimden önce: sendMessage'in çocuk modu/grup kurallarıyla aynı (yüklemeye boşuna başlanmasın) */
function kvCanSend(key){let k;try{k=keyInfo(key)}catch{return false}
 if(k.type==="bot"){toast("Botlara video gönderilemez.");return false}if(!guard())return false;if(k.type==="dm"&&!childGate(k.uid))return false;
 if(!S.admin){if(k.type==="meydan"&&isChild(S.uid)){toast("Çocuk modunda Meydan kapalı.");return false}
  if(k.type==="dm"&&!BOT[k.uid]&&isChild(k.uid)&&!isChild(S.uid)&&!(isFollowing(S.uid,k.uid)&&isFollowing(k.uid,S.uid))){toast("Bu kişi Çocuk Modu'nda; ona yalnızca karşılıklı arkadaşları yazabilir.");return false}
  if(k.type==="group"){const gc=S.chats[k.cid];if(gc?(Array.isArray(gc.members)&&!gc.members.includes(S.uid)):S._chatsIn){toast("Bu grubun üyesi değilsin.");return false}}}
 return true}
async function kvSendImg(key,img,extra={}){const iw=img.naturalWidth||img.width,ih=img.naturalHeight||img.height;const s=Math.min(1,900/Math.max(iw,ih));const c=document.createElement("canvas");c.width=Math.round(iw*s);c.height=Math.round(ih*s);c.getContext("2d").drawImage(img,0,0,c.width,c.height);S.forceBottom=true;return sendMessage(key,{img:encode(c,150000),text:"",...extra})}
function kvSendVideo(key,file,extra={}){if(!kvCanSend(key))return false;KVU.push({id:"u"+rid(),key,file,extra,st:"wait",pct:0,poster:"",ar:"9/16",ctl:{aborted:false,xhr:null}});S.forceBottom=true;kvuPaint();kvuPump();return true}
async function kvChatSend(key,items){const extra=S.replyTo?{reply:S.replyTo}:{};S.replyTo=null;drawReply();let first=true;
 for(const x of items){const ex=first?extra:{};first=false;if(x.video){kvSendVideo(key,x.video,ex);continue}if(x.img)await kvSendImg(key,x.img,ex)}}
async function kvuPump(){if(kvuBusy)return;kvuBusy=true;try{let u;while((u=KVU.find(x=>x.st==="wait")))await kvuDo(u)}finally{kvuBusy=false}}
async function kvuDo(u){const alive=()=>!u.ctl.aborted;let ref=null;
 try{u.st="prep";kvuUpd(u);let f=await kmMem(u.file);u.file=null;if(!alive())return;
  const url0=URL.createObjectURL(f);const pm=await kvPoster(url0);URL.revokeObjectURL(url0);if(pm){u.poster=pm.img;u.ar=pm.ar}if(!alive())return;kvuPaint();
  const dur=await vidDur(f).catch(()=>0);
  f=await kvPrep(f,{onProg:p=>{u.pct=p;kvuUpd(u)},alive});if(!alive())return;
  u.st="up";u.pct=0;kvuUpd(u);ref=await kvStore(f,(i,n)=>{u.pct=i/Math.max(1,n);kvuUpd(u)},u.ctl);if(!alive()){delChunks(ref);return}
  vcache[ref]=URL.createObjectURL(f);u.st="send";kvuUpd(u);const i=KVU.indexOf(u);if(i>=0)KVU.splice(i,1);
  const ok=await sendMessage(u.key,{video:ref,text:"",...(u.poster?{poster:u.poster}:{}),...(dur>0?{dur:Math.round(dur*10)/10}:{}),ar:u.ar,...u.extra});
  if(!ok){delChunks(ref);if(ok===false)toast("Video gönderilemedi.")}}
 catch(e){if(ref)delChunks(ref);if(!(e&&e.kvAbort)&&alive()){console.warn(e);toast("Video gönderilemedi: "+kvErrText(e))}}
 finally{const i=KVU.indexOf(u);if(i>=0)KVU.splice(i,1);kvuPaint()}}
function kvuRow(u){return`<div class="mrow me kvu-row" id="kvu-${u.id}"><div class="mcol"><div class="msg kvu"><div class="kvu-m" style="--kvp-ar:${kvpArN(u.ar)||9/16}">${u.poster?`<img src="${esc(u.poster)}" alt="">`:""}<span class="kvu-ring"><svg viewBox="0 0 44 44" aria-hidden="true"><circle cx="22" cy="22" r="19"/><circle class="kvu-pr" cx="22" cy="22" r="19" pathLength="100"/></svg><button type="button" class="kvu-x" data-kvux="${u.id}" aria-label="Gönderimi iptal et">${I("close")}</button></span><span class="kvu-st" role="status"></span></div></div></div></div>`}
function kvuUpd(u){const r=document.getElementById("kvu-"+u.id);if(!r)return;const p=Math.round(Math.max(0,Math.min(1,u.pct||0))*100);const ring=r.querySelector(".kvu-ring");if(ring)ring.style.setProperty("--p",u.st==="send"?100:u.st==="wait"?0:p);
 const s=r.querySelector(".kvu-st");if(s)s.textContent=u.st==="wait"?"Sırada":u.st==="prep"?(p?`Hazırlanıyor %${p}`:"Hazırlanıyor"):u.st==="up"?`Yükleniyor %${p}`:"Gönderiliyor";r.classList.toggle("spinning",(u.st==="prep"&&!p)||u.st==="send"||u.st==="wait")}
function kvuPaint(){const box=$("#msgs");if(!box||S.route.name!=="chat")return;box.querySelectorAll(".kvu-row").forEach(e=>e.remove());const list=KVU.filter(u=>u.key===S.route.params.key);if(!list.length)return;
 const pin=box._pin!==false||S.forceBottom;box.insertAdjacentHTML("beforeend",list.map(kvuRow).join(""));list.forEach(kvuUpd);if(pin){box.scrollTop=box.scrollHeight;S.forceBottom=false}}
document.addEventListener("click",e=>{const x=e.target.closest&&e.target.closest("[data-kvux]");if(!x)return;e.stopPropagation();const u=KVU.find(q=>q.id===x.dataset.kvux);if(!u)return;
 u.ctl.aborted=true;try{u.ctl.xhr&&u.ctl.xhr.abort()}catch{}const i=KVU.indexOf(u);if(i>=0)KVU.splice(i,1);kvuPaint();toast("Video gönderimi iptal edildi")},true);
function kvMsgHtml(m){const ref=String(m.video||"");const chunk=ref.startsWith("chunk:");const c=vcache[ref];const src=c||(chunk?"":cldPlay(ref));if(!c&&!chunk&&!kvpOkSrc(src))return"";
 const poster=/^data:image\//.test(m.poster||"")?m.poster:"";return kvpHtml({src,ref:chunk&&!c?ref:"",poster,dur:m.dur||0,ar:m.ar||"9/16",cls:"kvp-msg",label:"Video mesaj",id:"m-"+(m.id||"")})}
function kvMsgDecor(keep){if(S.route.name!=="chat")return;const box=$("#msgs");if(!box)return;let added=false;
 for(const m of currentMsgs()){if(!m||!m.video||m.del||!m.id)continue;const el=document.getElementById("m-"+m.id);if(!el||el.querySelector(".kvp"))continue;
  let node=keep&&keep.get("m-"+m.id);if(!node){const h=kvMsgHtml(m);if(!h)continue;const w=document.createElement("div");w.innerHTML=h;node=w.firstElementChild}
  const anc=[...el.children].filter(c=>c.matches(".fwd,.quote")).pop();if(anc)anc.after(node);else el.prepend(node);el.classList.add("has-kvp");kvpSync(node);added=true}
 if(added&&box._pin!==false)box.scrollTop=box.scrollHeight}
