/* 5.1 engelleme: profiles/{uid}.blocked = {uid: zaman|0}. Engelleyen ya da engellenen arasında paylaşım, mesaj, takip, arama, yorum ve bildirim görünmez. */
const blkOf=u=>((S.profiles[u]||{}).blocked)||{};
const iBlocked=u=>!!(u&&u!==S.uid&&blkOf(S.uid)[u]);
const blockedMe=u=>!!(u&&u!==S.uid&&blkOf(u)[S.uid]);
const isBlk=u=>iBlocked(u)||blockedMe(u);
{const f=allPosts;allPosts=function(...a){return f.apply(this,a).filter(p=>!isBlk(p.uid))}}
{const f=canSee;canSee=function(p){if(p&&isBlk(p.uid))return false;return f(p)}}
{const f=canSeeUser;canSeeUser=uid=>!isBlk(uid)&&f(uid)}
{const f=humans;humans=()=>f().filter(u=>!isBlk(u))}
{const f=commentsOf;commentsOf=function(p){return f(p).filter(c=>!iBlocked(c.uid))}}
{const f=currentMsgs;currentMsgs=function(){const k=keyInfo(S.route.params.key);const m=f();return k.type==="bot"?m:m.filter(x=>!iBlocked(x.from))}}
{const f=chatList;chatList=function(...a){return f.apply(this,a).filter(c=>c.group||!iBlocked(c.other))}}
{const f=notifyChats;notifyChats=function(m){const o={};for(const[id,c]of Object.entries(m||{}))if(!(c&&c.last&&isBlk(c.last.from)))o[id]=c;return f(o)}}
{const f=notifyMeta;notifyMeta=function(m){const o={};for(const[id,d]of Object.entries(m||{})){if(!d){o[id]=d;continue}const likes={},comments={};for(const[u,v]of Object.entries(d.likes||{}))if(!isBlk(u))likes[u]=v;for(const[c,v]of Object.entries(d.comments||{}))if(!(v&&isBlk(v.uid)))comments[c]=v;o[id]={...d,likes,comments}}return f(o)}}
{const f=sendMessage;sendMessage=async function(key,payload){const k=keyInfo(key);if(k.type==="dm"&&isBlk(k.uid)){toast(iBlocked(k.uid)?"Bu kişiyi engelledin. Mesaj için önce engeli kaldır.":"Bu kişiye mesaj gönderemezsin.");return false}return f.apply(this,arguments)}}
{const f=toggleFollow;toggleFollow=async function(uid){if(isBlk(uid)&&!isFollowing(S.uid,uid))return toast(iBlocked(uid)?"Engellediğin kişiyi takip edemezsin.":"Bu kişiyi takip edemezsin.");return f.apply(this,arguments)}}
{const f=startCall;startCall=async function(uid){if(isBlk(uid))return toast("Bu kişiyle arama yapılamıyor.");return f.apply(this,arguments)}}
{const f=incomingCall;incomingCall=function(id,d){if(d&&isBlk(d.from)){try{FB.F.updateDoc(FB.F.doc(FB.db,"calls/"+id),{status:"declined"}).catch(()=>{})}catch{}return}return f.apply(this,arguments)}}
{const f=vProfile;vProfile=function(uid){if(uid&&uid!==S.uid&&isBlk(uid)){const mine=iBlocked(uid);return`<div class="blk-card"><span class="ic">${I("lock")}</span><b>${mine?"Bu hesabı engelledin":"Bu profil görüntülenemiyor"}</b><span class="muted">${mine?"Paylaşımlarını, mesajlarını ve yorumlarını görmüyorsun; o da seni göremez.":"Bu hesabın paylaşımlarını şu an göremezsin."}</span>${mine?`<button class="btn sm" data-act="blkun" data-u="${esc(uid)}">Engeli kaldır</button>`:""}</div>`}return f.apply(this,arguments)}}
async function blkSet(uid,on){if(!guard()||!uid||uid===S.uid)return false;const t=on?now():0;const me=S.profiles[S.uid];if(!me)return false;
 const patch={blocked:{[uid]:t}};if(on&&isFollowing(S.uid,uid))patch.following={[uid]:0};
 if(!await write(()=>DB.update("profiles/"+S.uid,patch)))return false;
 S.profiles={...S.profiles,[S.uid]:{...me,blocked:{...(me.blocked||{}),[uid]:t},...(patch.following?{following:{...(me.following||{}),[uid]:0}}:{})}};
 toast(on?`@${P(uid).username} engellendi`:`@${P(uid).username} için engel kaldırıldı`);render(false);return true}
function blkAsk(uid){const u=P(uid);dialog(`@${u.username} engellensin mi?`,"Birbirinizin paylaşımlarını, hikâyelerini ve yorumlarını görmezsiniz; sana mesaj atamaz, arayamaz, seni takip edemez. İstediğin zaman engeli kaldırabilirsin.",[{label:"Engelle",cls:"danger",fn:()=>blkSet(uid,true)},{label:"Vazgeç"}])}
ACT.blk=(b)=>blkAsk(b.dataset.u);ACT.blkun=(b)=>blkSet(b.dataset.u,false);
{const f=profMenu;profMenu=function(uid){const r=f.apply(this,arguments);try{if(uid&&uid!==S.uid&&!S.guest&&!BOT[uid]){const l=$('#overlay [data-layer="menu"]');const box=l&&(l.querySelector(".opts")||l.querySelector(".sheet")||l);if(box&&!box.querySelector("[data-act=blk],[data-act=blkun]")){const on=iBlocked(uid);const bt=document.createElement("button");bt.className="opt"+(on?"":" danger");bt.dataset.act=on?"blkun":"blk";bt.dataset.u=uid;bt.innerHTML=`${I(on?"check":"lock")}${on?"Engeli kaldır":"Engelle"}`;bt.addEventListener("click",()=>closeLayer("menu"));box.appendChild(bt)}}}catch{}return r}}
/* engellenen kişi, beni engelleyeni takip ediyorsa takibi kendi cihazında bırakır */
HOOKS.profiles.push(()=>{if(!S.authed||S.guest||!S.uid)return;const me=S.profiles[S.uid];if(!me)return;for(const u of Object.keys(me.following||{}))if(me.following[u]&&blockedMe(u)&&!S._blkUnf){S._blkUnf=1;setTimeout(()=>{S._blkUnf=0},5000);DB.update("profiles/"+S.uid,{following:{[u]:0}}).catch(()=>{});break}});
/* Ayarlar: engellenen hesaplar listesi */
function blkSheet(){const ids=Object.keys(blkOf(S.uid)).filter(u=>blkOf(S.uid)[u]);sheet("blks","Engellenen hesaplar",ids.length?`<div style="padding:0 16px 16px">${ids.map(u=>`<div class="blk-row">${avatar(u,40,{click:false,ring:false,online:false})}<div class="t"><b>${esc(P(u).name)}</b><div class="muted">@${esc(P(u).username)}</div></div><button class="btn sec sm" data-act="blkun" data-u="${esc(u)}">Engeli kaldır</button></div>`).join("")}</div>`:`<div class="empty"><b>Kimseyi engellemedin</b>Birini engellemek için profilindeki üç noktaya dokun.</div>`)}
ACT.blklist=()=>blkSheet();
HOOKS.after.push(r=>{if(r!=="settings"||S.guest)return;const m=$("#main");if(!m||m.querySelector("#blkEntry"))return;const n=Object.values(blkOf(S.uid)).filter(Boolean).length;const d=document.createElement("div");d.id="blkEntry";d.className="box";d.style.margin="12px 16px";d.innerHTML=`<button class="row" data-act="blklist" style="width:100%">${I("lock")}<div class="t"><b>Engellenen hesaplar</b><div class="s">${n?n+" hesap":"Kimse yok"}</div></div>${I("next")}</button>`;m.appendChild(d)});
/*}@js:51BLOCK*/

