 const lastU=b.ai?([...msgs].reverse().find(m=>m.from===S.uid)||{}):{};const imgB=lastU.img?dataBlob(lastU.img):null;
 const lastQ=b.ai&&!imgB?String(lastU.text||"").slice(0,400):"";/* köprü genel sorularda internette arar (Tavily); fotoğraflı soruda aramaz, fotoğrafı gönderir (5.5.0) */
 const wrap=smp&&b.ai?Object.assign((p,o)=>smp(p,{...(o||{}),...(lastQ?{search:lastQ}:{}),...(imgB?{images:[imgB]}:{}),...(o&&typeof o.onText==="function"?{onText:x=>{calls++;if(calls>1)o.onText(x)}}:{})}),smp):null;if(wrap)S.caps.sample=wrap;
