 const ring=()=>{if(CALL!==c||c.status!=="incoming")return krStop();sysNote(p.name+" arıyor",(c.video?"Görüntülü arama":"Sesli arama")+" · yanıtlamak için Kadraj'a dön","call-"+c.id,{icon:p.avatar,force:true,kind:"call"})};
