/* ===== 6.1 sohbet (61CHAT) =====
   Sabit mesaj: mesaj menüsünde Sabitle/Sabitlemeyi kaldır (DM ve grup; en fazla PIN_MAX, en yenisi başta). Kayıt chats/{cid}.pins=[mid],
   sabitlenince sohbete sys notu düşer. Şerit .pinbar main.chatmode'un üstüne biner (liste yüksekliği değişmez); dokununca o mesaja gider ve
   sıradaki sabite geçer, (x) kaldırır. Meydan belgesi her mesajda baştan yazıldığı için (DB.set) Meydan'da sabit mesaj yok. */
const PIN_MAX=3;let pinIx=0;
const pinKey=()=>{if(S.route.name!=="chat")return null;const k=keyInfo(S.route.params.key);return k.type==="dm"||k.type==="group"?k:null};
const mpinsOf=k=>((S.chats[k.cid]||{}).pins||[]).filter(mid=>S.msgs.some(m=>m.id===mid&&!m.del));
async function pinSet(k,mid,on){if(!guard())return;const c=S.chats[k.cid]||{};let p=(c.pins||[]).filter(x=>x!==mid);if(on)p=[mid,...p].slice(0,PIN_MAX);
 S.chats={...S.chats,[k.cid]:{...c,pins:p}};pinIx=0;pinPaint();
 if(await write(()=>DB.update("chats/"+k.cid,{pins:p}))&&on){const at=now();await write(()=>DB.set(`chats/${k.cid}/msgs/${rid()}`,{from:S.uid,at,sys:"pin",text:`${me().name||me().username} bir mesajı sabitledi`}),{quiet:true})}
 toast(on?"Mesaj sabitlendi":"Sabitleme kaldırıldı")}
function pinPaint(){const main=$("#main");let bar=main&&main.querySelector(":scope>.pinbar");const k=pinKey();const p=k?mpinsOf(k):[];
 if(!p.length){if(bar)bar.remove();return}if(pinIx>=p.length)pinIx=0;const m=S.msgs.find(x=>x.id===p[pinIx]);
 const h=`<button type="button" class="pj" data-pinj="${esc(m.id)}">${I("pin")}<span><b>Sabit mesaj${p.length>1?` ${pinIx+1}/${p.length}`:""}</b><em>${esc(msgPreview(m).slice(0,90))}</em></span></button>${p.length>1?`<span class="pdots">${p.map((_,i)=>`<i class="${i===pinIx?"on":""}"></i>`).join("")}</span>`:""}<button type="button" class="px" data-pinx="${esc(m.id)}" aria-label="Sabitlemeyi kaldır">${I("close")}</button>`;
 if(!bar){bar=document.createElement("div");bar.className="pinbar";main.prepend(bar)}if(bar._h!==h){bar.innerHTML=h;bar._h=h}
 /* Vizör'de üst çubuk sohbetin üstüne biner: şerit mesaj kutusunun görünen üst kenarına oturur */
 const box=$("#msgs");if(box){const t=Math.max(0,Math.round(box.getBoundingClientRect().top-main.getBoundingClientRect().top))+8;const hd=$("#top");const hb=hd?hd.getBoundingClientRect().bottom-main.getBoundingClientRect().top+8:0;bar.style.top=Math.max(t,hb)+"px"}}
document.addEventListener("click",e=>{const j=e.target.closest&&e.target.closest("[data-pinj],[data-pinx]");if(!j)return;const k=pinKey();if(!k)return;e.preventDefault();e.stopPropagation();
 if(j.dataset.pinx)return pinSet(k,j.dataset.pinx,false);
 const el=document.getElementById("m-"+j.dataset.pinj);if(el){try{cfRelease()}catch{}el.scrollIntoView({block:"center",behavior:kbReduce()?"auto":"smooth"});el.classList.remove("flash");void el.offsetWidth;el.classList.add("flash")}
 const p=mpinsOf(k);if(p.length>1){pinIx=(pinIx+1)%p.length;pinPaint()}},true);
const msgMenuBase61=msgMenu;
msgMenu=function(mid,...a){const r=msgMenuBase61.call(this,mid,...a);try{const k=pinKey();const l=$('#overlay [data-layer="menu"]');const m=S.msgs.find(x=>x.id===mid);
  if(l&&m&&m.once){const f=l.querySelector("#mmF");if(f)f.remove()}
  if(k&&l&&m&&m.sch&&m.at>now()&&m.from===S.uid){const cancel=l.querySelector('.opt[data-act="close"]');const b=document.createElement("button");b.className="opt";b.innerHTML=`${I("send")}Hemen gönder`;
   b.onclick=async()=>{closeLayer("menu");const at=now();S.msgs=S.msgs.map(x=>x.id===mid?{...x,at,sch:null}:x).sort((x,y)=>x.at-y.at);renderMsgs();
    if(await write(()=>DB.update(`chats/${k.cid}/msgs/${mid}`,{at,sch:null})))await updateLast(k,{...m,at,sch:null})};if(cancel)cancel.before(b)}
  if(k&&l&&m&&!m.sys){const on=((S.chats[k.cid]||{}).pins||[]).includes(mid);const cancel=l.querySelector('.opt[data-act="close"]');
   const b=document.createElement("button");b.className="opt";b.innerHTML=`${I("pin")}${on?"Sabitlemeyi kaldır":"Sabitle"}`;b.onclick=()=>{closeLayer("menu");pinSet(k,mid,!on)};if(cancel)cancel.before(b)}}catch(e){console.warn(e)}return r};
const renderMsgsBase61=renderMsgs;
renderMsgs=function(...a){const r=renderMsgsBase61.apply(this,a);try{pinPaint()}catch(e){console.warn(e)}return r};
HOOKS.after.push(()=>{pinIx=0;try{pinPaint()}catch{}try{onceSweep()}catch{}});
/* Tek seferlik fotoğraf: + menüsünde "Tek seferlik fotoğraf" (DM ve grup). Mesaj {img, once:1}; alıcı dokununca tam ekranda bir kez açar, kapatınca
   opened.{uid}=zaman yazılır ve DM'de resim silinir (img:null); grupta herkes açınca ya da 24 saat sonra silinir. Gönderen resmi görmez.
   İlet, kopyala, sohbet ayrıntılarındaki Medya listesi bu mesajda yok; özet "Tek seferlik fotoğraf". Ekran görüntüsü web'de engellenemez. */
const ONCE_T=24*H;
function onceOthers(k,m){if(k.type==="dm")return[k.uid];const c=S.chats[k.cid]||{};return(c.members||[]).filter(u=>u!==m.from)}
function onceHtml(m){const op=m.opened||{};const mine=m.from===S.uid;let k=null;try{k=keyInfo(S.route.params.key)}catch{}
 const seenBy=k?onceOthers(k,m).filter(u=>op[u]).length:0;
 if(mine)return`<span class="once${m.img?"":" off"}"><span class="oi">${I("eye")}</span><span><b>Fotoğraf</b><small>Bir kez · ${seenBy?(k&&k.type==="group"?`${seenBy} kişi açtı`:"Açıldı"):"Gönderildi"}</small></span></span>`;
 if(op[S.uid]||!m.img)return`<span class="once off"><span class="oi">${I("eye")}</span><span><b>Fotoğraf</b><small>Açıldı</small></span></span>`;
 return`<button type="button" class="once" data-once="${esc(m.id)}"><span class="oi">${I("eye")}</span><span><b>Fotoğraf</b><small>Bir kez görüntülenir · dokun</small></span></button>`}
async function onceSend(){const key=S.route.params.key;const r=await pickImage({title:"Tek seferlik fotoğraf"});if(!r||!r.img)return;const iw=r.img.naturalWidth||r.img.width,ih=r.img.naturalHeight||r.img.height;
 const sc=Math.min(1,900/Math.max(iw,ih));const c=document.createElement("canvas");c.width=Math.round(iw*sc);c.height=Math.round(ih*sc);c.getContext("2d").drawImage(r.img,0,0,c.width,c.height);
 S.forceBottom=true;await sendMessage(key,{img:encode(c,150000),once:1,text:""})}
function onceOpen(mid){const k=keyInfo(S.route.params.key);const m=S.msgs.find(x=>x.id===mid);if(!m||!m.img||m.from===S.uid||(m.opened||{})[S.uid])return;
 const l=openLayer("oncev",`<div class="oncev" role="dialog" aria-label="Tek seferlik fotoğraf"><img src="${esc(m.img)}" alt="Fotoğraf"><span class="ot">Bir kez görüntülenir</span><button type="button" data-act="close" aria-label="Kapat">${I("close")}</button></div>`,{noScrim:true,onClose:()=>onceDone(k,mid)});
 l.addEventListener("contextmenu",e=>e.preventDefault())}
async function onceDone(k,mid){const m=S.msgs.find(x=>x.id===mid);if(!m)return;const at=now();const op={...(m.opened||{}),[S.uid]:at};
 const all=onceOthers(k,m).every(u=>op[u]);const patch={opened:{[S.uid]:at}};if(all||k.type==="dm")patch.img=null;
 S.msgs=S.msgs.map(x=>x.id===mid?{...x,opened:op,...(patch.img===null?{img:null}:{})}:x);renderMsgs();await write(()=>DB.update(`chats/${k.cid}/msgs/${mid}`,patch),{quiet:true})}
/* gönderen: 24 saati geçen açılmamış tek seferlik fotoğrafı siler */
function onceSweep(){const k=pinKey();if(!k)return;for(const m of S.msgs)if(m.once&&m.img&&m.from===S.uid&&now()-m.at>ONCE_T)write(()=>DB.update(`chats/${k.cid}/msgs/${m.id}`,{img:null}),{quiet:true})}
document.addEventListener("click",e=>{const b=e.target.closest&&e.target.closest("[data-once]");if(!b)return;e.preventDefault();e.stopPropagation();onceOpen(b.dataset.once)},true);
const plusMenuBase61=plusMenu;
plusMenu=function(...a){const r=plusMenuBase61.apply(this,a);try{const k=pinKey();const l=$('#overlay [data-layer="plus"]');const box=l&&l.querySelector(".srcs");const ph=box&&box.querySelector("#pph");
  if(k&&ph){const b=document.createElement("button");b.className="src";b.id="pon";b.innerHTML=`<span class="ic">${I("eye")}</span><span><b>Tek seferlik fotoğraf</b><small>Bir kez açılır, sonra kaybolur</small></span>`;b.onclick=()=>{closeLayer("plus");onceSend()};ph.after(b);
   const z=document.createElement("button");z.className="src";z.id="psch";z.innerHTML=`<span class="ic">${I("bell")}</span><span><b>Mesajı zamanla</b><small>Seçtiğin saatte görünsün</small></span>`;z.onclick=()=>{closeLayer("plus");schOpen()};b.after(z);
   const g=document.createElement("button");g.className="src";g.id="pog";g.innerHTML=`<span class="ic">${OG_IC}</span><span><b>Oyun oyna</b><small>XOX, 4'lü Bağla ya da Kelime</small></span>`;g.onclick=()=>{closeLayer("plus");ogPick(S.route.params.key)};z.after(g)}}catch(e){console.warn(e)}return r};
/* Mesaj zamanlama: + menüsünde "Zamanla" (DM ve grup, var olan sohbet). Sunucu olmadığı için mesaj hemen gelecek zamanla yazılır
   ({at:gelecek, sch:1}); alıcının cihazı zamanı gelene kadar göstermez (renderMsgs öncesi süzülür), son mesaj özeti ve bildirim o ana kadar
   değişmez. Zamanı gelince açık sohbette görünür ve görenin cihazı chats.last'ı günceller (o zaman uygulama içi bildirim düşer). Telefon
   bildirimi (push) zamanlanmış mesajda gönderilmez. Gönderen soluk "Zamanlandı · saat" balonu görür; mesaj menüsünde Hemen gönder, silmek
   için Herkesten sil. */
const schLabel=t=>{const d=new Date(t),n=new Date();const hm=d.toLocaleTimeString("tr-TR",{hour:"2-digit",minute:"2-digit"});
 if(d.toDateString()===n.toDateString())return"bugün "+hm;const y=new Date(n);y.setDate(n.getDate()+1);if(d.toDateString()===y.toDateString())return"yarın "+hm;
 return d.toLocaleDateString("tr-TR",{day:"numeric",month:"short"})+" "+hm};
function schOpts(){const n=new Date(),o=[];o.push(["1 saat sonra",now()+H]);const ev=new Date(n);ev.setHours(20,0,0,0);if(ev>n)o.push(["Bu akşam 20:00",+ev]);
 const tm=new Date(n);tm.setDate(n.getDate()+1);tm.setHours(9,0,0,0);o.push(["Yarın 09:00",+tm]);return o}
function schOpen(){const k=pinKey();if(!k)return;if(!S.chats[k.cid])return toast("Önce bir mesaj gönder, sonra zamanlayabilirsin.");
 const pad=x=>String(x).padStart(2,"0");const dflt=new Date(now()+H);const loc=`${dflt.getFullYear()}-${pad(dflt.getMonth()+1)}-${pad(dflt.getDate())}T${pad(dflt.getHours())}:${pad(dflt.getMinutes())}`;
 const l=sheet("sch","Mesajı zamanla",`<form class="schf" id="schF"><textarea class="in" id="schT" maxlength="2000" placeholder="Mesaj yaz…"></textarea>
  <div class="schq">${schOpts().map(([t,v],i)=>`<button type="button" data-schv="${v}" aria-pressed="${i===0}">${esc(t)}</button>`).join("")}<button type="button" data-schv="c" aria-pressed="false">Başka zaman</button></div>
  <input class="in" type="datetime-local" id="schD" value="${loc}" hidden><button class="btn block">Zamanla</button></form>`);
 const ta=$("#schT",l),dt=$("#schD",l);let pick=schOpts()[0][1];const mi=$("#msgIn");if(mi&&mi.value.trim())ta.value=mi.value.trim();ta.focus();
 $$("[data-schv]",l).forEach(b=>b.onclick=()=>{$$("[data-schv]",l).forEach(x=>x.setAttribute("aria-pressed",x===b));if(b.dataset.schv==="c"){dt.hidden=false;pick=null}else{dt.hidden=true;pick=+b.dataset.schv}});
 $("#schF",l).onsubmit=async e=>{e.preventDefault();if(!guard())return;const v=kidClean(ta.value.trim());if(!v)return toast("Mesaj boş.");
  const at=pick||(dt.value?new Date(dt.value).getTime():0);if(!at||at<now()+60e3)return toast("En az bir dakika sonrasını seç.");
  closeLayer("sch");if(mi&&mi.value.trim()===v){mi.value="";try{cfGrow(mi,true)}catch{}try{draftSet(S.route.params.key,"")}catch{}}
  const mid=rid();const msg={from:S.uid,at,text:v,sch:1};S.msgs=[...S.msgs,{id:mid,...msg}].sort((a,b)=>a.at-b.at);renderMsgs();
  if(await write(()=>DB.set(`chats/${k.cid}/msgs/${mid}`,msg)))toast("Zamanlandı: "+schLabel(at));else{S.msgs=S.msgs.filter(x=>x.id!==mid);renderMsgs()}}}
/* zamanı gelmemiş başkasının mesajı görünmez; zamanı gelince yeniden çizilir ve son mesaj özeti güncellenir */
let schT=0;
function schDue(k){const t=now();let next=Infinity;for(const m of S.msgs)if(m.sch&&m.at>t)next=Math.min(next,m.at);clearTimeout(schT);
 if(next<Infinity&&next-t<2147e6)schT=setTimeout(()=>{if(pinKey())renderMsgs()},next-t+300);
 const c=S.chats[k.cid]||{};const due=S.msgs.filter(m=>m.sch&&m.at<=t&&!m.del&&m.at>((c.last||{}).at||0));const last=due[due.length-1];
 if(last){S.chats={...S.chats,[k.cid]:{...c,last:{text:msgPreview(last).slice(0,80),from:last.from,at:last.at}}};write(()=>DB.update("chats/"+k.cid,{last:{text:msgPreview(last).slice(0,80),from:last.from,at:last.at},updatedAt:last.at}),{quiet:true})}}
const renderMsgsSch61=renderMsgs;
renderMsgs=function(...a){const k=pinKey();if(!k)return renderMsgsSch61.apply(this,a);const all=S.msgs;const t=now();
 if(all.some(m=>m.sch&&m.at>t&&m.from!==S.uid))S.msgs=all.filter(m=>!(m.sch&&m.at>t&&m.from!==S.uid));let r;try{r=renderMsgsSch61.apply(this,a)}finally{S.msgs=all}
 try{schDue(k)}catch(e){console.warn(e)}return r};
/* 6.1 klavye: Android Chrome yazı kutularında klavyenin üstüne eski yazılardan öneri ("Meraba") ve şifre/kart/adres şeridi koyuyordu (sahibi "beyaz şey
   rahatsız edici" dedi). Giriş/kayıt dışındaki autocomplete'i belirtilmemiş bütün kutulara autocomplete="off" yazılır (MutationObserver). */
(function(){const fix=root=>{for(const el of (root.querySelectorAll?root.querySelectorAll("input:not([autocomplete]),textarea:not([autocomplete])"):[])){const t=(el.type||"").toLowerCase();if(t==="password"||t==="email"||t==="file"||t==="range"||t==="checkbox"||t==="radio")continue;el.setAttribute("autocomplete","off");if(el.tagName==="INPUT"&&!el.name)el.name="k"+Math.random().toString(36).slice(2,8)}};
 fix(document);new MutationObserver(ms=>{for(const m of ms)for(const n of m.addedNodes)if(n.nodeType===1){if(n.matches&&n.matches("input,textarea"))fix(n.parentNode||document);else fix(n)}}).observe(document.documentElement,{childList:true,subtree:true})})();
/* 6.1.3: Android Chrome tek satırlık <input>'larda klavyenin üstüne şifre/kart/adres şeridini (beyaz şerit) koyuyor, <textarea>'da koymuyor (sohbet kutusu
   zaten textarea). Not, hikâye yanıtı, sohbette ara ve Keşfet araması tek satırlık textarea (.k1l): Enter yeni satır açmaz, formdaysa gönderir
   (data-k1own olanın kendi Enter işleyicisi var), yapıştırılan satır sonları boşluk olur. */
document.addEventListener("keydown",e=>{const t=e.target;if(!t||!t.classList||!t.classList.contains("k1l")||e.key!=="Enter"||e.isComposing)return;e.preventDefault();if(!t.dataset.k1own&&t.form){try{t.form.requestSubmit()}catch{t.form.dispatchEvent(new Event("submit",{cancelable:true}))}}},true);
