  const H=Math.max(240,L.length*58+90);const Y=Math.round((1280-H-84)/2);card(X,Y,W,H+84);const g2=x.createLinearGradient(X,Y,X+W,Y+H);g2.addColorStop(0,cs[0]);g2.addColorStop(1,cs[1]||cs[0]);x.save();shRR(x,X+12,Y+12,W-24,H-12,22);x.fillStyle=g2;x.fill();x.restore();
