/* 6.3.1: sahibi "cephe ve satranç görünmeyen bir yerde olsun" dedi: Keşfet'teki Oyunlar kartı kalktı, Ayarlar'da #k63G satırı (gmHub); sohbette + › Oyunlar duruyor.
   Keşfet'te yerine okul sayacı (okulHtml): sıradaki tatil, okulun kapanması (MEB 2026-2027: 25 Haziran 2027) ve LGS (MEB henüz açıklamadı, tahmini 12 Haziran 2027).
   Kart .chesscard sınıfını taşır (Clawd'ın Keşfet odası). Yeni yılda OKUL_* tarihlerini güncelle. */
const OKUL_TT=[["Ara tatile",new Date(2026,10,16),"16 Kasım"],["Yarıyıl tatiline",new Date(2027,0,25),"25 Ocak"],["Ara tatile",new Date(2027,2,8),"8 Mart"]],OKUL_SON=new Date(2027,5,25),OKUL_LGS=new Date(2027,5,12);
function okDays(d){const t=new Date();t.setHours(0,0,0,0);return Math.round((d-t)/864e5)}
function okulHtml(){const it=[];const tt=OKUL_TT.find(x=>okDays(x[1])>0);if(tt)it.push([tt[0],okDays(tt[1]),tt[2]]);const s=okDays(OKUL_SON);if(s>0)it.push(["Okulun kapanmasına",s,"25 Haziran"]);const l=okDays(OKUL_LGS);if(l>0)it.push(["LGS'ye",l,"12 Haziran · tahmini"]);if(!it.length)return"";
 return`<div class="square chesscard okc" role="group" aria-label="Okul takvimi">${it.map(([a,n,d])=>`<div class="okc-i"><small>${esc(a)}</small><b>${n}<span> gün</span></b><em>${esc(d)}</em></div>`).join("")}</div>`}
