 b.onclick=e=>{e.stopPropagation();if(pause)pause(true);sheet("svmus",m.t,`<div class="pm-sh">${musHtml(m)}<p class="muted" style="margin:0;font-size:.8rem">${musFrom(m)} önizlemesi. Kapatınca hikâye devam eder.</p></div>`,{onClose:()=>{try{itStop()}catch{}if(pause)pause(false)}})};
