const tmKey=()=>"kadraj_time_"+S.uid;const tmDay=(d=new Date())=>d.getFullYear()+"-"+String(d.getMonth()+1).padStart(2,"0")+"-"+String(d.getDate()).padStart(2,"0");
setInterval(()=>{if(!S.authed||S.guest||!S.uid||document.hidden)return;const k=tmKey();const t=LS.get(k)||{};const d=tmDay();t[d]=(t[d]||0)+30;const ks=Object.keys(t).sort();while(ks.length>14)delete t[ks.shift()];LS.set(k,t);
 const lim=+settings.timeLimit||0;if(lim&&t[d]>=lim*60&&LS.get("kadraj_tmw_"+S.uid)!==d){LS.set("kadraj_tmw_"+S.uid,d);toast(`Bugün Kadraj'da ${tmFmt(t[d])} geçirdin. Biraz mola vermeye ne dersin?`)}},30000);
const tmFmt=sec=>{const m=Math.round(sec/60);return m<60?m+" dk":Math.floor(m/60)+" sa"+(m%60?" "+m%60+" dk":"")};
function tmSheet(){const t=LS.get(tmKey())||{};const days=[...Array(7)].map((_,i)=>{const d=new Date();d.setDate(d.getDate()-6+i);return{d,k:tmDay(d),v:t[tmDay(d)]||0}});const mx=Math.max(60,...days.map(x=>x.v));const avg=days.reduce((a,x)=>a+x.v,0)/7;
 const dn=["Paz","Pzt","Sal","Çar","Per","Cum","Cmt"];const lim=+settings.timeLimit||0;
 const l=sheet("tm","Kadraj'da geçirdiğin süre",`<div class="tm"><div class="tm-h"><div><small>Bugün</small><b>${tmFmt(days[6].v)}</b></div><div><small>Günlük ortalama</small><b>${tmFmt(avg)}</b></div></div>
 <div class="tm-c">${days.map((x,i)=>`<div class="tm-b${i===6?" on":""}"><i style="height:${Math.max(3,Math.round(x.v/mx*100))}%"></i><small>${dn[x.d.getDay()]}</small></div>`).join("")}</div>
 <div class="tm-l"><b>Günlük hatırlatma</b><small>Süre dolunca Kadraj sana mola hatırlatır.</small><div class="chips">${[[0,"Kapalı"],[30,"30 dk"],[60,"1 saat"],[120,"2 saat"]].map(([v,n])=>`<button class="chip" type="button" data-tml="${v}" aria-pressed="${lim===v}">${n}</button>`).join("")}</div></div><p class="muted" style="margin:0;font-size:.78rem">Yalnızca bu cihazda, Kadraj açıkken sayılır.</p></div>`);
 l.onclick=e=>{const b=e.target.closest("[data-tml]");if(!b)return;settings.timeLimit=+b.dataset.tml;saveSettings();$$("[data-tml]",l).forEach(x=>x.setAttribute("aria-pressed",String(x===b)));toast(+b.dataset.tml?"Hatırlatma "+b.textContent+" olarak ayarlandı":"Hatırlatma kapatıldı")}}
