function hlErr(e){console.warn("hl",e);toast(e&&e.code==="permission-denied"?"Öne çıkanlar için yöneticinin Firebase kurallarını yeniden yayınlaması gerekiyor.":"Kaydedilemedi: "+(e&&e.message?e.message:"bilinmeyen hata"))}
