 const by=S.route.params&&S.route.params.by;if(by)return L.filter(p=>p.uid===by).sort((a,b)=>b.at-a.at);
 if(S._rsSeedFor!==S.route){S._rsSeedFor=S.route;S.reelSeed=(Math.random()*4294967295)>>>0}
 const sd=S.reelSeed,k={};const KL=kvList().filter(p=>!L.some(x=>x.id===p.id));for(const p of [...L,...KL])k[p.id]=hash32(String(p.id),sd);const srt=a=>a.slice().sort((a,b)=>k[a.id]<k[b.id]?-1:k[a.id]>k[b.id]?1:0);
 /* 6.8.11: keşif Klaketleri (bölge 71) karışık; Kadraj'dakiler bir, keşif iki sırayla serpiştirilir, keşif bitince kalanlar */
