vzMeta=function(r){const pr=S.route.params||{};try{
 if(r==="feed"){const h=new Date().getHours();const g=h<5||h>=22?"İyi geceler":h<11?"Günaydın":h<17?"İyi günler":"İyi akşamlar";const n=String(me().name||"").trim().split(/\s+/)[0];return n?`${g}, ${n}`:g}
 if(r==="explore")return"Kişiler, etiketler ve paylaşımlar";
 if(r==="chats"){const u=+unreadCount()||0;const a=activeUsers().length;return(u?`${u} okunmamış sohbet`:"Hepsi okundu")+(a?` · ${a} kişi aktif`:"")}
 if(r==="profile")return pr.uid===S.uid?"Senin kadrajın":activeLabel(pr.uid)||"";
 if(r==="post"){const p=postById(pr.id);return p?"@"+P(p.uid).username:""}
 if(r==="activity")return"Beğeniler, yorumlar ve takipler";
 if(r==="settings")return"Kadraj "+APP_VER;
 if(r==="edit")return"Ad, kullanıcı adı ve biyografi";
 if(r==="people")return pr.type==="followers"?"Takipçiler":"Takip edilenler";
 if(r==="invite")return"Bağlantı ve davet mesajı";
 if(r==="admin")return"Yönetim paneli"}catch{}return""};
vzUiRow=function(){const cur=vzMode();const k=esc(kbFold("arayüz görünüm vizör klasik tasarım stil yeni eski dok menü alt çubuk cam"));
 const mk=v=>`<span class="vz-mk ${v}" aria-hidden="true"><i class="c1"></i><i class="c2"></i><i class="bar"></i><i class="sh"></i></span>`;
 return`<div class="srow sblk vz-uirow" data-k="${k}"><div class="sbh"><span class="sic" style="--c:#FF8A4C">${I("aperture")}</span><span class="t">Arayüz<small>Vizör: menüler içeriğin üstünde cam gibi yüzer. Klasik: üst çubuk ve alt menü sabit durur.</small></span><span class="val">${cur==="vizor"?"Vizör":"Klasik"}</span></div><div class="vz-uic" role="group" aria-label="Arayüz">${[["vizor","Vizör"],["klasik","Klasik"]].map(([v,l])=>`<button data-act="uiset" data-v="${v}" aria-pressed="${cur===v}">${mk(v)}<span>${l}</span></button>`).join("")}</div></div>`};

