 const l=sheet("ogpick","Oyun oyna",`<div class="srcs">${gs.map(([t,n,d])=>`<button class="src" type="button" data-ogt="${t}"><span class="ic">${OG_IC}</span><span><b>${n}</b><small>${d}</small></span></button>`).join("")}</div>`);
