const bdOk=v=>{const m=/^(\d\d)-(\d\d)$/.exec(String(v||""));if(!m)return null;const mo=+m[1],d=+m[2];if(mo<1||mo>12||d<1||d>[31,29,31,30,31,30,31,31,30,31,30,31][mo-1])return null;return{mo,d}};
