const gunDay=(y,s)=>{const[m,d]=s.split("-").map(Number);return new Date(y,m-1,d)};
const gunKey=t=>t.getFullYear()+"-"+gunPad(t.getMonth()+1)+"-"+gunPad(t.getDate());
