function gunConfetti(tr){if(document.documentElement.classList.contains("reduce-motion")||matchMedia("(prefers-reduced-motion: reduce)").matches)return;const host=document.createElement("div");host.className="gconf";host.setAttribute("aria-hidden","true");
 const cols=tr?["#E30A17","#ffffff","#E30A17","#ffd7d9"]:["#ffcf4d","#3fd3ab","#e23e57","#1d4ed8","#f97316"];for(let i=0;i<46;i++){const c=document.createElement("i");c.style.cssText=`left:${Math.random()*100}%;background:${cols[i%cols.length]};animation-delay:${Math.random()*.6}s;animation-duration:${1.8+Math.random()*1.2}s;--r:${Math.random()*720-360}deg`;host.appendChild(c)}
 document.body.appendChild(host);setTimeout(()=>host.remove(),3800)}
