function gunWrap(ctx,txt,x,y,w,lh,max){const ws=String(txt).split(/\s+/);let ln="",n=0;for(const wd of ws){const t=ln?ln+" "+wd:wd;if(ctx.measureText(t).width>w&&ln){ctx.fillText(ln,x,y+n*lh);n++;ln=wd;if(n>=max)return n}else ln=t}if(ln){ctx.fillText(ln,x,y+n*lh);n++}return n}
async function gunCanvas(g){const c=document.createElement("canvas");c.width=720;c.height=1280;const x=c.getContext("2d");
 const bg=x.createLinearGradient(0,0,720,1280);const P={milli:["#b80612","#E30A17"],anma:["#0b0b0c","#2a2a2e"],dini:["#065f46","#0f766e"],gun:["#4338ca","#db2777"]}[g.t]||["#0c7a63","#0a4f73"];bg.addColorStop(0,P[0]);bg.addColorStop(1,P[1]);x.fillStyle=bg;x.fillRect(0,0,720,1280);
 let y=250;if(g.t==="milli"){try{const im=await loadImg("data:image/svg+xml;charset=utf-8,"+encodeURIComponent(GUN_FLAG.replace('class="gflag" ','xmlns="http://www.w3.org/2000/svg" width="1200" height="800" ')));x.save();x.shadowColor="rgba(0,0,0,.35)";x.shadowBlur=30;x.drawImage(im,90,170,540,360);x.restore();y=640}catch{}}
 else if(g.t==="anma"){try{const im=await loadImg("data:image/svg+xml;charset=utf-8,"+encodeURIComponent(GUN_RIB.replace('class="grib" ','xmlns="http://www.w3.org/2000/svg" width="200" height="280" ').replace('fill="#111"','fill="#e5e5e5"')));x.drawImage(im,280,170,160,224);y=500}catch{}}
 else if(g.t==="dini"){try{const im=await loadImg("data:image/svg+xml;charset=utf-8,"+encodeURIComponent(GUN_MOON.replace('class="gmoon" ','xmlns="http://www.w3.org/2000/svg" width="256" height="256" ')));x.drawImage(im,232,180,256,256);y=540}catch{}}
 x.fillStyle="#fff";x.textAlign="center";x.font="700 50px Unbounded, Figtree, sans-serif";y+=gunWrap(x,g.ad,360,y,600,64,4)*64+30;
 if(g.q){x.font="italic 500 34px Figtree, sans-serif";x.globalAlpha=.9;y+=gunWrap(x,"“"+g.q+"”",360,y,600,46,5)*46+10;x.font="600 26px Figtree, sans-serif";x.fillText("Mustafa Kemal Atatürk",360,y+6);y+=60;x.globalAlpha=1}
 x.font="500 34px Figtree, sans-serif";gunWrap(x,g.msg,360,y,600,46,7);
 x.globalAlpha=.75;x.font="700 30px Unbounded, Figtree, sans-serif";x.fillText("kadraj",360,1210);x.globalAlpha=1;return c}
