const qmTime=t=>{const d=new Date(t),n=new Date();const hm=d.toLocaleTimeString("tr-TR",{hour:"2-digit",minute:"2-digit"});return d.toDateString()===n.toDateString()?hm:"yarın "+hm};
function qmSheet(){const tm=()=>{const t=new Date();t.setDate(t.getDate()+1);t.setHours(8,0,0,0);return t.getTime()};const on=quietOn();
 const l=sheet("qm","Sessiz mod",`<div class="cf-top"><span class="cf-ic qm">${I("moon")}</span><p>Sessiz moddayken bildirim gelmez; sana yazanlar sessiz modda olduğunu görür. Uyku, ders ve sınav zamanı için.</p></div>${on?`<div class="banner" style="margin:0 0 10px">${I("moon")}<span><b>Sessiz mod açık</b><br>${esc(qmTime(qmUntil()))}'e kadar</span></div>`:""}<div class="opts">${[[3600e3,"1 saat"],[3*3600e3,"3 saat"],[8*3600e3,"8 saat"],["m","Yarın sabah 08:00'e kadar"]].map(([v,lb])=>`<button class="opt" data-qmv="${v}">${I("moon")}${lb}</button>`).join("")}${on?`<button class="opt red" data-qmv="0">${I("close")}Sessiz modu kapat</button>`:""}</div>`);
 l.onclick=e=>{const b=e.target.closest("[data-qmv]");if(!b)return;const v=b.dataset.qmv;closeLayer("qm");if(v==="0"){qmSet(0);return toast("Sessiz mod kapandı")}const u=v==="m"?tm():now()+(+v);qmSet(u);toast("Sessiz mod açık: "+qmTime(u)+"'e kadar")};return l}
