const gqKey=(d=new Date())=>d.getFullYear()+String(d.getMonth()+1).padStart(2,"0")+String(d.getDate()).padStart(2,"0");
function gqQ(d=new Date()){const n=Math.round(new Date(d.getFullYear(),d.getMonth(),d.getDate()).getTime()/864e5);return GQ_LIST[((n*7)%GQ_LIST.length+GQ_LIST.length)%GQ_LIST.length]}
